@dataclass
class MoveInputs:
    """v25.30: moving out of Florida: renting in the new state and keeping the Gulf Breeze house. Saved with the plan; it changes the model only
    when active is True ('Make it the plan' on the Moving page). Money is in today's (2026) dollars unless noted. 'overrides' holds any of the
    state's rules you changed (ret, ret_age, ss, local, veh), so choosing another state starts again from that state's own rules."""
    active: bool = False                 # True = the move is part of the plan
    keep_fl: bool = False                # v25.31: Florida stays home -- fewer than 184 nights a year in the new state, so no state income tax there,
                                         # the Gulf Breeze homestead is kept and the cars stay registered in Florida; the rent and other costs remain
    housing: str = "rent"                # v25.32: "rent" (rent there, keep Gulf Breeze) or "sell" (sell Gulf Breeze, buy there with the proceeds)
    state: str = "VA"
    area: str = "Loudoun County"
    year: int = 2031                     # the year you move
    month: int = 7                       # the month you move (the new state taxes you as a resident from then on)
    both_65_year: int = 2034             # first year you are both 65 or older
    rent_month: float = 3200.0           # rent a month, today's dollars (Loudoun 3-bedroom average about $3,250, Feb 2026)
    rent_growth: float = 0.03            # yearly rent increase
    other_month: float = 300.0           # other new costs a month: renter's insurance, a second set of utilities
    fl_savings_year: float = 0.0         # Gulf Breeze costs that stop once you leave (pool service and the like), a year
    fl_extra_tax_year: float = 1000.0    # extra Gulf Breeze property tax a year once it is no longer your homestead
    moving_cost: float = 15000.0         # one-off, in the year you move
    car_value: float = 30000.0           # cars you would register there, total value
    cars: int = 2
    tax_rv: bool = True                  # the motorhome is taxed too where vehicles are taxed
    muni_home_share: float = 0.0         # share of your muni interest from the new state's own bonds (not taxed there)
    # selling Gulf Breeze and buying there (housing == "sell"); no mortgage, the sale pays for the new home
    sell_cost_pct: float = 0.07          # agent's commission and closing costs on the sale
    buy_cost_pct: float = 0.02           # closing costs on the purchase
    buy_extra: float = 0.0               # spend this much more (or, negative, less) than the sale brings, today's dollars; it comes from cash
    home_insurance: float = 1500.0       # homeowner's insurance there, a year, today's dollars
    home_growth: float = 0.03            # the new home's value growth a year
    cars_from_networth: bool = True      # use the cars on the Net worth page for the vehicle tax
    fl_house: dict = field(default_factory=dict)   # set on every run from the Net worth page's house: value, rate, until, start
    fl_bills: dict = field(default_factory=dict)   # set on every run: Gulf Breeze's real-estate tax and insurance by year (they stop on a sale)
    car_items: list = field(default_factory=list)  # set on every run: the Net worth page's cars as [value, rate, until, start]
    overrides: dict = field(default_factory=dict)
    compare: list = field(default_factory=lambda: ["VA", "MD", "DC", "NC", "PA"])
    rv_value_now: float = 0.0            # set from the plan's RV on every run
    rv_depreciation: float = 0.10
    rv_sold_year: int = 0


def state_rule(mv: "MoveInputs", key: str, default=None, code: str | None = None):
    code = code or mv.state
    if code == mv.state and key in (mv.overrides or {}):
        return mv.overrides[key]
    return STATE_RULES.get(code, {}).get(key, default)


def state_income_tax(code: str, mv: "MoveInputs", y: int, inc: dict, inflation: float = 0.03) -> dict:
    """One full year's state income tax as residents, for a married couple filing jointly. inc: fed_agi (federal AGI, so without muni interest),
    ss_taxable (the part of Social Security in federal AGI), ret (IRA withdrawals, Roth conversions, deferred comp, SIPP), inv (interest,
    dividends, gains and the annuity gain), muni (muni interest from other states)."""
    r = STATE_RULES.get(code, {})
    if not r or r.get("none"):
        return {"taxable": 0.0, "tax": 0.0, "local": 0.0, "total": 0.0}
    rule = lambda k, d=None: state_rule(mv, k, d, code)
    f = (1 + inflation) ** max(0, y - 2026) if r.get("idx") else 1.0          # "std": only the deduction grows (it follows the federal one)
    fb = f if r.get("idx") is True else 1.0
    fed_agi = float(inc["fed_agi"])
    n65 = 2 if y >= mv.both_65_year else 0
    age_ok = lambda age: y >= mv.both_65_year - (65 - age)          # both of you have reached that age
    agi = fed_agi + (float(inc["muni"]) * (1 - mv.muni_home_share) if rule("muni", True) else 0.0)
    ss_t = float(inc["ss_taxable"])
    ss_rule, ss_part = rule("ss"), float(rule("ss_part", 1.0))
    if ss_rule is None or fed_agi <= float(ss_rule):
        agi -= ss_t                                                   # Social Security not taxed
    elif ss_part < 1:
        agi -= ss_t * (1 - ss_part)
    ret = float(rule("ret", 0.0) or 0.0)
    excl = 0.0
    if ret and age_ok(int(rule("ret_age", 0) or 0)) and fed_agi <= float(rule("ret_limit", _INF)):
        base = float(inc["ret"]) + (float(inc["inv"]) if rule("ret_inv") else 0.0)
        excl = min(base, ret * 2)
    age = 0.0
    if r.get("age") and n65:                                          # Virginia's age deduction
        each, start = r["age"]
        age = max(0.0, each * n65 - max(0.0, (fed_agi - ss_t) - start))
    ex = float(r.get("ex", 0.0)) + float(r.get("ex65", 0.0)) * n65
    if r.get("ex_phase"):
        ex = max(0.0, ex - max(0.0, fed_agi - r["ex_phase"]))
    ti = max(0.0, agi - excl - age - float(r.get("std", 0.0)) * f - ex * f)
    tax = 0.0
    br = [(lo * fb, rate) for lo, rate in r["b"]]
    for i, (lo, rate) in enumerate(br):
        hi = br[i + 1][0] if i + 1 < len(br) else _INF
        if ti > lo:
            tax += (min(ti, hi) - lo) * rate
    cr = float(r.get("credit", 0.0))
    if r.get("credit_phase"):
        start, rate = r["credit_phase"]
        cr = max(0.0, cr - rate * max(0.0, fed_agi - start))
    tax = max(0.0, tax - cr)
    local = ti * float(rule("local", 0.0) or 0.0)
    return {"taxable": ti, "tax": tax, "local": local, "total": tax + local, "excluded": excl}


def move_fraction(mv: "MoveInputs", y: int) -> float:
    """The share of year y lived in the new state."""
    if not mv.active or y < mv.year:
        return 0.0
    return 1.0 if y > mv.year else (13 - min(max(int(mv.month), 1), 12)) / 12


def _item_value(it, y: int) -> float:
    """A Net worth page item ([value, rate, until, start] or its dict) at year y."""
    v, rate, until, start = (it["value"], it["rate"], it.get("until"), it.get("start", 2026)) if isinstance(it, dict) else it
    n = (min(y, int(until)) if until else y) - int(start)
    return float(v) * (1 + float(rate)) ** max(n, 0)


def gulf_breeze_value(mv: "MoveInputs", y: int) -> float:
    return _item_value(mv.fl_house, y) if mv.fl_house else 0.0


def selling(mv: "MoveInputs") -> bool:
    return mv.housing == "sell" and not mv.keep_fl


def home_purchase(mv: "MoveInputs", inflation: float) -> dict:
    """Selling Gulf Breeze in the move year and buying with the proceeds: the sale, what is left after its costs, and the price that buys."""
    n = mv.year - 2026
    sale = gulf_breeze_value(mv, mv.year)
    net = sale * (1 - mv.sell_cost_pct)
    extra = mv.buy_extra * (1 + inflation) ** n
    price = max(0.0, net + extra) / (1 + mv.buy_cost_pct)
    return {"sale": sale, "net": net, "extra": extra, "price": price}


def new_home_value(mv: "MoveInputs", y: int, inflation: float) -> float:
    if not selling(mv) or y < mv.year:
        return 0.0
    return home_purchase(mv, inflation)["price"] * (1 + mv.home_growth) ** (y - mv.year)


def move_costs(mv: "MoveInputs", y: int, inflation: float) -> dict:
    """What the move adds to (or saves from) the year's spending."""
    f = move_fraction(mv, y)
    keys = ("rent", "other", "vehicle_tax", "fl_tax", "fl_savings", "moving", "home_tax", "home_insurance", "fl_bills", "home_cash")
    if f <= 0:
        return dict({k: 0.0 for k in keys}, total=0.0)
    n = y - 2026
    sell = selling(mv)
    rent = 0.0 if sell else mv.rent_month * 12 * (1 + mv.rent_growth) ** n * f
    other = 0.0 if sell else mv.other_month * 12 * (1 + inflation) ** n * f       # one household when you sell: utilities and the like just move
    veh_rate = float(state_rule(mv, "veh", 0.0) or 0.0)
    if mv.cars_from_networth and mv.car_items:
        cars = [_item_value(it, y) for it in mv.car_items]
    else:
        cars = [mv.car_value / max(int(mv.cars), 1)] * max(int(mv.cars), 1) if mv.car_value else []
    relief = sum(0.28 * min(v, 20000.0) for v in cars) if mv.state == "VA" else 0.0      # Virginia's car tax relief (28% in Loudoun, 2025)
    rv = mv.rv_value_now * (1 - mv.rv_depreciation) ** max(n, 0) if (mv.tax_rv and not (mv.rv_sold_year and y >= mv.rv_sold_year)) else 0.0
    vehicle = 0.0 if mv.keep_fl else veh_rate / 100 * (max(0.0, sum(cars) - relief) + rv) * f
    lost_homestead = not mv.keep_fl and not sell and (y > mv.year or int(mv.month) <= 1)   # Florida looks at January 1: the homestead goes the year after you leave
    fl_tax = mv.fl_extra_tax_year * (1 + inflation) ** n if lost_homestead else 0.0
    fl_sav = mv.fl_savings_year * (1 + inflation) ** n * f
    moving = mv.moving_cost * (1 + inflation) ** n if y == mv.year else 0.0
    home_tax = home_ins = fl_bills = home_cash = 0.0
    if sell:
        prop = float(state_rule(mv, "prop", PROPERTY_TAX.get(mv.state, 1.0)) or 0.0) / 100
        home_tax = prop * new_home_value(mv, y, inflation) * f
        home_ins = mv.home_insurance * (1 + inflation) ** n * f
        fl_bills = float(mv.fl_bills.get(y, mv.fl_bills.get(str(y), 0.0)) or 0.0) * f      # Gulf Breeze's tax and insurance stop
        home_cash = home_purchase(mv, inflation)["extra"] if y == mv.year else 0.0
    tot = rent + other + vehicle + fl_tax - fl_sav + moving + home_tax + home_ins - fl_bills + home_cash
    return {"rent": rent, "other": other, "vehicle_tax": vehicle, "fl_tax": fl_tax, "fl_savings": fl_sav, "moving": moving, "home_tax": home_tax,
            "home_insurance": home_ins, "fl_bills": fl_bills, "home_cash": home_cash, "total": tot}


def state_tax_year(code: str, mv: "MoveInputs", y: int, r, inflation: float) -> tuple[float, float]:
    """(state tax, of which on the Roth conversion) for year y of the tax summary row r, counting only the part of the year lived there."""
    f = move_fraction(mv, y)
    if f <= 0 or mv.keep_fl:
        return 0.0, 0.0
    ann = float(r.annuity_gain)
    ret = float(r.roth_conversion) + float(r.rmd_target) + float(r.defcomp) + float(r.sipp) + float(r.get("draw_income", 0.0))
    inv = float(r.base_income) - float(r.tax_exempt) + ann - float(r.loss_used)
    ss_t, muni = float(r.ss_taxable), float(r.tax_exempt)
    if y == mv.year:                         # the move year: what comes in after you arrive; the annuity pays in March
        k = 1.0 if int(mv.month) <= 3 else 0.0
        inv = (inv - ann) * f + ann * k
        ret, ss_t, muni = ret * f, ss_t * f, muni * f
    inc = {"fed_agi": ret + inv + ss_t, "ss_taxable": ss_t, "ret": ret, "inv": inv, "muni": muni}
    tot = state_income_tax(code, mv, y, inc, inflation)["total"]
    conv = float(r.roth_conversion) * (f if y == mv.year else 1.0)
    if conv <= 0:
        return round(tot, 2), 0.0
    inc2 = dict(inc, fed_agi=inc["fed_agi"] - conv, ret=ret - conv)
    return round(tot, 2), round(tot - state_income_tax(code, mv, y, inc2, inflation)["total"], 2)


@dataclass
class Inputs:
    # Social Security ('Assumptions'!B17, B18, and the two COLA/inflation rows)
    ss_monthly_today: float = 4000.0
    ss_taxable_pct: float = 0.85
    ss_cola_2027: float = 0.03
    inflation: float = 0.03
    ss_start_year: int = 2034
    ss_months_in_start_year: int = 8

    # Living-cost target ('Year Setup'!B11, 'Assumptions' "Annual Core living budget from 2028")
    living_cost_2027: float = 90000.0
    living_cost_2028: float | None = None      # 2028 on its own (a second cautious year, Sep 2026); None = same as from 2029
    living_cost_from_2028: float = 75000.0
    inflate_living_from: int = 2034

    # Annuity gain by year ('Tax Summary'!D). Only 2031 is populated in the workbook.
    annuity_gain: dict = field(default_factory=lambda: {2031: 200000.0})

    # Base investment income: finalized monthly actuals (dataframe: month_end, amount)
    monthly_finalized: pd.DataFrame | None = None
    base_income_fallback: float = 40000.0   # used only until at least one month is finalized
    base_income_override: float | None = None   # set by the dashboard's what-if switch
    # v21.16: a year whose interest and dividends are known month by month (the investment income table) gives the NEXT year's base as its
    # full-year total, instead of the average of finalized months x 12. Both are derived from the entries on every run, never saved.
    base_income_by_year: dict = field(default_factory=dict)     # prior year -> full-year interest + dividends
    tax_exempt_share: dict = field(default_factory=dict)        # prior year -> share of that total that is tax-exempt muni interest
    # v21.16: the UK SIPP drawdown and a capital loss carried forward, both part of MAGI. Set from plan.meta on every run, never saved here.
    sipp_gbp_month: float = 0.0          # pounds a month, paid every month from FIRST_YEAR
    sipp_fx: float = 1.0                 # dollars per pound
    sipp_last_year: int = 0              # last year it is paid; 0 = every year of the plan
    loss_carry: float = 0.0              # capital loss carried into loss_carry_year
    loss_carry_year: int = 2027          # used up at up to $3,000 a year against other income, from this year on
    draw_income: dict = field(default_factory=dict)   # v25.35: year -> taxable income from draws to stay at the cash line (worked out on every run)
    tbill_shift: dict = field(default_factory=dict)   # v25.47: year -> interest moved to the next year by T-bills maturing in January (set on every run)
    income_proj: dict = field(default_factory=dict)   # v25.45: year -> interest and dividends projected from the after-tax balance (worked out on every run)
    qual_share: float = 0.0              # v25.45: share of taxable interest and dividends that is qualified dividends (taxed at 0/15/20%)
    early_conv_on: bool = False          # v25.43: also convert in years before the window whose income is already over the ACA limit
    early_limits: dict = field(default_factory=dict)  # year -> ACA limit (set on every run); a year with no limit is not used

    # Roth
    roth_first_year: int = 2034
    roth_last_year: int = 2042
    roth_total: float = 1000000.0    # 'ACA-IRMAA Model'!B64 (typed in workbook)

    # RMD / withdrawal target begins ('Tax Summary'!I: IF(year<2043,"",J))
    rmd_start_year: int = 2043

    defcomp: DefCompInputs = field(default_factory=DefCompInputs)
    tax: TaxParams = field(default_factory=TaxParams)
    move: MoveInputs = field(default_factory=MoveInputs)       # v25.30


# ----------------------------------------------------------------------------
# Deferred compensation  ('DefComp Schedule' A15:J170)
# ----------------------------------------------------------------------------
def defcomp_schedule(d: DefCompInputs) -> pd.DataFrame:
    months = pd.date_range("2027-01-01", "2039-12-01", freq="MS")   # 156 rows in workbook
    df = pd.DataFrame({"month": months})
    df["year"] = df.month.dt.year
    df["growth"] = np.where(df.year == 2027,
                            1 + d.growth_2027,
                            (1 + d.growth_2027) * (1 + d.growth_after) ** (df.year - 2027))
    df["s2027"] = np.where(df.year == 2027, d.stream_2027_annual * df.growth / 12, 0.0)
    df["lump2032"] = np.where(df.month == pd.Timestamp("2032-01-01"), d.lump_2032 * df.growth, 0.0)
    in_5yr = (df.month >= "2032-01-01") & (df.month <= "2036-12-01")
    df["s5yr"] = np.where(in_5yr, d.stream_2032_annual * df.growth / 12, 0.0)
    in_2034 = (df.month >= "2034-10-01") & (df.month <= "2039-09-01")
    df["s2034"] = np.where(in_2034, d.stream_2034_annual * df.growth / 12, 0.0)
    df["bucket"] = 0.0
    if d.bucket_2029 > 0 and int(d.election_code) in (1, 2, 3):
        asof = pd.Timestamp(_dt.date.fromordinal(int(d.bucket_asof_ord))) if d.bucket_asof_ord else pd.Timestamp("2026-09-19")
        yrs = lambda ts: (pd.Timestamp(ts) - asof).days / 365.25
        code, b0, r = int(d.election_code), float(d.bucket_2029), float(d.bucket_rate)
        if code == 1:
            df.loc[df.month == pd.Timestamp("2029-10-01"), "bucket"] = b0 * (1 + r) ** yrs("2029-10-15")
        else:
            if code == 3:
                pay = _dt.date.fromordinal(int(d.bucket_pay_ord)) if d.bucket_pay_ord else _dt.date(2034, 9, 9)
                df.loc[df.month == pd.Timestamp(pay.year, pay.month, 1), "bucket"] = b0 * (1 + r) ** yrs(pd.Timestamp(pay))
            else:
                b34 = b0 * (1 + r) ** yrs("2034-10-01")
                # five yearly steps: each October the balance is divided by the years left; it keeps earning r
                g, bal, pay, a = (1 + r) ** (1 / 12), b34, [], 0.0
                for i in range(60):
                    if i % 12 == 0:
                        a = bal / (5 - i // 12)
                    bal *= g
                    m = a / 12 if i < 59 else bal
                    bal -= m
                    pay.append(m)
                df.loc[(df.month >= "2034-10-01") & (df.month <= "2039-09-01"), "bucket"] = pay
    df["gross"] = df[["s2027", "lump2032", "s5yr", "s2034", "bucket"]].sum(axis=1)
    df["withholding"] = df.gross * d.withholding_rate
    df["net"] = df.gross - df.withholding
    return df


def defcomp_annual(sched: pd.DataFrame) -> pd.DataFrame:
    return sched.groupby("year")[["gross", "withholding", "net"]].sum()


# ----------------------------------------------------------------------------
# Base investment income  ('Tax Summary'!B  -- the LET formula)
# ----------------------------------------------------------------------------
def base_investment_income(monthly_finalized: pd.DataFrame | None, years: list[int],
                           initial: float = 0.0, by_year: dict | None = None) -> tuple[pd.Series, dict]:
    """
    Workbook rule: for each plan year Y, look at FINALIZED months of year Y-1.
      n > 0  -> annualise:  sum * 12 / n
      n == 0 -> carry forward the previous row's value (first row falls back to 0)
    Returns (series by year, {prior_year: n_finalized_months}) so the UI can warn
    when the estimate rests on very few months.
    v21.16: when by_year holds the prior year (its full-year interest + dividends from the investment income table), that total is the base.
    """
    out, counts, prev = {}, {}, float(initial)
    m = monthly_finalized
    for y in years:
        py = y - 1
        if by_year and py in by_year:
            counts[py] = 12
            out[y] = prev = float(by_year[py])
            continue
        if m is not None and len(m):
            sel = m[pd.to_datetime(m.month_end).dt.year == py]
            n, total = len(sel), float(sel.amount.sum())
        else:
            n, total = 0, 0.0
        counts[py] = n
        val = total * 12 / n if n > 0 else prev
        out[y], prev = val, val
    return pd.Series(out, name="base_invest_income"), counts


# ----------------------------------------------------------------------------
# Living cost target and Social Security  ('Tax Summary'!J, K, L, M)
# ----------------------------------------------------------------------------
def living_cost_target(inp: Inputs, years: list[int]) -> pd.Series:
    out, prev = {}, None
    for y in years:
        if y == FIRST_YEAR:
            v = inp.living_cost_2027
        elif y == 2028 and inp.living_cost_2028 is not None:
            v = inp.living_cost_2028
        elif y < inp.inflate_living_from:
            v = inp.living_cost_from_2028
        else:
            v = _excel_round(prev * (1 + inp.inflation))
        out[y], prev = v, v
    return pd.Series(out, name="living_cost")


def _excel_round(x: float) -> float:
    """Excel ROUND(x,0) rounds half away from zero (Python's round() rounds half to even)."""
    return float(np.floor(abs(x) + 0.5) * np.sign(x))


def social_security_gross(inp: Inputs, years: list[int]) -> pd.Series:
    out = {}
    for y in years:
        if y < inp.ss_start_year:
            out[y] = 0.0
        else:
            months = inp.ss_months_in_start_year if y == inp.ss_start_year else 12
            out[y] = (inp.ss_monthly_today * months * (1 + inp.ss_cola_2027)
                      * (1 + inp.inflation) ** (y - 2027))
    return pd.Series(out, name="ss_gross")


# ----------------------------------------------------------------------------
# Federal tax  ('Tax Summary'!G, MFJ)
# ----------------------------------------------------------------------------
def federal_tax(magi: float, base_income: float, year: int, p: TaxParams, tax_exempt: float = 0.0, qualified: float = 0.0) -> float:
    """
    v21.16: tax_exempt (muni interest) is part of MAGI for the ACA but is not taxed, so it comes off both the income taxed and the
    net investment income before the brackets and NIIT are applied.
    10/12/22/24% brackets on (MAGI - standard deduction), plus NIIT of 3.8% on
    MIN(base investment income, MAGI over $250k). The workbook's 24% bracket has no
    cap (fine for the MAGI range in this plan); replicated as-is.
    """
    magi, base_income = magi - tax_exempt, base_income - tax_exempt
    f = (1 + p.index_rate) ** (year - BASE_TAX_YEAR) if p.index_brackets else 1.0
    std, w10, w12, w22, top = (p.std_deduction * f, p.width_10 * f, p.width_12 * f,
                               p.width_22 * f, p.top_start * f)
    ti = magi - std
    q = min(max(qualified, 0.0), max(ti, 0.0))              # v25.45: qualified dividends sit on top, at 0/15/20%
    oti = ti - q
    tax = (0.10 * min(max(oti, 0), w10)
           + 0.12 * min(max(oti - w10, 0), w12)
           + 0.22 * min(max(oti - w10 - w12, 0), w22)
           + 0.24 * max(oti - top, 0))
    if q > 0:
        cg0, cg15 = 98900.0 * f, 613700.0 * f
        at0 = max(0.0, min(q, cg0 - max(oti, 0.0)))
        at15 = max(0.0, min(q - at0, cg15 - max(oti, 0.0) - at0))
        tax += 0.15 * at15 + 0.20 * (q - at0 - at15)
    tax += p.niit_rate * min(base_income, max(0.0, magi - p.niit_threshold))
    return tax


# ---- a full-year federal tax forecast (v21.17): the year in progress, from your actual figures ------------------------------------------
# Published 2026 figures for married filing jointly (Rev. Proc. 2025-32, after the 2025 tax act). Law, not personal data.
TAX_LAW = {2026: {"std": 32200.0,
                  "brackets": [(24800.0, 0.10), (100800.0, 0.12), (211400.0, 0.22), (403550.0, 0.24), (512450.0, 0.32), (768700.0, 0.35), (float("inf"), 0.37)],
                  "cg0": 98900.0, "cg15": 613700.0, "niit_threshold": 250000.0, "niit_rate": 0.038, "loss_limit": 3000.0}}


def _ordinary_tax(ti: float, brackets) -> float:
    tax, lo = 0.0, 0.0
    for hi, rate in brackets:
        if ti <= lo:
            break
        tax += (min(ti, hi) - lo) * rate
        lo = hi
    return tax


def year_tax_forecast(year: int, f: dict) -> dict:
    """Federal tax for one year from its income lines, the way the return works it out (married filing jointly, standard deduction):
      - capital gains: short- and long-term are netted; a net loss offsets other income up to $3,000, the rest carries forward
      - qualified dividends and net long-term gain are taxed at 0/15/20% (Schedule D worksheet), stacked on top of ordinary income
      - the 3.8% net investment income tax on the lesser of investment income and income over $250,000
    f holds: wages, defcomp, sipp, other_ordinary, interest_ordinary (taxable interest + non-qualified dividends), qualified_div, tax_exempt,
    st_net, lt_net. Deferred comp, wages and the SIPP are not investment income for the 3.8% tax; interest, dividends and gains are."""
    L = TAX_LAW.get(year) or TAX_LAW[max(TAX_LAW)]
    g = lambda k: float(f.get(k) or 0.0)
    st_, lt_ = g("st_net"), g("lt_net")
    net_cg = st_ + lt_
    cg_allowed = net_cg if net_cg >= 0 else max(net_cg, -L["loss_limit"])
    carry = 0.0 if net_cg >= 0 else -net_cg - L["loss_limit"] if -net_cg > L["loss_limit"] else 0.0
    # the part of the gain taxed at the lower rates: net long-term gain less any net short-term loss (a net short-term gain is ordinary)
    pref_gain = max(0.0, min(lt_, lt_ + st_)) if net_cg > 0 else 0.0
    ordinary_in = g("wages") + g("defcomp") + g("sipp") + g("other_ordinary") + g("interest_ordinary")
    agi = ordinary_in + g("qualified_div") + cg_allowed
    taxable = max(0.0, agi - L["std"])
    pref = min(taxable, pref_gain + g("qualified_div"))
    ord_ti = taxable - pref
    ord_tax = _ordinary_tax(ord_ti, L["brackets"])
    at0 = max(0.0, min(pref, L["cg0"] - ord_ti))
    at15 = max(0.0, min(pref - at0, L["cg15"] - ord_ti - at0))
    at20 = pref - at0 - at15
    cg_tax = 0.15 * at15 + 0.20 * at20
    regular = min(ord_tax + cg_tax, _ordinary_tax(taxable, L["brackets"]))
    nii = g("interest_ordinary") + g("qualified_div") + max(cg_allowed, 0.0) + min(cg_allowed, 0.0)
    niit = L["niit_rate"] * max(0.0, min(nii, agi - L["niit_threshold"]))
    return {"ordinary_income": ordinary_in, "qualified_div": g("qualified_div"), "cg_allowed": cg_allowed, "carryover": carry, "agi": agi,
            "std": L["std"], "taxable": taxable, "ordinary_taxable": ord_ti, "ord_tax": ord_tax, "pref": pref, "at0": at0, "at15": at15, "at20": at20,
            "cg_tax": cg_tax, "regular": regular, "nii": nii, "niit": niit, "total": regular + niit, "tax_exempt": g("tax_exempt"),
            "marginal": next(r for hi, r in L["brackets"] if ord_ti < hi)}


# ----------------------------------------------------------------------------
# Roth levelling  ('ACA-IRMAA Model'!B65, D73:D81)
# ----------------------------------------------------------------------------
def level_conversions(non_roth: np.ndarray, total: float) -> tuple[np.ndarray, float, bool]:
    """
    Choose conversions so MAGI is the same in every conversion year:
        target = (total + sum(non_roth)) / n ;  conversion = target - non_roth
    Excel stops there and shows FAIL if any conversion is negative. Here a year whose
    non-Roth MAGI already exceeds the target gets zero and is dropped, then the rest
    are re-levelled (water-filling). Returns (conversions, target, clamped_flag).
    When nothing is clamped the result is identical to Excel.
    """
    non_roth = np.asarray(non_roth, dtype=float)
    active = np.ones(len(non_roth), dtype=bool)
    clamped = False
    while active.any():
        target = (total + non_roth[active].sum()) / active.sum()
        conv = np.where(active, target - non_roth, 0.0)
        neg = active & (conv < -1e-9)
        if not neg.any():
            return conv, float(target), clamped
        active &= ~neg
        clamped = True
    return np.zeros(len(non_roth)), float("nan"), True


# ----------------------------------------------------------------------------
# Tax Summary table  ('Tax Summary'!A1:R25)
# ----------------------------------------------------------------------------
CAP_LOSS_LIMIT = 3000.0      # the yearly cap on a net capital loss against other income (married filing jointly)


def run_tax_summary(inp: Inputs) -> tuple[pd.DataFrame, dict]:
    years = YEARS
    dc_year = defcomp_annual(defcomp_schedule(inp.defcomp)).reindex(years).fillna(0.0)
    base, month_counts = base_investment_income(inp.monthly_finalized, years, inp.base_income_fallback, inp.base_income_by_year)
    if inp.base_income_override is not None:
        base = pd.Series({y: float(inp.base_income_override) for y in years}, name="base_invest_income")
    elif inp.income_proj:                                   # v25.45: income grows with the after-tax investments that pay it
        base = pd.Series({y: float(inp.income_proj.get(y, inp.income_proj.get(str(y), base[y]))) for y in years}, name="base_invest_income")
    # tax-exempt share of the base: from the latest prior year that has one, carried forward like the base itself
    share, sh = {}, 0.0
    for y in years:
        sh = float(inp.tax_exempt_share.get(y - 1, sh))
        share[y] = sh
    ss = social_security_gross(inp, years)

    df = pd.DataFrame(index=pd.Index(years, name="year"))
    df["base_income"] = base
    df["tax_exempt"] = [round(float(base[y]) * share[y], 2) for y in years]     # of which muni interest: in MAGI, not taxed
    for y_, amt_ in (inp.tbill_shift or {}).items():        # v25.47: T-bills maturing next January -- the year's interest is taxed a year later
        y_ = int(y_)
        if y_ in df.index and y_ + 1 in df.index and amt_ > 0:
            df.loc[y_, "base_income"] -= float(amt_)
            df.loc[y_ + 1, "base_income"] += float(amt_)
    df["defcomp"] = dc_year.gross
    df["annuity_gain"] = [inp.annuity_gain.get(y, 0.0) for y in years]
    df["ss_gross"] = ss
    df["ss_taxable"] = ss * inp.ss_taxable_pct
    df["sipp"] = [float(inp.sipp_gbp_month) * 12 * float(inp.sipp_fx) if (not inp.sipp_last_year or y <= inp.sipp_last_year) else 0.0 for y in years]
    left, used = float(inp.loss_carry), []
    for y in years:                                     # a net capital loss offsets other income at up to $3,000 a year until used up
        u = min(CAP_LOSS_LIMIT, left) if y >= inp.loss_carry_year and left > 0 else 0.0
        used.append(round(u, 2)); left -= u
    df["loss_used"] = used
    df["draw_income"] = [float(inp.draw_income.get(y, inp.draw_income.get(str(y), 0.0)) or 0.0) for y in years]   # v25.35
    df["other_magi"] = df.sipp - df.loss_used + df.draw_income   # in MAGI alongside the rest (and in the income taxed)
    df["living_cost"] = living_cost_target(inp, years)
    df["withholding"] = dc_year.withholding
    df["defcomp_net"] = dc_year.net

    # Roth levelling over the conversion window
    win = (df.index >= inp.roth_first_year) & (df.index <= inp.roth_last_year)
    non_roth = (df.base_income + df.defcomp + df.annuity_gain + df.ss_taxable + df.other_magi)[win].to_numpy()
    conv, target, clamped = level_conversions(non_roth, inp.roth_total)
    df["roth_conversion"] = 0.0
    df.loc[win, "roth_conversion"] = conv

    df["rmd_target"] = np.where(df.index >= inp.rmd_start_year, df.living_cost, 0.0)
    df["early_conversion"] = 0.0
    df["aca_lost"] = False                                  # v25.45: income over the ACA limit before Medicare: no subsidy that year
    for y in df.index:
        lim = inp.early_limits.get(y, inp.early_limits.get(str(y)))
        if lim and y < inp.roth_first_year:
            r_ = df.loc[y]
            df.loc[y, "aca_lost"] = bool(float(r_.base_income + r_.defcomp + r_.annuity_gain + r_.ss_taxable + r_.other_magi + r_.rmd_target) > float(lim))
    if inp.early_conv_on:                                   # v25.43: the subsidy is lost anyway, so fill the year to the top of the 22% bracket
        p_ = inp.tax
        for y in df.index:
            lim = inp.early_limits.get(y, inp.early_limits.get(str(y)))
            if y >= inp.roth_first_year or not lim:
                continue
            r_ = df.loc[y]
            magi0 = float(r_.base_income + r_.defcomp + r_.annuity_gain + r_.ss_taxable + r_.other_magi + r_.rmd_target)
            if magi0 <= float(lim):
                continue
            f_ = (1 + p_.index_rate) ** (y - BASE_TAX_YEAR) if p_.index_brackets else 1.0
            top22 = (p_.width_10 + p_.width_12 + p_.width_22) * f_ + p_.std_deduction * f_ + float(r_.tax_exempt)
            df.loc[y, "early_conversion"] = round(max(0.0, top22 - magi0), 2)
    df["roth_conversion"] = df.roth_conversion + df.early_conversion
    df["total_magi"] = (df.base_income + df.defcomp + df.annuity_gain
                        + df.roth_conversion + df.rmd_target + df.ss_taxable + df.other_magi)
    df["fed_tax"] = [federal_tax(m, b, y, inp.tax, te, (b - te) * inp.qual_share)
                     for y, m, b, te in zip(df.index, df.total_magi, df.base_income, df.tax_exempt)]

    # v25.30: a move -- the new state's income tax and the move's running costs, from the month you move
    mv = inp.move
    st_tax, st_roth, mcost = [], [], []
    for y in df.index:
        t_, rt_ = state_tax_year(mv.state, mv, y, df.loc[y], inp.inflation)
        st_tax.append(t_); st_roth.append(rt_)
        mcost.append(round(move_costs(mv, y, inp.inflation)["total"], 2))
    df["state_tax"] = st_tax
    df["state_tax_roth"] = st_roth          # of which, the Virginia tax on that year's Roth conversion
    df["move_cost"] = mcost

    df["net_living_after_ss"] = np.maximum(0, df.living_cost - df.ss_gross)
    df["tax_due_after_wh"] = np.maximum(df.fed_tax - df.withholding, 0)
    df["excess_wh"] = np.maximum(df.withholding - df.fed_tax, 0)
    df["refund_from_prior"] = df.excess_wh.shift(1).fillna(0.0)
    df["net_tax_cash"] = df.tax_due_after_wh - df.refund_from_prior

    info = {"roth_target_magi": target, "roth_clamped": clamped,
            "finalized_months_by_prior_year": month_counts}
    return df, info


# ============================================================================
# SLICE 2 -- ACA and IRMAA   ('ACA-IRMAA Model' sheet)
# ============================================================================
IRMAA_BASE_YEAR = 2026


@dataclass
class IrmaaParams:
    """2026 MFJ IRMAA tiers and monthly per-person surcharges (Part B, Part D)."""
    tier_edges_2026: tuple = (218000.0, 274000.0, 342000.0, 410000.0)
    surcharges: tuple = ((81.2, 14.5), (202.9, 37.5), (324.6, 60.4), (446.3, 83.3))
    persons: int = 2
    months: int = 12                  # workbook multiplies by 24 = 2 persons x 12 months
    ceiling_2026: float = 274000.0    # 'Assumptions'!B20  (upper edge of Tier 1)
    index_rate: float = 0.03
    index_tier_edges: bool = False    # False = replicate Excel (tier labels/costs use flat 2026 edges)
    index_surcharges: bool = False    # False = replicate Excel (surcharge $ held at 2026 levels)
    # NOTE: the workbook ALWAYS indexes the Tier 1 ceiling ('20xx Plan'!B4); only the
    # tier labels and surcharge costs on the ACA-IRMAA sheet stay on flat 2026 edges.


@dataclass
class AcaParams:
    """ACA subsidy monitoring. limit_by_year = 400% of the applicable poverty guideline."""
    limit_by_year: dict = field(default_factory=lambda: {y: (84600.0 if y == 2026 else 86560.0) for y in range(2026, 2034)})
    warning_target: float = 70000.0    # 'Assumptions'!B84 in-year early-warning line
    year_end_buffer: float = 5000.0    # convert only up to (limit - buffer) at year end
    subsidy_per_year: float = 15000.0  # 'ACA-IRMAA Model'!B34:C34 (all-or-nothing in the workbook)


@dataclass
class AcaIrmaaInputs:
    # 'ACA-IRMAA Model'!C71:C81 -- the prior baseline Roth schedule (typed in the workbook)
    prior_baseline_roth: dict = field(default_factory=lambda: {
        2032: 0, 2033: 0, 2034: 100000, 2035: 100000, 2036: 100000, 2037: 100000,
        2038: 100000, 2039: 100000, 2040: 100000, 2041: 100000, 2042: 100000})
    niit_base_proxy: float = 56000.0   # the sheet's tax proxy uses a flat $56,000 NIIT base
    irmaa: IrmaaParams = field(default_factory=IrmaaParams)
    aca: AcaParams = field(default_factory=AcaParams)


TIER_LABELS = ["Base", "Tier 1", "Tier 2", "Tier 3", "Tier 4+"]


def _edge_factor(year: int, p: IrmaaParams) -> float:
    return (1 + p.index_rate) ** (year - IRMAA_BASE_YEAR) if p.index_tier_edges else 1.0


def irmaa_tier(magi: float, year: int, p: IrmaaParams) -> int:
    """0 = Base (no surcharge) ... 4 = Tier 4+."""
    f = _edge_factor(year, p)
    for i, edge in enumerate(p.tier_edges_2026):
        if magi <= edge * f:
            return i
    return 4


def irmaa_cost(magi: float, year: int, p: IrmaaParams) -> float:
    """Annual household surcharge (Part B + Part D) for the income level."""
    t = irmaa_tier(magi, year, p)
    if t == 0:
        return 0.0
    part_b, part_d = p.surcharges[t - 1]
    f = (1 + p.index_rate) ** (year - IRMAA_BASE_YEAR) if p.index_surcharges else 1.0
    return (part_b + part_d) * p.persons * p.months * f


def irmaa_ceiling(year: int, p: IrmaaParams) -> float:
    """Tier 1 ceiling proxy for an income year ('20xx Plan'!B4 = 274,000 x 1.03^(year-2026))."""
    return p.ceiling_2026 * (1 + p.index_rate) ** (year - IRMAA_BASE_YEAR)


def run_irmaa_scenario(ts: pd.DataFrame, inp: Inputs, ai: AcaIrmaaInputs) -> tuple[pd.DataFrame, dict]:
    """
    'ACA-IRMAA Model' rows 70-81 (flat-MAGI scenario) and summary cells E61:E69, H61:H65.
    ts is the output of run_tax_summary (slice 1).
    """
    yrs = list(range(2032, 2043))
    d = pd.DataFrame(index=pd.Index(yrs, name="year"))
    d["non_roth_magi"] = (ts.base_income + ts.defcomp + ts.annuity_gain + ts.ss_taxable + ts.other_magi).loc[yrs]
    d["baseline_roth"] = [float(ai.prior_baseline_roth.get(y, 0)) for y in yrs]
    d["adopted_roth"] = ts.roth_conversion.loc[yrs]
    d["adopted_magi"] = d.non_roth_magi + d.adopted_roth
    d["tier"] = [TIER_LABELS[irmaa_tier(m, y, ai.irmaa)] for y, m in zip(yrs, d.adopted_magi)]
    d["baseline_irmaa"] = [irmaa_cost(m, y, ai.irmaa) for y, m in
                           zip(yrs, d.non_roth_magi + d.baseline_roth)]
    d["adopted_irmaa"] = [irmaa_cost(m, y, ai.irmaa) for y, m in zip(yrs, d.adopted_magi)]
    d["baseline_tax"] = [federal_tax(m, ai.niit_base_proxy, y, inp.tax) for y, m in
                         zip(yrs, d.non_roth_magi + d.baseline_roth)]
    d["adopted_tax"] = [federal_tax(m, ai.niit_base_proxy, y, inp.tax) for y, m in
                        zip(yrs, d.adopted_magi)]
    d["annual_savings"] = (d.baseline_irmaa - d.adopted_irmaa) + (d.baseline_tax - d.adopted_tax)
    d["ceiling"] = [irmaa_ceiling(y, ai.irmaa) for y in yrs]
    d["ceiling_headroom"] = d.ceiling - d.adopted_magi

    win = d.index >= inp.roth_first_year
    s = {}
    s["baseline_roth_total"] = d.baseline_roth.sum()              # E61
    s["adopted_roth_total"] = d.adopted_roth.sum()                # E62
    s["total_difference"] = s["adopted_roth_total"] - s["baseline_roth_total"]   # E63
    s["baseline_irmaa_total"] = d.baseline_irmaa.sum()            # E64
    s["adopted_irmaa_total"] = d.adopted_irmaa.sum()              # E65
    s["irmaa_savings"] = s["baseline_irmaa_total"] - s["adopted_irmaa_total"]    # E66
    s["baseline_tax_total"] = d.baseline_tax.sum()                # E67
    s["adopted_tax_total"] = d.adopted_tax.sum()                  # E68
    s["net_savings"] = (s["baseline_tax_total"] - s["adopted_tax_total"]) + s["irmaa_savings"]  # E69
    s["target_magi"] = d.loc[win, "adopted_magi"].iloc[0]         # B65
    s["ceiling_2034"] = irmaa_ceiling(inp.roth_first_year, ai.irmaa)   # B61
    s["headroom_at_target"] = s["ceiling_2034"] - s["target_magi"]     # B66
    # Constraint checks (Excel H61:H65). Excel compares every year to the 2034 ceiling.
    s["chk_magi_under_2034_ceiling"] = bool(d.loc[win, "adopted_magi"].max() <= s["ceiling_2034"])
    s["chk_2032_zero"] = bool(d.loc[2032, "adopted_roth"] == 0)
    s["chk_2033_zero"] = bool(d.loc[2033, "adopted_roth"] == 0)
    s["chk_all_nonneg"] = bool(d.adopted_roth.min() >= 0)
    s["chk_total_preserved"] = bool(abs(s["total_difference"]) < 1)
    # New (per-year ceiling, income-year indexing): every year against ITS OWN ceiling
    s["chk_magi_under_own_ceiling"] = bool((d.loc[win, "ceiling_headroom"] >= 0).all())
    return d, s


# ---- ACA monitoring -------------------------------------------------------
def aca_limit(year: int, a: AcaParams) -> float:
    return a.limit_by_year[year]


def aca_year_status(total_magi: float, year: int, a: AcaParams) -> dict:
    """Planned annual MAGI vs the subsidy limit (Plan tab rows 4 and the ACA benefit test)."""
    lim = aca_limit(year, a)
    return {"limit": lim, "magi": total_magi, "headroom": lim - total_magi,
            "over_limit": total_magi > lim, "over_warning": total_magi > a.warning_target}


def aca_benefit_paired(magi_first: float, magi_second: float, first_year: int, a: AcaParams) -> float:
    """Workbook 'ACA-IRMAA Model'!E5: benefit only if BOTH 2032 and 2033 are under the limit."""
    ok = magi_first <= aca_limit(first_year, a) and magi_second <= aca_limit(first_year + 1, a)
    return 2 * a.subsidy_per_year if ok else 0.0


def aca_benefit_by_year(magi: float, year: int, a: AcaParams) -> float:
    """New per-year test: each year stands on its own."""
    return a.subsidy_per_year if magi <= aca_limit(year, a) else 0.0


def aca_year_end_window(year: int, ytd_finalized_magi: float, remaining_forecast_magi: float,
                        one_time_items: float, a: AcaParams, year_adjust: float = 0.0) -> dict:
    """
    Year-end conversion window. Every component is returned so the screen can show
    exactly how the number was built:
        capacity = max(0, limit - buffer - (finalized YTD + forecast rest of year + one-time items))
    """
    lim = aca_limit(year, a)
    projected = ytd_finalized_magi + remaining_forecast_magi + one_time_items + year_adjust
    ceiling = lim - a.year_end_buffer
    return {"limit": lim, "buffer": a.year_end_buffer, "conversion_ceiling": ceiling,
            "ytd_finalized": ytd_finalized_magi, "remaining_forecast": remaining_forecast_magi,
            "one_time_items": one_time_items, "year_adjust": year_adjust, "projected_year_end_magi": projected,
            "capacity": max(0.0, ceiling - projected)}


# ============================================================================
# SLICE 3 -- Cash flow and liquidity   ('Cash Flow' sheet)
# ============================================================================
@dataclass
class CashFlowInputs:
    # Opening cash bridge ('Assumptions'!B39)
    wells_savings: float = 400000.0
    wells_money_market: float = 100000.0
    tax_reserve_remaining_2026: float = 20000.0
    expense_transfers_remaining_2026: float = 15000.0
    # Planned releases from other buckets into cash, by year ('Cash Flow'!C13:C36, all zero today)
    money_market_release: dict = field(default_factory=dict)
    # One-off inflows
    annuity_cash: float = 700000.0        # gross liquidation proceeds
    annuity_year: int = 2031
    rv_current_value: float = 60000.0
    rv_depreciation: float = 0.10         # 2026 and 2027, then sold March 2028
    rv_sale_year: int = 2028
    # Spending buckets outside Core
    travel_2027: float = 30000.0
    travel_2028_2029: float = 20000.0
    travel_from_2030: float = 10000.0
    medical_cost: float = 15000.0
    medical_years: tuple = (2031, 2032)
    medical_extra: dict = field(default_factory=dict)   # year -> extra unsubsidized cost for a single year (the plan sets 2029 when the 2013 to 2015 lump is taken then)
    cash_growth_rate: float = 0.035       # applied to BEGINNING cash only, as in the workbook
    min_ending_cash: float = 0.0          # warn only when ending cash falls below this
    cash_floor: float = 0.0               # v25.33: when set, cash never ends a year below this: the rest is drawn from investments (0 = off)
                                          # v25.35: set on every run from the Cash flow safety line, so the whole plan follows it
    draw_order: list = field(default_factory=lambda: ["brokerage", "sipp", "ira"])   # v25.35: where draws come from, first to last
    brokerage_gain_share: float = 0.0     # share of a brokerage sale that is taxable gain (0: selling muni bonds at about cost)
    live_opening: dict = field(default_factory=dict)   # v21.20: {year: cash at the start of that year, built from today's Wells balances}; never saved
    live_stale: bool = False                           # v21.21: built from the last balances read, the fetch not being at hand

    @property
    def opening_cash(self) -> float:
        return (self.wells_savings + self.wells_money_market
                - self.tax_reserve_remaining_2026 - self.expense_transfers_remaining_2026)

    @property
    def rv_sale_proceeds(self) -> float:
        return self.rv_current_value * (1 - self.rv_depreciation) ** 2

    def travel(self, year: int) -> float:
        if year == 2027:
            return self.travel_2027
        if year in (2028, 2029):
            return self.travel_2028_2029
        return self.travel_from_2030


def run_cash_flow(ts: pd.DataFrame, cf: CashFlowInputs) -> tuple[pd.DataFrame, dict]:
    """
    Year-by-year spendable cash (savings + money market; ETFs and brokerage excluded).
        ending = beginning + releases + inflows + RMD/withdrawal - uses + growth
        uses   = travel + net core cost after Social Security + tax due after withholding + medical
    """
    years = list(ts.index)
    rows, beg = [], cf.opening_cash
    live = {int(k_): float(v) for k_, v in (cf.live_opening or {}).items()}
    for y in years:
        if y in live:                                                 # the year's start is known from your actual balances
            beg = live[y]
        t = ts.loc[y]
        release = float(cf.money_market_release.get(y, 0.0))
        inflows = (t.defcomp_net
                   + (cf.annuity_cash if y == cf.annuity_year else 0.0)
                   + (cf.rv_sale_proceeds if y == cf.rv_sale_year else 0.0)
                   + t.refund_from_prior)
        rmd = t.rmd_target
        available = beg + release + inflows + rmd                     # col G (excludes Social Security)
        travel = cf.travel(y)
        medical = (cf.medical_cost if y in cf.medical_years else 0.0) + float(cf.medical_extra.get(y, 0.0))
        if bool(t.get("aca_lost", False)):                    # v25.45: a year over the ACA limit pays full price, whatever the list says
            medical = max(medical, float(cf.medical_cost))
        state = float(t.get("state_tax", 0.0)) + float(t.get("move_cost", 0.0))         # v25.30: zero unless a move is in the plan
        uses = travel + t.net_living_after_ss + t.tax_due_after_wh + medical + state   # col L
        growth = max(0.0, beg) * cf.cash_growth_rate                  # col O
        end = available + growth - uses                               # col M
        draw = max(0.0, cf.cash_floor - end) if cf.cash_floor > 0 else 0.0     # v25.33: topped up from investments to stay at the floor
        end += draw
        rows.append({"year": y, "beginning_cash": beg, "mm_release": release, "inflows": inflows,
                     "rmd_withdrawal": rmd, "ss_gross": t.ss_gross, "available_before_ss": available,
                     "core_living": t.living_cost, "travel": travel, "net_core_after_ss": t.net_living_after_ss,
                     "tax_due": t.tax_due_after_wh, "medical": medical, "state_tax": float(t.get("state_tax", 0.0)),
                     "move_cost": float(t.get("move_cost", 0.0)), "total_uses": uses,
                     "growth": growth, "ending_cash": end, "drawdown": draw,
                     "status": "SHORTFALL" if end < cf.min_ending_cash else "OK"})
        beg = end
    df = pd.DataFrame(rows).set_index("year")

    short = df.index[df.status == "SHORTFALL"]
    s = {"opening_cash": float(df.beginning_cash.iloc[0]), "opening_live": bool(live), "opening_stale": bool(live) and bool(cf.live_stale),
         "first_shortfall_year": int(short[0]) if len(short) else None,
         "max_cumulative_shortfall": max(0.0, -float(df.ending_cash.min())),
         "total_releases": float(df.mm_release.sum()),
         "ending_cash_final_year": float(df.ending_cash.iloc[-1]),
         "lowest_ending_cash": float(df.ending_cash.min()),
         "lowest_ending_cash_year": int(df.ending_cash.idxmin()),
         "total_drawdown": float(df.drawdown.sum()),
         "first_drawdown_year": int(df.index[df.drawdown > 0.5][0]) if (df.drawdown > 0.5).any() else None}
    # 2031 pre-annuity liquidity bridge (rows 43-47): two months of 2031 uses before proceeds arrive
    y0 = cf.annuity_year
    s["bridge_prior_year_end"] = float(df.loc[y0 - 1, "ending_cash"])
    s["bridge_two_months_uses"] = float(df.loc[y0, "total_uses"]) * 2 / 12
    s["bridge_low_point"] = s["bridge_prior_year_end"] - s["bridge_two_months_uses"]
    # 2027-2031 reconciliation (rows 61-68). Excel's inflow sum spans columns D:F (inflows, RMD, SS gross).
    span = df.loc[2027:2031]
    s["recon_inflows"] = float((span.inflows + span.rmd_withdrawal + span.ss_gross).sum())
    s["recon_growth"] = float(span.growth.sum())
    s["recon_uses"] = float(span.total_uses.sum())
    s["recon_dec_2031_ending"] = (float(df.loc[2027, "beginning_cash"]) + s["recon_inflows"] + s["recon_growth"] - s["recon_uses"])
    return df, s


# ============================================================================
# SLICE 4 -- Portfolio forecast, RMD check, derived Roth total, conversion capacity
# ('Portfolio Forecast' sheet; derivation logic is new)
# ============================================================================
@dataclass
class PortfolioInputs:
    # Opening balances ('Portfolio Integration'!B9:B12, taken from the latest completed month)
    taxable_liquid: float = 1500000.0
    pretax: float = 2000000.0
    annuities: float = 500000.0
    hsa: float = 20000.0
    growth: float = 0.065                   # v25.42: the after-tax accounts (about 65% stocks), a realistic rate; post-2031 annuities too
    growth_after: float = 0.0625            # v25.44: from shift_year (both 65), after the planned 10-15% move from stocks to bonds
    pretax_growth_after: float = 0.06
    shift_year: int = 2034
    income_yield_bump: float = 0.003        # v25.45: the bond shift raises income by about this share of the after-tax balance
    pretax_growth: float = 0.0625           # v25.42: the IRA, SIPP, deferred comp and Roth: a realistic rate for their mix (about 55% stocks,
                                            # a little below the after-tax account's 65%); conversions are sized on it
    # Annuity components used through 2031 ('Portfolio Forecast'!M)
    planeasy_balance: float = 300000.0
    planeasy_growth: float = 0.06
    wells_sp: float = 100000.0
    wells_nasdaq: float = 100000.0
    wells_target_return: float = 0.09
    wells_reset_return: float = 0.05
    annuity_special_through: int = 2031
    min_liquidity_reserve: float = 500000.0
    hsa_zero_year: int = 2028               # HSA balance falls in a straight line to zero by the end of this year (all cash from Sep 2026; about $11K left at end 2026, spent over 2027-28)
    # Split of the pre-tax bucket ('Assumptions' rows for the three accounts; they sum to `pretax`)
    ira: float = 1200000.0                 # Schwab IRA
    empower: float = 300000.0              # Empower deferred compensation
    sipp: float = 500000.0                 # MES crystallized UK SIPP


def g_after(p, y: int) -> float:
    """v25.44: the after-tax growth rate in year y (lower from the shift year, when part of the stocks move to bonds)."""
    return float(p.growth_after) if y >= int(getattr(p, "shift_year", 9999)) else float(p.growth)


def g_pre(p, y: int) -> float:
    """v25.44: the pre-tax (and Roth) growth rate in year y."""
    return float(p.pretax_growth_after) if y >= int(getattr(p, "shift_year", 9999)) else float(p.pretax_growth)


def _annuity_growth(y: int, beg: float, p: PortfolioInputs) -> float:
    if y <= p.annuity_special_through:
        planeasy = p.planeasy_balance * (1 + p.planeasy_growth) ** (y - 2027) * p.planeasy_growth
        wells = ((p.wells_sp + p.wells_nasdaq) * (1 + p.wells_target_return)
                 * (1 + p.wells_reset_return) ** max(0, y - 2028)
                 * (p.wells_target_return if y == 2027 else p.wells_reset_return))
        return planeasy + wells
    return beg * g_after(p, y)


def run_portfolio(ts: pd.DataFrame, cf_df: pd.DataFrame, cf: CashFlowInputs,
                  p: PortfolioInputs) -> pd.DataFrame:
    """Bucket balances by year. Spending and inflows come from the Cash Flow table."""
    years = list(ts.index)
    conv = ts.roth_conversion
    roth = 0.0
    rows = []
    b_tax, b_pre, b_ann = p.taxable_liquid, p.pretax, p.annuities
    for y in years:
        c = cf_df.loc[y]
        cash_beg = c.beginning_cash
        tax_growth = (max(0.0, min(b_tax, cash_beg)) * cf.cash_growth_rate
                      + max(0.0, b_tax - cash_beg) * g_after(p, y))
        inflows = c.inflows + c.rmd_withdrawal
        draw_pre = float(c.get("draw_sipp", 0.0)) + float(c.get("draw_ira", 0.0))        # v25.35: a draw from the SIPP or IRA lands in cash
        e_tax = b_tax + tax_growth + inflows - c.total_uses + draw_pre
        pre_growth = b_pre * g_pre(p, y)
        pre_out = ts.loc[y, "defcomp"] + ts.loc[y, "rmd_target"] + draw_pre
        e_pre = max(0.0, b_pre + pre_growth - conv[y] - pre_out)
        ann_growth = _annuity_growth(y, b_ann, p)
        ann_dist = cf.annuity_cash if y == cf.annuity_year else 0.0
        e_ann = max(0.0, b_ann + ann_growth - ann_dist)
        hsa = min(p.hsa, max(0.0, p.hsa * (p.hsa_zero_year - y) / max(1, p.hsa_zero_year - 2026)))     # straight line from end 2026 to zero at the end of hsa_zero_year
        roth = roth * (1 + g_pre(p, y)) + conv[y] if y != years[0] else conv[y]
        total = e_tax + e_pre + e_ann + hsa + roth
        if e_tax < 0:
            status = "Shortfall"
        elif e_tax < p.min_liquidity_reserve:
            status = "Below reserve"
        else:
            status = "OK"
        if ann_dist == 0:
            ann_check = ""
        elif b_ann + ann_growth >= ann_dist:
            ann_check = "Funded"
        else:
            ann_check = "Short"
        rows.append({"year": y, "beg_taxable": b_tax, "taxable_growth": tax_growth, "cash_inflows": inflows,
                     "cash_uses": c.total_uses, "end_taxable": e_tax, "beg_pretax": b_pre,
                     "pretax_growth": pre_growth, "roth_conversion": conv[y], "defcomp_rmd": pre_out,
                     "end_pretax": e_pre, "beg_annuity": b_ann, "annuity_growth": ann_growth,
                     "annuity_dist": ann_dist, "end_annuity": e_ann, "hsa": hsa, "total_assets": total,
                     "liquidity_status": status, "annuity_check": ann_check, "roth_balance": roth})
        b_tax, b_pre, b_ann = e_tax, e_pre, e_ann
    return pd.DataFrame(rows).set_index("year")


# ---- pre-tax bucket path only (fast; used by the solver) --------------------
def pretax_end_balance(ts: pd.DataFrame, p: PortfolioInputs, through_year: int) -> float:
    b = p.pretax
    for y in ts.index:
        if y > through_year:
            break
        b = max(0.0, b + b * g_pre(p, y) - ts.loc[y, "roth_conversion"]
                - ts.loc[y, "defcomp"] - ts.loc[y, "rmd_target"])
    return b


RMD_DIVISOR_AGE_75 = 24.6   # IRS Uniform Lifetime Table, age 75 -- confirm before relying on it


def rmd_projection(ts: pd.DataFrame, p: PortfolioInputs, eligible_share: float = 1.0,
                   divisor: float = RMD_DIVISOR_AGE_75, rmd_year: int = 2043) -> dict:
    """RMD for rmd_year = RMD-eligible share of the prior year-end pre-tax balance / divisor."""
    bal = pretax_end_balance(ts, p, rmd_year - 1)
    rmd = bal * eligible_share / divisor
    return {"pretax_balance": bal, "eligible_share": eligible_share, "divisor": divisor, "rmd": rmd}


def implied_eligible_share(ts: pd.DataFrame, p: PortfolioInputs, target: float,
                           divisor: float = RMD_DIVISOR_AGE_75, rmd_year: int = 2043) -> float:
    """What share of the pre-tax bucket must be RMD-eligible for the RMD to equal `target`?"""
    return target * divisor / pretax_end_balance(ts, p, rmd_year - 1)


def solve_roth_total(inp: Inputs, p: PortfolioInputs, target: float, eligible_share: float = 1.0,
                     divisor: float = RMD_DIVISOR_AGE_75, rmd_year: int = 2043,
                     hi: float = 6e6) -> dict:
    """
    Total 2034-2042 conversions that make the rmd_year RMD equal `target`, following the
    year-by-year balance path (each converted dollar also stops growing).
    Bisection on the total; the levelling rule allocates it across years.
    """
    def rmd_for(total: float) -> float:
        i2 = copy_inputs(inp); i2.roth_total = total
        ts, _ = run_tax_summary(i2)
        return rmd_projection(ts, p, eligible_share, divisor, rmd_year)["rmd"]

    if rmd_for(0.0) <= target:
        return {"total": 0.0, "note": "RMD already at or below target with no conversions"}
    if rmd_for(hi) > target:
        return {"total": None, "note": "target not reachable within search range"}
    lo, up = 0.0, hi
    for _ in range(60):
        mid = (lo + up) / 2
        if rmd_for(mid) > target:
            lo = mid
        else:
            up = mid
    total = (lo + up) / 2
    return {"total": total, "rmd": rmd_for(total), "note": "solved"}


def copy_inputs(inp: Inputs) -> Inputs:
    import copy
    return copy.deepcopy(inp)


def roth_capacity(ts: pd.DataFrame, inp: Inputs, ai: AcaIrmaaInputs) -> dict:
    """
    Largest 2034-2042 total whose levelled MAGI stays at or below (indexed IRMAA ceiling - buffer)
    in every year. Levelled MAGI is the same each year, so the tightest ceiling (the earliest
    year) binds. Informational only: IRA balance and cash for tax also limit conversions.
    """
    yrs = [y for y in ts.index if inp.roth_first_year <= y <= inp.roth_last_year]
    non_roth = (ts.base_income + ts.defcomp + ts.annuity_gain + ts.ss_taxable + ts.other_magi).loc[yrs]
    buffer = 5000.0
    ceilings = pd.Series({y: irmaa_ceiling(y, ai.irmaa) - buffer for y in yrs})
    binding_year = int(ceilings.idxmin())
    max_magi = float(ceilings.min())
    total = len(yrs) * max_magi - float(non_roth.sum())
    return {"capacity_total": max(0.0, total), "binding_year": binding_year,
            "max_levelled_magi": max_magi, "buffer": buffer}


# ---- account-level pre-tax paths (RMD eligibility) ---------------------------
def account_balances(ts: pd.DataFrame, p: PortfolioInputs) -> pd.DataFrame:
    """
    End-of-year balances by account. Every account grows at p.growth; Roth conversions and
    post-2042 withdrawals come out of the Schwab IRA; scheduled deferred-comp distributions come
    out of Empower; the SIPP is untouched. Their sum equals the pooled pre-tax bucket unless an
    account is exhausted (flagged in `exhausted`).
    """
    ira_b, emp_b, sipp_b = p.ira, p.empower, p.sipp
    rows, exhausted = [], False
    for y in ts.index:
        ira_b = ira_b * (1 + g_pre(p, y)) - ts.loc[y, "roth_conversion"] - ts.loc[y, "rmd_target"]
        emp_b = emp_b * (1 + g_pre(p, y)) - ts.loc[y, "defcomp"]
        sipp_b = sipp_b * (1 + g_pre(p, y))
        if ira_b < 0 or emp_b < 0:
            exhausted = True
        ira_b, emp_b = max(0.0, ira_b), max(0.0, emp_b)
        rows.append({"year": y, "ira": ira_b, "empower": emp_b, "sipp": sipp_b})
    df = pd.DataFrame(rows).set_index("year")
    df.attrs["exhausted"] = exhausted
    return df


def rmd_from_accounts(ts: pd.DataFrame, p: PortfolioInputs, eligible=("ira",),
                      divisor: float = RMD_DIVISOR_AGE_75, rmd_year: int = 2043) -> dict:
    ab = account_balances(ts, p).loc[rmd_year - 1]
    bal = float(sum(ab[a] for a in eligible))
    return {"eligible_balance": bal, "divisor": divisor, "rmd": bal / divisor,
            "ira": float(ab.ira), "empower": float(ab.empower), "sipp": float(ab.sipp)}


def solve_roth_total_accounts(inp: Inputs, p: PortfolioInputs, target: float, eligible=("ira",),
                              divisor: float = RMD_DIVISOR_AGE_75, rmd_year: int = 2043,
                              hi: float = 6e6) -> dict:
    """Total 2034-2042 conversions that make the RMD-eligible accounts' RMD equal `target`."""
    def rmd_for(total: float) -> float:
        i2 = copy_inputs(inp); i2.roth_total = total
        ts, _ = run_tax_summary(i2)
        return rmd_from_accounts(ts, p, eligible, divisor, rmd_year)["rmd"]

    if rmd_for(0.0) <= target:
        return {"total": 0.0, "note": "RMD already at or below target with no conversions"}
    if rmd_for(hi) > target:
        return {"total": None, "note": "target not reachable within search range"}
    lo, up = 0.0, hi
    for _ in range(60):
        mid = (lo + up) / 2
        lo, up = (mid, up) if rmd_for(mid) > target else (lo, mid)
    total = (lo + up) / 2
    return {"total": total, "rmd": rmd_for(total), "note": "solved"}


# ============================================================================
# SLICE 5 -- Estimated-tax payments and safe harbor
# ('Current Year Tax Payments' sheet and 'ACA-IRMAA Model' rows 42-50)
# ============================================================================

QUARTER_SHARE = 0.25


def estimated_payment_schedule(year: int, annual_forecast: float, as_of: _dt.date,
                               actual_payments: dict | None = None) -> pd.DataFrame:
    """
    Four equal installments on the IRS individual schedule (Apr 15, Jun 15, Sep 15, Jan 15 next year).
    Workbook rule: an installment is ASSUMED PAID once its due date has passed. The app replaces
    TODAY() with an explicit as_of date and lets you record the real payment, which then overrides
    the assumption. actual_payments = {"Q1": amount, ...}.
    """
    due = {"Q1": _dt.date(year, 4, 15), "Q2": _dt.date(year, 6, 15),
           "Q3": _dt.date(year, 9, 15), "Q4": _dt.date(year + 1, 1, 15)}
    start = {"Q1": _dt.date(year, 1, 1), "Q2": _dt.date(year, 4, 16),
             "Q3": _dt.date(year, 6, 16), "Q4": _dt.date(year, 9, 16)}
    rows = []
    for q in ("Q1", "Q2", "Q3", "Q4"):
        forecast = annual_forecast * QUARTER_SHARE
        recorded = (actual_payments or {}).get(q)
        if recorded is not None:
            actual, status = float(recorded), "PAID (RECORDED)"
        elif as_of >= due[q]:
            actual, status = forecast, "ASSUMED PAID"
        else:
            actual, status = 0.0, "TO BE PAID"
        rows.append({"quarter": q, "period_start": start[q], "due_date": due[q],
                     "forecast_payment": forecast, "actual_payment": actual,
                     "variance": actual - forecast, "status": status})
    return pd.DataFrame(rows).set_index("quarter")


def safe_harbor(prior_tax: float, prior_agi: float, current_tax: float, planned_payments: float,
                high_income_agi: float = 150000.0) -> dict:
    """
    Required annual payment = the LOWER of
        prior-year tax x 100% (110% if prior-year AGI > $150,000), and
        90% of this year's projected tax.
    Mirrors 'ACA-IRMAA Model' G49:J50. With no prior-year tax on file the workbook asks for it.
    """
    mult = 1.10 if prior_agi > high_income_agi else 1.00
    prior_based = prior_tax * mult
    ninety = 0.90 * current_tax
    if prior_tax == 0:
        return {"multiplier": mult, "prior_year_safe_harbor": prior_based, "ninety_pct_current": ninety,
                "required": None, "planned": planned_payments, "gap": None, "status": "ENTER PRIOR TAX"}
    required = min(prior_based, ninety)
    gap = max(0.0, required - planned_payments)
    return {"multiplier": mult, "prior_year_safe_harbor": prior_based, "ninety_pct_current": ninety,
            "required": required, "planned": planned_payments, "gap": gap,
            "status": "FUNDED" if gap == 0 else "ADDITIONAL PAYMENT"}


def safe_harbor_by_year(ts: pd.DataFrame, planned: dict | None = None) -> pd.DataFrame:
    """Safe-harbor test for every plan year after the first, using the modelled prior-year tax and AGI."""
    rows = []
    for y in ts.index[1:]:
        p = ts.loc[y - 1]
        cur = ts.loc[y]
        pl = (planned or {}).get(y, cur.fed_tax)      # workbook default: planned payments = modelled tax
        r = safe_harbor(p.fed_tax, p.total_magi, cur.fed_tax, pl)
        r["year"] = y
        r["withholding"] = cur.withholding
        # Minimum estimated payments needed once withholding (treated as timely paid) is counted
        r["min_estimated_after_withholding"] = None if r["required"] is None else max(0.0, r["required"] - cur.withholding)
        rows.append(r)
    return pd.DataFrame(rows).set_index("year")


# ============================================================================
# SLICE 6 -- Monthly MAGI monitor  ('Monthly MAGI Inputs' col Q; Plan-tab monitor rows 28-43)
# ============================================================================
MONTHLY_COLUMNS = ["wells_interest", "wells_dividends", "schwab_interest", "schwab_dividends",
                   "realized_gains", "other_brokerage", "defcomp", "annuity_gain", "roth_conversion",
                   "sipp", "ira_rmd", "taxable_ss"]


def monthly_totals(m: pd.DataFrame) -> pd.DataFrame:
    """'Monthly MAGI Inputs' columns N and O: N = interest+dividends (4 cols); O = realized gains .. taxable SS."""
    m = m.copy()
    for c in MONTHLY_COLUMNS:
        if c not in m:
            m[c] = 0.0
    m[MONTHLY_COLUMNS] = m[MONTHLY_COLUMNS].fillna(0.0)
    m["total_interest_div"] = m[["wells_interest", "wells_dividends", "schwab_interest", "schwab_dividends"]].sum(axis=1)
    m["total_other"] = m[["realized_gains", "other_brokerage", "defcomp", "annuity_gain", "roth_conversion",
                          "sipp", "ira_rmd", "taxable_ss"]].sum(axis=1)
    return m


def projected_annual_magi_runrate(m: pd.DataFrame) -> pd.Series:
    """
    Workbook rule ('Monthly MAGI Inputs'!Q): cumulative through each FINALIZED row,
        (sum(N) + sum(O) - sum(gains)) x 12 / n_finalized  +  sum(gains)
    Everything recurring is annualised; realised gains are counted once, not annualised.
    NOTE: the workbook runs this cumulatively from the first row of the table, not per calendar year.
    """
    m = monthly_totals(m)
    out, n, s_all, s_gain = [], 0, 0.0, 0.0
    for _, r in m.iterrows():
        if r["status"] != "Finalized":
            out.append(np.nan)
            continue
        n += 1
        s_all += r.total_interest_div + r.total_other
        s_gain += r.realized_gains
        out.append((s_all - s_gain) * 12 / n + s_gain)
    return pd.Series(out, index=m.index, name="projected_annual_magi")


def monthly_plan(ts: pd.DataFrame, sched: pd.DataFrame, year: int, annuity_month: int = 3,
                 roth_month: int = 12, ss_start_month: int = 5, inv_weights: dict | None = None) -> pd.Series:
    """Planned MAGI by month for `year` from the annual plan (lumps placed in the month they occur).
    v21.16: inv_weights (month -> share of the year's interest and dividends, from the investment income table) places the quarterly fund
    dividends in March, June, September and December instead of spreading investment income evenly."""
    t = ts.loc[year]
    plan = pd.Series(0.0, index=range(1, 13))
    if inv_weights and abs(sum(inv_weights.values()) - 1.0) < 1e-6:
        for mth in range(1, 13):
            plan[mth] += t.base_income * float(inv_weights.get(mth, 0.0))
    else:
        plan += t.base_income / 12                                        # steady investment income
    dc = sched[sched.year == year].set_index(sched[sched.year == year].month.dt.month).gross
    plan = plan.add(dc.reindex(range(1, 13)).fillna(0.0), fill_value=0.0)  # deferred comp, month by month
    plan[annuity_month] += t.annuity_gain
    plan[roth_month] += t.roth_conversion
    if "sipp" in t.index and t.sipp:
        plan += t.sipp / 12                                               # SIPP drawdown, monthly
    if t.ss_taxable > 0:
        first = ss_start_month if year == 2034 else 1
        months = list(range(first, 13))
        for mth in months:
            plan[mth] += t.ss_taxable / len(months)
    if t.rmd_target > 0:
        plan += t.rmd_target / 12
    return plan


def aca_monthly_monitor(ts: pd.DataFrame, sched: pd.DataFrame, monthly: pd.DataFrame, year: int,
                        a: AcaParams, one_time_items: float = 0.0, **plan_kw) -> tuple[pd.DataFrame, dict]:
    """
    Month-by-month ACA monitor. A month counts as ACTUAL only when it is marked Finalized (never merely
    because something auto-populated it); every other month uses the plan. Returns the table and a
    summary with projected year-end MAGI, headroom and the alert level.
    """
    plan = monthly_plan(ts, sched, year, **plan_kw)
    mt = monthly_totals(monthly) if len(monthly) else monthly
    rows, running = [], 0.0
    fin_actual = 0.0
    n_final = 0
    for mth in range(1, 13):
        act, is_final = None, False
        if len(mt):
            sel = mt[(pd.to_datetime(mt.month_end).dt.year == year) &
                     (pd.to_datetime(mt.month_end).dt.month == mth) & (mt.status == "Finalized")]
            if len(sel):
                is_final = True
                act = float((sel.total_interest_div + sel.total_other).sum())
        value = act if is_final else float(plan[mth])
        running += value
        n_final += is_final
        fin_actual += act if is_final else 0.0
        lim = aca_limit(year, a)
        rows.append({"month": mth, "planned": float(plan[mth]), "actual": act, "basis": "ACTUAL" if is_final else "PLAN",
                     "value_used": value, "running_magi": running, "headroom_to_limit": lim - running})
    df = pd.DataFrame(rows).set_index("month")
    remaining_plan = float(df.loc[df.basis == "PLAN", "planned"].sum())
    # v21.16: a capital loss carried over is never in a month's entries, so it counts for the year whatever is finalized
    year_adjust = -float(ts.loc[year, "loss_used"]) if "loss_used" in ts.columns and year in ts.index else 0.0
    projected = fin_actual + remaining_plan + year_adjust
    lim = aca_limit(year, a)
    with_one = projected + one_time_items          # known or expected one-time items count toward the alert
    level = ("OVER LIMIT" if with_one > lim else "EARLY WARNING" if with_one > a.warning_target else "OK")
    s = {"finalized_months": int(n_final), "finalized_actual": fin_actual, "remaining_plan": remaining_plan,
         "projected_year_end_magi": projected, "one_time_items": one_time_items,
         "projected_with_one_time": with_one, "limit": lim, "headroom": lim - with_one,
         "warning_target": a.warning_target, "alert": level, "planned_annual": float(plan.sum()) + year_adjust, "year_adjust": year_adjust}
    return df, s


# ============================================================================
# SLICE 7 -- Expenses  (monthly ledgers, 'Expense Import', 'Spending Tracker', 'Year Setup')
# ============================================================================
def _n(x) -> float:
    """Excel N(): numbers pass through, everything else (blank, text) counts as 0."""
    if isinstance(x, (int, float, np.integer, np.floating)) and not isinstance(x, bool):
        return 0.0 if pd.isna(x) else float(x)      # blank cells arrive as NaN and must count as 0
    return 0.0


def classify_ledger(led: pd.DataFrame) -> pd.DataFrame:
    """
    Adds the three classified amount columns exactly as the ledger tables do. Only RECONCILED rows count.
      Core     = debit (or minus credit when there is no debit)   [Budget Class = Core]
      One-Time = debit - credit                                   [Budget Class = One-Time]
      Excluded = debit                                            [Budget Class = Excluded]
    Expected columns: date, description, credit, debit, reconciled, budget_class (+ any others).
    """
    led = led.copy()
    credit = led["credit"].map(_n)
    debit = led["debit"].map(_n)
    rec = led["reconciled"].astype(str).str.lower().eq("yes")
    cls = led["budget_class"].astype(str).str.lower()
    # A Core line may carry a one-time portion (part of a credit card bill set aside as one-time): that part leaves Core and joins One-Time.
    split = led["ot_split"].map(_n) if "ot_split" in led.columns else pd.Series(0.0, index=led.index)
    split = pd.Series(np.where(cls == "core", np.minimum(np.maximum(split, 0.0), debit), 0.0), index=led.index)
    led["split_eff"] = split
    led["core"] = np.where(rec & (cls == "core"), np.where(debit == 0, -credit, debit - split), 0.0)
    led["one_time"] = np.where(rec & (cls == "one-time"), debit - credit, 0.0) + np.where(rec, split, 0.0)
    led["excluded"] = np.where(rec & (cls == "excluded"), debit, 0.0)
    return led


def ledger_balances(led: pd.DataFrame, opening: float) -> pd.Series:
    """Running balance: opening + cumulative credits - cumulative debits."""
    return opening + led["credit"].map(_n).cumsum() - led["debit"].map(_n).cumsum()


CARD_KEYWORDS = ("card",)   # replaced by the data file's own keywords


def monthly_control(ledgers: pd.DataFrame, year: int, card_allowance: float = 4800.0,
                    card_keywords=CARD_KEYWORDS, pending_through: int = 0) -> pd.DataFrame:
    """
    'Expense Import' rows 4-15. `ledgers` = every ledger row with an extra `ledger_month` (1-12) column
    (the sheet the row lives on). Rows are limited to dates inside `year`.
    normalized_core is a reconciled card payment counted at its real amount, same as any other Core line -- there is
    no more swap for a flat monthly allowance (that smoothing turned out to hide real dollars rather than clarify
    the pace; a one-off large purchase is handled by the separate One-Time budget instead, not by this figure).
    card_allowance and card_keywords are accepted for call-site compatibility but no longer change the result.
    """
    led = classify_ledger(ledgers)
    led = led[pd.to_datetime(led["date"]).dt.year == year]
    # pending_through: for months up to this one, a Core line already on the ledger counts while still pending, the same as once it is ticked --
    # so reconciling a bill you already knew about never moves the figures; only something new, or a different amount, does (Andrew, Sep 2026).
    rec = led["reconciled"].astype(str).str.lower().eq("yes") if len(led) else pd.Series(dtype=bool)
    if len(led):
        deb, cre = led["debit"].map(_n), led["credit"].map(_n)
        led["pending_core"] = np.where(~rec & led["budget_class"].astype(str).str.lower().eq("core"),
                                       np.where(deb == 0, -cre, deb - led["split_eff"]), 0.0)
    else:
        led["pending_core"] = []
    rows = []
    for m in range(1, 13):
        x = led[led.ledger_month == m]
        core, one, exc = x.core.sum(), x.one_time.sum(), x.excluded.sum()
        forecast_core = float(core + x.pending_core.sum())            # every Core line on the ledger for the month, ticked or not: its forecast
        has_core = bool(len(x) and x["budget_class"].astype(str).str.lower().eq("core").any())
        if m <= pending_through:
            core += float(x.pending_core.sum())
        pending = int(((x.reconciled.astype(str).str.lower() == "pending") & (x.debit.map(_n) > 0)).sum())
        if core + one + exc == 0:
            status, norm = "NO DATA", 0.0
        else:
            status, norm = ("Pending" if pending > 0 else "Reconciled"), core
        rows.append({"month": m, "core": core, "one_time": one, "excluded": exc,
                     "pending_debits": pending, "status": status, "normalized_core": norm,
                     "forecast_core": forecast_core, "has_core": has_core})
    return pd.DataFrame(rows).set_index("month")


def pace_actual_start_month(year: int) -> int:
    """The first month whose real reconciled Core dollars are trusted for the Dashboard pace figure. 2026's first
    half still has big one-off items sitting in Core from before the One-Time/Core split was consistently used, so
    those months are assumed to have landed exactly on budget instead of counted at their real total; July on (and
    every year after 2026) uses the real number, same as always."""
    return 7 if year == 2026 else 1


def spending_tracker(control: pd.DataFrame, year: int, core_budget: float,
                     one_time_annual: float) -> tuple[pd.DataFrame, dict]:
    """
    'Spending Tracker' monthly reconciliation (rows 11-22) and control views (rows 27-32).
    2026 is a partial year: the One-Time budget covers Sep-Dec only (one third of the annual bucket).
    """
    one_time_budget = one_time_annual * (1 / 3 if year == 2026 else 1)
    monthly_budget = core_budget / 12
    rows, cum_one = [], 0.0
    core = control.core.tolist()
    for i, m in enumerate(range(1, 13)):
        pre2026_sep = (year == 2026 and m < 9)
        g = 0.0 if pre2026_sep else float(control.loc[m, "one_time"])
        f = 0.0 if pre2026_sep else one_time_budget - cum_one
        cum_one += g
        window = core[max(0, i - 2): i + 1]
        rows.append({"month": m, "core_budget": monthly_budget, "core_actual": core[i],
                     "core_variance": monthly_budget - core[i], "core_avg_3m": float(np.mean(window)),
                     "one_time_budget": f, "one_time_spend": g, "one_time_remaining": one_time_budget - cum_one,
                     "total_actual": core[i] + g, "status": control.loc[m, "status"]})
    df = pd.DataFrame(rows).set_index("month")

    live = int((control.status != "NO DATA").sum())
    raw_core_ytd = float(df.core_actual.sum())          # every reconciled month, exactly as recorded -- audit only, not what the Dashboard shows

    # The figure the Dashboard actually shows: for 2026, January through June are assumed to have landed exactly
    # on budget rather than counted at their real reconciled total. That early in the year the One-Time/Core split
    # wasn't consistently applied yet, so those months' real Core dollars still carry big one-off items that
    # belong in One-Time -- using them here would just reintroduce the same distortion smoothing used to hide.
    # July on (and every year after 2026, where the split was in place from day one) uses the real number.
    pace_start = pace_actual_start_month(year)
    assumed_months = pace_start - 1
    pace_live = int(sum(1 for m in range(pace_start, 13) if control.loc[m, "status"] != "NO DATA"))
    pace_actual = assumed_months * monthly_budget + sum(core[m - 1] for m in range(pace_start, 13) if control.loc[m, "status"] != "NO DATA")
    pace_months = assumed_months + pace_live
    # the full-year forecast is built the way it would be done by hand: what's actually happened (or, for Jan-Jun
    # 2026, assumed at budget) so far, plus the plain monthly budget for whichever months are still ahead -- not
    # an average-pace-times-12 guess. With nothing reconciled yet (a fresh January), this is simply the full
    # annual budget: the best forecast before anything has happened is that the year goes exactly to plan.
    # Months still ahead use the forecast already on the ledger for them -- the card-payment estimates, bills and annual items (real-estate tax,
    # insurance) -- and the plain monthly budget only for a month with no Core lines at all (Andrew, Sep 2026: October's known bills were well under
    # budget, and a flat budget for every month ahead hid that).
    ahead = [m for m in range(pace_start, 13) if control.loc[m, "status"] == "NO DATA"]
    use_ledger = "forecast_core" in control.columns
    pace_full_year = pace_actual + sum((float(control.loc[m, "forecast_core"]) if use_ledger and bool(control.loc[m, "has_core"]) else monthly_budget)
                                       for m in ahead) + monthly_budget * max(0, 12 - pace_months - len(ahead))

    s = {"core_budget": core_budget, "one_time_budget": one_time_budget,
         "raw_core_ytd": raw_core_ytd,
         "budget_to_date": live * monthly_budget,
         "normalized_core_ytd": pace_actual,
         "normalized_budget_to_date": pace_months * monthly_budget,
         "normalized_full_year": pace_full_year}
    s["raw_variance"] = s["budget_to_date"] - s["raw_core_ytd"]
    s["normalized_variance"] = s["normalized_budget_to_date"] - s["normalized_core_ytd"]
    s["normalized_status"] = "ON TRACK" if s["normalized_variance"] >= 0 else "OVER"
    s["full_year_variance"] = core_budget - s["normalized_full_year"]
    s["full_year_status"] = "ON TRACK" if s["full_year_variance"] >= 0 else "OVER"
    s["one_time_balance"] = one_time_budget - float(df.one_time_spend.sum())
    return df, s


# ---- recurring forecast and headroom ---------------------------------------
def extra_active(x: dict, key: str) -> bool:
    """Is this repeating item due in month `key` ('YYYY-MM')? It starts at `from`, stops after `until`, and skips deleted months."""
    return x.get("from", "") <= key and (not x.get("until") or key <= x["until"]) and key not in x.get("skip", [])


@dataclass
class RecurringForecast:
    """Approved recurring Core items. `*_from_2028` dicts override an item by name from 2028 on.
    `extras` are repeating items added later in the app: {id, name, amount, day, from, until, skip}."""
    monthly: dict = field(default_factory=lambda: {
        "Credit card A": 2000.0, "Credit card B": 1500.0, "Utilities": 600.0, "Phone and internet": 250.0})
    monthly_from_2028: dict = field(default_factory=dict)
    annual_bills: dict = field(default_factory=lambda: {
        "Home insurance": 2000.0, "Property tax": 2500.0, "Vehicle insurance": 1400.0})
    annual_bills_from_2028: dict = field(default_factory=dict)
    annual_bill_day: dict = field(default_factory=dict)          # {item name (from `annual_bills`): [{"month": M, "day": D}, ...]}.
                                                                   # A list because one item can be due more than once a year (two
                                                                   # semiannual payments). No entry means the due date hasn't been
                                                                   # confirmed yet, so the item posts no dated ledger line at all --
                                                                   # unlike a monthly item, there's no safe "day 1" default for
                                                                   # something that only happens once a year.
    annual_bill_year_amounts: dict = field(default_factory=dict)  # {item name: {"YYYY": amount}}, explicit per-year overrides
                                                                   # (a tax bill with its own multi-year schedule) on top of the
                                                                   # `annual_bills` / `annual_bills_from_2028` split.
    extras: list = field(default_factory=list)
    monthly_day: dict = field(default_factory=dict)   # {item name (from `monthly`): confirmed day of the month}. Every
                                                        # item posts pending ledger lines regardless; an item with no
                                                        # entry here posts on a guessed day, flagged for review.
    monthly_start: dict = field(default_factory=dict)  # v25.37: {item name: "YYYY-MM"} first month a monthly bill posts (none: from now)
    monthly_end: dict = field(default_factory=dict)    # v25.37: {item name: "YYYY-MM"} last month it posts (none: no end)
    income_day: dict = field(default_factory=dict)     # {item name (from RECURRING_INCOME_ITEMS): confirmed day of the month}.
                                                        # Only the day is ever confirmed here -- the amount is always derived
                                                        # (see monthly_funding_target() and defcomp_year_amount below).
    deposit_buffer: float = 0.0                         # cushion added on top of the Core-budget-derived monthly funding
                                                        # target (see monthly_funding_target()), so the target isn't a flat
                                                        # hand-maintained number disconnected from the Core budget -- it
                                                        # follows the budget automatically (core_budget / 12), with just this
                                                        # buffer left to set by hand, for peaks and troughs. Core budget and
                                                        # the required deposit are one and the same thing, so the existing
                                                        # "Suggested Core budget" 90-day-lookback recommendation (Spending
                                                        # page) is also the deposit recommendation -- applying it moves the
                                                        # funding target, and so Savings deposit, right along with it
                                                        # (Andrew's call, September 2026). Savings deposit is simply the
                                                        # target minus that month's DefComp payment -- a plain subtraction,
                                                        # not a top-up against whatever has already posted, and never
                                                        # independently confirmed to some other flat figure either, so the
                                                        # two can't silently drift apart or add up to more than the target.
    defcomp_year_amount: dict = field(default_factory=dict)  # {"YYYY": DefComp's fixed monthly amount for that year}.
                                                        # DefComp pays what your plan says it pays, not what last happened
                                                        # to land in the bank, so its guess is fixed per calendar year here
                                                        # instead of carried from the last reconciled deposit. A year with
                                                        # no entry falls back to the closest earlier year that has one;
                                                        # with none set at all yet, it falls back to the old guess (the most
                                                        # recent matching reconciled deposit), flagged for review.

    def extras_annual(self, year: int) -> float:
        return float(sum(float(x.get("amount", 0.0)) * sum(1 for m in range(1, 13) if extra_active(x, f"{year}-{m:02d}"))
                         for x in self.extras))

    def monthly_total(self, year: int) -> float:
        """A month's worth of the monthly bills, averaged over the year: a bill that starts or ends part-way counts only its months (v25.37)."""
        m = dict(self.monthly)
        if year >= 2028:
            m.update(self.monthly_from_2028)
        return float(sum(v * monthly_active_months(self, n, year) / 12 for n, v in m.items()))

    def annual_bill_total(self, year: int) -> float:
        names = set(self.annual_bills) | set(self.annual_bills_from_2028) | set(self.annual_bill_year_amounts)
        return float(sum(annual_bill_amount_for(self, n, year) for n in names))


def monthly_active(rf: "RecurringForecast", name: str, k: str) -> bool:
    """v25.37: whether a monthly bill posts in month k ("YYYY-MM"), given its start and end months."""
    st_, en_ = (getattr(rf, "monthly_start", {}) or {}).get(name), (getattr(rf, "monthly_end", {}) or {}).get(name)
    return not ((st_ and k < st_) or (en_ and k > en_))


def monthly_active_months(rf: "RecurringForecast", name: str, year: int) -> int:
    return sum(1 for m in range(1, 13) if monthly_active(rf, name, f"{year}-{m:02d}"))


def annual_bill_amount_for(rf: "RecurringForecast", name: str, year: int) -> float:
    """Resolve one 'Scheduled annual bills' item's dollar amount for `year`: an explicit per-year override
    (annual_bill_year_amounts) first, then the `_from_2028` bucket for 2028 on, then the base `annual_bills` figure."""
    overrides = rf.annual_bill_year_amounts.get(name) or {}
    if str(year) in overrides:
        return float(overrides[str(year)])
    if year >= 2028 and name in rf.annual_bills_from_2028:
        return float(rf.annual_bills_from_2028[name])
    return float(rf.annual_bills.get(name, 0.0))


# Recurring deposits the ledger and tax engine already key off by this exact description (defcomp_received,
# roll_forward_ledger): posted forward automatically the same way Recurring items are, mirror-image on the credit side.
# Order matters: DefComp payment is resolved first each month, since Savings deposit tops up to the funding target
# after it (whatever DefComp pays, Savings covers the rest -- exhausted DefComp just means Savings covers it all).
RECURRING_INCOME_ITEMS = ["DefComp payment", "Savings deposit"]


def core_forecast_headroom(year: int, core_budget: float, rf: RecurringForecast,
                           use_year_specific_items: bool = True) -> dict:
    """
    Budget minus 12 months of recurring items minus scheduled annual bills.
    The workbook always uses the 2026-27 item set (use_year_specific_items=False replicates that);
    the app uses the item set for the year being tracked.
    """
    y = year if use_year_specific_items else 2027
    monthly = rf.monthly_total(y)
    bills = rf.annual_bill_total(y)
    extras = rf.extras_annual(year)                   # repeating items added in the app; none in the workbook
    committed = monthly * 12 + extras + bills
    return {"core_budget": core_budget, "monthly_recurring": monthly, "recurring_annual": monthly * 12,
            "extras_annual": extras, "scheduled_bills": bills, "committed": committed,
            "headroom": core_budget - committed}


# ---- year rollover (replaces the ExpenseYearCloseout macro) ----------------------
def shift_date_to_year(d, new_year: int):
    """VBA ShiftDateToYear: same month/day in the new year; Feb 29 becomes Feb 28 when needed."""
    d = pd.Timestamp(d)
    last_day = pd.Timestamp(new_year, d.month, 1).days_in_month
    return pd.Timestamp(new_year, d.month, min(d.day, last_day))


def roll_forward_ledger(prev: pd.DataFrame, target_year: int, savings_funding: float = 7500.0) -> pd.DataFrame:
    """
    Build a new-year ledger from a prior-year one, following the 'FutureProof' macro:
      * every date moves into the target year
      * from 2028: DefComp payment rows are dropped and the savings deposit becomes the full
        $7,500, classed Excluded
      * every populated row is reset to 'Pending' for monthly reconciliation
    """
    out = prev.copy().reset_index(drop=True)
    out["date"] = out["date"].map(lambda d: shift_date_to_year(d, target_year) if pd.notna(d) else d)
    if target_year >= 2028:
        desc = out["description"].astype(str).str.strip().str.lower()
        out = out[desc != "defcomp payment"].reset_index(drop=True)
        desc = out["description"].astype(str).str.strip().str.lower()
        is_sav = desc == "savings deposit"
        out.loc[is_sav, "credit"] = savings_funding
        out.loc[is_sav, "debit"] = np.nan
        out.loc[is_sav, "budget_class"] = "Excluded"
        out.loc[is_sav, "note"] = "Full $7,500 monthly expense-account funding from Savings."
    populated = (out["credit"].map(_n) != 0) | (out["debit"].map(_n) != 0)
    out.loc[populated, "reconciled"] = "Pending"
    return out


# ============================================================================
# SLICE 8 -- Monthly close: completeness, due dates, reminders, balances, forecast variance
# ('Update Reminders' backlog, 'Monthly Net Worth Updates')
# ============================================================================
import calendar as _cal

BALANCE_FIELDS = ["wells_cash_mm", "schwab_taxable", "schwab_ira", "empower_defcomp", "mes_sipp",
                  "planeasy_annuities", "wells_indexed_annuities", "hsa", "etrade"]
CAPITAL_FIELD = "capital_assets"


def _present(v) -> bool:
    return v is not None and not (isinstance(v, float) and np.isnan(v)) and v != ""


def eomonth(d: _dt.date, offset: int = 0) -> _dt.date:
    y, m = d.year, d.month + offset
    y += (m - 1) // 12
    m = (m - 1) % 12 + 1
    return _dt.date(y, m, _cal.monthrange(y, m)[1])


def close_due_date(month_end: _dt.date) -> _dt.date:
    """Workbook: end of month + 10 days."""
    return eomonth(month_end, 0) + _dt.timedelta(days=10)


def magi_complete(values: dict, status: str, zero_counts_as_entered: bool = True) -> bool:
    """
    Every one of the 12 income fields is filled in AND the month is marked Finalized.
    In the app, an explicit 0 counts as entered (the workbook needs a value in every cell, and its
    deferred-comp cell is blank when there is no DefComp payment).
    """
    filled = all(_present(values.get(k)) for k in MONTHLY_COLUMNS)
    return bool(filled and status == "Finalized")


def networth_complete(values: dict) -> bool:
    """All nine account balances plus capital assets are entered."""
    return all(_present(values.get(k)) for k in BALANCE_FIELDS + [CAPITAL_FIELD])


def expenses_complete(ledger: pd.DataFrame) -> bool:
    """At least one dated row, and every dated row is reconciled ('Yes')."""
    if ledger is None or len(ledger) == 0:
        return False
    dated = ledger[ledger["date"].notna()]
    if len(dated) == 0:
        return False
    return bool((dated["reconciled"].astype(str).str.lower() == "yes").all())


def close_status(month_end: _dt.date, as_of: _dt.date, magi_ok: bool, nw_ok: bool, exp_ok: bool) -> str:
    """FUTURE until the month has ended; COMPLETE when all three pieces are done; OVERDUE after the due date."""
    if month_end > eomonth(as_of, -1):
        return "FUTURE"
    if magi_ok and nw_ok and exp_ok:
        return "COMPLETE"
    return "OVERDUE" if as_of > close_due_date(month_end) else "DUE"


def missing_items(magi_ok: bool, nw_ok: bool, exp_ok: bool) -> str:
    return ", ".join([n for n, ok in (("MAGI", magi_ok), ("Net worth", nw_ok), ("Expenses", exp_ok)) if not ok])


def alert_due_today(status: str, month_end: _dt.date, as_of: _dt.date) -> bool:
    """Reminder fires every 3 days starting on the due date, while the month is still incomplete."""
    due = close_due_date(month_end)
    return status not in ("COMPLETE", "FUTURE") and as_of >= due and (as_of - due).days % 3 == 0


def net_worth_row(balances: dict, capital, prior_total) -> dict:
    """Total financial assets needs all nine balances; net worth adds capital assets; growth vs prior month."""
    count = sum(_present(balances.get(k)) for k in BALANCE_FIELDS)
    total = float(sum(balances[k] for k in BALANCE_FIELDS)) if count >= 9 else None
    nw = total + capital if (total is not None and _present(capital)) else None
    growth = (total - prior_total) if (total is not None and prior_total is not None) else None
    pct = (growth / prior_total) if (growth is not None and prior_total) else None
    return {"total_financial": total, "net_worth": nw, "growth": growth, "growth_pct": pct}


def forecast_financial_assets(month_end: _dt.date, baseline_total: float, portfolio_total_by_year: dict,
                              baseline_growth: float = 0.05, baseline_month: int = 8):
    """
    'Monthly Net Worth Updates'!Q. 2026: baseline compounding monthly from the August baseline.
    Later years: straight line between the portfolio forecast's year-end totals.
    """
    y, m = month_end.year, month_end.month
    if y == 2026:
        return baseline_total * (1 + baseline_growth) ** ((m - baseline_month) / 12)
    if y not in portfolio_total_by_year:
        return None
    prior = portfolio_total_by_year.get(y - 1, baseline_total)
    return prior + (portfolio_total_by_year[y] - prior) * m / 12


def defcomp_from_ledger(ledger: pd.DataFrame, withholding_rate: float = 0.22):
    """
    'Monthly MAGI Inputs'!H: gross up the RECONCILED 'DefComp payment' credits by the withholding rate,
    rounded to cents. Returns None when there is no reconciled DefComp payment (the app treats that as 0).
    """
    d = ledger["description"].astype(str).str.lower().eq("defcomp payment")
    r = ledger["reconciled"].astype(str).str.lower().eq("yes")
    sel = ledger[d & r]
    if len(sel) == 0:
        return None
    total = float(sel["credit"].map(_n).sum()) / (1 - withholding_rate)
    return _excel_round(total * 100) / 100
