# ---- months ------------------------------------------------------------------------
MONTH_LOOKAHEAD = 18   # months always available from the current one on, so committed items keep a runway to post into


def month_list(plan: Plan, today: _dt.date) -> list[str]:
    first, last = plan.meta.get("first_month", "2026-08"), plan.meta.get("last_month", "2027-12")
    ty, tm = divmod(today.year * 12 + today.month - 1 + MONTH_LOOKAHEAD - 1, 12)
    end = max(last, f"{ty}-{tm + 1:02d}")
    out, (y, m) = [], map(int, first.split("-"))
    ey, em = map(int, end.split("-"))
    while (y, m) <= (ey, em):
        out.append(f"{y}-{m:02d}")
        m += 1
        if m > 12:
            y, m = y + 1, 1
    return out


def month_end_date(key: str) -> _dt.date:
    y, m = map(int, key.split("-"))
    return (pd.Timestamp(y, m, 1) + pd.offsets.MonthEnd(0)).date()


def due_date(key: str) -> _dt.date:
    """The 10th of the following month (as in the workbook's Update Reminders sheet)."""
    y, m = map(int, key.split("-"))
    y2, m2 = (y + 1, 1) if m == 12 else (y, m + 1)
    return _dt.date(y2, m2, 10)


# ---- monthly entries -> engine ----------------------------------------------------------
def ledger_frame(rows: list[dict]) -> pd.DataFrame:
    """Ledger rows in the shape the engine expects (date, description, credit, debit, reconciled, budget_class)."""
    return pd.DataFrame([{"date": pd.Timestamp(r["date"]) if r.get("date") else pd.NaT, "description": r.get("desc", ""),
                          "credit": r.get("credit"), "debit": r.get("debit"), "reconciled": r.get("rec", "Pending"),
                          "budget_class": r.get("cls", ""), "note": r.get("note", ""), "ot_split": r.get("ot_split") or 0.0} for r in rows],
                        columns=["date", "description", "credit", "debit", "reconciled", "budget_class", "note", "ot_split"])


def defcomp_received(rows: list[dict], rate: float):
    """'Deferred Comp Received': reconciled DefComp deposits grossed up for withholding; None if none."""
    hits = [r for r in rows if str(r.get("desc", "")).lower() == "defcomp payment" and str(r.get("rec", "")).lower() == "yes"]
    if not hits:
        return None
    return round(sum(_n(r.get("credit")) for r in hits) / (1 - rate), 2)


def income_record(entries: dict, key: str, rate: float) -> dict:
    rec = dict(entries["magi"].get(key, {}))
    dc = defcomp_received(entries["ledger"].get(key, []), rate)
    rec["defcomp"] = 0.0 if dc is None else dc
    return rec


def income_totals(rec: dict) -> dict:
    g = lambda k: _n(rec.get(k))
    int_div = g("wellsInt") + g("wellsDiv") + g("schwabInt") + g("schwabDiv")
    other = g("gains") + g("other") + g("defcomp") + g("annuity") + g("roth") + g("sipp") + g("ira") + g("ss")
    return {"int_div": int_div, "other": other, "gains": g("gains"), "total": int_div + other}


def finalized_months(entries: dict) -> list[str]:
    return sorted(k for k, v in entries["magi"].items() if v.get("status") == "Finalized")


def monthly_finalized_from_entries(entries: dict):
    """Base investment income rule: interest + dividends + realized gains + other brokerage, finalized months only."""
    rows = []
    for k in finalized_months(entries):
        r = entries["magi"][k]
        amt = sum(_n(r.get(f)) for f in ("wellsInt", "wellsDiv", "schwabInt", "schwabDiv", "gains", "other"))
        rows.append({"month_end": month_end_date(k), "amount": amt})
    if not rows:
        return None
    df = pd.DataFrame(rows)
    df["month_end"] = pd.to_datetime(df["month_end"])
    return df


def run_rate_projection(entries: dict, rate: float, include: str | None = None):
    """Workbook column Q: (sum(all) - sum(gains)) x 12 / n + sum(gains) over finalized months.
    v21.17: allows for the quarterly fund dividends. The quarterly part of a March, June, September or December (as the 'if this continues'
    check measures it) is taken out before the months are multiplied up, and four quarterly payments are added back for the year, so a
    quarterly month no longer inflates the figure and an ordinary month no longer leaves the quarterlies out."""
    keys = [k for k in sorted(entries["magi"]) if entries["magi"][k].get("status") == "Finalized" or k == include]
    if not keys:
        return None, 0
    tot = gains = bumps = 0.0
    for k in keys:
        t = income_totals(income_record(entries, k, rate))
        tot += t["total"]; gains += t["gains"]
        bumps += quarterly_part(entries, k, rate, t)
    q = quarterly_extra(entries, _inv_key(int(keys[-1][:4]), int(keys[-1][5:7]) + 1), rate)
    return (tot - gains - bumps) * 12 / len(keys) + gains + q * len(QUARTER_MONTHS), len(keys)


# ---- investment income table (v21.16) ---------------------------------------------------------------------------------------------------
# Interest and dividends by month and account, by payment date, from the statements. Kept apart from 'magi_history' (the workbook's monthly
# MAGI totals, which stay as they were). A month not in the table falls back to its finalized monthly update; a month with neither is estimated.
INV_ACCOUNTS = [("wells", "Wells savings"), ("wellstrade", "WellsTrade"), ("schwab", "Schwab")]
INV_FIELDS = [f for f, _l in INV_ACCOUNTS]
QUARTER_MONTHS = (3, 6, 9, 12)       # the months the stock and bond funds pay their quarterly dividends


def _inv_key(y: int, m: int) -> str:
    y, m = (y - 1, m + 12) if m < 1 else (y, m)
    return f"{y}-{m:02d}"


def inv_known(entries: dict, key: str, rate: float = 0.22) -> dict | None:
    """One month's interest and dividends as known: the table first, then a finalized monthly update. None when neither has it.
    Returns {'wells','wellstrade','schwab','muni','qtr','total','source','note'}; a figure the source does not split out is None."""
    row = (entries.get("invest_income") or {}).get(key)
    if isinstance(row, dict):
        vals = {f: (float(row[f]) if isinstance(row.get(f), (int, float)) else None) for f in INV_FIELDS}
        return {**vals, "muni": float(row.get("muni") or 0.0), "qtr": float(row.get("qtr") or 0.0),
                "total": round(sum(v or 0.0 for v in vals.values()), 2), "source": "Statement", "note": str(row.get("note") or "")}
    rec = (entries.get("magi") or {}).get(key) or {}
    if rec.get("status") == "Finalized":
        w = _n(rec.get("wellsInt")) + _n(rec.get("wellsDiv"))
        sc = _n(rec.get("schwabInt")) + _n(rec.get("schwabDiv"))
        return {"wells": round(w, 2), "wellstrade": None, "schwab": round(sc, 2), "muni": _n(rec.get("muni")), "qtr": None,
                "total": round(w + sc, 2), "source": "Monthly update", "note": "Wells savings and WellsTrade together"}
    return None


def inv_has_table(entries: dict, year: int) -> bool:
    return any(str(k).startswith(f"{year}-") for k in (entries.get("invest_income") or {}))


def invest_year(entries: dict, year: int, rate: float = 0.22) -> dict:
    """The year's interest and dividends month by month. A month with no figures is estimated from the month three before it (the same
    place in the quarter, so a quarterly dividend month is estimated from the last quarterly month), working forward. If you saved your own
    estimate for the open months (invest_income_est), the app's estimate is scaled to match it, and keeps that ratio as months close.
    Tax-exempt muni interest is estimated the same way and is not scaled."""
    rows, by_m = [], {}
    for m in range(1, 13):
        k = _inv_key(year, m)
        kn = inv_known(entries, k, rate)
        if kn is not None:
            by_m[m] = kn
            rows.append({"month": k, **kn, "estimated": False})
            continue
        src = by_m.get(m - 3) if m > 3 else inv_known(entries, _inv_key(year, m - 3), rate)
        if src is None:
            known = [r for r in rows if not r["estimated"]]
            if not known:
                rows.append({"month": k, "wells": None, "wellstrade": None, "schwab": None, "muni": 0.0, "qtr": 0.0, "total": None,
                             "source": "Not known", "note": "", "estimated": True})
                continue
            avg = sum(r["total"] for r in known) / len(known)       # nothing three months back: the average known month
            src = {"wells": None, "wellstrade": None, "schwab": None, "muni": sum(r["muni"] for r in known) / len(known), "qtr": 0.0, "total": avg}
        est = {"wells": src.get("wells"), "wellstrade": src.get("wellstrade"), "schwab": src.get("schwab"), "muni": float(src.get("muni") or 0.0),
               "qtr": float(src.get("qtr") or 0.0), "total": float(src["total"]), "source": "Estimate",
               "note": f"From {month_short(_inv_key(year, m - 3))}", "estimated": True}
        by_m[m] = est
        rows.append({"month": k, **est})
    open_ = [r for r in rows if r["estimated"] and r["total"] is not None]
    app_est = round(sum(r["total"] for r in open_), 2)
    ov = ((entries.get("invest_income_est") or {}).get(str(year)) or {})
    factor, ov_used = 1.0, None
    if open_ and isinstance(ov.get("amount"), (int, float)) and ov.get("months"):
        cover = set(ov["months"])
        if {r["month"] for r in open_} <= cover:
            # your estimate against the app's for the same months: the months three before each, as they stand now
            full = sum(_inv_app_estimate(entries, by_m, year, int(mk[5:7]), rate) for mk in cover if mk.startswith(f"{year}-"))
            if full > 0:
                factor = float(ov["amount"]) / full
                ov_used = {"amount": float(ov["amount"]), "months": sorted(cover), "factor": factor, "app": round(full, 2)}
    if factor != 1.0:
        for r in open_:
            for f in INV_FIELDS + ["total"]:
                if isinstance(r.get(f), (int, float)):
                    r[f] = round(r[f] * factor, 2)
    actual = [r for r in rows if not r["estimated"]]
    total_known = all(r["total"] is not None for r in rows)
    out = {"year": year, "rows": rows, "actual_total": round(sum(r["total"] for r in actual), 2),
           "estimate_total": round(sum(r["total"] for r in open_), 2), "app_estimate": app_est, "override": ov_used,
           "n_actual": len(actual), "open_months": [r["month"] for r in open_], "complete": total_known,
           "muni_actual": round(sum(r["muni"] for r in actual), 2), "muni_total": round(sum(r["muni"] or 0.0 for r in rows), 2),
           "has_table": inv_has_table(entries, year)}
    out["total"] = round(out["actual_total"] + out["estimate_total"], 2) if total_known else None
    return out


def _inv_app_estimate(entries: dict, by_m: dict, year: int, m: int, rate: float) -> float:
    """The app's own (unscaled) estimate for a month: the month three before it, for working out how your saved estimate compares."""
    r = by_m.get(m - 3) if m > 3 else inv_known(entries, _inv_key(year, m - 3), rate)
    return float((r or {}).get("total") or 0.0)


BASE_METHODS = {"run_rate": "Today's run rate", "full_year": "Full year"}


def invest_run_rate(entries: dict, year: int, rate: float = 0.22) -> dict | None:
    """Next year's interest and dividends at today's rate, from the year's actual months (v21.18):
      - Wells savings: the latest month x 12, so a balance that is being drawn down is followed rather than averaged
      - WellsTrade and Schwab: the latest full quarter x 4, so the quarterly fund dividends are in and a portfolio built up during the
        year counts at its current size
      - tax-exempt muni: the latest full quarter x 4
    A month from a monthly update has Wells savings and WellsTrade together; then that month's Wells total x 12 is used for both.
    None until the year has a full quarter of actual months."""
    rows = [r for r in invest_year(entries, year, rate)["rows"] if not r["estimated"]]
    by_m = {int(r["month"][5:7]): r for r in rows}
    qend = next((q for q in (12, 9, 6, 3) if all(m in by_m for m in (q - 2, q - 1, q))), None)
    if qend is None:
        return None
    last = by_m[max(by_m)]
    qrows = [by_m[m] for m in (qend - 2, qend - 1, qend)]
    sch = 4 * sum(float(r.get("schwab") or 0.0) for r in qrows)
    muni = 4 * sum(float(r.get("muni") or 0.0) for r in qrows)
    if last.get("wellstrade") is not None:
        wsav = 12 * float(last.get("wells") or 0.0)
        wtr = 4 * sum(float(r.get("wellstrade") or 0.0) for r in qrows)
    else:
        wsav, wtr = 12 * float(last.get("wells") or 0.0), 0.0
    total = round(wsav + wtr + sch, 2)
    return {"total": total, "muni": round(muni, 2), "wells_savings": round(wsav, 2), "wellstrade": round(wtr, 2), "schwab": round(sch, 2),
            "last_month": last["month"], "quarter": (f"{year}-{qend - 2:02d}", f"{year}-{qend:02d}")}


def invest_base_method(entries: dict) -> str:
    return (entries.get("invest_income_meta") or {}).get("base_method", "run_rate")


def invest_inputs(entries: dict, rate: float = 0.22) -> tuple[dict, dict]:
    """For the engine: {year: next year's base interest + dividends} and {year: its tax-exempt share} for every year the table covers.
    v21.18: by default the base is today's run rate (invest_run_rate); 'full_year' uses the year's full total (actual plus estimate), as in v21.16."""
    by_year, share = {}, {}
    method = invest_base_method(entries)
    for y in sorted({int(str(k)[:4]) for k in (entries.get("invest_income") or {})}):
        rr = invest_run_rate(entries, y, rate) if method == "run_rate" else None
        if rr and rr["total"] > 0:
            by_year[y], share[y] = rr["total"], rr["muni"] / rr["total"]
            continue
        t = invest_year(entries, y, rate)
        if t["total"]:
            by_year[y] = t["total"]
            share[y] = t["muni_total"] / t["total"] if t["total"] > 0 else 0.0
    return by_year, share


def invest_weights(entries: dict, year: int, rate: float = 0.22) -> dict | None:
    """Each month's share of the investment income, from the latest year up to `year` the table covers. None when there is none."""
    ys = [y for y in sorted({int(str(k)[:4]) for k in (entries.get("invest_income") or {})}) if y <= year]
    if not ys:
        return None
    t = invest_year(entries, ys[-1], rate)
    if not t["total"]:
        return None
    return {int(r["month"][5:7]): float(r["total"]) / t["total"] for r in t["rows"]}


def quarterly_extra(entries: dict, k: str, rate: float = 0.22) -> float:
    """The size of the last quarterly fund dividend before month k (the extra a March, June, September or December brings).
    From the table's 'qtr' figure where you have it; otherwise a quarterly month's interest and dividends less the average of the two
    months before it. Looks back up to a year; 0 when nothing is known."""
    y, m = int(k[:4]), int(k[5:7])
    for back in range(1, 13):
        mk = _inv_key(y, m - back)
        if int(mk[5:7]) not in QUARTER_MONTHS:
            continue
        kn = inv_known(entries, mk, rate)
        if kn is None:
            continue
        if kn.get("qtr"):
            return float(kn["qtr"])
        y2, m2 = int(mk[:4]), int(mk[5:7])
        prev = [inv_known(entries, _inv_key(y2, m2 - i), rate) for i in (1, 2)]
        prev = [p["total"] for p in prev if p is not None]
        if prev:
            return max(0.0, round(kn["total"] - sum(prev) / len(prev), 2))
    return 0.0


def quarterly_part(entries: dict, k: str, rate: float, t: dict | None = None) -> float:
    """How much of month k's income is this quarter's fund dividend: 0 outside March, June, September and December; otherwise the part of
    its interest and dividends above the two months before it, capped at the last known quarterly amount (so a real jump is not hidden)."""
    mth = int(k[5:7])
    if mth not in QUARTER_MONTHS:
        return 0.0
    q = quarterly_extra(entries, k, rate)
    if q <= 0:
        return 0.0
    t = t or income_totals(income_record(entries, k, rate))
    prev = [inv_known(entries, _inv_key(int(k[:4]), mth - i), rate) for i in (1, 2)]
    prev = [p_["total"] for p_ in prev if p_ is not None]
    bump = t["int_div"] - (sum(prev) / len(prev) if prev else 0.0)
    return min(q, max(bump, 0.0), max(t["total"] - t["gains"], 0.0))


def history_check(entries: dict, year: int, rate: float = 0.22) -> list[dict]:
    """The imported history totals set against the table's interest and dividends. The history total is all MAGI for the month, so it can
    never be below that month's interest and dividends; a month where it is (or where what is left is far below the other months) probably
    missed the quarterly dividends. Information only: the history stays as it is."""
    hist = entries.get("magi_history") or {}
    rows = []
    for k in sorted(h for h in hist if h.startswith(f"{year}-")):
        kn = (entries.get("invest_income") or {}).get(k)
        if not isinstance(kn, dict):
            continue
        idv = inv_known(entries, k, rate)["total"]
        rows.append({"month": k, "history": float(hist[k].get("total", 0.0)), "int_div": idv, "rest": round(float(hist[k].get("total", 0.0)) - idv, 2)})
    if rows:
        med = float(np.median([r["rest"] for r in rows]))
        for r in rows:
            r["flag"] = r["rest"] < 0 or (med > 0 and r["rest"] < med / 2)
    return rows


def wells_feed_check(plan, inbox: dict | None) -> dict:
    """Which bank accounts feed the Wells interest line, and any WellsTrade account that does not (it should)."""
    snaps = (inbox or {}).get("snapshots") or {}
    accts = {a["id"]: a for k2 in sorted(snaps) for a in (snaps[k2].get("accounts") or [])}
    mapping = income_inbox_mapping(plan, inbox)
    name = lambda a: f"{a.get('org', '')} {a.get('name', '')}".strip()
    feeding = [name(accts[i]) for i, ln in mapping.items() if ln == "wells" and i in accts]
    trade = [a for a in accts.values() if "wellstrade" in name(a).lower().replace(" ", "") or "1505" in name(a)]
    missing = [name(a) for a in trade if mapping.get(a["id"]) != "wells"]
    return {"known": bool(accts), "feeding": sorted(feeding), "wellstrade": [name(a) for a in trade], "missing": missing}


def latest_complete_balances(entries: dict):
    for k in sorted(entries["balances"], reverse=True):
        b = entries["balances"][k]
        if all(isinstance(b.get(a), (int, float)) for a in NINE_ACCOUNTS):
            return k, b
    return None, None


def portfolio_from_entries(pin: PortfolioInputs, entries: dict) -> PortfolioInputs:
    """Opening balances from the latest month with all nine accounts entered (Portfolio Integration rule)."""
    k, b = latest_complete_balances(entries)
    if b is None:
        return pin
    pin.taxable_liquid = b["wells"] + b["schwabTax"] + b["etrade"]
    pin.pretax = b["schwabIra"] + b["empower"] + b["sipp"]
    pin.annuities = b["planeasy"] + b["wellsAnn"]
    pin.hsa = b["hsa"]
    pin.ira, pin.empower, pin.sipp = b["schwabIra"], b["empower"], b["sipp"]
    pin.planeasy_balance = b["planeasy"]
    pin.wells_sp = pin.wells_nasdaq = b["wellsAnn"] / 2      # the two indexed components are modelled as equal halves
    return pin


def qualified_share(entries: dict, rate: float = 0.22) -> float:
    """v25.45: the share of taxable interest and dividends that is qualified -- the quarterly fund dividends, as in the year's tax forecast --
    from the latest year in the investment income table. 0 when there is no table."""
    ys = sorted({int(str(k)[:4]) for k in (entries.get("invest_income") or {})})
    if not ys:
        return 0.0
    t = invest_year(entries, ys[-1], rate)
    total, muni = float(t["total"] or 0.0), float(t["muni_total"] or 0.0)
    qual = sum(float(r.get("qtr") or 0.0) for r in t["rows"])
    return max(0.0, min(1.0, qual / (total - muni))) if total - muni > 0 else 0.0


def realistic_rates_once(plan) -> None:
    """v25.42: the plan moves once from the cautious 5% to realistic rates by account: after-tax 6.5%, pre-tax 6.25%. After that the
    two Growth sliders set them, and what you choose is saved with the plan."""
    if plan.meta.get("rates_v2542"):
        return
    plan.portfolio.growth, plan.portfolio.pretax_growth = 0.065, 0.0625
    plan.meta["rates_v2542"] = True


def rmd_cap_once(plan) -> None:
    """v25.48: the RMD cap moves once to $100,000 (fewer conversions). After that the RMD cap box sets it and is saved with the plan."""
    if plan.meta.get("rmd_v2548"):
        return
    plan.expenses["rmd_goal"] = 100000.0
    plan.meta["rmd_v2548"] = True


def default_settings(plan: Plan, entries: dict) -> dict:
    realistic_rates_once(plan)
    rmd_cap_once(plan)
    rate = plan.inputs.defcomp.withholding_rate
    rr, _ = run_rate_projection(entries, rate)
    return {"living_from_2028": core_budget_for(plan, 2029), "_lf_budget": core_budget_for(plan, 2029), "travel_from_2030": plan.cash.travel_from_2030,
            "inflation": plan.inputs.inflation, "growth": plan.portfolio.growth, "roth_total": plan.inputs.roth_total,
            "pretax_growth": plan.portfolio.pretax_growth, "growth_after": plan.portfolio.growth_after,
            "pretax_growth_after": plan.portfolio.pretax_growth_after,
            "replica": False, "limit_growth": bool(plan.expenses.get("aca_limit_growth", True)), "override_income": False, "base_income": 0.0,
            "warning": plan.aca_irmaa.aca.warning_target, "buffer": plan.aca_irmaa.aca.year_end_buffer,
            "aca_year": 2027, "whatif": False, "k": 0, "r": 4000.0, "one_time": 0.0}


def build_inputs(plan: Plan, s: dict, entries: dict):
    infl = float(s["inflation"])
    inp = _copy.deepcopy(plan.inputs)
    inp.monthly_finalized = monthly_finalized_from_entries(entries)
    inp.base_income_by_year, inp.tax_exempt_share = invest_inputs(entries, plan.inputs.defcomp.withholding_rate)
    inp.annuity_gain = {int(plan.cash.annuity_year): annuity_gain_auto(plan)}     # v21.22: proceeds less what was paid in, always
    sp, lc = plan.meta.get("sipp") or {}, plan.meta.get("loss_carryover") or {}
    inp.sipp_gbp_month, inp.sipp_fx = float(sp.get("gbp_month") or 0.0), float(sp.get("fx") or 1.0)
    inp.sipp_last_year = int(sp.get("last_year") or 0)
    inp.loss_carry, inp.loss_carry_year = float(lc.get("amount") or 0.0), int(lc.get("year") or FIRST_YEAR)
    inp.inflation = infl
    inp.tax.index_rate = infl
    inp.tax.index_brackets = not s["replica"]
    # Living costs in the cash flow come from the Core budget, so the two can never drift apart (Andrew, Sep 2026): 2027 is that year's budget, and
    # 2028 on is the sidebar figure, which starts from -- and follows -- the 2028 budget (see sync_budget_settings). Travel, medical and tax stay separate.
    inp.living_cost_2027 = core_budget_for(plan, 2027)
    inp.living_cost_2028 = core_budget_for(plan, 2028)
    inp.living_cost_from_2028 = float(s["living_from_2028"])            # 2029 on
    inp.move.rv_value_now = float(plan.cash.rv_current_value)          # v25.30: the motorhome's value for Virginia's vehicle tax
    inp.move.rv_depreciation = float(plan.cash.rv_depreciation)
    inp.move.rv_sold_year = int(plan.cash.rv_sale_year or 0)
    _start = int(str(plan.meta.get("as_of") or "2026-08-31")[:4] or 2026)            # v25.32: the house and cars from the Net worth page
    _caps = [x for x in plan.meta.get("capital_items", []) if isinstance(x, dict)]
    _house = next((x for x in _caps if "house" in str(x.get("name", "")).lower() or "home" in str(x.get("name", "")).lower()), None)
    inp.move.fl_house = {"value": float(_house["value"]), "rate": float(_house.get("rate") or 0), "until": _house.get("until"), "start": _start} if _house else {}
    inp.move.car_items = [[float(x["value"]), float(x.get("rate") or 0), x.get("until"), _start] for x in _caps
                          if x is not _house and float(x.get("rate") or 0) < 0 and not x.get("sale_year")]
    inp.move.fl_bills = {y: annual_bill_amount_for(plan.recurring, "Real-estate tax", y) + annual_bill_amount_for(plan.recurring, "Homeowners insurance", y)
                         for y in YEARS}
    inp.roth_total = float(s["roth_total"])
    if s.get("override_income"):
        inp.base_income_override = float(s["base_income"])
    ai = _copy.deepcopy(plan.aca_irmaa)
    ai.irmaa.index_rate = infl
    ai.irmaa.index_tier_edges = not s["replica"]
    ai.irmaa.index_surcharges = not s["replica"]
    lim27 = plan.aca_irmaa.aca.limit_by_year.get(2027, 86560.0)
    ai.aca.limit_by_year = {y: (lim27 * (1 + infl) ** (y - 2027) if (s["limit_growth"] and y >= 2028) else
                                (plan.aca_irmaa.aca.limit_by_year.get(y, lim27)))
                            for y in range(2026, 2034)}
    ai.aca.warning_target = float(s["warning"])
    inp.early_conv_on = bool(plan.expenses.get("early_conv", True))      # v25.43
    inp.qual_share = qualified_share(entries, plan.inputs.defcomp.withholding_rate)   # v25.45
    tb = plan.expenses.get("tbill") or {"on": True, "year": 2033, "amount": 600000.0}   # v25.47: {"on", "year", "amount"}
    inp.tbill_shift = ({int(tb.get("year", 2033)): round(float(tb.get("amount", 0.0)) * float(plan.cash.cash_growth_rate), 2)}
                       if tb.get("on") and float(tb.get("amount", 0.0)) > 0 else {})
    inp.early_limits = {int(y): float(v) for y, v in ai.aca.limit_by_year.items()}
    ai.aca.year_end_buffer = float(s["buffer"])
    cf = _copy.deepcopy(plan.cash)
    lo = s.get("live_opening")
    cf.live_opening = {int(lo["year"]): float(lo["opening"])} if isinstance(lo, dict) and lo.get("opening") is not None else {}
    cf.live_stale = bool(isinstance(lo, dict) and lo.get("stale"))
    cf.travel_from_2030 = float(s["travel_from_2030"])
    cf.cash_floor = cash_warn_level(plan)                                # v25.35: cash is kept at the safety line; the rest comes from investments
    pin = portfolio_from_entries(_copy.deepcopy(plan.portfolio), entries)
    pin.growth = float(s["growth"])
    pin.pretax_growth = float(s.get("pretax_growth", pin.pretax_growth))
    pin.growth_after = float(s.get("growth_after", pin.growth_after))
    pin.pretax_growth_after = float(s.get("pretax_growth_after", pin.pretax_growth_after))
    return inp, ai, cf, pin


def aca_monthly_frame(entries: dict, plan: Plan, s: dict, year: int) -> pd.DataFrame:
    """Finalized months of `year` as engine rows; or a what-if run rate when the what-if switch is on."""
    cols = ["month_end", "status", "wells_interest", "wells_dividends", "schwab_interest", "schwab_dividends",
            "realized_gains", "other_brokerage", "defcomp", "annuity_gain", "roth_conversion", "sipp", "ira_rmd", "taxable_ss"]
    rows = []
    if s.get("whatif"):
        for m in range(1, int(s["k"]) + 1):
            rows.append({"month_end": pd.Timestamp(year, m, 28), "status": "Finalized", "wells_interest": float(s["r"])})
    else:
        rate = plan.inputs.defcomp.withholding_rate
        for m in range(1, 13):
            k = f"{year}-{m:02d}"
            if entries["magi"].get(k, {}).get("status") == "Finalized":
                r = income_record(entries, k, rate)
                rows.append({"month_end": pd.Timestamp(year, m, 28), "status": "Finalized",
                             "wells_interest": _n(r.get("wellsInt")), "wells_dividends": _n(r.get("wellsDiv")),
                             "schwab_interest": _n(r.get("schwabInt")), "schwab_dividends": _n(r.get("schwabDiv")),
                             "realized_gains": _n(r.get("gains")), "other_brokerage": _n(r.get("other")),
                             "defcomp": _n(r.get("defcomp")), "annuity_gain": _n(r.get("annuity")),
                             "roth_conversion": _n(r.get("roth")), "sipp": _n(r.get("sipp")),
                             "ira_rmd": _n(r.get("ira")), "taxable_ss": _n(r.get("ss"))})
    return pd.DataFrame(rows, columns=cols)


def split_draws(cf_df: pd.DataFrame, pf: pd.DataFrame, cf: "CashFlowInputs", pin: "PortfolioInputs") -> pd.DataFrame:
    """v25.35: which account each year's draw (to keep cash at the safety line) comes from, in the order set: the Schwab brokerage (what is
    invested beyond the cash), then the UK SIPP, then the IRA, each only as far as it holds money. The SIPP and IRA are followed roughly
    (growth, less earlier draws); they are only reached if the brokerage runs out."""
    order = [o for o in (cf.draw_order or []) if o in ("brokerage", "sipp", "ira")] or ["brokerage", "sipp", "ira"]
    bal = {"sipp": float(pin.sipp), "ira": float(pin.ira)}
    taken = 0.0
    rows = []
    for y in cf_df.index:
        bal = {k: v * (1 + g_pre(pin, y)) for k, v in bal.items()}
        need = float(cf_df.loc[y, "drawdown"])
        avail = {"brokerage": max(0.0, float(pf.loc[y, "end_taxable"]) - float(cf_df.loc[y, "ending_cash"])), **bal}
        got = {"brokerage": 0.0, "sipp": 0.0, "ira": 0.0}
        for src in order:
            t = min(need, avail[src])
            got[src] += t
            need -= t
            if src in bal:
                bal[src] -= t
        if need > 0.005:
            got[order[-1]] += need                                    # nothing left anywhere: shown against the last source
        taken += sum(got.values())
        rows.append({"year": y, "draw_brokerage": got["brokerage"], "draw_sipp": got["sipp"], "draw_ira": got["ira"]})
    return pd.DataFrame(rows).set_index("year")


def run_cash_and_portfolio(inp: "Inputs", cf: "CashFlowInputs", pin: "PortfolioInputs"):
    """Tax summary, cash flow and portfolio together. v25.35: when cash is kept at the safety line, each draw is assigned to an account, and
    any taxable income it creates (gain on a brokerage sale, a SIPP or IRA withdrawal) goes back into that year's income and tax; repeated
    until it settles (it changes the draws only a little each time)."""
    inp.draw_income = {}
    ts, ts_info = run_tax_summary(inp)
    cf_df, cf_sum = run_cash_flow(ts, cf)
    pf = run_portfolio(ts, cf_df, cf, pin)
    for _ in range(15):
        if float(cf_df.drawdown.sum()) <= 0.5:
            break
        sp = split_draws(cf_df, pf, cf, pin)
        for col in sp.columns:
            cf_df[col] = sp[col]
        inc = {int(y): round(float(sp.loc[y, "draw_brokerage"]) * float(cf.brokerage_gain_share) + float(sp.loc[y, "draw_sipp"])
                             + float(sp.loc[y, "draw_ira"]), 2) for y in sp.index}
        inc = {y: v for y, v in inc.items() if v > 0.5}
        if all(abs(inc.get(y, 0.0) - float(inp.draw_income.get(y, 0.0))) < 1.0 for y in set(inc) | set(inp.draw_income)):
            pf = run_portfolio(ts, cf_df, cf, pin)
            break
        inp.draw_income = inc
        ts, ts_info = run_tax_summary(inp)
        cf_df, cf_sum = run_cash_flow(ts, cf)
        pf = run_portfolio(ts, cf_df, cf, pin)
    if "draw_brokerage" not in cf_df.columns and float(cf_df.drawdown.sum()) > 0.5:     # stopped before settling: label the last run's draws
        sp = split_draws(cf_df, pf, cf, pin)
        for col in sp.columns:
            cf_df[col] = sp[col]
        pf = run_portfolio(ts, cf_df, cf, pin)
    for col in ("draw_brokerage", "draw_sipp", "draw_ira"):
        if col not in cf_df.columns:
            cf_df[col] = 0.0
    cf_sum["draws_by_source"] = {k: float(cf_df[f"draw_{k}"].sum()) for k in ("brokerage", "sipp", "ira")}
    return ts, ts_info, cf_df, cf_sum, pf


def roth_auto_on(plan) -> bool:
    return bool(plan.expenses.get("roth_auto", True))


def rmd_cap(plan) -> float:
    return float(plan.expenses.get("rmd_goal", 100000.0))


def roth_total_for_cap(inp, pin, plan) -> float:
    """v25.42: the conversion total that brings the first RMD (2043, Schwab IRA) down to the cap, at the pre-tax growth rate. Rounded up to
    the next $1,000. 0 when the RMD is under the cap without converting."""
    i0 = _copy.deepcopy(inp)
    i0.roth_total = 0.0
    ts0, _ = run_tax_summary(i0)
    t = solve_total_for_rmd(ts0, i0, pin, rmd_cap(plan), ("ira",))
    return 3000000.0 if t is None else float(math.ceil(t / 1000.0) * 1000.0)


def run_core(plan, inp, cf, pin, auto: bool):
    """v25.45: tax, cash flow and portfolio, with investment income following the after-tax balance (today's yield, a little higher from the
    shift year for the bonds) and the conversions sized to the RMD cap -- repeated until the income settles, since the income changes the
    tax, the tax changes the balance, and the balance changes the income."""
    inp.income_proj = {}
    y0 = None
    out = None
    for _ in range(6):
        if auto:
            inp.roth_total = roth_total_for_cap(inp, pin, plan)
        out = run_cash_and_portfolio(inp, cf, pin)
        ts, pf = out[0], out[4]
        if inp.base_income_override is not None or not plan.expenses.get("income_grows", True):
            break
        if y0 is None:
            y0 = float(ts.loc[FIRST_YEAR, "base_income"]) / max(1.0, float(pf.loc[FIRST_YEAR, "beg_taxable"]))
        new = {int(y): round(max(0.0, float(pf.loc[y, "beg_taxable"])) * (y0 + (pin.income_yield_bump if y >= pin.shift_year else 0.0)), 2)
               for y in ts.index if y > FIRST_YEAR}
        if inp.income_proj and all(abs(new[y] - float(inp.income_proj.get(y, 0.0))) < 50.0 for y in new):
            break
        inp.income_proj = new
    return out


def run_model(plan: Plan, s: dict, entries: dict) -> dict:
    inp, ai, cf, pin = build_inputs(plan, s, entries)
    ts, ts_info, cf_df, cf_sum, pf = run_core(plan, inp, cf, pin, roth_auto_on(plan) and not s.get("roth_manual"))
    irm, irm_sum = run_irmaa_scenario(ts, inp, ai)
    cap = roth_capacity(ts, inp, ai)
    sched = defcomp_schedule(inp.defcomp)
    year = int(s["aca_year"])
    mon_df, mon = aca_monthly_monitor(ts, sched, aca_monthly_frame(entries, plan, s, year), year, ai.aca,
                                      one_time_items=float(s["one_time"]),
                                      inv_weights=invest_weights(entries, year - 1, inp.defcomp.withholding_rate))
    window = aca_year_end_window(year, mon["finalized_actual"], mon["remaining_plan"], float(s["one_time"]), ai.aca, mon["year_adjust"])
    rmd_ira = rmd_from_accounts(ts, pin, ("ira",))
    rmd_both = rmd_from_accounts(ts, pin, ("ira", "empower"))
    return {"ts": ts, "ts_info": ts_info, "cf": cf_df, "cf_sum": cf_sum, "pf": pf, "irm": irm, "irm_sum": irm_sum,
            "cap": cap, "aca_df": mon_df, "aca": mon, "window": window, "rmd_ira": rmd_ira, "rmd_both": rmd_both,
            "aca_year": year, "limits": dict(ai.aca.limit_by_year), "warning": ai.aca.warning_target, "roth_total": float(inp.roth_total),
            "early_conv": {int(y): float(v) for y, v in ts.early_conversion.items() if v > 0.5},
            "edges": ai.irmaa, "buffer_irmaa": 5000.0}


# ---- fast RMD-goal solver (array based; matches solve_roth_total_accounts) ------------------
def solve_total_for_rmd(ts: pd.DataFrame, inp: Inputs, pin: PortfolioInputs, target: float, eligible=("ira",),
                        divisor: float = RMD_DIVISOR_AGE_75, rmd_year: int = 2043, hi: float = 6e6):
    yrs = list(ts.index)
    win = [y for y in yrs if inp.roth_first_year <= y <= inp.roth_last_year]
    non_roth = (ts.base_income + ts.defcomp + ts.annuity_gain + ts.ss_taxable + ts.other_magi).loc[win].to_numpy()
    upto = yrs.index(rmd_year - 1)

    def rmd_for(total: float) -> float:
        conv, _, _ = level_conversions(non_roth, total)
        cmap = dict(zip(win, conv))
        ira, emp, sipp = pin.ira, pin.empower, pin.sipp
        for y in yrs[: upto + 1]:
            g = g_pre(pin, y)
            ira = max(0.0, ira * (1 + g) - (cmap[y] if y in cmap else float(ts.loc[y, "roth_conversion"])) - ts.loc[y, "rmd_target"])
            emp = max(0.0, emp * (1 + g) - ts.loc[y, "defcomp"])
            sipp = sipp * (1 + g)
        bal = {"ira": ira, "empower": emp, "sipp": sipp}
        return sum(bal[a] for a in eligible) / divisor

    if rmd_for(0.0) <= target:
        return 0.0
    if rmd_for(hi) > target:
        return None
    lo, up = 0.0, hi
    for _ in range(60):
        mid = (lo + up) / 2
        lo, up = (mid, up) if rmd_for(mid) > target else (lo, mid)
    return (lo + up) / 2


def derived_totals(plan: Plan, s: dict, entries: dict) -> list[dict]:
    """Totals that hit each RMD goal exactly, for both readings of the $80,000 and both eligibility bases."""
    inp, ai, cf, pin = build_inputs(plan, s, entries)
    ts, _ = run_tax_summary(inp)
    workbook_goal = float(ts.loc[2043, "living_cost"])
    plain = float(plan.expenses.get("rmd_goal", 60000.0))
    goals = [(f"${plain:,.0f} in 2043", plain), (f"Plan goal, ${workbook_goal:,.0f} in 2043", workbook_goal)]
    out = []
    for gl, tgt in goals:
        for el_label, el in (("Schwab IRA only", ("ira",)), ("IRA and Empower", ("ira", "empower"))):
            total = solve_total_for_rmd(ts, inp, pin, tgt, el)
            row = {"goal": gl, "counts": el_label, "total": total, "magi": None}
            if total is not None:
                i2 = _copy.deepcopy(inp); i2.roth_total = total
                row["magi"] = run_tax_summary(i2)[1]["roth_target_magi"]
            out.append(row)
    return out


# ---- rows, repeating items, yearly spending control, history ------------------------------------------------------
def new_id() -> str:
    return _uuid.uuid4().hex[:10]


def ensure_ids(rows: list[dict]) -> None:
    for r in rows:
        if not r.get("id"):
            r["id"] = new_id()


def next_month_key(key: str) -> str:
    y, m = map(int, key.split("-"))
    return f"{y + 1}-01" if m == 12 else f"{y}-{m + 1:02d}"


def ensure_recurring_lines(plan: Plan, entries: dict, months: list[str]) -> int:
    """Every month a repeating item is due gets one pending Core line for it (created once, never duplicated)."""
    added = 0
    for x in plan.recurring.extras:
        for k in months:
            if not extra_active(x, k):
                continue
            rows = entries["ledger"].get(k, [])
            if any(r.get("recur") == x["id"] for r in rows):
                continue
            y, m = map(int, k.split("-"))
            day = min(int(x.get("day", 1) or 1), pd.Timestamp(y, m, 1).days_in_month)
            entries["ledger"].setdefault(k, []).append(
                {"id": new_id(), "date": f"{k}-{day:02d}", "desc": x["name"], "credit": None, "debit": float(x["amount"]),
                 "rec": "Pending", "cls": "Core", "note": "Repeating", "recur": x["id"]})
            added += 1
    return added


def merged_monthly_items(rf: RecurringForecast, year: int) -> dict:
    """The 'Recurring items' table for one year: name -> amount, with the 2028-on overrides applied."""
    items = dict(rf.monthly)
    if year >= 2028:
        items.update(rf.monthly_from_2028)
    return items


def infer_monthly_day(entries: dict, name: str, months: list[str], today_date) -> int | None:
    """A default day of the month for a 'Recurring items' entry, read from the most recent reconciled Core line
    whose description matches it. None when nothing in the ledger looks like a match, so the app never guesses silently."""
    best = None
    for k in sorted((m for m in months if m <= f"{today_date.year}-{today_date.month:02d}"), reverse=True):
        for r in entries.get("ledger", {}).get(k, []):
            if not is_reconciled(r) or str(r.get("cls", "")).lower() != "core" or _n(r.get("debit")) <= 0:
                continue
            if bank_overlap(name, r.get("desc", "")) < 1:
                continue
            try:
                day = _dt.date.fromisoformat(str(r["date"])).day
            except (ValueError, TypeError):
                continue
            if best is None or k > best[0]:
                best = (k, day)
        if best is not None:
            return best[1]
    return None


RECUR_GUESS_NOTE = "Recurring item, day guessed — replace with actual once you confirm it."
RECUR_CONFIRMED_NOTE = "Recurring item"


def ensure_monthly_recurring_lines(plan: Plan, entries: dict, months: list[str], today_date) -> int:
    """Every 'Recurring items' entry posts one pending Core line a month, across the whole plan horizon, the
    same way a repeating item does -- there is no opt-in step, because a budgeted item that posts nothing is a
    silent gap in the ledger, the balance outlook and every alert built on it. When you have not confirmed a day
    for an item, the day is read from a matching reconciled line if one exists, or day 1 otherwise, and the line
    is tagged so it shows up as needing review (the same 'Prefilled' flag used for the workbook's forecast lines),
    until you confirm or correct it. A month that already has a matching Core line -- reconciled OR still pending,
    whether posted by this same function earlier or entered by hand ahead of time -- is skipped, so nothing is
    ever duplicated or double counted against a bill you already added yourself. Self-healing in two ways: a stale
    pending guess now shadowing a real line for the same item (the bug this replaced) is removed here too, not
    just prevented going forward; and an unconfirmed guess already posted for a future month is re-guessed on
    every run, not frozen at whatever day it first guessed -- so once a bill you hadn't paid yet finally reconciles
    and teaches the app its real day, every later month's still-pending guess picks that day up too, immediately,
    not just new guesses from here on."""
    added = 0
    for k in months:
        year = int(k[:4])
        items = merged_monthly_items(plan.recurring, year)
        rows = entries["ledger"].setdefault(k, [])
        for name, amount in items.items():
            if recur_skipped(entries, name, k):
                continue                    # v25.22: you deleted this month's line; it stays deleted
            if not monthly_active(plan.recurring, name, k):        # v25.37: before it starts or after it ends -- no pending line
                rows[:] = [r for r in rows if not (r.get("recur_monthly") == name and not is_reconciled(r))]
                continue
            tagged_ids = {id(r) for r in rows if r.get("recur_monthly") == name}
            # v21.17: a line that belongs to ANOTHER recurring item never stands in for this one, and words such as CREDIT CARD don't count as a
            # match on their own. Before, "Costco credit card" (tagged as Costco) counted as the "One Pay credit card" bill, so One Pay was never
            # posted; and once Costco was set to $0, One Pay appeared and in turn removed the Costco line.
            other = any(id(r) not in tagged_ids and not r.get("recur_monthly") and str(r.get("cls", "")).lower() == "core" and _n(r.get("debit")) > 0
                        and item_overlap(name, r.get("desc", "")) >= 1 for r in rows)
            if other:
                stale = [r for r in rows if id(r) in tagged_ids and not is_reconciled(r)]
                for r in stale:
                    rows.remove(r)
                continue
            confirmed = plan.recurring.monthly_day.get(name)
            day = confirmed or infer_monthly_day(entries, name, months, today_date) or 1
            y, m = map(int, k.split("-"))
            day = min(int(day), pd.Timestamp(y, m, 1).days_in_month)
            if tagged_ids:
                for r in rows:
                    if id(r) not in tagged_ids or is_reconciled(r):
                        continue
                    if confirmed is None and r.get("date") != f"{k}-{day:02d}":
                        r["date"] = f"{k}-{day:02d}"
                    # the item's amount changed (Your data): every still-pending line follows it, the way a confirmed day already does --
                    # except a line whose amount you set by hand for that one month
                    if not r.get("hand_amt") and abs(_n(r.get("debit")) - float(amount)) >= 0.005:
                        r["debit"] = float(amount)
                continue
            if k < f"{today_date.year}-{today_date.month:02d}":
                continue                    # v21.17: never post a new guess into a month that has already passed
            rows.append({"id": new_id(), "date": f"{k}-{day:02d}", "desc": name, "credit": None, "debit": float(amount),
                        "rec": "Pending", "cls": "Core", "note": RECUR_CONFIRMED_NOTE if confirmed else RECUR_GUESS_NOTE,
                        "recur_monthly": name})
            added += 1
    return added


def confirm_monthly_day(plan: Plan, entries: dict, name: str, day: int, months: list[str]) -> int:
    """Save the confirmed day for a 'Recurring items' entry, and correct every pending line already posted for it
    (guessed or previously confirmed) to that day, clearing the 'needs review' flag. Returns lines corrected."""
    plan.recurring.monthly_day[name] = int(day)
    n = 0
    for k in months:
        for r in entries.get("ledger", {}).get(k, []):
            if r.get("recur_monthly") == name and not is_reconciled(r):
                y, m = map(int, k.split("-"))
                d = min(int(day), pd.Timestamp(y, m, 1).days_in_month)
                r["date"], r["note"] = f"{k}-{d:02d}", RECUR_CONFIRMED_NOTE
                n += 1
    return n


def infer_income_line(entries: dict, name: str, months: list[str], today_date) -> tuple[int | None, float | None]:
    """A default (day, amount) for a recurring deposit, read from the most recent reconciled credit line
    whose description matches it -- both None when nothing in the ledger looks like a match yet, since an
    amount can't be guessed out of thin air the way an expense's amount can (it's already budgeted elsewhere)."""
    best = None
    for k in sorted((m for m in months if m <= f"{today_date.year}-{today_date.month:02d}"), reverse=True):
        for r in entries.get("ledger", {}).get(k, []):
            if not is_reconciled(r) or _n(r.get("credit")) <= 0 or _is_savings_transfer(r):
                continue
            if bank_overlap(name, r.get("desc", "")) < 1:
                continue
            try:
                day = _dt.date.fromisoformat(str(r["date"])).day
            except (ValueError, TypeError):
                continue
            if best is None or k > best[0]:
                best = (k, day, _n(r.get("credit")))
        if best is not None:
            return best[1], best[2]
    return None, None


RECUR_INCOME_GUESS_NOTE = "Recurring deposit, amount guessed — replace with actual once you confirm it, or set DefComp's fixed amount for the year on the Spending page."
RECUR_INCOME_FIXED_NOTE = "Recurring deposit, from your fixed total and DefComp amount"


def _is_savings_transfer(r: dict) -> bool:
    """A transfer from savings (scheduled, one-tap, or the workbook's one-time ones). It shares the word 'savings' with the
    'Savings deposit' recurring item, so without this check it was mistaken for that month's Savings deposit and the real
    deposit line was removed -- a month with a transfer on it suddenly lost thousands of dollars of income."""
    d = str(r.get("desc", "")).lower()
    return bool(r.get("xfer")) or d.startswith("transfer from savings") or d.startswith("one-time savings transfer")


def posted_credit(rows: list[dict], name: str) -> float:
    """Whatever is already on the ledger this month for a recurring deposit -- guessed or a real line entered by
    hand or the bank -- used as DefComp's stand-in only for a year that has no fixed defcomp_year_amount yet."""
    return sum(_n(r.get("credit")) for r in rows if _n(r.get("credit")) > 0 and not _is_savings_transfer(r) and bank_overlap(name, r.get("desc", "")) >= 1)


def defcomp_amount_for_year(plan: Plan, year: int) -> float | None:
    """DefComp payment's fixed monthly amount for `year`: that year's own entry in defcomp_year_amount if there is
    one, else the closest earlier year that has one, else None (nothing has ever been set for it or any earlier
    year, so the caller falls back to the old ledger-inferred guess)."""
    ys = plan.recurring.defcomp_year_amount
    if str(year) in ys:
        return float(ys[str(year)])
    earlier = [int(y) for y in ys if int(y) <= year]
    return float(ys[str(max(earlier))]) if earlier else None


def ensure_income_recurring_lines(plan: Plan, entries: dict, months: list[str], today_date) -> int:
    """Mirror image of ensure_monthly_recurring_lines, for the credit side: Savings deposit and DefComp payment
    are expected every month same as any recurring bill, so a forecast that posts recurring expenses forward but
    not recurring income overstates every future shortfall. There are only ever two of these, and the relationship
    between them is fixed, not dynamic: DefComp payment is a flat amount set per calendar year (defcomp_year_amount),
    since it pays what the plan says it pays, not what last happened to land in the bank; Savings deposit is always
    monthly_funding_target() (the Core budget for that month's year, amortized, plus the buffer -- Core budget and
    the required deposit are one and the same thing) minus that same month's DefComp payment, a plain subtraction --
    never topped up against whatever has already posted, and never confirmed to some other flat figure of its own,
    so the two can never silently drift apart or add up to more than the target (Andrew's call, September 2026: the
    old 'top up to whatever's left after DefComp already posted' version let Savings get locked in at a stale figure
    that no longer matched, so the two together quietly exceeded the intended total). A year with no fixed DefComp
    amount at all falls back to the old guess -- the most recent matching reconciled deposit -- and Savings is sized
    off that guess instead, flagged for review the same as DefComp's own guess is. Skips a month that already has a
    matching credit line, pending or reconciled, so nothing is duplicated. Self-healing three ways: a stale pending
    guess now shadowing a real matching deposit is removed, not just prevented going forward; an unconfirmed guess
    already posted for a future month is re-computed on every run, not frozen at whatever day or amount it first
    guessed -- so a newly-applied Core budget, a changed per-year DefComp figure, or a DefComp payment that just
    reconciled is picked up immediately in every later month's still-pending guess; and every tagged line is forced
    back to prio 0 on every run too, not just when first posted -- a line created before that field existed (or by
    an earlier version of this function) would otherwise sit tied with a same-day bill at the default priority
    forever, silently reopening the exact phantom same-day dip the prio fix exists to prevent."""
    added = 0
    for k in months:
        rows = entries["ledger"].setdefault(k, [])
        year = int(k[:4])
        fixed_defcomp = defcomp_amount_for_year(plan, year)
        target = monthly_funding_target(plan, year)
        for name in RECURRING_INCOME_ITEMS:
            confirmed_day = plan.recurring.income_day.get(name)
            if recur_skipped(entries, "income:" + name, k):
                continue                    # v25.22: you deleted this month's deposit line; it stays deleted
            tagged_ids = {id(r) for r in rows if r.get("recur_income") == name}
            other = any(id(r) not in tagged_ids and _n(r.get("credit")) > 0 and not _is_savings_transfer(r)
                        and bank_overlap(name, r.get("desc", "")) >= 1 for r in rows)
            if other:
                stale = [r for r in rows if id(r) in tagged_ids and not is_reconciled(r)]
                for r in stale:
                    rows.remove(r)
                continue
            g_day, g_amount = infer_income_line(entries, name, months, today_date)
            if name == "DefComp payment":
                amount = fixed_defcomp if fixed_defcomp is not None else g_amount
            else:
                defcomp_this_month = fixed_defcomp if fixed_defcomp is not None else posted_credit(rows, "DefComp payment")
                amount = round(max(0.0, target - defcomp_this_month), 2)
            day = confirmed_day or g_day or 1
            fixed_note = fixed_defcomp is not None
            if tagged_ids:
                y, m = map(int, k.split("-"))
                d = min(int(day), pd.Timestamp(y, m, 1).days_in_month) if (day and amount) else None
                note = RECUR_INCOME_FIXED_NOTE if fixed_note else RECUR_INCOME_GUESS_NOTE
                for r in rows:
                    if id(r) in tagged_ids and not is_reconciled(r):
                        # A line posted before the same-day-ordering fix existed (or before this fix's own
                        # backfill) never got 'prio': 0 in the first place, and nothing else here ever revisits
                        # it -- so it silently stayed tied with same-day bills at the default priority forever,
                        # reintroducing the exact phantom same-day dip the prio fix was supposed to prevent.
                        # Enforced on every run, on every tagged line, not just newly posted ones.
                        if r.get("prio") != 0:
                            r["prio"] = 0
                        if r.get("note") != note:
                            r["note"] = note
                        if d is not None:
                            new_date = f"{k}-{d:02d}"
                            if r.get("date") != new_date or round(_n(r.get("credit")), 2) != round(amount, 2):
                                r["date"], r["credit"] = new_date, float(amount)
                continue
            if not day or not amount:
                continue
            y, m = map(int, k.split("-"))
            day = min(int(day), pd.Timestamp(y, m, 1).days_in_month)
            note = RECUR_INCOME_FIXED_NOTE if fixed_note else RECUR_INCOME_GUESS_NOTE
            # prio 0, same as a scheduled transfer from savings: a same-day deposit lands before same-day spending,
            # so a bill and a deposit both defaulting to day 1 don't create a same-day phantom dip in the running balance.
            rows.append({"id": new_id(), "date": f"{k}-{day:02d}", "desc": name, "credit": float(amount), "debit": None,
                        "rec": "Pending", "cls": "Excluded", "note": note, "recur_income": name, "prio": 0})
            added += 1
    return added


def confirm_income_day(plan: Plan, entries: dict, name: str, day: int, months: list[str]) -> int:
    """Save the confirmed day of the month for a recurring deposit (DefComp payment or Savings deposit), and
    correct every pending line already posted for it to that day. Returns lines corrected. Only the day is ever
    confirmed this way -- DefComp's amount comes from its fixed per-year figure (or the ledger guess, if it
    doesn't have one yet) and Savings deposit's is always the total minus DefComp, so there is no separate flat
    amount left to lock in or reset here."""
    plan.recurring.income_day[name] = int(day)
    n = 0
    for k in months:
        for r in entries.get("ledger", {}).get(k, []):
            if r.get("recur_income") == name and not is_reconciled(r):
                y, m = map(int, k.split("-"))
                d = min(int(day), pd.Timestamp(y, m, 1).days_in_month)
                r["date"] = f"{k}-{d:02d}"
                n += 1
    return n


RECUR_ANNUAL_CONFIRMED_NOTE = "Scheduled bill"


def ensure_annual_bill_lines(plan: Plan, entries: dict, months: list[str], today_date) -> int:
    """'Scheduled annual bills' used to be nothing but a yearly budget total -- no date anywhere, so the balance
    outlook and every alert built from it never saw it (the real source of the February dip Andrew reported: real
    annual bills that had simply never been posted to the ledger at all). Posts one pending Core line per
    confirmed due date, the same self-healing way Recurring items and Recurring deposits already post forward.
    Every occurrence needs a confirmed month and day (plan.recurring.annual_bill_day[name], a list of {month, day}
    dicts) -- unlike a monthly item there's no safe 'day 1' default for something that happens once a year, so an
    item with no confirmed date yet posts nothing, on purpose, rather than guess a month that could be off by any
    amount. A name can have more than one date a year (Auto insurance's two semiannual payments): each occurrence
    gets its own pending line, tagged with a compound name#month key so the two never collide, and the resolved
    annual total (annual_bill_amount_for -- which already applies year-specific overrides, like a tax bill's own
    multi-year schedule) is split evenly across however many occurrences that name has. Self-healing the same way
    as the other recurring posters: a month that already has a real matching Core line (reconciled or pending,
    entered by hand or from the bank) skips posting and removes any stale pending guess shadowing it; and an
    already-posted, not-yet-reconciled line has its date and amount refreshed on every run, so confirming a date
    for the first time, or a year-specific override changing after the line already posted, is picked up
    immediately instead of freezing at whatever it first posted."""
    added = 0
    cur = f"{today_date.year}-{today_date.month:02d}"
    due_months = {nm: {int(o.get("month", 0)) for o in (oc if isinstance(oc, list) else [oc])} for nm, oc in plan.recurring.annual_bill_day.items()}
    for k, rows in entries.get("ledger", {}).items():            # v21.27: a bill moved to other dates (or paid less often) drops its
        if k < cur:                                               # now-unused pending lines from this month on; past months are left alone
            continue
        for r in list(rows):
            tag = r.get("recur_annual")
            if not tag or "#" not in tag or is_reconciled(r):
                continue
            nm, mm = tag.rsplit("#", 1)
            if nm in due_months and int(mm) not in due_months[nm]:
                rows.remove(r)
    for k in months:
        year, month = int(k[:4]), int(k[5:7])
        rows = entries["ledger"].setdefault(k, [])
        for name, occurrences in plan.recurring.annual_bill_day.items():
            occ_list = [o for o in occurrences] if isinstance(occurrences, list) else [occurrences]
            due_here = [o for o in occ_list if int(o.get("month", 0)) == month]
            if not due_here or not occ_list:
                continue
            per_occurrence = round(annual_bill_amount_for(plan.recurring, name, year) / len(occ_list), 2)
            for occ in due_here:
                tag = f"{name}#{int(occ['month']):02d}"
                if recur_skipped(entries, tag, k):
                    continue                                 # v25.22: you deleted this one; it stays deleted
                tagged_ids = {id(r) for r in rows if r.get("recur_annual") == tag}
                other = any(id(r) not in tagged_ids and not r.get("recur_monthly") and not r.get("recur_annual")       # v21.26: not another item's line
                            and str(r.get("cls", "")).lower() == "core" and _n(r.get("debit")) > 0
                            and item_overlap(name, r.get("desc", "")) >= 1 for r in rows)
                if other:
                    stale = [r for r in rows if id(r) in tagged_ids and not is_reconciled(r)]
                    for r in stale:
                        rows.remove(r)
                    continue
                day = min(int(occ.get("day", 1)), pd.Timestamp(year, month, 1).days_in_month)
                if tagged_ids:
                    for r in rows:
                        if id(r) in tagged_ids and not is_reconciled(r) and not r.get("hand_amt"):    # v25.29: an edited line stays as edited
                            new_date = f"{k}-{day:02d}"
                            if r.get("date") != new_date or round(_n(r.get("debit")), 2) != per_occurrence:
                                r["date"], r["debit"] = new_date, float(per_occurrence)
                    continue
                if k < f"{today_date.year}-{today_date.month:02d}":
                    continue                                 # v21.26: never post a new line into a month already past
                rows.append({"id": new_id(), "date": f"{k}-{day:02d}", "desc": name, "credit": None,
                            "debit": float(per_occurrence), "rec": "Pending", "cls": "Core",
                            "note": RECUR_ANNUAL_CONFIRMED_NOTE, "recur_annual": tag})
                added += 1
    return added


def confirm_annual_bill_dates(plan: Plan, name: str, occurrences: list[dict]) -> None:
    """Save the confirmed due date(s) for a 'Scheduled annual bills' item -- a list of {'month': M, 'day': D},
    one entry per payment in a year. ensure_annual_bill_lines picks the change up (and refreshes any already-posted
    pending line) the next time it runs, same as every other recurring poster."""
    plan.recurring.annual_bill_day[name] = [{"month": int(o["month"]), "day": int(o["day"])} for o in occurrences]


def _month_or_zero(v) -> int:
    """A month/day cell from the 'Check the due date for each bill' editor: a real number, or None/NaN when the
    person cleared it (deliberately, to leave a bill unconfirmed -- Auto insurance paid by credit card, say).
    Treated as 0 rather than raised, so clearing a cell to opt a bill back out can never crash the Save button."""
    try:
        return 0 if v is None or v != v else int(v)   # 'v != v' is true only for NaN, float or numpy
    except (TypeError, ValueError):
        return 0


def parse_annual_bill_date_rows(rows: list[dict]) -> dict:
    """Turn edited 'Check the due date for each bill' rows ({'Bill', 'Month 1', 'Day 1', 'Month 2', 'Day 2'}) into
    {name: [{'month', 'day'}, ...]}, ready for confirm_annual_bill_dates -- one occurrence per non-empty month.
    A row with both months blank/0 (an item left off the list on purpose) contributes nothing, not an empty list,
    so calling code can skip it rather than confirm zero dates for it."""
    out = {}
    for row in rows:
        occs = []
        for i in (1, 2, 3, 4):                                   # v21.26: up to four payments a year (quarterly bills)
            mi = _month_or_zero(row.get(f"Month {i}"))
            if mi:
                occs.append({"month": mi, "day": _month_or_zero(row.get(f"Day {i}")) or 1})
        if occs:
            out[row["Bill"]] = occs
    return out


BILL_FREQUENCIES = {"Monthly": 12, "Every two months": 6, "Quarterly": 4, "Twice a year": 2, "Annually": 1}
SCHEDULED_FREQUENCIES = {k: v for k, v in BILL_FREQUENCIES.items() if v != 12}      # the ones kept as scheduled bills (monthly ones are Recurring items)


def bill_dates(per_year: int, month: int, day: int) -> list[dict]:
    """The due dates for a bill paid per_year times a year (1, 2, 4 or 6), equally spaced from one known due date."""
    step = 12 // per_year
    return sorted(({"month": (int(month) - 1 + i * step) % 12 + 1, "day": int(day)} for i in range(per_year)), key=lambda o: o["month"])


def bill_frequency(occs: list[dict]) -> str | None:
    """The frequency a scheduled bill's dates follow ('Quarterly' ...), or None when they are not equally spaced on one day (a custom set)."""
    if not occs:
        return None
    n = len(occs)
    name = next((k for k, v in SCHEDULED_FREQUENCIES.items() if v == n), None)
    if name and occs == bill_dates(n, occs[0]["month"], occs[0]["day"]):
        return name
    return None


def bill_next_due(occs: list[dict], today_date) -> tuple[int, int]:
    """(month, day) of the next due date on or after today, for showing and editing a bill by its next payment."""
    for k in range(13):
        y, m = divmod(today_date.year * 12 + today_date.month - 1 + k, 12)
        for o in occs:
            if o["month"] == m + 1:
                if k == 0 and o["day"] < today_date.day:
                    continue
                return o["month"], o["day"]
    return occs[0]["month"], occs[0]["day"]


def _pending_lines_for(entries: dict, name: str) -> int:
    """How many unreconciled lines carry this item's name (for the 'added' message, which shouldn't count other items' catch-up lines)."""
    return sum(1 for rows in entries.get("ledger", {}).values() for r in rows if r.get("desc") == name and not is_reconciled(r))


def add_recurring_bill(plan: Plan, entries: dict, name: str, amount_each: float, per_year: int, first_due, months: list[str], today_date):
    """v21.27: one way to add any recurring bill -- monthly, every two months, quarterly, twice a year or annually -- from a name, the amount
    paid each time and the next due date. A monthly bill joins the Recurring items (posted on that day each month); the others become
    scheduled bills whose due dates follow from the next one, with the yearly total (amount x payments a year) split back evenly when
    posted. Returns (ok, message)."""
    name = " ".join(str(name or "").split())
    rf = plan.recurring
    if not name or amount_each <= 0 or per_year not in BILL_FREQUENCIES.values():
        return False, "Enter a name, an amount and how often."
    taken = set(rf.monthly) | set(rf.monthly_from_2028) | set(rf.annual_bills) | set(rf.annual_bills_from_2028) | set(rf.annual_bill_day) \
        | {x.get("name") for x in rf.extras}
    if name in taken:
        return False, f"There is already an item called {name}."
    if per_year == 12:
        rf.monthly[name] = round(float(amount_each), 2)
        rf.monthly_day[name] = int(first_due.day)
        if first_due.strftime("%Y-%m") > today_date.strftime("%Y-%m"):
            rf.monthly_start[name] = first_due.strftime("%Y-%m")      # v25.37: nothing posts before the first due date
        ensure_monthly_recurring_lines(plan, entries, months, today_date)
        n = _pending_lines_for(entries, name)
        return True, (f"{name} added: {money(amount_each, 2)} on day {first_due.day} of every month ({money(amount_each * 12, 2)} a year); "
                      f"{n} pending line{'s' if n != 1 else ''} posted.")
    occs = bill_dates(per_year, first_due.month, first_due.day)
    rf.annual_bills[name] = round(float(amount_each) * per_year, 2)
    confirm_annual_bill_dates(plan, name, occs)
    ensure_annual_bill_lines(plan, entries, months, today_date)
    n = _pending_lines_for(entries, name)
    when = ", ".join(f"{MONTH_NAMES[o['month'] - 1][:3]} {o['day']}" for o in occs)
    return True, f"{name} added: {money(amount_each, 2)} on {when} each year ({money(amount_each * per_year, 2)} a year); {n} pending line{'s' if n != 1 else ''} posted."


def retime_bill(plan: Plan, name: str, per_year: int, month: int, day: int, year: int) -> None:
    """Change how often a scheduled bill is paid (or when), keeping what is paid each time: the yearly figure is rescaled to the new count."""
    rf = plan.recurring
    old = rf.annual_bill_day.get(name) or []
    if old and len(old) != per_year:
        each = annual_bill_amount_for(rf, name, year) / len(old)
        rf.annual_bills[name] = round(each * per_year, 2)
        if name in rf.annual_bills_from_2028:
            rf.annual_bills_from_2028[name] = round(rf.annual_bills_from_2028[name] / len(old) * per_year, 2)
    confirm_annual_bill_dates(plan, name, bill_dates(per_year, month, day))


def remove_monthly_item(plan: Plan, entries: dict, name: str) -> int:
    """Drop a monthly Recurring item entirely, with its pending lines (reconciled ones stay as the record). Returns how many lines went."""
    rf = plan.recurring
    for d in (rf.monthly, rf.monthly_from_2028, rf.monthly_day, rf.monthly_start, rf.monthly_end):
        d.pop(name, None)
    n = 0
    for k, rows in entries["ledger"].items():
        keep = [r for r in rows if not (r.get("recur_monthly") == name and not is_reconciled(r))]
        n += len(rows) - len(keep)
        entries["ledger"][k] = keep
    return n


def _next_monthly_date(day: int, today_date) -> _dt.date:
    """The next date on or after today that falls on this day of the month (short months use their last day)."""
    for k in range(2):
        y, m = divmod(today_date.year * 12 + today_date.month - 1 + k, 12)
        d = _dt.date(y, m + 1, min(int(day), pd.Timestamp(y, m + 1, 1).days_in_month))
        if d >= today_date:
            return d
    return d


def _next_bill_date(occs: list[dict], today_date) -> _dt.date:
    m, d = bill_next_due(occs, today_date)
    y = today_date.year if (m, d) >= (today_date.month, today_date.day) else today_date.year + 1
    return _dt.date(y, m, min(int(d), pd.Timestamp(y, m, 1).days_in_month))


def all_recurring_bills(plan: Plan, entries: dict, months: list[str], today_date, year: int) -> list[dict]:
    """v21.29: every recurring bill in one list -- monthly items, bills paid every 2, 3, 6 or 12 months, and repeating items
    ticked on the ledger -- each with how often, the next due date, the amount each time and the yearly total, soonest first.
    kind: 'monthly', 'scheduled' or 'extra'."""
    rf, out = plan.recurring, []
    for name, amt in merged_monthly_items(rf, year).items():
        day = rf.monthly_day.get(name)
        guess = None if day else (infer_monthly_day(entries, name, months, today_date) or 1)
        note = f"{money(rf.monthly_from_2028[name], 2)} a month from 2028" if name in rf.monthly_from_2028 and year < 2028 else ""
        sm, em = rf.monthly_start.get(name), rf.monthly_end.get(name)
        nxt = _next_monthly_date(day or guess, today_date)
        if em and nxt.strftime("%Y-%m") > em:
            continue                                                   # v25.38: ended -- no payment left to come
        if sm and nxt.strftime("%Y-%m") < sm:
            y_, m_ = int(sm[:4]), int(sm[5:7])
            nxt = _dt.date(y_, m_, min(int(day or guess), pd.Timestamp(y_, m_, 1).days_in_month))
        note = "; ".join(x for x in (note, f"from {month_label(sm)}" if sm and sm > today_date.strftime("%Y-%m") else "",
                                     f"last payment {month_label(em)}" if em else "") if x)
        out.append({"name": name, "kind": "monthly", "freq": "Monthly", "per_year": 12, "next": nxt,
                    "each": float(amt), "year_total": float(amt) * 12, "note": note, "status": "Confirmed" if day else "Day guessed, check it",
                    "locked_freq": name in rf.monthly_from_2028, "locked_amt": False})
    names = sorted(set(rf.annual_bills) | set(rf.annual_bills_from_2028) | set(rf.annual_bill_year_amounts))
    for name in names:
        occ = rf.annual_bill_day.get(name) or []
        total = annual_bill_amount_for(rf, name, year)
        fq = bill_frequency(occ) if occ else None
        notes = []
        if rf.annual_bill_year_amounts.get(name):
            notes.append("amount set by year")
        if name in rf.annual_bills_from_2028 and year < 2028 and not rf.annual_bill_year_amounts.get(name):
            notes.append(f"{money(rf.annual_bills_from_2028[name])} a year from 2028")
        if occ and fq is None:
            notes.append("custom dates: " + ", ".join(f"{MONTH_NAMES[o['month'] - 1][:3]} {o['day']}" for o in occ))
        out.append({"name": name, "kind": "scheduled", "freq": fq or (f"{len(occ)} dates a year" if occ else "Not set"),
                    "per_year": len(occ) or 1, "next": _next_bill_date(occ, today_date) if occ else None,
                    "each": total / max(1, len(occ)), "year_total": total, "note": "; ".join(notes),
                    "status": "Confirmed" if occ else "No due date yet -- nothing posts until you set one",
                    "locked_freq": bool(rf.annual_bill_year_amounts.get(name) or name in rf.annual_bills_from_2028) or (bool(occ) and fq is None),
                    "locked_amt": bool(rf.annual_bill_year_amounts.get(name))})
    cur = f"{today_date.year}-{today_date.month:02d}"
    for x in rf.extras:
        if x.get("until") and x["until"] < cur:
            continue
        start = max(x.get("from") or cur, cur)
        y0, m0 = int(start[:4]), int(start[5:7])
        nd = _next_monthly_date(int(x.get("day", 1)), max(today_date, _dt.date(y0, m0, 1)))
        until = f"until {month_label(x['until'])}" if x.get("until") else ""
        out.append({"name": x["name"], "kind": "extra", "freq": "Monthly", "per_year": 12, "next": nd, "each": float(x["amount"]),
                    "year_total": float(x["amount"]) * 12, "note": ("added from the ledger " + until).strip(), "status": "Change or stop it below",
                    "locked_freq": True, "locked_amt": True})
    out.sort(key=lambda b: (b["next"] is None, b["next"] or _dt.date.max, b["name"].lower()))
    return out


def apply_bill_edits(plan: Plan, entries: dict, before: list[dict], rows: list[dict], months: list[str], today_date, year: int) -> tuple[int, list[str]]:
    """Save the 'Change a bill' editor: per bill, a new frequency (monthly <-> every 2/3/6/12 months included), a new next due date and a
    new amount each time. Returns (bills changed, notes on anything that could not be changed)."""
    rf, by_name, changed, notes = plan.recurring, {b["name"]: b for b in before}, 0, []
    for row in rows:
        b = by_name.get(row.get("Bill"))
        if not b or b["kind"] == "extra":
            continue
        name, freq = b["name"], row.get("How often") or b["freq"]
        nd = row.get("Next due")
        if nd is not None and not isinstance(nd, _dt.date):
            try:
                nd = pd.Timestamp(nd).date()
            except (TypeError, ValueError):
                nd = None
        if nd is not None and nd != nd:
            nd = None
        try:
            each = round(float(row.get("Each time")), 2)
            each = each if each == each else b["each"]
        except (TypeError, ValueError):
            each = b["each"]
        n_new = BILL_FREQUENCIES.get(freq)
        amt_changed = abs(each - b["each"]) >= 0.005
        freq_changed = n_new is not None and freq != b["freq"]
        date_changed = nd is not None and nd != b["next"]
        if not (amt_changed or freq_changed or date_changed):
            continue
        if freq_changed and b["locked_freq"]:
            notes.append(f"{name}: how often was left as it is (it has amounts set by year, a 2028 change or custom dates).")
            freq_changed, n_new = False, b["per_year"]
        if amt_changed and b["locked_amt"]:
            notes.append(f"{name}: the amount is set by year; change it under Year-specific amounts.")
            amt_changed = False
        if not (amt_changed or freq_changed or date_changed):
            continue
        if b["kind"] == "monthly":
            if freq_changed and n_new != 12:
                d = nd or b["next"]
                remove_monthly_item(plan, entries, name)
                rf.annual_bills[name] = round(each * n_new, 2)
                confirm_annual_bill_dates(plan, name, bill_dates(n_new, d.month, d.day))
                changed += 1
                continue
            if amt_changed:
                rf.monthly[name] = each
            if date_changed and nd is not None:                       # v25.37: a next due date in a later month starts the bill then
                if nd.strftime("%Y-%m") > today_date.strftime("%Y-%m"):
                    rf.monthly_start[name] = nd.strftime("%Y-%m")
                else:
                    rf.monthly_start.pop(name, None)
            if date_changed or nd is not None and name not in rf.monthly_day:
                confirm_monthly_day(plan, entries, name, (nd or b["next"]).day, months)
            changed += 1
            continue
        # a scheduled bill
        if freq_changed and n_new == 12:
            d = nd or b["next"] or today_date
            remove_annual_bill(plan, entries, name)
            rf.monthly[name] = each
            rf.monthly_day[name] = d.day
            changed += 1
            continue
        if nd is None and not rf.annual_bill_day.get(name):
            if amt_changed or freq_changed:
                notes.append(f"{name}: set its next due date as well, so it knows when to post.")
            continue
        n = n_new if freq_changed else (b["per_year"] if b["freq"] in SCHEDULED_FREQUENCIES or rf.annual_bill_day.get(name) else 1)
        if freq_changed or date_changed or not rf.annual_bill_day.get(name):
            if not (rf.annual_bill_day.get(name) and bill_frequency(rf.annual_bill_day[name]) is None and not freq_changed):
                d = nd or b["next"]
                retime_bill(plan, name, n, d.month, d.day, year)
        if amt_changed:
            rf.annual_bills[name] = round(each * n, 2)
        changed += 1
    ensure_monthly_recurring_lines(plan, entries, months, today_date)
    ensure_annual_bill_lines(plan, entries, months, today_date)
    return changed, notes


def cb_bill_edits(key: str, year: int):
    """v25.37: save the 'Change a bill' table the moment a cell is changed, instead of waiting for a Save button -- on the iPad the last cell
    typed into was often not yet in the table when Save was tapped, so the change looked saved but the old amount came back."""
    ss = st.session_state
    state = ss.get(key) or {}
    edits = state.get("edited_rows") or {}
    base = ss.get("sp_bills_base") or []
    if not edits or not base:
        return
    rows = []
    for i, b in enumerate(base):
        r = {"Bill": b["name"], "How often": b["freq"] if b["freq"] in BILL_FREQUENCIES else None, "Next due": b["next"], "Each time": round(b["each"], 2)}
        r.update(edits.get(i, edits.get(str(i), {})) or {})
        rows.append(r)
    months = month_list(ss.plan, today())
    n_ch, notes = apply_bill_edits(ss.plan, ss.entries, base, rows, months, today(), year)
    ensure_monthly_recurring_lines(ss.plan, ss.entries, months, today())
    ensure_annual_bill_lines(ss.plan, ss.entries, months, today())
    names = [rows[int(i)]["Bill"] for i in edits if int(i) < len(rows)]
    ss.sp_msg = ((f"Saved: {', '.join(names)}." if n_ch else "Nothing changed.") + ("" if not notes else " " + " ".join(notes)))
    ss.sp_bills_rev = ss.get("sp_bills_rev", 0) + 1


def rename_recurring_bill(plan: Plan, entries: dict, old: str, new: str) -> tuple[bool, str]:
    """v21.38: rename a monthly Recurring item or a scheduled bill, keeping everything about it: amount, 2028-on figure, due dates,
    per-year amounts. Pending lines take the new name (so the bank's wording can match it); reconciled lines keep the description
    they were reconciled under, as the record, but are re-tagged to the new name so the bill never posts a second line into a
    month that already has one. Returns (ok, message)."""
    rf = plan.recurring
    new = " ".join(str(new or "").split())
    if not new:
        return False, "Enter the new name."
    if new == old:
        return False, f"{old} already has that name."
    taken = set(rf.monthly) | set(rf.monthly_from_2028) | set(rf.annual_bills) | set(rf.annual_bills_from_2028) | set(rf.annual_bill_day) \
        | set(rf.annual_bill_year_amounts) | {x.get("name") for x in rf.extras}
    if new in taken:
        return False, f"There is already an item called {new}."
    monthly = old in rf.monthly or old in rf.monthly_from_2028
    annual = old in rf.annual_bills or old in rf.annual_bills_from_2028 or old in rf.annual_bill_day or old in rf.annual_bill_year_amounts
    if not (monthly or annual):
        return False, f"{old} is not in your recurring bills any more."
    for d in (rf.monthly, rf.monthly_from_2028, rf.monthly_day, rf.monthly_start, rf.monthly_end, rf.annual_bills, rf.annual_bills_from_2028,
              rf.annual_bill_day, rf.annual_bill_year_amounts):
        if old in d:
            d[new] = d.pop(old)
    kept = plan.expenses.get("bill_sugg_kept") or {}
    if old in kept:
        kept[new] = kept.pop(old)
    n = 0
    for rows in entries.get("ledger", {}).values():
        for r in rows:
            hit = False
            if r.get("recur_monthly") == old:
                r["recur_monthly"], hit = new, True
            tag = str(r.get("recur_annual") or "")
            if tag.startswith(f"{old}#") and tag.rsplit("#", 1)[0] == old:
                r["recur_annual"], hit = f"{new}#{tag.rsplit('#', 1)[1]}", True
            if hit and not is_reconciled(r):
                r["desc"] = new
                n += 1
    return True, f"{old} is now {new}; {n} pending line{'s' if n != 1 else ''} renamed. Reconciled lines keep their old wording as the record."


BILL_SUGG_DAYS = 90         # v21.38: look back this far at what each recurring bill really cost ...
BILL_SUGG_PCT = 0.15        # ... and suggest a new amount when the average is more than this far off
BILL_SUGG_SNOOZE_DAYS = 60  # Keep hides a suggestion for this long (Andrew, Oct 2026: two months)


def _bill_actuals(plan: Plan, entries: dict, name: str, kind: str, since: str) -> list[float]:
    """Reconciled payments for one recurring bill dated on or after `since`: the lines tagged to it, plus untagged Core lines whose wording
    names it (a bank line imported before the bill had that name) as long as they are not another bill's line."""
    out = []
    for rows in entries.get("ledger", {}).values():
        for r in rows:
            if not is_reconciled(r) or str(r.get("date", ""))[:10] < since or str(r.get("cls", "")).lower() != "core" or _n(r.get("credit")):
                continue
            tagged = r.get("recur_monthly") == name if kind == "monthly" else str(r.get("recur_annual") or "").rsplit("#", 1)[0] == name
            loose = not (r.get("recur_monthly") or r.get("recur_annual") or r.get("recur")) and item_overlap(name, r.get("desc", "")) >= 1
            if tagged or loose:
                out.append(_n(r.get("debit")))
    return out


def bill_amount_suggestions(plan: Plan, entries: dict, today_date) -> list[dict]:
    """v21.38 (Andrew, Oct 2026): for each recurring bill, the average of what was really paid over the last 90 days; a suggestion when it is
    more than 15% above or below the bill's amount each time, so the pending lines (and the budget and cash flow built on them) follow the
    ledger. Monthly bills need two payments in the window, the others one. Keep snoozes a bill's suggestion for 60 days; after that it comes
    back only if the bill is still more than 15% off. Bills with a year-specific amount for this year are left out (set on purpose)."""
    rf = plan.recurring
    since = (today_date - _dt.timedelta(days=BILL_SUGG_DAYS)).isoformat()
    kept = plan.expenses.get("bill_sugg_kept") or {}
    out = []
    cands = [(n, "monthly", float(a)) for n, a in rf.monthly.items()]
    for n, occ in rf.annual_bill_day.items():
        occ_l = occ if isinstance(occ, list) else [occ]
        if not occ_l or str(today_date.year) in (rf.annual_bill_year_amounts.get(n) or {}):
            continue
        cands.append((n, "scheduled", annual_bill_amount_for(rf, n, today_date.year) / len(occ_l)))
    for name, kind, cur in cands:
        paid = _bill_actuals(plan, entries, name, kind, since)
        if len(paid) < (2 if kind == "monthly" else 1) or cur <= 0:
            continue
        avg = round(sum(paid) / len(paid), 2)
        pct = (avg - cur) / cur
        if abs(pct) <= BILL_SUGG_PCT or str(kept.get(name, "")) > today_date.isoformat():      # kept: {name: "snoozed until" date}
            continue
        out.append({"name": name, "kind": kind, "current": round(cur, 2), "avg": avg, "n": len(paid), "pct": pct,
                    "use": float(math.ceil(avg))})          # the suggested amount: the average rounded up to the dollar (Andrew, Oct 2026)
    return sorted(out, key=lambda x: -abs(x["pct"]))


def apply_bill_suggestion(plan: Plan, entries: dict, name: str, kind: str, amount: float, months: list[str], today_date) -> str:
    """Set a recurring bill's amount each time to `amount`. Pending lines follow (except one you set by hand for its month); reconciled lines
    stay as the record. A monthly bill's 2028-on figure, if it has one, is left as it is."""
    rf = plan.recurring
    amount = round(float(amount), 2)
    if kind == "monthly":
        rf.monthly[name] = amount
        ensure_monthly_recurring_lines(plan, entries, months, today_date)
    else:
        occ = rf.annual_bill_day.get(name) or []
        n = len(occ if isinstance(occ, list) else [occ]) or 1
        rf.annual_bills[name] = round(amount * n, 2)
        ensure_annual_bill_lines(plan, entries, months, today_date)
    (plan.expenses.get("bill_sugg_kept") or {}).pop(name, None)
    return f"{name} is now {money(amount, 2)} each time; its pending lines follow."


def remove_annual_bill(plan: Plan, entries: dict, name: str) -> int:
    """Drop a 'Scheduled annual bills' item entirely -- not just leave its due date unconfirmed -- for one that
    turns out not to belong there at all (paid by credit card and already covered elsewhere, say, rather than
    something with its own due date). Clears every bucket it could be sitting in: the base amount, the 2028-on
    override, any per-year override, and the confirmed due date. Any pending line already posted for it (from
    before it was removed) is removed too, so it doesn't sit orphaned in the ledger forever with nothing left to
    refresh it -- a reconciled line is real money that already moved, so that's left alone, same as every other
    self-healing remover here. Returns the number of pending lines removed."""
    plan.recurring.annual_bills.pop(name, None)
    plan.recurring.annual_bills_from_2028.pop(name, None)
    plan.recurring.annual_bill_year_amounts.pop(name, None)
    plan.recurring.annual_bill_day.pop(name, None)
    n = 0
    for rows in entries.get("ledger", {}).values():
        stale = [r for r in rows if str(r.get("recur_annual", "")).startswith(f"{name}#") and not is_reconciled(r)]
        for r in stale:
            rows.remove(r)
            n += 1
    return n


def parse_annual_bill_year_rows(rows: list[dict]) -> dict:
    """Turn edited 'Year-specific amounts' rows ({'Bill', 'Year', 'Amount'}) into {name: {'YYYY': amount}},
    ready to replace plan.recurring.annual_bill_year_amounts wholesale. The editor is a dynamic (add/delete-row)
    table, so a freshly added row arrives with everything blank -- None or NaN, not a real Bill/Year/Amount --
    until the person fills it in; that row is skipped entirely rather than raised on or saved as a bogus entry,
    the same 'blank means nothing yet, not zero' handling that fixed the due-date editor's crash."""
    def blank(v):
        return v is None or v == "" or (isinstance(v, float) and v != v)
    out = {}
    for row in rows:
        name, yr, amt = row.get("Bill"), row.get("Year"), row.get("Amount")
        if blank(name) or blank(yr) or blank(amt):
            continue
        try:
            out.setdefault(name, {})[str(int(yr))] = float(amt)
        except (TypeError, ValueError):
            continue
    return out


def core_budget_for(plan: Plan, year: int) -> float:
    ex = plan.expenses                     # three periods: 2026-27, 2028 (its own, once set), and 2029 on (the key kept its old name, core_budget_from_2028)
    if year < 2028:
        return float(ex["core_budget_2027"])
    if year == 2028 and ex.get("core_budget_2028") is not None:
        return float(ex["core_budget_2028"])
    return float(ex["core_budget_from_2028"])


def suggested_core_budget(entries: dict, asof: _dt.date, window_days: int = 90, min_days: int = 30) -> dict | None:
    """A recommended annual Core budget from real recent spending: the trailing `window_days` of reconciled Core
    dollars (the same reconciled-only figure used everywhere else -- no smoothing, no guessing), annualized to a
    full year. Andrew's call (September 2026): spending is expected to settle as the first year of retirement goes
    on, and that's better tracked from what's actually happening than set by feel -- so this offers a number to
    review and apply, the same guess-then-confirm pattern already used everywhere else in this app (DefComp,
    recurring items, annual bills). It never changes the Core budget on its own. Returns None if there isn't at
    least `min_days` of real reconciled history inside the window to build it from, since annualizing a mostly-
    empty window would just manufacture a misleadingly low number rather than an honest one."""
    window_start_wanted = asof - _dt.timedelta(days=window_days)
    frames = [f for yr in sorted({window_start_wanted.year, asof.year}) for f in [year_ledgers(entries, yr)] if not f.empty]
    if not frames:
        return None
    led = classify_ledger(pd.concat(frames, ignore_index=True))
    dates = pd.to_datetime(led["date"])
    reconciled = led["reconciled"].astype(str).str.lower().eq("yes")
    seen = dates[reconciled & (led["core"] != 0)]
    if seen.empty:
        return None
    window_start = max(window_start_wanted, seen.min().date())
    days_covered = (asof - window_start).days + 1
    if days_covered < min_days:
        return None
    mask = (dates.dt.date >= window_start) & (dates.dt.date <= asof)
    sample_total = float(led.loc[mask, "core"].sum())
    return {"sample_total": round(sample_total, 2), "days_covered": days_covered, "window_start": window_start,
            "window_end": asof, "annualized": round(sample_total * 365.0 / days_covered, 2),
            "full_window": days_covered >= window_days}


def monthly_funding_target(plan: Plan, year: int) -> float:
    """The monthly deposit target (DefComp + Savings deposit) that Savings deposit is sized against: that year's
    Core budget, amortized to a monthly figure, plus a manual buffer for peaks and troughs. Core budget and the
    required deposit are one and the same thing -- so updating the budget (by hand, or via the Spending page's
    "Suggested Core budget" 90-day-lookback recommendation) is what moves this too; the buffer is the one piece
    still set by hand."""
    return core_budget_for(plan, year) / 12.0 + float(plan.recurring.deposit_buffer)


def year_ledgers(entries: dict, year: int) -> pd.DataFrame:
    frames = []
    for key, rows in entries["ledger"].items():
        if key.startswith(f"{year}-") and rows:
            f = ledger_frame(rows)
            f["ledger_month"] = int(key[-2:])
            frames.append(f)
    if frames:
        return pd.concat(frames, ignore_index=True)
    return pd.DataFrame(columns=["date", "description", "credit", "debit", "reconciled", "budget_class", "note", "ledger_month"])


def year_control(plan: Plan, entries: dict, year: int, replica: bool = False) -> dict:
    """Annual budget, committed items and headroom, plus the monthly reconciliation and pace views."""
    t = today()
    through = 12 if year < t.year else (t.month if year == t.year else 0)
    control = monthly_control(year_ledgers(entries, year), year, plan.expenses["card_allowance"], tuple(plan.expenses["card_keywords"]),
                              pending_through=through)
    budget = core_budget_for(plan, year)
    tracker, summary = spending_tracker(control, year, budget, plan.expenses["one_time_annual"])
    head = core_forecast_headroom(year, budget, plan.recurring, use_year_specific_items=not replica)
    # Headroom used to be budget minus just the named recurring items and scheduled bills -- a small, mostly fixed
    # list that barely moves month to month, no matter how real (variable) spending is actually running. Andrew's
    # call (September 2026): that made the number nearly meaningless -- it stayed the same whether he was tracking
    # right on budget or regularly running over, since only the handful of named items ever changed it. Headroom
    # is now budget minus this year's real reconciled spending so far plus the forecast for the rest of the year --
    # summary["full_year_variance"] -- so it actually moves with what's happening. (It's the same number, always,
    # as summary["normalized_variance"], the Dashboard's own pace figure: with the remaining months forecast at a
    # flat monthly rate, "how far off budget-to-date am I" and "where does that put the full year" are identical
    # arithmetic, just framed two ways -- so Headroom and the pace tile will always agree now, which they never did
    # before.) head["committed"] (the named-items total) is kept as its own figure -- still useful to see what your
    # fixed commitments add up to -- it just no longer defines headroom by itself. The old committed-only figure
    # is kept too, under committed_headroom, for anything (like cross-checking against the original workbook's own
    # Spending Tracker!G6, a fundamentally different, forward-only "do my named items alone fit" check) that still
    # wants that narrower number specifically -- nothing user-facing reads it any more.
    head["committed_headroom"] = head["headroom"]
    head["headroom"] = summary["full_year_variance"]
    return {"year": year, "budget": budget, "control": control, "tracker": tracker, "summary": summary, "headroom": head}


def one_time_start_month(year: int) -> int:
    """The one-time budget for 2026 covers September to December only (the workbook's rule); every other year runs January to December."""
    return 9 if year == 2026 else 1


def one_time_register(plan: Plan, entries: dict, year: int, today_date) -> dict:
    """
    Every One-Time ledger line dated in `year`, with whether it counts against that year's one-time budget, plus the budget picture.
    Counts = reconciled and in a month the budget covers. That is exactly what the spending tracker adds up, so the totals agree with it.
    Amount is debit minus credit: a refund or a sale shows as a negative amount.
    """
    start = one_time_start_month(year)
    rows, seq = [], 0
    for key in sorted(k for k in entries["ledger"] if k.startswith(f"{year}-")):
        month = int(key[5:7])
        for r in entries["ledger"][key]:
            seq += 1
            cls = str(r.get("cls", "")).lower()
            part = round(min(max(_n(r.get("ot_split")), 0.0), _n(r.get("debit"))), 2) if cls == "core" else 0.0
            if cls != "one-time" and part <= 0:
                continue
            try:
                d = pd.Timestamp(r["date"])
            except Exception:  # noqa: BLE001 - a line with no usable date is not part of any year's figures (the tracker skips it too)
                continue
            if pd.isna(d) or d.year != year:
                continue
            if cls == "one-time":
                amount, desc, from_card = round(_n(r.get("debit")) - _n(r.get("credit")), 2), str(r.get("desc", "")), False
            else:                                                # the one-time part of a card payment
                amount, desc, from_card = part, f"{r.get('ot_desc') or 'One-time part'} (part of {r.get('desc', '')})", True
            rec = str(r.get("rec", "")).lower() == "yes"
            in_period = month >= start
            counted = rec and in_period
            why = ("Counts" if counted else ("Before the September start" if not in_period else "Not until it is reconciled"))
            rows.append({"date": d.strftime("%Y-%m-%d"), "month": key, "desc": desc, "amount": amount, "reconciled": rec, "from_card": from_card,
                         "counted": counted, "why": why, "note": str(r.get("note", "") or ""), "_seq": seq})
    rows.sort(key=lambda x: (x["date"], x["_seq"]))
    run = 0.0
    for x in rows:
        if x["counted"]:
            run = round(run + x["amount"], 2)
        x["running"] = run if x["counted"] else None
        del x["_seq"]
    yc = year_control(plan, entries, year)
    budget = float(yc["summary"]["one_time_budget"])
    spent = round(sum(x["amount"] for x in rows if x["counted"]), 2)
    pending = round(sum(x["amount"] for x in rows if not x["reconciled"] and x["month"] >= f"{year}-{start:02d}"), 2)
    before = round(sum(x["amount"] for x in rows if x["month"] < f"{year}-{start:02d}"), 2)
    if year < today_date.year:
        months_left = 0
    elif year > today_date.year:
        months_left = 12 - start + 1
    else:
        months_left = max(0, 12 - today_date.month)          # the months after this one
    remaining = round(budget - spent, 2)
    reserved = alloc_reserved(entries, year)
    items = []
    for x in sorted((x for x in plan_items(entries) if str(x.get("date", ""))[:4] == str(year)), key=lambda x: (x["date"], x["name"])):
        linked = plan_linked(entries, x["id"])
        items.append({"id": x["id"], "name": x["name"], "date": x["date"], "amount": float(x["amount"]), "done": bool(x.get("done")), "linked": linked,
                      "left": 0.0 if x.get("done") else round(max(float(x["amount"]) - linked, 0.0), 2)})
    planned = round(sum(i["left"] for i in items), 2)
    after_reserved = round(remaining - reserved - pending, 2)               # what is left once card charges and lines waiting to be reconciled are counted
    return {"year": year, "reserved": reserved, "after_reserved": after_reserved, "plan_items": items, "planned": planned,
            "rest": round(after_reserved - planned, 2), "rest_name": entries.get("ot_rest_name") or "Holidays and the rest", "start_month": start, "rows": rows, "budget": budget, "spent": spent, "remaining": remaining,
            "used": (spent / budget) if budget > 0 else 0.0, "pending": pending, "before": before, "months_left": months_left,
            "per_month": (remaining / months_left) if months_left > 0 else None,
            "monthly": [{"month": m, "spent": float(yc["tracker"].loc[m, "one_time_spend"]), "left": float(yc["tracker"].loc[m, "one_time_remaining"])} for m in range(start, 13)],
            "tracker_spent": float(yc["tracker"]["one_time_spend"].sum())}


# ---- planned one-time items ---------------------------------------------------------------------------------------------------------------------------
# A planned item holds back part of the one-time budget for something you know is coming (a cruise). What is still held back is the plan less the
# card charges linked to it (those are already set aside or counted, so they are not held back twice). Marking it done releases whatever is left.
# Whatever no plan holds back is "the rest" (for example, the holidays).
def plan_items(entries: dict) -> list:
    return entries.setdefault("ot_plan", [])


def plan_find(entries: dict, pid: str):
    return next((x for x in plan_items(entries) if x.get("id") == pid), None)


def plan_add(entries: dict, name: str, amount, date: str) -> tuple[bool, str]:
    name = (name or "").strip()
    try:
        amount = round(float(amount), 2)
        if pd.isna(pd.Timestamp(date)):
            raise ValueError("no date")
    except Exception:  # noqa: BLE001
        return False, "Enter an amount and the date it is expected."
    if not name:
        return False, "Name it, for example the cruise."
    if amount <= 0:
        return False, "Enter an amount above zero."
    plan_items(entries).append({"id": new_id(), "name": name, "amount": amount, "date": str(date)[:10], "done": False})
    return True, f"{name}: {amount:,.2f} is now held back for {str(date)[:10]}."


def plan_update(entries: dict, pid: str, amount) -> tuple[bool, str]:
    x = plan_find(entries, pid)
    try:
        amount = round(float(amount), 2)
    except (TypeError, ValueError):
        return False, "Enter an amount."
    if x is None:
        return False, "That planned item is not in the list any more."
    if amount <= 0:
        return False, "Enter an amount above zero."
    x["amount"] = amount
    return True, f"{x['name']} is now planned at {amount:,.2f}."


def plan_set_done(entries: dict, pid: str, done: bool) -> tuple[bool, str]:
    x = plan_find(entries, pid)
    if x is None:
        return False, "That planned item is not in the list any more."
    x["done"] = bool(done)
    return True, (f"{x['name']} is done: what was still held back for it goes back into the rest." if done else f"{x['name']} is open again.")


def plan_delete(entries: dict, pid: str) -> tuple[bool, str]:
    x = plan_find(entries, pid)
    if x is None:
        return False, "That planned item is not in the list any more."
    for a in alloc_list(entries):
        if a.get("plan") == pid:
            a["plan"] = None                                      # its charges stay; they are just no longer part of a plan
    entries["ot_plan"] = [y for y in plan_items(entries) if y is not x]
    return True, f"{x['name']} is removed from the plan."


def plan_linked(entries: dict, pid: str) -> float:
    return round(sum(float(a["amount"]) for a in alloc_list(entries) if a.get("plan") == pid), 2)


# ---- credit card charges set aside for the one-time budget ----------------------------------------------------------------------------------------
# A one-time purchase on a card is recorded as a "card charge". It is set aside (reserved) from the one-time budget straight away. When the card is
# paid, the charge is applied to that payment line: the line keeps the bank's amount, and `ot_split` says how much of it is one-time. From then on
# that part counts against the one-time budget, not the core budget, once the payment is reconciled.
def alloc_list(entries: dict) -> list:
    return entries.setdefault("card_alloc", [])


def _alloc(entries: dict, alloc_id: str):
    return next((a for a in alloc_list(entries) if a.get("id") == alloc_id), None)


def alloc_add(entries: dict, desc: str, amount, date: str, card: str, plan_id: str | None = None, sfin_id: str | None = None) -> tuple[bool, str]:
    desc = (desc or "").strip()
    try:
        amount = round(float(amount), 2)
        if pd.isna(pd.Timestamp(date)):
            raise ValueError("no date")
    except Exception:  # noqa: BLE001
        return False, "Enter an amount and a date."
    if not desc:
        return False, "Say what it was, for example the flight."
    if amount <= 0:
        return False, "Enter an amount above zero."
    if not (card or "").strip():
        return False, "Pick the card it went on."
    if plan_id and plan_find(entries, plan_id) is None:
        return False, "That planned item is not in the list any more."
    entry = {"id": new_id(), "date": str(date)[:10], "desc": desc, "amount": amount, "card": card.strip().lower(), "line": None, "plan": plan_id or None}
    if sfin_id:
        entry["sfin_id"] = sfin_id                  # the real bank transaction this came from, so it is never proposed to you again
    alloc_list(entries).append(entry)
    return True, f"{desc}: {amount:,.2f} is now set aside on the {card} card."


def alloc_reserved(entries: dict, year: int) -> float:
    """Card charges set aside but not yet applied to a payment, dated in `year`."""
    return round(sum(float(a["amount"]) for a in entries.get("card_alloc", []) if not a.get("line") and str(a.get("date", ""))[:4] == str(year)), 2)


def _row_ref(entries: dict, month: str, ref: str):
    """A ledger row by its id, or by 'month#position' for a line that has no id yet (lines from an imported history file)."""
    rows = entries["ledger"].get(month, [])
    for i, r in enumerate(rows):
        if (r.get("id") and r["id"] == ref) or (not r.get("id") and ref == f"{month}#{i}"):
            return r
    return None


CARD_PAY_WINDOW_DAYS = 75


def card_payment_lines(plan: Plan, entries: dict, card: str | None = None, on_or_after: str | None = None) -> list[dict]:
    """Core lines that look like a payment on a card (the description holds the card's name) with some of the amount not yet set aside.
    A charge can only be paid by a payment made on or after the day it was charged, so `on_or_after` limits the list to those."""
    kws = [card.lower()] if card else [str(k).lower() for k in plan.expenses["card_keywords"]]
    out = []
    for month in sorted(entries["ledger"]):
        for i, r in enumerate(entries["ledger"][month]):
            debit = _n(r.get("debit"))
            if str(r.get("cls", "")).lower() != "core" or debit <= 0 or not any(k in str(r.get("desc", "")).lower() for k in kws):
                continue
            free = round(debit - min(_n(r.get("ot_split")), debit), 2)
            if on_or_after and str(r.get("date", ""))[:10] < str(on_or_after)[:10]:
                continue
            if on_or_after and str(r.get("date", ""))[:10] > (pd.Timestamp(str(on_or_after)[:10]) + pd.Timedelta(days=CARD_PAY_WINDOW_DAYS)).strftime("%Y-%m-%d"):
                continue                                # a charge is paid by one of the next two statements, not a forecast payment a year out
            if free > 0.004:
                out.append({"month": month, "ref": r.get("id") or f"{month}#{i}", "date": str(r.get("date", "")), "desc": str(r.get("desc", "")), "debit": debit,
                            "set_aside": round(debit - free, 2), "free": free, "reconciled": is_reconciled(r)})
    return sorted(out, key=lambda x: (x["date"], x["desc"]))


def alloc_apply(entries: dict, alloc_id: str, month: str, ref: str, now=None) -> tuple[bool, str]:
    a = _alloc(entries, alloc_id)
    r = _row_ref(entries, month, ref)
    if a is None:
        return False, "That card charge is not in the list any more."
    if a.get("line"):
        return False, "That card charge is already applied to a payment."
    if r is None:
        return False, "That payment is not in your transactions any more."
    debit = _n(r.get("debit"))
    if str(r.get("cls", "")).lower() != "core" or debit <= 0:
        return False, "Pick a card payment that is a Core line with an amount going out."
    free = round(debit - min(_n(r.get("ot_split")), debit), 2)
    if free <= 0.004:
        return False, f"All {debit:,.2f} of that payment is already set aside. Pick another payment."
    # A charge bigger than the room left is allowed (v21.14): the payment line keeps the bank's amount, and everywhere a split is used it is
    # capped at the payment, so only what this payment covered counts as one-time; the small remainder is on the card's next bill.
    over = round(a["amount"] - free, 2) if a["amount"] > free + 0.004 else 0.0
    r["id"] = r.get("id") or new_id()
    r["ot_split"] = round(_n(r.get("ot_split")) + a["amount"], 2)
    r["ot_desc"] = "; ".join(x for x in (r.get("ot_desc"), a["desc"]) if x)
    a["line"] = {"month": month, "rid": r["id"]}
    stamp(r, "one-time", f"{a['amount']:,.2f} of this payment set aside as one-time: {a['desc']}", now=now)
    return True, f"{a['desc']}: {a['amount']:,.2f} of the {r.get('desc')} payment on {r.get('date')} is now one-time." + (
        f" The charge is {over:,.2f} more than this payment had room for; that part is paid with the card's next bill." if over else "") + ("" if is_reconciled(r) else " It counts against the one-time budget once that payment is reconciled.")


def alloc_line(entries: dict, a: dict):
    return _row_ref(entries, a["line"]["month"], a["line"]["rid"]) if a.get("line") else None


def alloc_undo(entries: dict, alloc_id: str, now=None) -> tuple[bool, str]:
    a = _alloc(entries, alloc_id)
    if a is None or not a.get("line"):
        return False, "That card charge is not applied to a payment."
    r = alloc_line(entries, a)
    if r is not None:
        r["ot_split"] = round(max(_n(r.get("ot_split")) - a["amount"], 0.0), 2) or None
        rest = [x["desc"] for x in alloc_list(entries) if x is not a and x.get("line") and x["line"]["rid"] == a["line"]["rid"]]
        r["ot_desc"] = "; ".join(rest)
        if not r["ot_split"]:
            r.pop("ot_split", None)
            r.pop("ot_desc", None)
        stamp(r, "one-time", f"{a['amount']:,.2f} taken back out of one-time: {a['desc']}", now=now)
    a["line"] = None
    return True, f"{a['desc']} is set aside on the card again, and no longer part of that payment."


def alloc_delete(entries: dict, alloc_id: str, now=None) -> tuple[bool, str]:
    a = _alloc(entries, alloc_id)
    if a is None:
        return False, "That card charge is not in the list any more."
    if a.get("line"):
        alloc_undo(entries, alloc_id, now=now)
    entries["card_alloc"] = [x for x in alloc_list(entries) if x is not a]
    return True, f"{a['desc']} is removed from the card charges."


# ---- changing a line's class from the one-time register --------------------------------------------------------------------------------------------
CLASS_CHOICES = ("Core", "One-Time", "Excluded")


def one_time_class_lines(entries: dict, year: int) -> list[dict]:
    """The lines the register's class control can change: every One-Time line dated in `year`, plus any line already moved out of One-Time from
    there (so it can be put back). Works on any month that has lines, including earlier months from an imported history file."""
    out = []
    for month in sorted(k for k in entries["ledger"] if k.startswith(f"{year}-")):
        for i, r in enumerate(entries["ledger"][month]):
            cls = str(r.get("cls", "")).lower()
            moved = r.get("moved_from") == "One-Time" and cls != "one-time"
            if cls != "one-time" and not moved:
                continue
            try:
                d = pd.Timestamp(r["date"])
            except Exception:  # noqa: BLE001
                continue
            if pd.isna(d) or d.year != year:
                continue
            out.append({"month": month, "ref": r.get("id") or f"{month}#{i}", "date": d.strftime("%Y-%m-%d"), "desc": str(r.get("desc", "")),
                        "amount": round(_n(r.get("debit")) - _n(r.get("credit")), 2), "cls": r.get("cls") or "No class", "moved": moved})
    return sorted(out, key=lambda x: (x["date"], x["desc"]))


def set_line_class(entries: dict, month: str, ref: str, new_cls: str, now=None) -> tuple[bool, str]:
    r = _row_ref(entries, month, ref)
    if r is None:
        return False, "That line is not in your transactions any more."
    if new_cls not in CLASS_CHOICES:
        return False, "Pick Core, One-Time or Excluded."
    old = r.get("cls") or ""
    if old == new_cls:
        return False, f"{r.get('desc')} is already {new_cls}."
    if _n(r.get("ot_split")) > 0:
        return False, "Part of this payment is set aside as one-time. Take that card charge off it first, on the Card charges tab."
    r["id"] = r.get("id") or new_id()
    r["cls"] = new_cls
    if old.lower() == "one-time":
        r["moved_from"] = "One-Time"                    # remembered, so the control can put it back
    elif new_cls.lower() == "one-time":
        r.pop("moved_from", None)
    stamp(r, "edited", f"class {old or 'none'} to {new_cls} (from the one-time register)", now=now)
    if new_cls == "One-Time":
        return True, f"{r.get('desc')} is One-Time again and counts in the register."
    return True, (f"{r.get('desc')} is now {new_cls}. It no longer counts as one-time spending. To put it back, pick it under this same control and choose One-Time."
                  if old.lower() == "one-time" else f"{r.get('desc')} is now {new_cls}.")


def merge_history(entries: dict, hist: dict) -> tuple[list[str], list[str]]:
    """Add earlier months from a history file. A month that already has lines is never touched."""
    if (not isinstance(hist, dict) or hist.get("format") != "plan-history-v1"
            or not any(isinstance(hist.get(s), dict) for s in ("ledger", "magi_history", "plan_add", "forecast_lines", "invest_income", "inv_growth", "balances", "balances_replace"))):
        raise ValueError("This does not look like a history file.")
    added, kept = [], []
    for key, rows in sorted((hist.get("ledger") or {}).items()):
        if entries["ledger"].get(key):
            kept.append(key)
        else:
            entries["ledger"][key] = [dict(r) for r in rows]
            added.append(key)
    return added, kept


# ---- transaction actions (pure functions on the entries, so they can be tested without a screen) ---------------------
def find_row(entries: dict, key: str, rid: str):
    for r in entries["ledger"].get(key, []):
        if r.get("id") == rid:
            return r
    return None


def is_reconciled(r: dict) -> bool:
    return str(r.get("rec", "")).lower() == "yes"


DEFAULT_TZ = "America/Chicago"


def _now_iso(now=None) -> str:
    n = now or _dt.datetime.now(_dt.timezone.utc)
    return n.astimezone(_dt.timezone.utc).isoformat(timespec="seconds")


def stamp(r: dict, event: str, detail: str = "", now=None) -> None:
    """Add a dated entry to a line's audit trail (times are stored in UTC and shown in your time zone)."""
    r.setdefault("audit", []).append({"t": _now_iso(now), "e": event, "d": detail})


def _fmt_local(iso: str, tz_name: str) -> str:
    t = _dt.datetime.fromisoformat(iso)
    try:
        from zoneinfo import ZoneInfo
        t = t.astimezone(ZoneInfo(tz_name))
    except Exception:  # noqa: BLE001 - an unknown zone falls back to UTC
        t = t.astimezone(_dt.timezone.utc)
    return f"{t.strftime('%b')} {t.day}, {t.year} {t.hour % 12 or 12}:{t.minute:02d} {'AM' if t.hour < 12 else 'PM'} {t.tzname()}"


def audit_line(r: dict, tz_name: str = DEFAULT_TZ) -> str:
    """The one-line audit note shown on a card."""
    if is_reconciled(r):
        return f"Reconciled {_fmt_local(r['rec_at'], tz_name)}" if r.get("rec_at") else "Reconciled (before timestamps were kept)"
    ev = r.get("audit") or []
    return f"Reconciliation undone {_fmt_local(ev[-1]['t'], tz_name)}" if ev and ev[-1]["e"] == "undone" else ""


def audit_history(r: dict, tz_name: str = DEFAULT_TZ) -> list[str]:
    names = {"reconciled": "Reconciled", "undone": "Reconciliation undone", "edited": "Edited after reconciling"}
    return [f"{_fmt_local(a['t'], tz_name)}: {names.get(a['e'], a['e'])}" + (f" ({a['d']})" if a.get("d") else "") for a in r.get("audit", [])]


def reconcile_row(entries: dict, key: str, rid: str, now=None) -> str:
    """Tick a line. A line needs a class first. Returns '' on success, otherwise the reason it was refused."""
    r = find_row(entries, key, rid)
    if r is None:
        return "That line is no longer here."
    if not r.get("cls"):
        return f"Choose a class for {r.get('desc') or 'this line'} first."
    r["rec"] = "Yes"
    r["rec_at"] = _now_iso(now)
    stamp(r, "reconciled", now=now)
    return ""


def reconcile_warnings(plan, entries: dict, inbox: dict | None, r: dict, today_date) -> list[str]:
    """Reasons to ask before ticking a line by hand: dated after today, or not in the checking account's online activity (the daily fetch).
    A line that came from the fetch (it carries the bank's id) is fine. If a card account shows a payment of that amount that checking has not
    taken yet, that is said, since it is the usual way a card payment gets ticked a day or two early."""
    out = []
    d = str(r.get("date", ""))[:10]
    if d > today_date.isoformat():
        out.append(f"It is dated {d}, after today.")
    acct = plan.expenses.get("sfin_account")
    if r.get("bank_id") or not inbox or not acct:
        return out
    if not _n(r.get("credit")) and not _n(r.get("debit")):
        return out                                      # v21.17: a $0 line (a statement that came to nothing) never reaches the bank
    lines = inbox.get("lines") or []
    mine = [x for x in lines if x.get("acct") == acct]
    if not mine:
        return out
    try:
        rd = _dt.date.fromisoformat(d)
    except ValueError:
        return out
    if rd < _dt.date.fromisoformat(min(x["date"] for x in mine)[:10]):
        return out                                      # older than the fetch keeps: nothing to check against
    money_in = _n(r.get("credit")) > 0 and not _n(r.get("debit"))
    amt = _n(r.get("credit")) if money_in else _n(r.get("debit"))
    used = {x.get("bank_id") for rows in entries["ledger"].values() for x in rows if x.get("bank_id") and x is not r}
    found = any(x.get("id") not in used and abs(abs(x["amount"]) - amt) < 0.005 and (x["amount"] > 0) == money_in
                and abs((_dt.date.fromisoformat(str(x["date"])[:10]) - rd).days) <= 10 for x in mine)
    if found:
        return out
    when = inbox.get("last_fetch") or "the last fetch"
    msg = f"It is not in your checking account's online activity (as of the fetch on {when})."
    if not money_in:
        cards = {a["id"]: a for a in (plan.expenses.get("sfin_card_accounts") or []) if a.get("id")}
        hit = next((x for x in lines if x.get("acct") in cards and x["amount"] > 0 and abs(x["amount"] - amt) < 0.005
                    and is_card_payment_credit(x.get("desc", "")) and abs((_dt.date.fromisoformat(str(x["date"])[:10]) - rd).days) <= 10), None)
        if hit:
            msg += (f" {cards[hit['acct']].get('name') or 'The card'} shows the payment on {str(hit['date'])[:10]}, so it has probably not left checking yet"
                    " -- usually one to three business days.")
    out.append(msg)
    return out


def unreconcile_row(entries: dict, key: str, rid: str, now=None) -> None:
    r = find_row(entries, key, rid)
    if r is not None:
        r["rec"] = "Pending"
        r.pop("rec_at", None)
        stamp(r, "undone", now=now)


def edit_row(entries: dict, key: str, rid: str, desc: str, date: str, note: str, amount: float, money_in: bool) -> str:
    """Save an edit. If the line was already reconciled, what changed is written to its audit trail. Returns a change summary."""
    r = find_row(entries, key, rid)
    if r is None:
        return ""
    before = (r.get("desc"), r.get("date"), r.get("note"), _n(r.get("credit")), _n(r.get("debit")))
    r["desc"], r["date"], r["note"] = desc, date, note
    r["credit"], r["debit"] = (float(amount), None) if money_in else (None, float(amount))
    if r.get("recur_monthly") and (before[3], before[4]) != (_n(r.get("credit")), _n(r.get("debit"))):
        r["hand_amt"] = True        # set by hand for this one month: a later change to the item's amount leaves this line alone
    if r.get("recur_annual") and (before[1], before[3], before[4]) != (date, _n(r.get("credit")), _n(r.get("debit"))):
        r["hand_amt"] = True        # v25.29: an annual bill edited by hand (the real tax bill) keeps its amount and date; the nightly refresh
                                    # from the plan used to put the planned figure straight back, so the edit seemed not to save
    after = (desc, date, note, _n(r.get("credit")), _n(r.get("debit")))
    changes = []
    for label, b, a in zip(("description", "date", "note", "in", "out"), before, after):
        if b != a:
            changes.append(f"{label} {b or 'blank'} to {a or 'blank'}")
    if changes and is_reconciled(r):
        stamp(r, "edited", "; ".join(changes))
    return "; ".join(changes)


def set_row_class(entries: dict, key: str, rid: str, cls) -> None:
    r = find_row(entries, key, rid)
    if r is not None:
        old = r.get("cls") or ""
        r["cls"] = cls or ""
        if old != (cls or ""):                          # a class change moves the spending figures, so it is recorded like any other edit
            stamp(r, "edited", f"class {old or 'none'} to {cls or 'none'}")


def mark_all_reconciled(entries: dict, key: str, now=None, today_iso: str | None = None) -> tuple[int, int, int]:
    """Ticks every classed pending line in the month, except lines dated after today (they cannot have cleared yet).
    Returns (ticked, needing a class, left because dated later)."""
    done = skipped = later = 0
    for r in entries["ledger"].get(key, []):
        if not is_reconciled(r):
            if today_iso and str(r.get("date", ""))[:10] > today_iso:
                later += 1
            elif r.get("cls"):
                r["rec"] = "Yes"; r["rec_at"] = _now_iso(now); stamp(r, "reconciled", "mark all", now=now); done += 1
            else:
                skipped += 1
    return done, skipped, later


def add_row(entries: dict, key: str, date: str, desc: str, amount: float, money_in: bool, cls: str, note: str = "") -> dict:
    ensure_ids(entries["ledger"].setdefault(key, []))
    r = {"id": new_id(), "date": date, "desc": desc, "credit": amount if money_in else None, "debit": None if money_in else amount,
         "rec": "Pending", "cls": cls or "", "note": note}
    entries["ledger"][key].append(r)
    return r


# ---- bank activity import: match pasted bank lines to the ledger, and add what is missing --------------------------------------------------------------
_BANK_STOP = {"THE", "AND", "ONLINE", "PAYMENT", "PYMT", "PYMTS", "PMT", "CARD", "POS", "PURCHASE", "DEBIT", "CHECKCARD", "AUTOPAY", "WEB", "ACH", "RECURRING",
              "SVC", "PCS", "INC", "LLC", "CORP", "MEMBER", "FEES", "FEE"}
# ELEC used to be stopped here too, as generic "ELECTRONIC" banking noise -- but a bank statement abbreviates an
# electric company down to just that word ("FL ELEC", "FPL...ELEC PYMTS"), and stopping it left an item literally
# named "Florida Electric" with nothing left to match against, so it kept re-posting a duplicate guess every month
# alongside the real reconciled bill. Kept as an ordinary word instead.


def _bank_amount(s):
    import re as _re
    t = str(s).strip()
    if not t:
        return None
    neg = t.startswith("-") or t.startswith("(") or t.startswith("\u2212")
    t = _re.sub(r"[()$,\s\u2212-]", "", t)
    try:
        v = float(t)
    except ValueError:
        return None
    return -v if neg else v


def _bank_date(s):
    import re as _re
    t = str(s).strip()
    m = _re.match(r"^(\d{1,2})/(\d{1,2})/(\d{2}|\d{4})$", t)
    if m:
        y = int(m.group(3))
        y = y + 2000 if y < 100 else y
        try:
            return _dt.date(y, int(m.group(1)), int(m.group(2))).isoformat()
        except ValueError:
            return None
    if _re.match(r"^\d{4}-\d{2}-\d{2}$", t):
        return t
    return None


def bank_tokens(desc: str) -> list:
    import re as _re
    # Glue characters (&, ', -) are stripped before splitting into words, not treated as breaks: "AT&T" is one
    # word, not "AT" + "T" (both too short to count as a token on their own, so an item literally named "AT&T"
    # could never match anything -- neither the bank's own "AT&T..." wording nor even itself). Applied identically
    # to both sides of every comparison, so this only glues letters that were already touching (T-MOBILE ->
    # TMOBILE), never merges separate space-separated words.
    cleaned = _re.sub(r"[&'\-]", "", str(desc).upper())
    return [t for t in _re.findall(r"[A-Z]{3,}", cleaned) if t not in _BANK_STOP]


def bank_overlap(a: str, b: str) -> int:
    """How many merchant words two descriptions share, counting a word that begins the other (APPLE / APPLECARD) and a name run together (APPLE CARD / APPLECARD)."""
    ta, tb = bank_tokens(a), bank_tokens(b)
    n = len(set(ta) & set(tb))
    n += sum(1 for x in set(ta) - set(tb) for y in set(tb) - set(ta) if len(x) >= 4 and len(y) >= 4 and (x.startswith(y) or y.startswith(x)))
    if not n:
        ca, cb = "".join(t for t in __import__("re").findall(r"[A-Z]+", str(a).upper())), "".join(__import__("re").findall(r"[A-Z]+", str(b).upper()))
        # Checked both directions -- a short description's letters run together and buried inside a longer one, from
        # either side. This used to only check ca-in-cb (the bank wording contained inside the ledger wording), which
        # missed the far more common reverse case: a short ledger description ("Water") embedded inside a longer,
        # glued-together bank payee string with no spaces ("MIDWAYWATER..."), where "WATER" lands at the *end* of the
        # glued word rather than the start, so even the startswith check above never sees it either.
        if (len(ca) >= 5 and ca in cb) or (len(cb) >= 5 and cb in ca):
            n = 1
    return n


_ITEM_GENERIC = {"CREDIT", "CARD", "CARDS", "PAYMENT", "PMT", "BILL", "AUTOPAY", "ONLINE", "MONTHLY",
                 "USA", "INC", "LLC", "CORP", "THE", "COMPANY", "SERVICES", "SERVICE"}     # v21.28: company-name filler words


def item_overlap(name: str, desc: str) -> int:
    """bank_overlap for deciding whether a hand-entered line already covers a recurring item: words that half the card bills share
    (CREDIT, CARD, PAYMENT...) are left out, so 'Costco credit card' and 'One Pay credit card' are not taken for each other. A name made only
    of such words falls back to the plain comparison."""
    strip = lambda t: " ".join(w for w in str(t).upper().replace("-", " ").split() if w.strip(".,") not in _ITEM_GENERIC)
    a, b = strip(name), strip(desc)
    return bank_overlap(a, b) if a.strip() and b.strip() else bank_overlap(name, desc)


def bank_key(desc: str) -> str:
    t = bank_tokens(desc)
    return t[0] if t else ""


def _bank_split(line: str):
    """Split one pasted line into cells: tabs, or two or more spaces, or a quoted CSV line."""
    import csv as _csv
    import re as _re
    if "\t" in line:
        return [p.strip() for p in line.split("\t")]
    if line.count(",") >= 2 and _re.match(r'^\s*"?\d', line):
        try:
            return [p.strip() for p in next(_csv.reader([line]))]
        except (_csv.Error, StopIteration):
            pass
    return [p.strip() for p in _re.split(r"\s{2,}", line.strip())]


def parse_bank_paste(text: str, flip: bool = False):
    """Lines as copied from Wells Fargo activity. Understands: date, description, deposits, withdrawals (either may be blank); date, description, signed amount,
    running balance; date, description, one signed amount; and the CSV download (date, amount, *, check number, description). Returns (rows, skipped lines)."""
    staged, skipped = [], []
    for line in str(text).splitlines():
        if not line.strip():
            continue
        parts = _bank_split(line)
        d = _bank_date(parts[0]) if parts else None
        if d is None and parts and parts[0].strip().upper() in ("DATE", "POSTING DATE", "TRANSACTION DATE"):
            continue                                              # a header row
        if d is None or len(parts) < 3:
            skipped.append(line)
            continue
        if _bank_amount(parts[1]) is not None and not _bank_date(parts[1]) and len(parts) >= 4 and _bank_amount(parts[-1]) is None:
            staged.append((d, parts[-1], [parts[1]], line))                # the CSV download: date, amount, *, check number, description
        else:
            staged.append((d, parts[1], parts[2:], line))
    both = sum(1 for _, _, cells, _l in staged if len(cells) >= 2 and _bank_amount(cells[0]) is not None and _bank_amount(cells[1]) is not None)
    filled = sum(1 for _, _, cells, _l in staged if any(_bank_amount(c) is not None for c in cells[:2]))
    signed_layout = filled > 0 and both * 2 >= filled            # amount and balance side by side: the first number is the amount
    rows = []
    for d, desc, cells, line in staged:
        a0 = _bank_amount(cells[0]) if cells else None
        a1 = _bank_amount(cells[1]) if len(cells) > 1 else None
        credit = debit = None
        if signed_layout or len(cells) == 1 or (a0 is not None and a0 < 0):
            if a0 is not None:
                credit, debit = (a0, None) if a0 > 0 else (None, -a0)
        elif a0 is not None and a1 is None:
            credit = abs(a0)
        elif a1 is not None and a0 is None:
            debit = abs(a1)
        elif a0 is not None and a1 is not None:
            credit, debit = (abs(a0) or None), (abs(a1) or None)
        if (credit is None and debit is None) or (not credit and not debit):
            skipped.append(line)
            continue
        if flip:
            credit, debit = debit, credit
        rows.append({"date": d, "desc": " ".join(desc.split()), "credit": credit, "debit": debit})
    return rows, skipped


def guess_class(entries: dict, desc: str, money_in: bool) -> str:
    """The class most often used for earlier lines that start with the same merchant word."""
    key = bank_key(desc)
    if not key:
        return ""
    counts = {}
    for rows in entries.get("ledger", {}).values():
        for r in rows:
            if r.get("cls") and key in (bank_key(r.get("desc", "")), bank_key(r.get("bank_desc", ""))) and bool(_n(r.get("credit"))) == money_in:
                counts[r["cls"]] = counts.get(r["cls"], 0) + 1
    return max(counts, key=counts.get) if counts else ""


def _learned_bank_words(entries: dict) -> dict:
    """v25.24: recurring item -> the bank wordings (bank_key) its reconciled lines were paid under, so a payment worded by the bank
    ('CHASE CREDIT CRD AUTOPAY') is known to be that item ('Amazon') even though the words differ."""
    out: dict = {}
    for rows_ in (entries.get("ledger") or {}).values():
        for r in rows_:
            if not (r.get("bank_desc") and is_reconciled(r)):
                continue
            k = bank_key(r["bank_desc"])
            item = str(r.get("recur_monthly") or r.get("recur_annual") or r.get("recur") or "").rsplit("#", 1)[0]
            for name in {item.strip().lower(), str(r.get("desc") or "").strip().lower()} - {""}:
                if k:
                    out.setdefault(name, set()).add(k)       # by the item's name and the line's own name ('amazon' before it was an item)
    return out


def plan_bank_import(entries: dict, bank_rows: list, months: list, window: int = 7) -> list:
    """For each bank line, decide: match an unreconciled ledger line, already imported, new line, or outside the months the app tracks."""
    claimed, out = set(), []
    ledger = entries.get("ledger", {})
    for rows_ in ledger.values():
        ensure_ids(rows_)                                   # older lines may not have an id yet
    learned = _learned_bank_words(entries)
    for i, b in enumerate(sorted(bank_rows, key=lambda r: r["date"])):
        money_in = b["credit"] is not None
        amt = float(b["credit"] if money_in else b["debit"])
        bd = _dt.date.fromisoformat(b["date"])
        k = b["date"][:7]
        p = {"i": i, "bank": b, "k": k, "amount": amt, "money_in": money_in, "action": "new", "rid": "", "rk": "", "row_desc": "", "cls": "", "strength": ""}
        if k not in months:
            p["action"] = "outside"
            out.append(p)
            continue
        neighbours = [k, next_month_key(k), f"{int(k[:4]) - 1}-12" if k[5:] == "01" else f"{k[:4]}-{int(k[5:]) - 1:02d}"]
        best, haveline, near, upd = None, None, None, None
        for mk in neighbours:
            for r in ledger.get(mk, []):
                if (str(mk), r.get("id")) in claimed:
                    continue
                ra = _n(r.get("credit")) if money_in else _n(r.get("debit"))
                direction_ok = not ((money_in and _n(r.get("debit"))) or (not money_in and _n(r.get("credit"))))
                if abs(ra - amt) >= 0.005 or not direction_ok:
                    if ra and direction_ok and (str(mk), r.get("id")) not in claimed:
                        try:
                            g2 = abs((_dt.date.fromisoformat(str(r.get("date"))) - bd).days)
                        except ValueError:
                            g2 = 99
                        o2 = bank_overlap(b["desc"], r.get("desc", ""))
                        # A possible match always needs some shared wording -- amount closeness alone was flagging
                        # too much (any coincidentally similar charge, with no real connection to the ledger line).
                        # Andrew's call (September 2026): require wording AND (a close date OR a close amount), not
                        # amount by itself. The date gap and the 10%-of-the-ledger-amount tolerance are each enough
                        # on their own once there's a shared word -- a rounded/tip-adjusted charge posted close in
                        # time, or an exact amount that posted well outside the old 10-day window (the reported
                        # "Water $16.00" case: 3 days out and worded "MIDWAYWATER", which needed the bank_overlap fix
                        # below, not this one, but both together are what makes this tier work as intended).
                        by_amount = ra > 0 and abs(ra - amt) <= 0.10 * ra
                        if o2 > 0 and (g2 <= 10 or by_amount) and (near is None or (g2, -o2) < near[0]):
                            near = ((g2, -o2), r, ra, mk)
                        # v21.38: a PENDING line close enough to be the same payment at a different amount -- within 10% and dated within a
                        # week (10 days with shared wording), or a recurring bill's line with shared wording at any amount (a utility bill
                        # that varies). Offered as a match that updates the line to the bank's amount, unticked until you confirm it.
                        recur_ = bool(r.get("recur_monthly") or r.get("recur_annual") or r.get("recur"))
                        small_ = 0 < ra < AUTO_BILL_LIMIT and abs(ra - amt) <= AUTO_BILL_TOLERANCE
                        if (not is_reconciled(r) and g2 <= (10 if o2 else window) and (by_amount or (o2 > 0 and (recur_ or small_)))
                                and (upd is None or (g2, -o2, abs(ra - amt)) < upd[0])):
                            upd = ((g2, -o2, abs(ra - amt)), r, ra, mk)
                    continue
                if (b.get("id") and r.get("bank_id") == b["id"]) or (r.get("bank_desc") == b["desc"] and r.get("bank_date") == b["date"]):
                    p.update(action="dupe", rid=r["id"], rk=mk, row_desc=r.get("desc", ""))
                    best = "dupe"
                    break
                try:
                    gap = abs((_dt.date.fromisoformat(str(r.get("date"))) - bd).days)
                except ValueError:
                    continue
                overlap = bank_overlap(b["desc"], r.get("desc", ""))
                if is_reconciled(r):
                    if gap <= (10 if overlap else window) and (haveline is None or (gap, -overlap) < haveline[0]):
                        haveline = ((gap, -overlap), mk, r)
                    continue
                if gap > (10 if overlap else window):
                    continue
                score = (gap, -overlap)
                if best is None or (best != "dupe" and score < best[0]):
                    best = (score, mk, r, overlap)
            if best == "dupe":
                break
        if best == "dupe":
            pass
        elif best is None and haveline is not None:
            hs, mk, r = haveline
            claimed.add((mk, r["id"]))
            p.update(action="have", rid=r["id"], rk=mk, row_desc=r.get("desc", ""), strength="" if hs[1] else "Check: different wording")
        elif best is not None:
            _, mk, r, overlap = best
            claimed.add((mk, r["id"]))
            p.update(action="match", rid=r["id"], rk=mk, row_desc=r.get("desc", ""), cls=r.get("cls") or guess_class(entries, b["desc"], money_in),
                     strength="Strong" if overlap else "Check: same amount and date, different wording")
            # v25.24: an exact match -- the same amount to the cent, dated within a week, and the same wording (or the bank wording this
            # recurring item has been paid under before, e.g. Amazon -> CHASE CREDIT CRD AUTOPAY) -- is ticked without asking.
            try:
                gap_ = abs((_dt.date.fromisoformat(str(r.get("date"))) - bd).days)
            except ValueError:
                gap_ = 99
            item_ = str(r.get("recur_monthly") or r.get("recur_annual") or r.get("recur") or r.get("desc") or "").rsplit("#", 1)[0].strip().lower()
            known_ = bool(item_) and bank_key(b["desc"]) in learned.get(item_, set())
            p["auto"] = (not is_reconciled(r)) and gap_ <= 7 and (overlap > 0 or known_)
            if known_ and not overlap:
                p["strength"] = "Strong (paid under this wording before)"
        else:
            p["cls"] = guess_class(entries, b["desc"], money_in)
            if upd is not None and (str(upd[3]), upd[1].get("id")) not in claimed:
                r, mk_ = upd[1], upd[3]
                claimed.add((str(mk_), r["id"]))
                p.update(action="update", rid=r["id"], rk=mk_, row_desc=f"{r.get('desc', '')} ({r.get('date', '')}, {upd[2]:,.2f})",
                         cls=r.get("cls") or p["cls"], old_amt=upd[2], strength="" if upd[0][1] else "different wording")
                # v21.38 (Andrew, Oct 2026), only when the wording matches:
                #   a recurring bill under $100 and within $10 of it -> applied on its own when the app opens (auto)
                #   otherwise within 10% (or a small line within $10) -> pre-ticked, you press Apply (sure)
                #   anything else -> unticked, you check it
                wording_, ra_, d_ = bool(upd[0][1]), upd[2], abs(upd[2] - amt)
                recur_ = bool(r.get("recur_monthly") or r.get("recur_annual") or r.get("recur"))
                p["auto"] = wording_ and recur_ and 0 < ra_ < AUTO_BILL_LIMIT and d_ <= AUTO_BILL_TOLERANCE
                p["sure"] = wording_ and not p["auto"] and (d_ <= 0.10 * ra_ or (ra_ < AUTO_BILL_LIMIT and d_ <= AUTO_BILL_TOLERANCE))
            elif near is not None:
                r = near[1]
                p.update(action="near", row_desc=f"{r.get('desc', '')} ({r.get('date', '')}, {near[2]:,.2f})")
        out.append(p)
    return out


def _clean_bank_desc(desc: str) -> str:
    words = [w for w in str(desc).split() if not (sum(c.isdigit() for c in w) >= 5)]
    return " ".join(words)[:70] or str(desc)[:70]


def apply_bank_import(entries: dict, proposals: list, choices: dict, now=None) -> dict:
    """choices: {proposal index: {"apply": bool, "cls": class}}. Returns counts and the lines that could not be reconciled for want of a class."""
    res = {"matched": 0, "added": 0, "skipped": 0, "pending": []}
    for p in proposals:
        c = choices.get(p["i"], {})
        if p["action"] == "have" and c.get("apply"):
            r = find_row(entries, p["rk"], p["rid"])
            if r is not None and not r.get("bank_desc"):
                r["bank_desc"], r["bank_date"] = p["bank"]["desc"], p["bank"]["date"]
                if p["bank"].get("id"):
                    r["bank_id"] = p["bank"]["id"]
                stamp(r, "bank wording noted", p["bank"]["desc"], now=now)
            res["skipped"] += 1
            continue
        if not c.get("apply") or p["action"] in ("dupe", "outside"):
            res["skipped"] += 1
            continue
        b, cls = p["bank"], c.get("cls") or ""
        if p["action"] == "update":                               # v21.38: the bill's pending line takes the bank's amount, then is ticked
            r = find_row(entries, p["rk"], p["rid"])
            if r is None or is_reconciled(r):
                res["skipped"] += 1
                continue
            old_amt = _n(r.get("credit")) or _n(r.get("debit"))
            r["credit"], r["debit"] = (float(p["amount"]), None) if p["money_in"] else (None, float(p["amount"]))
            if r.get("recur_monthly"):
                r["hand_amt"] = True                             # this month only: the bill's usual amount is left as it is
            if cls and not r.get("cls"):
                r["cls"] = cls
            if b["date"][:7] == p["rk"] and str(r.get("date")) != b["date"]:
                r["forecast_date"] = r.get("date")
                r["date"] = b["date"]
            r["bank_desc"], r["bank_date"] = b["desc"], b["date"]
            if b.get("id"):
                r["bank_id"] = b["id"]
            stamp(r, "bank match", f"{b['desc']}; amount {old_amt:,.2f} to {float(p['amount']):,.2f}", now=now)
            err = reconcile_row(entries, p["rk"], r["id"], now=now)
            if err:
                res["pending"].append(r.get("desc") or b["desc"])
            else:
                res["matched"] += 1
            continue
        if p["action"] == "match":
            r = find_row(entries, p["rk"], p["rid"])
            if r is None:
                res["skipped"] += 1
                continue
            if cls and not r.get("cls"):
                r["cls"] = cls
            if b["date"][:7] == p["rk"] and str(r.get("date")) != b["date"]:
                r["forecast_date"] = r.get("date")
                r["date"] = b["date"]
            r["bank_desc"], r["bank_date"] = b["desc"], b["date"]
            if b.get("id"):
                r["bank_id"] = b["id"]
            stamp(r, "bank match", b["desc"], now=now)
            err = reconcile_row(entries, p["rk"], r["id"], now=now)
            if err:
                res["pending"].append(r.get("desc") or b["desc"])
            else:
                res["matched"] += 1
        else:                                                    # a new line, or a possible match the user chose to add anyway
            r = add_row(entries, p["k"], b["date"], _clean_bank_desc(b["desc"]), p["amount"], p["money_in"], cls, note="Imported from bank activity")
            r["bank_desc"], r["bank_date"] = b["desc"], b["date"]
            if b.get("id"):
                r["bank_id"] = b["id"]
            stamp(r, "imported", b["desc"], now=now)
            if cls:
                reconcile_row(entries, p["k"], r["id"], now=now)
            else:
                res["pending"].append(r["desc"])
            res["added"] += 1
    return res


AUTO_INTEREST_LIMIT = 5.00
AUTO_BILL_LIMIT = 100.00        # v21.38: a recurring bill under this, matched by name ...
AUTO_BILL_TOLERANCE = 10.00     # ... and within this many dollars of it, is applied without asking


def auto_apply_small_bills(plan, entries: dict, inbox: dict | None, today_date, now=None) -> list:
    """v21.38 (Andrew, Oct 2026): a bank line from the daily fetch that matches a recurring bill's pending line by name, where the bill is
    under $100 and the bank amount is within $10 of it, updates that line to the bank's amount and ticks it -- no review needed. Uses the
    same matching as the import, so nothing is ever added twice. Everything else still waits for review. Returns what was done."""
    acct = plan.expenses.get("sfin_account")
    if not inbox or not acct:
        return []
    ignored = set(plan.expenses.get("inbox_ignored") or [])
    on_ledger = {r.get("bank_id") for rows_ in entries.get("ledger", {}).values() for r in rows_ if r.get("bank_id")}
    rows = [r for r in inbox_rows(inbox.get("lines") or [], acct) if r["id"] not in ignored and r["id"] not in on_ledger and r["debit"] is not None]
    if not rows:
        return []
    props = [p for p in plan_bank_import(entries, rows, month_list(plan, today_date)) if p["action"] in ("update", "match") and p.get("auto")]
    if not props:
        return []
    apply_bank_import(entries, props, {p["i"]: {"apply": True, "cls": p["cls"] or "Core"} for p in props}, now=now)
    out = []
    for p in props:
        r = find_row(entries, p["rk"], p["rid"])
        if r is not None and is_reconciled(r):
            stamp(r, "edited", "reconciled automatically: " + ("exact match" if p["action"] == "match" else
                                                                f"bill under {money(AUTO_BILL_LIMIT, 0)}, within {money(AUTO_BILL_TOLERANCE, 0)}"), now=now)
            out.append(f"{r.get('desc')} {money(p['amount'], 2)}")
    plan.expenses["inbox_done"] = (list(plan.expenses.get("inbox_done") or []) + [p["bank"]["id"] for p in props if p["bank"].get("id")])[-2000:]
    return out


def auto_reconcile_small_interest(plan, entries: dict, inbox: dict | None, today_date, now=None) -> list:
    """Interest credits under $5 from the daily fetch go straight onto the ledger as Excluded and reconciled -- interest is income, not spending,
    so Excluded keeps it out of the spending figures (a money-in Core line would count as a refund). Andrew, Sep 2026. Everything else still
    waits for review. Uses the same checks as the import, so a line already on the ledger is never added twice. Returns what was done."""
    acct = plan.expenses.get("sfin_account")
    if not inbox or not acct:
        return []
    done_ids = set(plan.expenses.get("inbox_done") or [])
    rows = [r for r in inbox_rows(inbox.get("lines") or [], acct) if r["id"] not in done_ids and r["credit"] is not None
            and 0 < float(r["credit"]) < AUTO_INTEREST_LIMIT and "INTEREST" in bank_tokens(r["desc"])]
    if not rows:
        return []
    props = plan_bank_import(entries, rows, month_list(plan, today_date))
    choices = {p["i"]: {"apply": p["action"] not in ("dupe", "outside"), "cls": "Excluded"} for p in props}
    apply_bank_import(entries, props, choices, now=now)
    out = []
    for p in props:
        b = p["bank"]
        if p["action"] in ("new", "near", "match", "update"):
            for r in entries["ledger"].get(p["k"] if p["action"] not in ("match", "update") else p["rk"], []):
                if r.get("bank_id") == b.get("id") and b.get("id"):
                    stamp(r, "edited", f"reconciled automatically: interest under {money(AUTO_INTEREST_LIMIT, 2)}, Excluded", now=now)
                    out.append(f"{b['date']} {money(float(b['credit']), 2)}")
    plan.expenses["inbox_done"] = (list(plan.expenses.get("inbox_done") or []) + [r["id"] for r in rows])[-600:]
    return out


def find_extra(plan: Plan, xid: str):
    return next((x for x in plan.recurring.extras if x["id"] == xid), None)


def make_repeating(plan: Plan, entries: dict, key: str, rid: str):
    """Turn a Core money-out line into a repeating item from next month on. Returns the item, or None if the line does not qualify."""
    r = find_row(entries, key, rid)
    if r is None or r.get("cls") != "Core" or not _n(r.get("debit")) or r.get("recur"):
        return None
    day = int(str(r.get("date") or f"{key}-01")[8:10] or 1)
    x = {"id": new_id(), "name": r.get("desc") or "Repeating item", "amount": float(r["debit"]), "day": day,
         "from": next_month_key(key), "until": None, "skip": []}
    plan.recurring.extras.append(x)
    r["recur"] = x["id"]
    return x


def add_extra(plan: Plan, name: str, amount: float, day: int, start: str) -> dict:
    x = {"id": new_id(), "name": name, "amount": float(amount), "day": int(day), "from": start, "until": None, "skip": []}
    plan.recurring.extras.append(x)
    return x


def stop_repeating(plan: Plan, entries: dict, xid: str, last_key: str) -> int:
    """Stop after `last_key`. Later lines that are still pending are removed; reconciled ones stay. Returns lines removed."""
    x = find_extra(plan, xid)
    if x is None:
        return 0
    x["until"] = last_key
    removed = 0
    for k, rows in entries["ledger"].items():
        if k > last_key:
            keep = [r for r in rows if not (r.get("recur") == xid and not is_reconciled(r))]
            removed += len(rows) - len(keep)
            entries["ledger"][k] = keep
    return removed


def update_extra_amount(plan: Plan, entries: dict, xid: str, amount: float, from_key: str) -> int:
    x = find_extra(plan, xid)
    if x is None:
        return 0
    x["amount"] = float(amount)
    n = 0
    for k, rows in entries["ledger"].items():
        if k >= from_key:
            for r in rows:
                if r.get("recur") == xid and not is_reconciled(r):
                    r["debit"] = float(amount); n += 1
    return n


def delete_row(plan: Plan, entries: dict, key: str, rid: str) -> None:
    r = find_row(entries, key, rid)
    if r is None:
        return
    entries["ledger"][key] = [x for x in entries["ledger"][key] if x.get("id") != rid]
    x = find_extra(plan, r.get("recur") or "")
    if x is not None and key >= x.get("from", "") and key not in x["skip"]:
        x["skip"].append(key)               # a deleted month stays deleted
    tag = r.get("recur_monthly") or r.get("recur_annual") or (("income:" + r["recur_income"]) if r.get("recur_income") else None)
    if tag and not is_reconciled(r):        # v25.22: same for a Recurring items or annual bill line -- deleting it means "not this month"
        sk = entries.setdefault("recur_skip", [])
        if f"{tag}|{key}" not in sk:
            sk.append(f"{tag}|{key}")


def recur_skipped(entries: dict, tag: str, key: str) -> bool:
    """v25.22: True when you deleted this recurring item's pending line for this month (paid another way, say), so it is not posted again."""
    return f"{tag}|{key}" in (entries.get("recur_skip") or [])


# ---- checking-account balance: running balance, lowest point, and the minimum-balance alert ---------------------------
DEFAULT_MIN_BALANCE = 1000.0


def min_balance(plan: Plan) -> float:
    return float(plan.expenses.get("min_balance", DEFAULT_MIN_BALANCE))


def top_up_target(plan: Plan) -> float:
    """The balance a transfer from savings should reach. One threshold, same as the minimum -- there used to be a
    separate, higher 'top up to' setting for extra headroom, but that made two numbers do a job with just one."""
    return min_balance(plan)


def _row_date(r: dict):
    try:
        return pd.Timestamp(r.get("date"))
    except (ValueError, TypeError):
        return pd.Timestamp.max


def _row_key(r: dict):
    return (_row_date(r), r.get("prio", 1))       # a transfer from savings (prio 0) lands before same-day spending


def ordered_rows(rows: list[dict], by_date: bool = True) -> list[dict]:
    """Ledger order for display. By date (stable, so same-day lines keep their order); by_date=False is the workbook's row order."""
    return sorted(rows, key=_row_key) if by_date else list(rows)


def running_balances(rows: list[dict], opening: float, by_date: bool = True) -> dict:
    """Running balance after every line: the opening balance plus each credit and minus each debit, reconciled or not."""
    bal, lines = float(opening), []
    for r in ordered_rows(rows, by_date):
        bal += _n(r.get("credit")) - _n(r.get("debit"))
        lines.append((r, round(bal, 2)))
    return {"opening": round(float(opening), 2), "lines": lines, "closing": round(bal, 2),
            "by_id": {r.get("id"): b for r, b in lines if r.get("id")}}


def start_balance(b: dict) -> float:
    """The balance at the start of the month, counting all money in dated on the 1st (it lands before anything else).
    v25.28: every credit on the 1st, not just transfers from savings -- the monthly Savings deposit and DefComp payment are
    recurring deposits without the transfer flag, so October 2026 showed the bare carried-in 1,356.40 as its lowest point
    when the account never went below about 6,000."""
    return round(b["opening"] + sum(_n(r.get("credit")) for r, _ in b["lines"] if str(r.get("date", ""))[:10].endswith("-01")), 2)


def day_end_points(b: dict) -> list:
    """(date, balance, line) at the END of each day: the bank settles a day's lines together, so money in and out on the same day
    never creates a dip in between (v21.14 -- a 7,700 transfer in and the 7,700 card payment it paid for, both on Sep 28, showed
    as a false -6,343 low because the payment happened to be listed before the transfer). The line given is the day's biggest
    payment out, so an alert names what caused the drop."""
    out, by_day = [], {}
    for r, bal in b["lines"]:
        d = _row_date(r)
        if d not in by_day:
            by_day[d] = len(out)
            out.append([r.get("date"), bal, r])
        slot = out[by_day[d]]
        slot[1] = bal
        if _n(r.get("debit")) > _n((slot[2] or {}).get("debit")):
            slot[2] = r
    return [tuple(x) for x in out]


def low_point(b: dict) -> dict:
    pts = [("Start of month", start_balance(b), None)] + day_end_points(b)
    lo = min(pts, key=lambda p: p[1])
    return {"balance": lo[1], "date": lo[0], "row": lo[2]}


def reconciled_balance(entries: dict, months: list[str], k: str, first_opening: float) -> float:
    """What the bank should show once every line that has cleared is ticked: opening plus reconciled activity up to month k."""
    bal = float(first_opening)
    for mk in months:
        for r in entries["ledger"].get(mk, []):
            if is_reconciled(r):
                bal += _n(r.get("credit")) - _n(r.get("debit"))
        if mk == k:
            break
    return round(bal, 2)


def transfer_plan(entries: dict, mk: str, opening_fn, minimum: float, target: float):
    """Where and how much to transfer so month mk never dips below the minimum and its lowest point reaches the target.
    The transfer is dated at the first dip, so every later balance rises by the same amount."""
    b = running_balances(entries["ledger"].get(mk, []), opening_fn(mk))
    pts = [("Start of month", start_balance(b))] + [(d, bal) for d, bal, _ in day_end_points(b)]
    first = next((d for d, v in pts if v < minimum), None)
    if first is None:
        return None
    return {"month": mk, "date": f"{mk}-01" if first == "Start of month" else first, "amount": math.ceil(max(target, minimum) - min(v for _, v in pts))}


def _scheduled_line(entries: dict, month: str, mark: dict | None):
    """The pending ledger line a 'scheduled at my bank' mark points at, or None."""
    rid = (mark or {}).get("id")
    if not rid:
        return None
    return next((r for r in entries["ledger"].get(month, []) if r.get("id") == rid and not is_reconciled(r)), None)


def scheduled_transfer(entries: dict, month: str):
    """The transfer from savings you have set up at your bank for a month ({'amount', 'date', 'on', 'id'}), or None.
    Ticking 'scheduled at my bank' writes a pending 'Transfer from savings' line into that month's ledger, so the balance projection
    counts the money -- the tick is no longer just a note. A mark counts only while its ledger line is still there and not yet reconciled:
    an old tick from before this change (no ledger line), a line you have deleted, or one that has landed and been ticked off is ignored,
    so a stale tick can never make a dip look covered."""
    m = (entries.get("scheduled_transfers") or {}).get(month)
    line = _scheduled_line(entries, month, m)
    return dict(m, amount=_n(line.get("credit")), date=line.get("date")) if line else None


def set_scheduled_transfer(entries: dict, month: str, date: str, amount: float, on: str) -> None:
    """Record a transfer scheduled at the bank AND put it on the ledger. If the month already has one, it is raised by `amount`
    (the extra the plan now needs) rather than adding a second, stacking line -- one transfer per month at the bank, one line here."""
    marks = entries.setdefault("scheduled_transfers", {})
    line = _scheduled_line(entries, month, marks.get(month))
    if line:
        line["credit"] = round(_n(line.get("credit")) + float(amount), 2)
        line["date"] = min(str(line.get("date")), str(date))
    else:
        line = add_transfer(entries, month, date, amount)
        line["note"] = "Scheduled at your bank"
    marks[month] = {"id": line["id"], "amount": round(_n(line["credit"]), 2), "date": line["date"], "on": on}


def clear_scheduled_transfer(entries: dict, month: str) -> None:
    """Untick: take the pending ledger line off again (only if it hasn't been reconciled) and drop the mark."""
    marks = entries.get("scheduled_transfers") or {}
    line = _scheduled_line(entries, month, marks.get(month))
    if line:
        entries["ledger"][month] = [r for r in entries["ledger"][month] if r is not line]
    marks.pop(month, None)


def prune_scheduled_transfers(entries: dict) -> int:
    """Drop marks with no live ledger line behind them (old note-only ticks, deleted lines, transfers that have landed). Returns how many."""
    marks = entries.get("scheduled_transfers") or {}
    gone = [m for m, v in marks.items() if not _scheduled_line(entries, m, v)]
    for m in gone:
        marks.pop(m, None)
    return len(gone)


def transfer_covered(entries: dict, month: str, needed: float) -> bool:
    """Whether a dip is already covered by a scheduled transfer. Always False now: a scheduled transfer is a ledger line, so the
    projection already counts it, and any dip still showing is money needed on top of it."""
    return False


def pending_transfer(entries: dict) -> bool:
    return any(r.get("xfer") and not is_reconciled(r) for rows in entries["ledger"].values() for r in rows)


TRANSFER_ACTION_DAYS = 30  # how close to the date a transfer is needed by before the app asks you to actually schedule it, rather than just noting it for planning


def transfer_due_soon(fix_date, today_date, window: int = TRANSFER_ACTION_DAYS) -> bool:
    """Whether a transfer needed by fix_date is close enough to prompt scheduling it now. A dip forecast months out is
    likely to move -- a card charge corrected, a bill that turns out different -- several times before it is actually
    due, so asking you to act on it that early is more noise than help; you still see the amount and date for planning,
    just not a button to act on yet. today_date can be a date or an ISO string, to match either caller's own type."""
    try:
        d = _dt.date.fromisoformat(str(fix_date))
        t = today_date if isinstance(today_date, _dt.date) else _dt.date.fromisoformat(str(today_date))
    except (ValueError, TypeError):
        return True   # an odd or missing date: don't hide the prompt over a parsing quirk
    return (d - t).days <= window


def add_transfer(entries: dict, mk: str, date: str, amount: float) -> dict:
    ensure_ids(entries["ledger"].setdefault(mk, []))
    r = {"id": new_id(), "date": date, "desc": "Transfer from savings", "credit": float(amount), "debit": None, "rec": "Pending",
         "cls": "Excluded", "note": "Added by the balance alert", "xfer": True, "prio": 0}
    entries["ledger"][mk].append(r)
    return r


def balance_alerts(entries: dict, months: list[str], k: str, opening_fn, minimum: float, first_opening: float,
                   target: float | None = None, include_now: bool = True, today_str: str | None = None) -> list[dict]:
    """Alerts for the reconciled balance now (if include_now) and for the projected low point in month k and the month after.
    Each alert says how much to transfer to reach the target, and the date to do it by."""
    target = max(minimum if target is None else target, minimum)
    out = []
    if include_now:
        rb = reconciled_balance(entries, months, k, first_opening)
        if rb < minimum:
            out.append({"kind": "now", "month": k, "balance": rb, "transfer": math.ceil(target - rb), "fix_date": today_str or f"{k}-01"})
    for mk in [k] + ([months[months.index(k) + 1]] if k in months and months.index(k) + 1 < len(months) else []):
        b = running_balances(entries["ledger"].get(mk, []), opening_fn(mk))
        lo = low_point(b)
        if lo["balance"] < minimum:
            tp = transfer_plan(entries, mk, opening_fn, minimum, target)
            out.append({"kind": "low", "month": mk, "balance": lo["balance"], "date": lo["date"], "desc": (lo["row"] or {}).get("desc", ""),
                        "transfer": tp["amount"], "fix_date": tp["date"]})
    return out


def prev_month_key(key: str) -> str:
    y, m = map(int, key.split("-"))
    return f"{y - 1}-12" if m == 1 else f"{y}-{m - 1:02d}"


def back_opening(entries: dict, first_month: str, key: str):
    """Opening balance of an earlier month: start from the first tracked month's opening and undo each month's activity going back.
    Returns None when a month in between has no lines (the chain is unknown)."""
    b = float(entries["opening"].get(first_month, 0.0))
    mk = first_month
    while mk > key:
        mk = prev_month_key(mk)
        rows = entries["ledger"].get(mk, [])
        if not rows:
            return None
        b -= sum(_n(r.get("credit")) - _n(r.get("debit")) for r in rows)
    return round(b, 2)


# ---- checking the ledger against the bank: bank-style running balance and "why don't they match" hints ---------------
def bank_balances(rows: list[dict], opening: float, by_date: bool = True) -> list[tuple[dict, float]]:
    """The balance your bank would show after each RECONCILED line (pending lines have not reached the bank yet)."""
    bal, out = float(opening), []
    for r in ordered_rows(rows, by_date):
        if is_reconciled(r):
            bal += _n(r.get("credit")) - _n(r.get("debit"))
            out.append((r, round(bal, 2)))
    return out


def bank_opening(entries: dict, months: list[str], k: str, first_opening: float) -> float:
    """What the bank showed at the start of month k: the reconciled balance at the end of the month before."""
    return round(float(first_opening), 2) if k not in months or months.index(k) == 0 else reconciled_balance(entries, months, months[months.index(k) - 1], first_opening)


def explain_difference_items(entries: dict, plan: Plan, months: list[str], k: str, diff: float, inbox: dict | None = None) -> list[dict]:
    """diff = bank balance minus ledger balance. What would explain it, most likely first, each as {"text", "act", "found"}: a line not ticked
    yet (act: tick it), a line ticked before it reached the bank -- typically a card payment the card company already shows but checking has
    not taken yet (act: untick it), a monthly item with no line, or, when nothing fits, general advice (found False)."""
    if abs(diff) < 0.005:
        return []
    amt, items = round(abs(diff), 2), []
    side = "debit" if diff < 0 else "credit"
    other = "credit" if diff < 0 else "debit"
    scope = months[: months.index(k) + 1] if k in months else months

    def when(r):
        try:
            return _day(str(r.get("date"))[:10])
        except Exception:  # noqa: BLE001
            return str(r.get("date", ""))

    card_note = ""
    if diff > 0 and inbox:                               # the card feeds: a payment the card already shows that checking has not taken yet
        cards = {a["id"]: a for a in (plan.expenses.get("sfin_card_accounts") or []) if a.get("id")}
        acct = plan.expenses.get("sfin_account")
        lines = inbox.get("lines") or []
        for ln in lines:
            if ln.get("acct") in cards and ln["amount"] > 0 and abs(ln["amount"] - amt) < 0.005 and is_card_payment_credit(ln.get("desc", "")):
                d = str(ln["date"])[:10]
                if not any(x.get("acct") == acct and abs(-x["amount"] - amt) < 0.005 and str(x["date"])[:10] >= d for x in lines):
                    card_note = f"{cards[ln['acct']].get('name') or ln.get('acct_name') or 'The card'} shows a payment of ${amt:,.2f} on {d} that has not left checking yet."
                    break
    for mk in scope[-2:]:                                # a line ticked before it reached the bank: only recent months are likely
        for r in entries["ledger"].get(mk, []):
            if is_reconciled(r) and not r.get("bank_id") and abs(_n(r.get(other)) - amt) < 0.005:
                items.append({"text": f"{r.get('desc')} on {when(r)} for ${amt:,.2f} is ticked, but has not reached your bank yet. "
                                      + (card_note + " " if card_note else ("A card payment often shows at the card company a day or two before it leaves checking. " if other == "debit" else ""))
                                      + "Untick it now, and the bank fetch ticks it when it clears.",
                              "act": ("untick", mk, r["id"]) if r.get("id") else None, "found": True})
    for mk in scope:
        for r in entries["ledger"].get(mk, []):
            if not is_reconciled(r) and abs(_n(r.get(side)) - amt) < 0.005:
                items.append({"text": f"{r.get('desc')} on {when(r)} for ${amt:,.2f} is not ticked yet. If it has cleared at the bank, tick it.",
                              "act": ("tick", mk, r["id"]) if r.get("id") else None, "found": True})
    if card_note and not any(i["act"] and i["act"][0] == "untick" for i in items):
        items.append({"text": card_note + " That is the difference; it goes away when the payment leaves checking, usually within one to three business days.",
                      "act": None, "found": True})
    if diff < 0:
        names = {n.lower(): v for n, v in plan.recurring.monthly.items()}
        names.update({x["name"].lower(): float(x["amount"]) for x in plan.recurring.extras})
        have = " ".join(str(r.get("desc", "")).lower() for r in entries["ledger"].get(k, []))
        for n, v in names.items():
            if abs(v - amt) < 0.005 and n.split()[0] not in have:
                items.append({"text": f"{n.title()} (a ${v:,.2f} monthly item) has no line in this month. Add it if it has gone out.", "act": None, "found": True})
    if not items:
        items.append({"text": f"No single line in the ledger or the card feeds equals ${amt:,.2f}. Look for a transaction at your bank that is not in the ledger, "
                              "or two that add up to it.", "act": None, "found": False})
    seen, out = set(), []
    for i in items:
        if i["text"] not in seen:
            seen.add(i["text"]); out.append(i)
    return out


def explain_difference(entries: dict, plan: Plan, months: list[str], k: str, diff: float, inbox: dict | None = None) -> list[str]:
    """The same, as plain sentences."""
    return [i["text"] for i in explain_difference_items(entries, plan, months, k, diff, inbox)]


# ---- the register: every line with the balance after it, and Wells checkpoints to find the first mismatch --------------
def register_lines(rows: list[dict], opening: float, bank_open: float) -> list[dict]:
    """Date-ordered register. For each line: the running balance (every line, like the workbook's Balance column), the bank balance
    (reconciled lines only), and what to compare a Wells balance with: the bank balance for a ticked line, the running balance otherwise."""
    bank = {id(r): b for r, b in bank_balances(rows, bank_open)}
    out = []
    for r, bal in running_balances(rows, opening)["lines"]:
        rec = is_reconciled(r)
        ref = bank.get(id(r)) if rec else bal
        w = r.get("wells")
        out.append({"row": r, "date": r.get("date"), "desc": r.get("desc"), "out": r.get("debit"), "in": r.get("credit"), "running": bal,
                    "bank": bank.get(id(r)), "rec": rec, "ref": ref, "wells": w, "diff": None if w is None else round(float(w) - ref, 2)})
    return out


def wells_findings(lines: list[dict]):
    """Walk the checkpoints in date order. Returns None with no checkpoints; otherwise the first line where Wells and the ledger differ
    (and the last one that matched), or a match."""
    checkpoints = [l for l in lines if l["wells"] is not None]
    if not checkpoints:
        return None
    last_ok = None
    for l in checkpoints:
        if abs(l["diff"]) >= 0.005:
            between = [x for x in lines if (last_ok is None or x["row"] is not last_ok["row"]) and _in_span(lines, x, last_ok, l)]
            return {"status": "mismatch", "first": l, "last_ok": last_ok, "diff": l["diff"], "between": between}
        last_ok = l
    return {"status": "match", "last_ok": last_ok}


def _in_span(lines: list[dict], x: dict, start: dict | None, end: dict) -> bool:
    """Is line x after `start` (or from the beginning) and up to and including `end`?"""
    idx = {id(l["row"]): i for i, l in enumerate(lines)}
    lo = -1 if start is None else idx[id(start["row"])]
    return lo < idx[id(x["row"])] <= idx[id(end["row"])]


def clear_wells(entries: dict, key: str) -> int:
    n = 0
    for r in entries["ledger"].get(key, []):
        if "wells" in r:
            r.pop("wells"); n += 1
    return n


def merge_extras(plan: Plan, entries: dict, hist: dict) -> dict:
    """The other parts of a history file: monthly MAGI history and added plan inputs. Nothing that already exists is changed."""
    out = {"magi": [], "plan": [], "forecast": [], "invest": [], "balances": []}
    bal = entries.setdefault("balances", {})                    # v21.46: month-end balances for earlier months (only accounts still blank)
    for key, v in sorted((hist.get("balances") or {}).items()):
        if not isinstance(v, dict):
            continue
        cur = bal.setdefault(str(key), {})
        for a, amt in v.items():
            if a in NINE_ACCOUNTS + ["capital"] and isinstance(amt, (int, float)) and not isinstance(cur.get(a), (int, float)):
                cur[a] = float(amt)
                out["balances"].append(f"{key} {a}")
        if isinstance(v.get("notes"), str) and v["notes"] and not cur.get("notes"):
            cur["notes"] = v["notes"]
    out["replaced"] = []                                         # v21.49: corrections a file names on purpose ("balances_replace"); each is shown before you add it
    for key, v in sorted((hist.get("balances_replace") or {}).items()):
        if not isinstance(v, dict):
            continue
        cur = bal.setdefault(str(key), {})
        for a, amt in v.items():
            if a in NINE_ACCOUNTS + ["capital"] and isinstance(amt, (int, float)):
                was = cur.get(a)
                if isinstance(was, (int, float)) and abs(float(was) - float(amt)) < 0.005:
                    continue
                cur[a] = float(amt)
                out["replaced"].append((str(key), a, was, float(amt)))
        why = v.get("why")
        if isinstance(why, str) and why and why not in (cur.get("notes") or ""):
            cur["notes"] = ((cur.get("notes") or "") + " " + why).strip()
    inv = entries.setdefault("invest_income", {})             # v21.16: interest and dividends by month and account (months not there yet)
    for key, v in sorted((hist.get("invest_income") or {}).items()):
        if key not in inv and isinstance(v, dict):
            inv[key] = {f: float(v[f]) if isinstance(v.get(f), (int, float)) else v.get(f) for f in v}
            out["invest"].append(key)
    est = entries.setdefault("invest_income_est", {})
    for yk, v in (hist.get("invest_income_est") or {}).items():
        if str(yk) not in est and isinstance(v, dict) and isinstance(v.get("amount"), (int, float)):
            est[str(yk)] = {"amount": float(v["amount"]), "months": [str(m) for m in v.get("months") or []], "note": str(v.get("note") or "")}
            out["invest"].append(f"estimate {yk}")
    fl = entries.setdefault("forecast_lines", {})
    for key, rows in sorted((hist.get("forecast_lines") or {}).items()):        # forecast lines for months that have none yet
        if key not in fl and not any(not r.get("xfer") for r in entries["ledger"].get(key, [])) and isinstance(rows, list):
            fl[key] = [dict(r) for r in rows]
            out["forecast"].append(key)
    ig = hist.get("inv_growth") or {}                          # v21.39: investment growth figures (only what is not there yet)
    if ig:
        g = _growth_store(entries)
        for part in ("start", "values", "flows"):
            for key, v in (ig.get(part) or {}).items():
                if isinstance(v, dict):
                    cur = g[part].setdefault(str(key), {})
                    for a, amt in v.items():
                        if a not in cur and isinstance(amt, (int, float)):
                            cur[a] = float(amt)
                            out["invest"].append(f"growth {part} {key} {a}")
    have = entries.setdefault("magi_history", {})
    for key, v in sorted((hist.get("magi_history") or {}).items()):
        if key not in have:
            have[key] = dict(v) if isinstance(v, dict) else {"total": float(v)}
            out["magi"].append(key)
    for section, items in (hist.get("plan_add") or {}).items():
        target = {"expenses": plan.expenses, "meta": plan.meta}.get(section)
        if target is None or not isinstance(items, dict):
            continue
        for name, value in items.items():
            if name not in target:
                target[name] = json.loads(json.dumps(value))
                out["plan"].append(f"{section}.{name}")
    return out


# ---- overview: the numbers behind the quick health check --------------------------------------------------------------------
def latest_net_worth(entries: dict):
    """Net worth and financial assets from the latest month in which all nine accounts were entered."""
    done = [r for r in networth_table(entries) if r["complete"]]          # v21.45: the same months (and statement values) as the Month by month table
    if not done:
        return None
    r = done[-1]
    return {"month": r["month"], "assets": r["assets"], "capital": round(r["capital"] or 0.0, 2), "net_worth": r["net_worth"]}


def aca_practice(entries: dict, rate: float, months: list[str], year: int, guardrail: float, reference: float) -> dict:
    """The practice-year MAGI check (no subsidy limit applies yet): running MAGI so far, a full-year forecast, and the room left under the guardrail.
    Running MAGI = the earlier months' history plus every month entered since (the current draft month included).
    Forecast = the average of the finalized months (history plus finalized months) times 12."""
    hist = entries.get("magi_history", {})
    hk = sorted(k for k in hist if k.startswith(f"{year}-"))
    if len(hk) < 7:
        return {"needs_history": True}
    base = sum(float(hist[k].get("total", 0.0)) for k in hk)
    running, fin_sum, nfin = base, 0.0, 0
    for mk in months:
        if not mk.startswith(f"{year}-") or mk in hist:
            continue
        tot = income_totals(income_record(entries, mk, rate))["total"]
        fin = entries["magi"].get(mk, {}).get("status") == "Finalized"
        if fin:
            fin_sum += tot
            nfin += 1
        if tot != 0 or fin:
            running += tot
    forecast = (base + fin_sum) / (len(hk) + nfin) * 12
    over_ref, over_guard = running > reference or forecast > reference, running > guardrail or forecast > guardrail
    return {"needs_history": False, "running": round(running, 2), "forecast": round(forecast, 2), "guardrail": guardrail, "reference": reference,
            "room": round(guardrail - running, 2), "status": "bad" if over_ref else ("warn" if over_guard else "ok")}


def networth_table(entries: dict) -> list[dict]:
    """One row per month that has balances: every account, financial assets, capital assets, net worth and the change since the last complete month.
    Totals appear only for a month in which all nine accounts were entered."""
    rows, prev = [], None
    gv = (entries.get("inv_growth") or {}).get("values") or {}          # v21.45: month-end values from the statements (Investment growth figures)
    for k in sorted(set(entries.get("balances", {})) | set(gv)):
        b = entries.get("balances", {}).get(k) or {}
        sv = gv.get(k) or {}                                               # a statement value comes first, as in growth_value()
        accts = {a: float(sv[a]) if isinstance(sv.get(a), (int, float)) else b.get(a) for a in NINE_ACCOUNTS}
        if not any(isinstance(v, (int, float)) for v in list(accts.values()) + [b.get("capital")]):
            continue
        complete = all(isinstance(v, (int, float)) for v in accts.values())
        assets = round(sum(float(v) for v in accts.values()), 2) if complete else None
        cap = float(b["capital"]) if isinstance(b.get("capital"), (int, float)) else None
        nw = round(assets + (cap or 0.0), 2) if assets is not None else None
        change = None if nw is None or prev is None else round(nw - prev, 2)
        if nw is not None:
            prev = nw
        rows.append({"month": k, **accts, "assets": assets, "capital": cap, "net_worth": nw, "change": change, "complete": complete})
    return rows


# ---- capital assets: an itemized list with a year-by-year forecast ----------------------------------------------------------------
def capital_items(plan: Plan) -> list[dict]:
    """House and the vehicles come from plan.meta['capital_items']; the RV comes from the cash inputs, so its sale proceeds in the cash flow
    and its value here can never disagree. Empty until the list has been added."""
    items = [dict(x) for x in plan.meta.get("capital_items", [])]
    if not items:
        return []
    rv = {"name": "RV", "value": float(plan.cash.rv_current_value), "rate": -float(plan.cash.rv_depreciation), "until": None,
          "sale_year": int(plan.cash.rv_sale_year) if plan.cash.rv_sale_year else None, "linked": True}   # 0 or blank: no sale assumed
    return items[:1] + [rv] + items[1:]


def capital_value(item: dict, year: int, start_year: int) -> float:
    if item.get("sale_year") and year >= int(item["sale_year"]):
        return 0.0
    n = (min(year, int(item["until"])) if item.get("until") is not None else year) - start_year
    return float(item["value"]) * (1.0 + float(item["rate"])) ** max(n, 0)


def capital_total_now(plan: Plan) -> float:
    return round(sum(float(x["value"]) for x in capital_items(plan)), 2)


def capital_forecast(plan: Plan, years) -> pd.DataFrame:
    """Value of each item at each year, and the total (the workbook's Capital Assets sheet)."""
    start = int(str(plan.meta.get("as_of", "2026-08-31"))[:4])
    items = capital_items(plan)
    rows = []
    for y in years:
        row = {"Year": str(y)}
        for it in items:
            row[it["name"]] = capital_value(it, int(y), start)
        row["Total"] = sum(row[it["name"]] for it in items)
        rows.append(row)
    return pd.DataFrame(rows)


def income_watch(entries: dict, rate: float, months: list[str], year: int, k: str, guardrail: float, reference: float, adjust: float = 0.0) -> dict:
    """The 'if this continues' check for the month being entered.
    Year so far = earlier history (the practice year) plus every month entered through k. If this month's recurring income repeats every
    month to December, the year ends at: year so far + (this month less realized gains) x months left. Realized gains count once."""
    hist = entries.get("magi_history", {})
    hk = [m for m in hist if m.startswith(f"{year}-")]
    # a year that tracking began part-way through needs the earlier months from the history import
    if months and months[0].startswith(f"{year}-") and int(months[0][5:7]) > 1 and len(hk) < int(months[0][5:7]) - 1:
        return {"needs_history": True}
    ytd = sum(float(hist[m].get("total", 0.0)) for m in hk)
    for mk in months:
        if mk.startswith(f"{year}-") and mk <= k and mk not in hist:
            ytd += income_totals(income_record(entries, mk, rate))["total"]
    t = income_totals(income_record(entries, k, rate))
    mth = int(k[5:7])
    remaining = 12 - mth
    recurring = t["total"] - t["gains"]
    # v21.16: quarterly fund dividends (March, June, September, December). In a quarterly month the last known quarterly amount is taken out
    # before this month is repeated, and it is added back once for each quarterly month still to come -- so neither a quarterly month
    # (repeated nine times) nor an ordinary one (which would leave the coming quarterlies out) gives a false reading.
    q = quarterly_extra(entries, k, rate)
    q_here = quarterly_part(entries, k, rate, t)      # a month still being filled in (no fund dividends yet) is not discounted
    q_left = sum(1 for m2 in range(mth + 1, 13) if m2 in QUARTER_MONTHS)
    steady = recurring - q_here
    cont = ytd + steady * remaining + q * q_left + adjust     # adjust: a capital loss carried over (negative), never in a month's entries
    over_ref, over_guard = ytd > reference or cont > reference, ytd > guardrail or cont > guardrail
    return {"needs_history": False, "ytd": round(ytd, 2), "this_month": round(t["total"], 2), "recurring": round(recurring, 2), "remaining": remaining,
            "quarterly": round(q, 2), "quarterly_here": round(q_here, 2), "quarter_month": mth in QUARTER_MONTHS, "quarterly_left": q_left, "steady": round(steady, 2),
            "continues": round(cont, 2), "guardrail": guardrail, "reference": reference, "room": round(guardrail - ytd, 2),
            "ytd_over_guardrail": ytd > guardrail, "ytd_over_reference": ytd > reference,
            "status": "bad" if over_ref else ("warn" if over_guard else "ok")}


# ---- the whole-year balance outlook -------------------------------------------------------------------------------------------------
def start_month_from_forecast(entries: dict, mk: str) -> int:
    """Copy a month's forecast lines into the ledger so it can be reconciled. Does nothing if the month already has lines."""
    rows = entries.get("forecast_lines", {}).get(mk)
    have = entries["ledger"].get(mk, [])
    if not rows or any(not r.get("xfer") for r in have):
        return 0
    entries["ledger"][mk] = [dict(r) for r in rows] + have        # keep a scheduled transfer that was already there
    ensure_ids(entries["ledger"][mk])
    return len(rows)


def is_planned_transfer(r: dict) -> bool:
    """A one-time transfer from savings that the workbook wrote into a forecast month (a credit, not income)."""
    return _n(r.get("credit")) > 0 and not _n(r.get("debit")) and str(r.get("desc", "")).lower().startswith("one-time savings transfer")


def outlook(entries: dict, months: list[str], first_opening: float, minimum: float, target: float, from_month: str,
            today_str: str | None = None, use_planned: bool = False) -> dict:
    """The checking balance month by month from from_month: a month with real lines uses them, a later month uses the forecast lines, and each
    month opens where the one before closed.
    The workbook's forecast months contain one-time transfers from savings (annual bills). By default these are treated as transfers, not income:
    the balance is recalculated without them and the transfers actually needed to keep every month above the minimum are worked out (each is
    dated at the first dip and lifts every later balance, so later months are checked with the earlier transfers already counted). With
    use_planned=True the workbook's own transfers are kept as ordinary credits, which reproduces the workbook's balances exactly.
    In the current month only the days from today on count towards the lowest point and any transfer (a dip that has passed cannot be fixed).
    Each row: opening and month-end include the transfers so far; lowest is the lowest point before that month's own transfer."""
    target = max(minimum if target is None else target, minimum)
    fl = entries.get("forecast_lines", {})
    bal, carry = float(first_opening), 0.0                  # bal: the chain with no computed transfer; carry: transfers needed so far
    rows, transfers = [], []
    for mk in months:
        actual = entries["ledger"].get(mk, [])
        real = [r for r in actual if not r.get("xfer")]      # a transfer line alone doesn't mean the month has been started
        fcl = [] if real else fl.get(mk, [])
        planned = [r for r in fcl if is_planned_transfer(r)]
        lines = actual if real else ([r for r in actual if r.get("xfer")] + (fcl if use_planned else [r for r in fcl if not is_planned_transfer(r)]))
        if mk < from_month:
            bal += sum(_n(r.get("credit")) - _n(r.get("debit")) for r in actual)
            continue
        if not lines:
            continue
        opening = bal + carry
        b = running_balances(lines, opening)
        if mk == from_month and today_str:
            fut = [r for r in lines if str(r.get("date", ""))[:10] >= today_str]
            now_bal = opening + sum(_n(r.get("credit")) - _n(r.get("debit")) for r in lines if str(r.get("date", ""))[:10] < today_str)
            lo = low_point(running_balances(fut, now_bal))
            if lo["date"] == "Start of month":
                lo = dict(lo, date="Today")
            tp = transfer_plan({"ledger": {mk: fut}}, mk, lambda _m, o=now_bal: o, minimum, target)
            if tp and tp["date"] == f"{mk}-01":
                tp = dict(tp, date=today_str)
        else:
            lo = low_point(b)
            tp = transfer_plan({"ledger": {mk: lines}}, mk, lambda _m, o=opening: o, minimum, target)
        amount = tp["amount"] if tp else 0
        planned_amt = round(sum(_n(r.get("credit")) for r in planned), 2)
        if tp:
            transfers.append({"month": mk, "date": tp["date"], "amount": amount, "lowest": lo["balance"], "carried": round(carry, 2), "planned": planned_amt})
            carry += amount
        bal += sum(_n(r.get("credit")) - _n(r.get("debit")) for r in lines)
        rows.append({"month": mk, "source": "Actual" if real else "Forecast", "opening": round(opening, 2),
                     "in": round(sum(_n(r.get("credit")) for r in lines), 2), "out": round(sum(_n(r.get("debit")) for r in lines), 2),
                     "closing": round(bal + carry, 2), "lowest": lo["balance"], "lowest_date": lo["date"], "below": lo["balance"] < minimum,
                     "transfer": amount, "transfer_date": tp["date"] if tp else None, "cum_transfers": round(carry, 2),
                     "planned": planned_amt, "planned_date": planned[0]["date"] if planned else None})
    return {"rows": rows, "transfers": transfers, "total_transfers": round(carry, 2),
            "planned_total": round(sum(r["planned"] for r in rows), 2),
            "lowest": min(rows, key=lambda r: r["lowest"]) if rows else None}


def alerts_by_outlook(alerts: list[dict], ol: dict) -> list[dict]:
    """Line up the month-by-month balance alerts with the outlook's transfer plan. The alerts chain each month from the ledger alone, so a
    transfer planned or scheduled in an earlier month -- not a ledger line until it actually lands -- isn't counted, and a later month that
    the earlier transfer keeps above the minimum still looked like a separate dip needing its own transfer (a second button, a second orange
    tile, a second email; tapping it would have moved money twice). The outlook dates each transfer at the first dip and carries it into every
    later month, so it is the authority here:
      - a month the outlook needs no transfer of its own for, because an earlier planned transfer covers it, has no alert;
      - a month that still needs one on top of an earlier transfer gets the outlook's figures -- only the extra amount, and its low point
        with the earlier transfer counted.
    Anything else is left exactly as it was ('now' alerts; months before the outlook starts; a month with no earlier transfer)."""
    by = {t["month"]: t for t in ol.get("transfers") or []}
    rows = {r["month"]: r for r in ol.get("rows") or []}
    first = min(by) if by else None
    out = []
    for a in alerts:
        if a["kind"] != "low":
            out.append(a)
            continue
        t = by.get(a["month"])
        if t is None:
            if first is not None and first < a["month"]:
                continue
            out.append(a)
            continue
        if t.get("carried", 0) > 0:
            r = rows.get(a["month"]) or {}
            a = dict(a, transfer=t["amount"], fix_date=t["date"], balance=r.get("lowest", a["balance"]))
        out.append(a)
    return out


def planned_balance_alerts(entries: dict, months: list[str], k: str, minimum: float, target: float, include_now: bool, today_str: str) -> list[dict]:
    """balance_alerts() for month k (and the one after), lined up with the outlook's transfer plan (see alerts_by_outlook). What the Dashboard,
    Monthly updates, the banner on every page and the nightly email all use, so none of them can offer a transfer the plan doesn't need."""
    first = entries["opening"].get(months[0], 0.0) if months else 0.0
    al = balance_alerts(entries, months, k, lambda mk: ledger_opening(entries, months, mk), minimum, first, target, include_now, today_str)
    if not any(a["kind"] == "low" for a in al):
        return al
    cur = today_str[:7]
    cur = cur if cur in months else (months[0] if months and cur < months[0] else (months[-1] if months else cur))
    return alerts_by_outlook(al, outlook(entries, months, first, minimum, target, cur, today_str))


def ledger_opening(entries: dict, months: list[str], k: str) -> float:
    """Month k's opening balance in the ledger: the first month's opening plus every line of every earlier month, reconciled or not."""
    b = float(entries["opening"].get(months[0], 0.0)) if months else 0.0
    for mk in months:
        if mk == k:
            return b
        b += sum(_n(r.get("credit")) - _n(r.get("debit")) for r in entries["ledger"].get(mk, []))
    return b


def cash_state(plan: Plan, entries: dict, months: list[str], cur: str, today_date) -> dict:
    """The one decision behind the Dashboard's checking tile, and behind the checking alert in the reminder email -- kept here so the app and
    the nightly bank job can't disagree about it. Returns a dict: 'state' is one of
      now        the reconciled balance is below the minimum already
      soon       a dip, not covered by a transfer scheduled at the bank, within TRANSFER_ACTION_DAYS: orange, and an open alert
      far        the same further off: a heads-up only, not an alert (it will become one once it is close enough to act on)
      scheduled  every dip is covered by a transfer you've marked scheduled
      above      no dip at all ('empty' when there is nothing to project yet)
    'near' says whether it came from this month and next (with a day) or from the longer outlook (by month); 'alert' is what the reminder
    note carries for it (an id, a kind and a month: never an amount), or None."""
    minimum, target = min_balance(plan), top_up_target(plan)
    ts = today_date.strftime("%Y-%m-%d")
    first = entries["opening"].get(months[0], 0.0) if months else 0.0
    alerts = planned_balance_alerts(entries, months, cur, minimum, target, True, ts)
    now_a, low_a = [a for a in alerts if a["kind"] == "now"], [a for a in alerts if a["kind"] == "low"]
    if now_a:
        return {"state": "now", "near": True, "minimum": minimum, "month": cur, "alert": {"id": f"cash_now:{cur}", "kind": "cash_now", "month": cur}}
    if low_a:
        open_ = [a for a in low_a if not transfer_covered(entries, a["month"], a["transfer"])]
        soon = [a for a in open_ if transfer_due_soon(a["fix_date"], today_date)]
        pick = soon[0] if soon else (open_[0] if open_ else low_a[0])
        state = "soon" if soon else ("far" if open_ else "scheduled")
        return {"state": state, "near": True, "minimum": minimum, "month": pick["month"], "balance": pick["balance"], "date": pick["date"],
                "fix_date": pick["fix_date"], "alert": {"id": f"cash_low:{pick['month']}", "kind": "cash_low", "month": pick["month"]} if state == "soon" else None}
    ol = outlook(entries, months, first, minimum, target, cur, ts)
    if not ol["rows"]:
        return {"state": "empty", "near": False, "minimum": minimum, "alert": None}
    dips = [r for r in ol["rows"] if r["below"]]
    open_ = [r for r in dips if not transfer_covered(entries, r["month"], r["transfer"])]
    soon = [r for r in open_ if transfer_due_soon(r.get("transfer_date") or f"{r['month']}-01", today_date)]
    if soon or open_ or dips:
        pick = soon[0] if soon else (open_[0] if open_ else dips[0])
        state = "soon" if soon else ("far" if open_ else "scheduled")
        return {"state": state, "near": False, "minimum": minimum, "month": pick["month"], "balance": pick["lowest"],
                "alert": {"id": f"cash_low:{pick['month']}", "kind": "cash_low", "month": pick["month"]} if state == "soon" else None}
    return {"state": "above", "near": False, "minimum": minimum, "month": ol["rows"][-1]["month"], "alert": None}


def bank_balance_alert(plan: Plan, inbox: dict | None, today_date) -> dict | None:
    """The real checking balance at the bank, from this morning's fetch, below the minimum -- whether or not its lines have been reconciled
    yet, so an unexpected charge is caught the day it lands rather than once you have ticked it. None when it is fine or unknown."""
    acct = plan.expenses.get("sfin_account")
    snap = ((inbox or {}).get("snapshots") or {}).get(today_date.strftime("%Y-%m")) or {}
    if not acct or snap.get("date") != today_date.isoformat():     # only today's own reading counts: an old balance says nothing about now
        return None
    bal = next((a.get("balance") for a in snap.get("accounts") or [] if a.get("id") == acct), None)
    if bal is None or float(bal) >= min_balance(plan):
        return None
    return {"id": "cash_bank_now", "kind": "cash_bank_now"}


def remember_live_balance(entries: dict, acct: str, accts: list, now=None) -> bool:
    """v21.19: a fetch you run yourself brings back the checking balance as it stands now. It is kept (with the time) so the bank check
    compares the ledger with that balance rather than with the daily job's older one -- otherwise lines imported from your own fetch
    showed up as a difference against this morning's balance."""
    a = next((x for x in accts or [] if x.get("id") == acct), None)
    if not acct or a is None or a.get("balance") is None:
        return False
    entries["bank_live"] = {"acct": acct, "balance": round(float(a["balance"]), 2), "t": _now_iso(now)}
    return True


def auto_bank_check(plan: Plan, entries: dict, inbox: dict | None, today_date) -> dict | None:
    """The bank check done for you: the checking balance from the latest fetch against the ledger's reconciled balance for this month.
    A line ticked by hand after that fetch ran is left out of the ledger side (the bank's reading is older than the tick), unless it came from
    the fetch itself. status: 'match', 'waiting' (fetched lines not reviewed yet, so a difference is expected) or 'off'. None when unknown."""
    acct = plan.expenses.get("sfin_account")
    snaps = (inbox or {}).get("snapshots") or {}
    if not acct or not snaps:
        return None
    key = max(snaps)
    snap = snaps[key]
    bal = next((a.get("balance") for a in snap.get("accounts") or [] if a.get("id") == acct), None)
    months = month_list(plan, today_date)
    k = today_date.strftime("%Y-%m")
    if bal is None or k not in months or key != k:
        return None
    ledger = reconciled_balance(entries, months, k, entries["opening"].get(months[0], 0.0))
    try:
        fetched = _dt.datetime.strptime(str(inbox.get("updated", ""))[:16], "%Y-%m-%d %H:%M").replace(tzinfo=_dt.timezone.utc)
    except ValueError:
        fetched = _dt.datetime.combine(_dt.date.fromisoformat(snap["date"]) + _dt.timedelta(days=1), _dt.time.min, tzinfo=_dt.timezone.utc)
    source = "daily"
    live = entries.get("bank_live") or {}
    if live.get("acct") == acct and live.get("balance") is not None:     # your own fetch, if it is newer than the daily job's, is the bank side
        try:
            lt = _dt.datetime.fromisoformat(str(live["t"]))
            lt = lt if lt.tzinfo else lt.replace(tzinfo=_dt.timezone.utc)
        except ValueError:
            lt = None
        if lt is not None and lt > fetched and lt.astimezone(_dt.timezone.utc).strftime("%Y-%m") >= k:
            bal, fetched, source = float(live["balance"]), lt, "manual"
    late = 0.0
    for mk in months[: months.index(k) + 1]:
        for r in entries["ledger"].get(mk, []):
            if is_reconciled(r) and not r.get("bank_id") and r.get("rec_at"):
                try:
                    t = _dt.datetime.fromisoformat(str(r["rec_at"]))
                except ValueError:
                    continue
                if t > fetched:
                    late += _n(r.get("credit")) - _n(r.get("debit"))
    ledger = round(ledger - late, 2)
    diff = round(float(bal) - ledger, 2)
    waiting = inbox_waiting(plan, entries, inbox, today_date)
    status = "match" if abs(diff) < 0.005 else ("waiting" if waiting else "off")
    if source == "manual":                                              # the day of your fetch, in your own time zone
        try:
            from zoneinfo import ZoneInfo as _ZI
            ldate = fetched.astimezone(_ZI(str(plan.meta.get("timezone", DEFAULT_TZ)))).date().isoformat()
        except Exception:  # noqa: BLE001 - an unknown zone falls back to UTC
            ldate = fetched.date().isoformat()
    return {"k": k, "bank": round(float(bal), 2), "ledger": ledger, "diff": diff, "date": snap.get("date") if source == "daily" else ldate,
            "waiting": waiting, "status": status, "late": round(late, 2), "source": source, "at": fetched.isoformat()}


def auto_bank_record(entries: dict, chk: dict | None) -> bool:
    """A match found by the automatic check goes into the same record as a match you confirm by hand, once per fetch."""
    if not chk or chk["status"] != "match":
        return False
    checks = entries.setdefault("bank_checks", [])
    if any(c.get("auto") == chk["date"] for c in checks):
        return False
    checks.append({"t": _now_iso(), "month": chk["k"], "balance": chk["bank"], "auto": chk["date"]})
    return True


# ---- cash flow: what makes up one year ---------------------------------------------------------------------------------------------
def cash_year_detail(plan: Plan, R: dict, year: int):
    """The parts of one year of the cash flow, in order, with whether each counts as income for the ACA figure.
    Starting cash plus every line equals the year's ending cash."""
    cf, ts = R["cf"], R["ts"]
    if year not in cf.index:
        return None
    c, t, row = plan.cash, ts.loc[year], cf.loc[year]
    lines = []

    def add(label, amount, aca="", note=""):
        if abs(float(amount)) > 0.005:
            lines.append({"label": label, "amount": float(amount), "aca": aca, "note": note})

    add("Money-market release", row.mm_release)
    add("Deferred compensation, net of withholding", t.defcomp_net, "Counts as income", "Grossed up for the withholding in your ACA figure")
    add("Annuity cash received", c.annuity_cash if year == c.annuity_year else 0.0, "Only the gain counts", "The cash comes in; only the gain is income")
    add("RV sale", c.rv_sale_proceeds if year == c.rv_sale_year else 0.0, "Not income", "Assumed sold at or below cost; confirm with your CPA")
    add("Refund from last year's taxes", t.refund_from_prior, "Not income")
    add("Required minimum distribution taken to cash", row.rmd_withdrawal, "Counts as income")
    add("Core living cost", -row.core_living)
    add("Social Security", row.core_living - row.net_core_after_ss, "", "Offsets the living cost")
    add("Travel and one-time", -row.travel)
    add("Tax due after withholding", -row.tax_due)
    add("Unsubsidized health insurance", -row.medical, "", "The years your income is above the ACA limit")
    add("State income tax (after a move)", -float(row.get("state_tax", 0.0)))
    add("Moving: rent and other running costs", -float(row.get("move_cost", 0.0)))
    add("Growth on starting cash", row.growth)
    for k_, nm_ in (("brokerage", "Schwab brokerage"), ("sipp", "UK SIPP"), ("ira", "Schwab IRA")):     # v25.35: by account
        add(f"Drawn from {nm_} to stay at the safety line", float(row.get(f"draw_{k_}", 0.0)),
            "Not income" if k_ == "brokerage" else "Counts as income", "Only any gain on what is sold counts as income" if k_ == "brokerage" else "")
    left_ = float(row.get("drawdown", 0.0)) - sum(float(row.get(f"draw_{k_}", 0.0)) for k_ in ("brokerage", "sipp", "ira"))
    add("Drawn from investments to stay at the safety line", left_, "Not income")
    beginning, ending = float(row.beginning_cash), float(row.ending_cash)
    not_income = [l for l in lines if l["aca"] == "Not income"]
    return {"year": int(year), "beginning": beginning, "lines": lines, "ending": ending,
            "gap": round(ending - (beginning + sum(l["amount"] for l in lines)), 6),
            "not_income_total": round(sum(l["amount"] for l in not_income), 2), "not_income_labels": [l["label"] for l in not_income]}


# ---- year end: tax documents, the year-close check and the January startup -------------------------------------------------------
YEAR_DOC_STATUSES = ["Not yet", "Received", "Not needed"]
JAN_TASKS = [("assumptions", "Review the assumptions for the new year"),
             ("limits", "Confirm the ACA and IRMAA limits for the new year"),
             ("opening", "Confirm the opening balances carried forward"),
             ("budget", "Set the new year's spending budget"),
             ("approve", "Approve the new year's plan")]


def tax_documents(plan: Plan, R: dict, year: int) -> list[dict]:
    """The documents to collect for a tax year, built from what happens in that year of the plan."""
    ts, irm = R["ts"], R["irm"]
    t = ts.loc[year] if year in ts.index else None
    docs = [{"id": "brokerage", "label": "Brokerage tax forms: Schwab, E*TRADE and Wells (interest, dividends, sales)",
             "when": "Typically mid February; corrected forms can follow into March"}]
    if year <= 2026 or (t is not None and float(t["defcomp_net"]) > 0):
        docs.append({"id": "defcomp", "label": "Deferred compensation year-end statement", "when": "Typically by the end of January"})
    if t is not None and float(t["defcomp_net"]) > 60000:
        docs.append({"id": "defcomp_lump", "label": "Deferred compensation lump sum: the payout and the withholding", "when": "Typically by the end of January"})
    if year == plan.cash.annuity_year:
        docs.append({"id": "annuity", "label": "Annuity liquidation: Form 1099-R and the gain worksheet (cost basis)", "when": "Typically by the end of January"})
    if year == 2026 or (t is not None and float(t["tax_due_after_wh"]) > 0):
        docs.append({"id": "estimated", "label": "Estimated tax payment confirmations (federal and state)", "when": "Yours to keep as each payment is made"})
    if 2027 <= year <= 2033:
        docs.append({"id": "f1095a", "label": "Form 1095-A from the Marketplace", "when": "Typically by the end of January"})
        docs.append({"id": "f8962", "label": "Form 8962 (premium tax credit reconciliation), prepared with the return", "when": "Your preparer completes it from the 1095-A"})
    docs.append({"id": "hsa", "label": "HSA forms: 1099-SA (distributions) and 5498-SA (contributions)", "when": "1099-SA typically by the end of January; 5498-SA by late spring"})
    if year in irm.index and float(irm.loc[year].adopted_roth) > 0:
        docs.append({"id": "roth", "label": "Roth conversions: Form 1099-R for each conversion, and Form 8606", "when": "1099-R typically by the end of January"})
    if t is not None and float(t["ss_gross"]) > 0:
        docs.append({"id": "ssa", "label": "Social Security: Form SSA-1099", "when": "Typically by the end of January, and online"})
    if t is not None and float(t["rmd_target"]) > 0:
        docs.append({"id": "rmd", "label": "Required minimum distributions: Form 1099-R and the custodian's RMD statement", "when": "Typically by the end of January"})
    docs.append({"id": "property", "label": "Real estate tax bill and proof of payment", "when": "Yours to keep as each bill is paid"})
    docs.append({"id": "filed", "label": "Return filed (federal and state)", "when": "Set to Received when it is filed and you hold the copy"})
    return docs


def doc_state(entries: dict, year: int, doc_id: str) -> dict:
    return dict({"status": "Not yet", "date": "", "note": ""}, **entries.get("year_end", {}).get(str(year), {}).get("docs", {}).get(doc_id, {}))


def set_doc(entries: dict, year: int, doc_id: str, **kw) -> dict:
    d = entries.setdefault("year_end", {}).setdefault(str(year), {}).setdefault("docs", {}).setdefault(doc_id, {"status": "Not yet", "date": "", "note": ""})
    d.update(kw)
    return d


def docs_progress(entries: dict, docs: list[dict], year: int) -> dict:
    st_ = [doc_state(entries, year, d["id"])["status"] for d in docs]
    return {"received": sum(s == "Received" for s in st_), "needed": sum(s != "Not needed" for s in st_), "total": len(docs)}


# ---- documents kept for the CPA: an index in the plan data (names, categories, sizes), the files themselves in the private repository ----------------
DOC_STATEMENTS, DOC_OTHER = "Statements", "Other"


def safe_filename(name: str) -> str:
    import re as _re
    base = _re.sub(r"[^A-Za-z0-9._ ()&+-]+", "_", str(name).replace("\\", "/").split("/")[-1]).strip(" .") or "document"
    return base[:120]


def docs_index(entries: dict, year: int) -> list[dict]:
    return list(entries.get("documents", {}).get(str(year), {}).get("files", []))


def docs_archived(entries: dict, year: int) -> str:
    return entries.get("documents", {}).get(str(year), {}).get("archived", "")


def docs_add(entries: dict, year: int, rec: dict) -> dict:
    d = entries.setdefault("documents", {}).setdefault(str(year), {})
    d.setdefault("files", []).append(rec)
    return rec


def docs_remove(entries: dict, year: int, doc_id: str) -> None:
    d = entries.get("documents", {}).get(str(year), {})
    d["files"] = [f for f in d.get("files", []) if f["id"] != doc_id]


def docs_total_bytes(entries: dict, year: int) -> int:
    return sum(int(f.get("size", 0)) for f in docs_index(entries, year) if not f.get("gone"))


def docs_mark_archived(entries: dict, year: int, on: str) -> None:
    d = entries.setdefault("documents", {}).setdefault(str(year), {})
    d["archived"] = on
    for f in d.get("files", []):
        f["gone"] = True


def docs_folder(rec: dict, labels: dict) -> str:
    """The folder a document goes in, inside the package: the checklist item it was added under, or Statements / Other."""
    return safe_filename(labels.get(rec.get("cat"), rec.get("cat") or DOC_OTHER))[:60]


def docs_sheet(entries: dict, year: int, labels: dict) -> "pd.DataFrame":
    rows = [{"Folder": docs_folder(f, labels), "File": f["name"], "Added": f.get("added", ""), "Size (KB)": round(int(f.get("size", 0)) / 1024, 1),
             "In package": "No (archived)" if f.get("gone") else "Yes"} for f in docs_index(entries, year)]
    return pd.DataFrame(rows, columns=["Folder", "File", "Added", "Size (KB)", "In package"])


def package_zip(year: int, main: tuple, files: list, index_df: "pd.DataFrame", note: str = "") -> bytes:
    """The whole package as one zip: the workbook, the documents in folders, and a list of what is inside. files: [(folder, file name, bytes)]."""
    import io as _io
    import zipfile as _zip
    root = f"CPA_package_{year}"
    buf = _io.BytesIO()
    used = set()
    with _zip.ZipFile(buf, "w", _zip.ZIP_DEFLATED) as z:
        z.writestr(f"{root}/{main[0]}", main[1])
        for folder, name, data in files:
            path = f"{root}/Documents/{folder}/{name}"
            stem, dot, ext = path.rpartition(".") if "." in name else (path, "", "")
            n = 1
            while path in used:
                n += 1
                path = f"{stem} ({n}){dot}{ext}"
            used.add(path)
            z.writestr(path, data)
        z.writestr(f"{root}/Documents/_list_of_documents.csv", index_df.to_csv(index=False))
        if note:
            z.writestr(f"{root}/README.txt", note)
    return buf.getvalue()


def year_close_checks(plan: Plan, entries: dict, year: int, month_state: dict, classes, ended: bool) -> list[dict]:
    """The year-close check. month_state: for each month the app tracks live, {'exp': transactions reconciled, 'magi': income finalized,
    'unclassified': lines without a class}. Earlier months (imported history) count as done when they have lines or MAGI history.
    ended: the year is over (a missing item is then red rather than amber)."""
    keys = [f"{year}-{m:02d}" for m in range(1, 13)]
    hist = entries.get("magi_history", {})
    bad = "bad" if ended else "warn"

    def names(ks):
        return ", ".join(["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][int(k[5:]) - 1] for k in ks)

    def line(cid, label, missing, ok_text):
        return {"id": cid, "label": label, "status": "ok" if not missing else bad,
                "detail": ok_text if not missing else f"Still to do: {names(missing)}"}
    tx_missing = [k for k in keys if not (month_state[k]["exp"] if k in month_state else bool(entries["ledger"].get(k)))]
    inc_missing = [k for k in keys if not (month_state[k]["magi"] if k in month_state else k in hist)]
    unclass = sum(month_state[k]["unclassified"] for k in keys if k in month_state) + \
        sum(1 for k in keys if k not in month_state for r in entries["ledger"].get(k, []) if str(r.get("cls", "")) not in classes)
    nw = [r for r in networth_table(entries) if r["month"] == f"{year}-12" and r["complete"]]
    checks = [line("tx", "Transactions reconciled, all 12 months", tx_missing, "Every month is reconciled"),
              line("income", "Income finalized, all 12 months", inc_missing, "Every month is finalized"),
              {"id": "classes", "label": "Every transaction has a class", "status": "ok" if unclass == 0 else bad,
               "detail": "All lines are classified" if unclass == 0 else f"{unclass} line{'s' if unclass != 1 else ''} without a class"},
              {"id": "balances", "label": "December balances entered (all nine accounts)", "status": "ok" if nw else bad,
               "detail": f"Net worth {nw[0]['net_worth']:,.2f}" if nw else "Enter December's balances on Monthly updates"}]
    bank = [c for c in entries.get("bank_checks", []) if c.get("month") in (f"{year}-12", f"{year + 1}-01")]
    checks.append({"id": "bank", "label": "December matched to the bank", "status": "ok" if bank else bad,
                   "detail": (f"Matched at {bank[-1]['balance']:,.2f} on {str(bank[-1]['t'])[:10]}" if bank else "Check the December ledger against Wells on Monthly updates and record the match")})
    return checks


def year_closed(entries: dict, year: int) -> str:
    return entries.get("year_end", {}).get(str(year), {}).get("closed", "")


def set_year_closed(entries: dict, year: int, date_str: str) -> None:
    y = entries.setdefault("year_end", {}).setdefault(str(year), {})
    if date_str:
        y["closed"] = date_str
    else:
        y.pop("closed", None)


def jan_done(entries: dict, year: int) -> dict:
    return dict(entries.get("year_end", {}).get(str(year), {}).get("jan", {}))


def set_jan(entries: dict, year: int, task: str, date_str: str) -> None:
    j = entries.setdefault("year_end", {}).setdefault(str(year), {}).setdefault("jan", {})
    if date_str:
        j[task] = date_str
    else:
        j.pop(task, None)


# ---- the year-end chores list: one ordered checklist, from before December 31 to the filed return ---------------------------------------------------
_ORD = {"Q1": "first", "Q2": "second", "Q3": "third", "Q4": "fourth"}
MANUAL_CHORES = {"roth_do": "Complete the Roth conversion", "aca_check": "Check the year's income against the ACA guardrail", "send_cpa": "Send your documents and the CPA package to your CPA", "archive_docs": "Archive the year's documents",
                 "review": "Review the draft return with your CPA", "pay_balance": "Pay any balance due, or note the refund",
                 "defcomp_check": "Compare your deferred-compensation balances with the plan website"}


def chore_done(entries: dict, year: int, cid: str) -> str:
    return entries.get("year_end", {}).get(str(year), {}).get("chores", {}).get(cid, "")


def set_chore(entries: dict, year: int, cid: str, date_str: str) -> None:
    c = entries.setdefault("year_end", {}).setdefault(str(year), {}).setdefault("chores", {})
    if date_str:
        c[cid] = date_str
    else:
        c.pop(cid, None)


def _usd(x) -> str:
    return f"${abs(float(x)):,.0f}"


def year_chores(plan: Plan, entries: dict, R: dict, year: int, checks: list[dict]) -> list[dict]:
    """The chores for closing `year` and filing its return, in the order you do them. Each item is done, open, or not needed; most are read from what the
    app already tracks (tax payments, the year-close checks, the January setup, the documents), and the rest are ticked by hand."""
    secs: list[dict] = []

    def item(cid, label, kind, done=False, on="", detail="", where="", na=False):
        return {"id": cid, "label": label, "kind": kind, "done": bool(done), "on": on or "", "detail": detail, "where": where, "na": bool(na)}

    def manual(cid, label, detail, where):
        d = chore_done(entries, year, cid)
        return item(cid, label, "manual", bool(d), d, detail, where)

    rows = [r for r in tax_schedule(plan, R, year) if float(r["amount"]) > 0.005]
    # 1. before the year ends
    s1 = []
    for r in rows:
        if str(r["due"])[:4] == str(year):
            s1.append(item(f"pay_{r['label']}", f"Pay the {_ORD.get(r['label'], r['label'])} estimated tax payment, {_usd(r['amount'])}", "auto", r.get("paid"), r.get("paid_on") if r.get("paid") else "",
                           f"Due {r['due']}. {r.get('source', '')}".strip(), "Tax payments"))
    ir = R["irm"]
    conv = float(ir.loc[year].adopted_roth) if year in ir.index else 0.0
    if conv > 0:
        s1.append(manual("roth_do", f"Complete the Roth conversion planned for {year}: {_usd(conv)}", "Do it before December 31, and check the amount against the ACA and IRMAA limits first.", "Roth"))
    if year <= 2033:
        s1.append(manual("aca_check", f"Check {year}'s income against the ACA guardrail", "Compare income so far with the guardrail while there is still time to adjust before year end.", "ACA"))
    if s1:
        secs.append({"id": "before", "title": f"Before {year} ends", "when": f"by December 31, {year}", "items": s1})
    # 2. the first days of the new year
    where = {"tx": "Monthly updates, Transactions", "income": "Monthly updates, Income", "classes": "Monthly updates, Transactions", "balances": "Monthly updates, Balances",
             "bank": "Monthly updates, Transactions"}
    s2 = [item(f"chk_{c['id']}", c["label"], "auto", c["status"] == "ok", "", c["detail"], where.get(c["id"], "Year end")) for c in checks]
    if plan.inputs.defcomp.bucket_2029 > 0 and year <= 2034:
        s2.append(manual("defcomp_check", "Compare your deferred-compensation balances with the plan's website",
                         "The plan grows them at 5% a year. If the website is noticeably different, enter the new figures on the DefComp page.", "DefComp"))
    closed = year_closed(entries, year)
    s2.append(item("closed", f"Mark {year} as closed", "auto", bool(closed), closed, "Available once every check above is done.", "Year end, Year-close check"))
    secs.append({"id": "first", "title": f"The first days of {year + 1}", "when": "December 31 to about January 10", "items": s2})
    # 3. the last estimated payment
    s3 = [item(f"pay_{r['label']}", f"Pay the {_ORD.get(r['label'], r['label'])} estimated tax payment, {_usd(r['amount'])}", "auto", r.get("paid"), r.get("paid_on") if r.get("paid") else "",
               f"Due {r['due']}. {r.get('source', '')}".strip(), "Tax payments") for r in rows if str(r["due"])[:4] != str(year)]
    # v21.18: the savings account's special rate runs to January 15 each year and is renewed by phone (backdated, so no gap)
    s3.append(manual("savings_rate", "Renew the savings account's special interest rate",
                     "It expires January 15. Call your personal banker to lock in the new rate; they backdate it, so there is no gap. A new rate usually needs "
                     "new cash moved in from the brokerage: mark that transfer Neither in the bank-line review so it is not counted as income. "
                     "The ACA forecast follows the new rate once January is finalized.", "Monthly updates, Income"))
    secs.append({"id": "jan15", "title": "By January 15", "when": f"January 15, {year + 1}", "items": s3})
    # 4. set up the new year
    jd = jan_done(entries, year + 1)
    secs.append({"id": "setup", "title": f"January: set up {year + 1}", "when": "once the year is closed",
                 "items": [item(f"jan_{t}", label, "auto", bool(jd.get(t)), jd.get(t, ""), "", "Year end, January tab") for t, label in JAN_TASKS]})
    # 5. the tax documents, roughly in the order they arrive
    docs = [d for d in tax_documents(plan, R, year) if d["id"] != "filed"]

    def arrives(d):
        w = d["when"].lower()
        return 0 if "yours to keep" in w else (1 if "end of january" in w else (2 if "february" in w else 3))
    s5 = []
    for d in sorted(docs, key=arrives):
        st_ = doc_state(entries, year, d["id"])
        s5.append(item(f"doc_{d['id']}", d["label"], "doc", st_["status"] == "Received", st_["date"] if st_["status"] == "Received" else "", d["when"], "Year end, Tax documents", na=st_["status"] == "Not needed"))
    secs.append({"id": "docs", "title": "Tax documents, as they arrive", "when": "January to spring", "items": s5})
    # 6. filing
    fs = doc_state(entries, year, "filed")
    secs.append({"id": "filing", "title": "Filing", "when": "after the documents are in",
                 "items": [manual("send_cpa", "Send your documents and the CPA package to your CPA", "On the Reporting page, build the package once the brokerage forms, and any corrected ones, are in. Then send him the zip.", "Reporting"),
                           manual("review", "Review the draft return with your CPA", "", ""),
                           manual("pay_balance", "Pay any balance due, or note the refund", "", "Tax payments"),
                           item("doc_filed", "Return filed (federal and state)", "doc", fs["status"] == "Received", fs["date"] if fs["status"] == "Received" else "",
                                "Set on the Tax documents tab when it is filed and you hold the copy.", "Year end, Tax documents", na=fs["status"] == "Not needed"),
                           manual("archive_docs", "Archive the year's documents", "After filing: build the final package, save the zip, then use Archive on the Reporting page to keep the storage small.", "Reporting")]})
    return secs


def chores_progress(sections: list[dict]) -> dict:
    its = [i for s in sections for i in s["items"] if not i["na"]]
    return {"done": sum(1 for i in its if i["done"]), "total": len(its)}


def chores_html(sections: list[dict], year: int, name: str, generated: str) -> str:
    """A plain page for printing: black on white, a box to tick by each chore, the done ones already ticked. Open it in the browser and print (Ctrl+P)."""
    e = _html.escape
    pr = chores_progress(sections)
    css = ("body{font-family:Arial,Helvetica,sans-serif;color:#111;margin:24px;max-width:780px}h1{font-size:22px;margin:0 0 2px}.sub{color:#555;font-size:12px;margin-bottom:14px}"
           "h2{font-size:15px;margin:18px 0 4px;border-bottom:2px solid #111;padding-bottom:2px}h2 span{font-weight:normal;color:#555;font-size:12px}"
           ".row{display:flex;gap:10px;padding:5px 0;border-bottom:1px solid #ddd;page-break-inside:avoid}.box{width:15px;height:15px;border:1.5px solid #111;flex:none;margin-top:2px;text-align:center;font-size:13px;line-height:14px}"
           ".t{font-size:13px}.d{font-size:11px;color:#555}.done .t{color:#555}.na .t{text-decoration:line-through;color:#888}.notes{margin-top:22px;font-size:12px}"
           ".line{border-bottom:1px solid #999;height:22px}@media print{body{margin:0.4in}.noprint{display:none}}")
    out = [f"<!DOCTYPE html><html><head><meta charset='utf-8'><title>Year-end chores {year}</title><style>{css}</style></head><body>",
           f"<h1>Year-end chores for {year}</h1><div class='sub'>{e(name)} &middot; made {e(generated)} &middot; {pr['done']} of {pr['total']} done &middot; ticked boxes are already done in the app</div>",
           "<div class='noprint sub'>To print: press Ctrl+P (on an iPad, use the Share button, then Print).</div>"]
    for s in sections:
        out.append(f"<h2>{e(s['title'])} <span>&middot; {e(s['when'])}</span></h2>")
        for i in s["items"]:
            cls = "row " + ("na" if i["na"] else ("done" if i["done"] else ""))
            box = "&#10003;" if (i["done"] and not i["na"]) else ("&ndash;" if i["na"] else "")
            bits = [x for x in (i["detail"], ("Where: " + i["where"]) if i["where"] else "", ("Done " + i["on"]) if i["done"] and i["on"] else "") if x]
            out.append(f"<div class='{cls}'><div class='box'>{box}</div><div><div class='t'>{e(i['label'])}</div>" + (f"<div class='d'>{e(' &middot; '.join(bits)).replace('&amp;middot;', '&middot;')}</div>" if bits else "") + "</div></div>")
    out.append("<div class='notes'>Notes<div class='line'></div><div class='line'></div><div class='line'></div></div>")
    out.append("<div class='sub' style='margin-top:14px'>Figures come from your plan and are estimates, not advice. Your CPA confirms the final numbers.</div></body></html>")
    return "".join(out)


# ---- the CPA package: one workbook for your tax preparer -----------------------------------------------------------------------------------
def _month_rows_in(year: int, keys) -> list[str]:
    return sorted(k for k in set(keys) if str(k).startswith(f"{year}-"))


def cpa_package(plan: Plan, entries: dict, R: dict, year: int, account_labels: list, chores: list, generated: str, who: str = "Shooman retirement plan", docs_df=None) -> list:
    """The sheets of the CPA package for a tax year, as [(sheet name, DataFrame)]. Plain values only: no formulas, so it opens the same everywhere.
    chores is year_chores(...) for the same year."""
    rate = plan.inputs.defcomp.withholding_rate
    sheets = []
    # -- income by month
    cols = [("wellsInt", "Wells interest"), ("wellsDiv", "Wells dividends"), ("schwabInt", "Schwab interest"), ("schwabDiv", "Schwab dividends"),
            (MUNI_FIELD, "Of which tax-exempt muni (in Schwab dividends)"), ("gains", "Realized gains"),
            ("other", "Other brokerage income"), ("defcomp", "Deferred comp (grossed up for withholding)"), ("annuity", "Annuity"), ("roth", "Roth conversion"), ("sipp", "SIPP"),
            ("ira", "IRA distributions"), ("ss", "Social Security")]
    hist = entries.get("magi_history", {})
    inc = []
    for k in _month_rows_in(year, list(entries.get("magi", {})) + list(hist)):
        if k in entries.get("magi", {}):
            rec = income_record(entries, k, rate)
            t = income_totals(rec)
            row = {"Month": k, "Status": rec.get("status", "")}
            row.update({lab: _n(rec.get(f)) for f, lab in cols})
            row.update({"Interest and dividends": t["int_div"], "Total income": t["total"], "Notes": rec.get("notes", "")})
        else:                                                                # a month from the imported history: only its total is known
            row = {"Month": k, "Status": "History"}
            row.update({lab: None for _f, lab in cols})
            row.update({"Interest and dividends": None, "Total income": float(hist[k].get("total", 0.0)), "Notes": "From the imported history: total only"})
        inc.append(row)
    df = pd.DataFrame(inc, columns=["Month", "Status"] + [lab for _f, lab in cols] + ["Interest and dividends", "Total income", "Notes"])
    if len(df):
        tot = {c: float(df[c].sum()) for c in df.columns if c not in ("Month", "Status", "Notes")}
        df = pd.concat([df, pd.DataFrame([{"Month": "Total", "Status": "", **tot, "Notes": ""}])], ignore_index=True)
    sheets.append(("Income by month", df))
    # -- interest and dividends by account (v21.16), when the year has the table
    if inv_has_table(entries, year):
        t = invest_year(entries, year, rate)
        idf = pd.DataFrame([{"Month": r["month"], **{lab: r.get(f) for f, lab in INV_ACCOUNTS}, "Of which tax-exempt muni": r.get("muni"),
                             "Of which quarterly fund dividends": r.get("qtr"), "Total": r["total"], "Basis": r["source"], "Note": r.get("note", "")} for r in t["rows"]])
        idf = pd.concat([idf, pd.DataFrame([{"Month": "Total", **{c: float(pd.to_numeric(idf[c], errors="coerce").fillna(0).sum())
                                                                  for c in idf.columns if c not in ("Month", "Basis", "Note")}, "Basis": "", "Note": ""}])], ignore_index=True)
        sheets.append(("Interest and dividends", idf))
    # -- net worth
    lab = dict(account_labels)
    nw = [r for r in networth_table(entries) if f"{year - 1}-12" <= r["month"] <= f"{year}-12"]
    nwdf = pd.DataFrame([{"Month": r["month"], **{lab.get(a, a): r.get(a) for a in NINE_ACCOUNTS}, "Financial assets": r["assets"], "Capital assets": r["capital"],
                          "Net worth": r["net_worth"], "Change since the last complete month": r["change"]} for r in nw])
    sheets.append(("Net worth", nwdf if len(nwdf) else pd.DataFrame({"Note": [f"No balances entered for {year - 1}-12 to {year}-12."]})))
    # -- capital assets
    items = capital_items(plan)
    start = int(str(plan.meta.get("first_month") or plan.meta.get("as_of") or "2026")[:4])
    if items:
        cdf = pd.DataFrame([{"Item": i["name"], "Value on record": float(i["value"]), "Yearly change": f"{float(i['rate']) * 100:.1f}%",
                             "Assumed sale year": i.get("sale_year") or "", f"Estimated value in {year}": capital_value(i, year, start)} for i in items])
        cdf = pd.concat([cdf, pd.DataFrame([{"Item": "Total", "Value on record": float(cdf["Value on record"].sum()), "Yearly change": "", "Assumed sale year": "",
                                             f"Estimated value in {year}": float(cdf[f"Estimated value in {year}"].sum())}])], ignore_index=True)
    else:
        cdf = pd.DataFrame({"Note": ["No capital assets entered yet."]})
    sheets.append(("Capital assets", cdf))
    # -- tax payments (last year's January payment is paid in this calendar year)
    trows = []
    for ty in (year - 1, year):
        if ty < 2026:
            continue
        for r in tax_schedule(plan, R, ty):
            if ty == year - 1 and not str(r["due"]).startswith(str(year)):
                continue
            trows.append({"Tax year": ty, "Payment": r["label"], "Due": r["due"], "Amount": float(r["amount"]), "Paid": "Yes" if r.get("paid") else "No",
                          "Paid on": r.get("paid_on") or "", "Source": r.get("source", "")})
    tdf = pd.DataFrame(trows, columns=["Tax year", "Payment", "Due", "Amount", "Paid", "Paid on", "Source"])
    sheets.append(("Tax payments", tdf if len(tdf) else pd.DataFrame({"Note": ["No estimated payments for this year."]})))
    # -- deferred compensation
    yrs = defcomp_year_rows(plan)
    ddf = pd.DataFrame([{"Year": r["year"], "What is paid": r["what"], "Statement amount": r["statement"] or None, "Plan carries (grown)": r["modelled"]} for r in yrs],
                       columns=["Year", "What is paid", "Statement amount", "Plan carries (grown)"])
    sheets.append(("Deferred comp", ddf))
    # -- the year-end checklist
    crows = []
    for sec in chores:
        for i in sec["items"]:
            crows.append({"Stage": sec["title"], "Item": i["label"], "Status": "Not needed" if i["na"] else ("Done" if i["done"] else "Open"),
                          "Done on": i["on"] if i["done"] else "", "Where in the app": i["where"], "Detail": i["detail"]})
    sheets.append(("Year-end checklist", pd.DataFrame(crows, columns=["Stage", "Item", "Status", "Done on", "Where in the app", "Detail"])))
    # -- the ledger
    lrows = []
    for k in _month_rows_in(year, entries.get("ledger", {})):
        for r in entries["ledger"][k]:
            lrows.append({"Date": r.get("date", ""), "Description": r.get("desc", ""), "Credit": r.get("credit"), "Debit": r.get("debit"),
                          "Reconciled": r.get("rec", ""), "Class": r.get("cls", ""), "Note": r.get("note", "")})
    ldf = pd.DataFrame(lrows, columns=["Date", "Description", "Credit", "Debit", "Reconciled", "Class", "Note"]).sort_values("Date", kind="stable") if lrows else \
        pd.DataFrame({"Note": [f"No ledger lines for {year}."]})
    sheets.append(("Ledger", ldf))
    if docs_df is not None and len(docs_df):
        sheets.append(("Documents", docs_df))
    # -- the summary goes first
    d = plan.inputs.defcomp
    tp = [r for r in trows if r["Tax year"] == year]
    paid = sum(r["Amount"] for r in tp if r["Paid"] == "Yes")
    pr = chores_progress(chores)
    srows = [("Package for tax year", str(year)), ("Prepared on", generated), ("Prepared from", who),
             ("Estimated payments for the year", f"{sum(1 for r in tp if r['Paid'] == 'Yes')} of {len(tp)} paid, {paid:,.2f} paid of {sum(r['Amount'] for r in tp):,.2f}" if tp else "None"),
             ("Year-end checklist", f"{pr['done']} of {pr['total']} done")]
    if d.bucket_2029 > 0 and int(d.election_code) == 3:
        sub = int(plan.expenses.get("defcomp_submitted", 0) or 0)
        srows += [("Deferred comp election", f"The 2013 to 2015 deferrals, deferred from {defcomp_original_date(plan).isoformat()} to one lump on {defcomp_lump_date(plan).isoformat()}"),
                  ("Deferred comp election form", f"Submitted {_dt.date.fromordinal(sub).isoformat()}" if sub else "Not yet submitted")]
    through = str(plan.expenses.get("tax_autopay_through") or "")
    if through:
        srows.append(("Automatic IRS payments", f"Set up through {through}"))
    latest = next((r for r in reversed(nw) if r["net_worth"] is not None), None)
    if latest:
        srows.append(("Latest net worth", f"{latest['net_worth']:,.2f} as of {latest['month']}"))
    srows += [("Sheets", ", ".join(n for n, _ in sheets)),
              ("Note", "Figures come from your plan and entries. Forecast and grown amounts are estimates, not advice; your CPA confirms the final numbers.")]
    return [("Summary", pd.DataFrame(srows, columns=["Item", "Value"]))] + sheets


def cpa_xlsx(sheets: list) -> bytes:
    """The sheets as one Excel workbook (needs openpyxl): a bold header, frozen, widths to fit, money with two decimals."""
    import io
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    wb = Workbook()
    wb.remove(wb.active)
    for name, df in sheets:
        ws = wb.create_sheet(name[:31])
        ws.append([str(c) for c in df.columns])
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF")
            c.fill = PatternFill("solid", fgColor="3B7DB5")
            c.alignment = Alignment(wrap_text=True, vertical="top")
        money_cols = {i for i, c in enumerate(df.columns) if pd.api.types.is_float_dtype(df[c])}
        for rec in df.itertuples(index=False):
            ws.append([None if (v is None or (isinstance(v, float) and v != v)) else (v.item() if hasattr(v, "item") else v) for v in rec])
        for j, col in enumerate(df.columns):
            letter = ws.cell(row=1, column=j + 1).column_letter
            width = max([len(str(col))] + [len(str(v)) for v in df[col].tolist()[:200] if v is not None])
            ws.column_dimensions[letter].width = min(max(10, width + 2), 70 if j else 40)
            if j in money_cols:
                for r in range(2, ws.max_row + 1):
                    ws.cell(row=r, column=j + 1).number_format = "#,##0.00"
        for row in ws.iter_rows(min_row=2):
            for c in row:
                if isinstance(c.value, str) and len(c.value) > 60:
                    c.alignment = Alignment(wrap_text=True, vertical="top")
        ws.freeze_panes = "A2"
        if name == "Summary":
            ws.column_dimensions["A"].width = 34
            ws.column_dimensions["B"].width = 90
            for row in ws.iter_rows(min_row=2):
                row[1].alignment = Alignment(wrap_text=True, vertical="top")
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def cpa_zip(sheets: list) -> bytes:
    """The same sheets as CSV files in one zip: the fallback when Excel writing is not available."""
    import io
    import zipfile
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for i, (name, df) in enumerate(sheets):
            z.writestr(f"{i:02d}_{name.replace(' ', '_')}.csv", df.to_csv(index=False))
    return buf.getvalue()


# ---- estimated tax payments: four a year, from your CPA where set, otherwise from the forecast tax ----------------------------------------
_QDUE = [("Q1", 4, 15, 0), ("Q2", 6, 15, 0), ("Q3", 9, 15, 0), ("Q4", 1, 15, 1)]      # label, month, day, years after the tax year


def tax_schedule(plan: Plan, R: dict, year: int) -> list[dict]:
    """The four estimated payments for a tax year. A schedule you have edited or saved wins. Otherwise 2026 is the CPA's four equal payments
    (from the tax already paid and the amount still to pay), and later years are the forecast tax after withholding divided by four."""
    stored = plan.meta.get("tax_payments", {}).get(str(year))
    if stored:
        return [dict(r) for r in stored]
    dues = [f"{year + off}-{m:02d}-{d:02d}" for _l, m, d, off in _QDUE]
    paid_amt = plan.expenses.get("tax_paid_2026")
    if year == 2026 and paid_amt is not None:
        per = (float(paid_amt) + float(plan.cash.tax_reserve_remaining_2026)) / 4.0
        n_paid = min(4, int(round(float(paid_amt) / per))) if per else 0
        return [{"label": l, "due": dues[i], "amount": per, "paid": i < n_paid, "paid_on": dues[i] if i < n_paid else "", "source": "From your CPA"}
                for i, (l, *_r) in enumerate(_QDUE)]
    ts = R["ts"]
    if year in ts.index:
        per = float(ts.loc[year]["tax_due_after_wh"]) / 4.0
        return [{"label": l, "due": dues[i], "amount": per, "paid": False, "paid_on": "", "source": "Forecast"} for i, (l, *_r) in enumerate(_QDUE)]
    return []


def ensure_tax_schedule(plan: Plan, R: dict, year: int) -> list[dict]:
    """Save the schedule into the plan (so edits stick) and return the saved rows."""
    tp = plan.meta.setdefault("tax_payments", {})
    if not tp.get(str(year)):
        tp[str(year)] = tax_schedule(plan, R, year)
    return tp[str(year)]


def tax_summary(rows: list[dict]) -> dict:
    unpaid = [r for r in rows if not r.get("paid")]
    nxt = next((r for r in unpaid if float(r["amount"]) > 0.005), None)
    return {"paid": round(sum(float(r["amount"]) for r in rows if r.get("paid")), 2), "unpaid": round(sum(float(r["amount"]) for r in unpaid), 2),
            "n": len(rows), "n_paid": sum(1 for r in rows if r.get("paid")), "next_due": nxt["due"] if nxt else None,
            "next_amount": float(nxt["amount"]) if nxt else 0.0, "total": round(sum(float(r["amount"]) for r in rows), 2)}


# ---- the year in progress: its tax forecast against what is withheld and paid (v21.17) ----------------------------------------------------
TAX_YEAR_FIELDS = [   # (key, label, help) -- what you enter for the year; interest and dividends come from the interest and dividends table
    ("wages", "Wages", "From your W-2s."),
    ("wages_wh", "Tax withheld from wages", ""),
    ("defcomp", "Deferred comp paid (gross)", "Lump sums and monthly payments together, before withholding."),
    ("defcomp_wh_rate", "Withholding rate on deferred comp", "As a fraction: 0.22 for 22%."),
    ("sipp", "UK SIPP received (dollars)", ""),
    ("other_ordinary", "Other ordinary income", "Anything else taxed as ordinary income."),
    ("st_net", "Short-term gains less losses (net)", "From your realized gain/loss reports; a loss is negative."),
    ("lt_net", "Long-term gains less losses (net)", ""),
    ("prior_year_tax", "Last year's total tax (optional)", "For the 110% safe-harbor check. Leave 0 if you don't have it."),
]


def year_tax_inputs(plan, entries: dict, year: int) -> tuple[dict, dict] | tuple[None, None]:
    """The year's income lines for year_tax_forecast: what you entered (plan.meta['tax_year'][year]) plus interest and dividends from the
    investment income table -- taxable interest and non-qualified dividends as ordinary income, the quarterly fund dividends as qualified,
    the muni interest as tax-exempt. Returns (lines, notes about where each came from); (None, None) when nothing is entered for the year."""
    ent = (plan.meta.get("tax_year") or {}).get(str(year))
    if not ent:
        return None, None
    f = {k: float(ent.get(k) or 0.0) for k, *_ in TAX_YEAR_FIELDS}
    notes = {}
    if inv_has_table(entries, year):
        t = invest_year(entries, year, plan.inputs.defcomp.withholding_rate)
        total, muni = float(t["total"] or 0.0), float(t["muni_total"] or 0.0)
        qual = sum(float(r.get("qtr") or 0.0) for r in t["rows"])
        notes["inv"] = (f"From the {year} interest and dividends table: {money(total)} in all, of which {money(muni)} tax-exempt muni and "
                        f"{money(qual)} quarterly fund dividends (treated as qualified)" + (f"; {', '.join(month_short(m) for m in t['open_months'])} estimated" if t["open_months"] else ""))
    else:
        total = muni = qual = 0.0
        notes["inv"] = f"No {year} interest and dividends table, so none is included."
    f["qualified_div"] = float(ent["qualified_div"]) if isinstance(ent.get("qualified_div"), (int, float)) else qual
    f["interest_ordinary"] = float(ent["interest_ordinary"]) if isinstance(ent.get("interest_ordinary"), (int, float)) else total - muni - qual
    f["tax_exempt"] = muni
    f["withheld"] = f["wages_wh"] + f["defcomp"] * f["defcomp_wh_rate"]
    return f, notes


def year_tax_position(plan, entries: dict, R: dict, year: int) -> dict | None:
    """Forecast tax for the year against withholding and the estimated payments (made and still scheduled): the expected refund or balance,
    what the next payment would need to be to cover the forecast exactly, and the least it can be while staying inside the safe harbor."""
    f, notes = year_tax_inputs(plan, entries, year)
    if f is None:
        return None
    t = year_tax_forecast(year, f)
    rows = tax_schedule(plan, R, year)
    s = tax_summary(rows)
    paid, sched = s["paid"], s["unpaid"]
    total_pay = f["withheld"] + paid + sched
    balance = t["total"] - total_pay                                  # positive: owed in April; negative: refund
    need_full = max(0.0, t["total"] - f["withheld"] - paid)             # remaining payments that would cover the forecast exactly
    sh90 = max(0.0, 0.9 * t["total"] - f["withheld"] - paid)            # least remaining payments for the 90%-of-this-year safe harbor
    py = float(f.get("prior_year_tax") or 0.0)
    rate_py = 1.10 if t["agi"] > 150000 else 1.00
    sh_py = max(0.0, rate_py * py - f["withheld"] - paid) if py > 0 else None
    sh_min = min(sh90, sh_py) if sh_py is not None else sh90
    return {"f": f, "t": t, "notes": notes, "rows": rows, "paid": paid, "scheduled": sched, "withheld": f["withheld"], "total_pay": total_pay,
            "balance": balance, "need_full": need_full, "sh90": sh90, "sh_py": sh_py, "sh_min": sh_min, "rate_py": rate_py, "n_left": s["n"] - s["n_paid"]}


# ---- live starting cash for the cash flow (v21.20) -----------------------------------------------------------------------------------------
def wells_live_balance(plan, entries: dict, inbox: dict | None):
    """Today's Wells savings, money market and checking together: the accounts that feed the Wells line, from the latest daily fetch, with
    the checking account taken from your own fetch when that is newer. Returns (total, as-of text, [(account, balance)]) or None."""
    snaps = (inbox or {}).get("snapshots") or {}
    if not snaps:
        return None
    snap = snaps[max(snaps)]
    mapping = income_inbox_mapping(plan, inbox)
    accts = [a for a in snap.get("accounts") or [] if mapping.get(a.get("id")) == "wells" and a.get("balance") is not None]
    if not accts:
        return None
    parts = {a["id"]: [f"{a.get('org', '')} {a.get('name', '')}".strip() or a["id"], float(a["balance"])] for a in accts}
    asof = f"the fetch of {snap.get('date', '')}"
    try:
        ft = _dt.datetime.strptime(str(inbox.get("updated", ""))[:16], "%Y-%m-%d %H:%M").replace(tzinfo=_dt.timezone.utc)
    except ValueError:
        ft = _dt.datetime.combine(_dt.date.fromisoformat(str(snap.get("date"))[:10]), _dt.time.min, tzinfo=_dt.timezone.utc)
    t_read = ft
    live = entries.get("bank_live") or {}
    acct = plan.expenses.get("sfin_account")
    if live.get("acct") == acct and acct in parts:
        try:
            lt = _dt.datetime.fromisoformat(str(live["t"]))
            lt = lt if lt.tzinfo else lt.replace(tzinfo=_dt.timezone.utc)
            if lt > ft:
                parts[acct][1] = float(live["balance"])
                asof += f", checking from your fetch of {str(live['t'])[:10]}"
                t_read = lt                                       # the ledger lines are all checking lines, so they go by the checking reading
        except (ValueError, KeyError):
            pass
    return round(sum(v for _n_, v in parts.values()), 2), asof, [tuple(v) for v in parts.values()], t_read.isoformat()


def remember_wells_balance(entries: dict, wb) -> bool:
    """v21.21: keep the last Wells balances read from a fetch, so the cash flow can start from them when no fetch is at hand (the app's
    connection to the fetch file is down, say) rather than from the plan's fixed figure, which goes stale. Changes the data only when new."""
    if not wb:
        return False
    rec = {"total": wb[0], "asof": wb[1], "parts": [list(x) for x in wb[2]], "t": wb[3]}
    if entries.get("wells_last") == rec:
        return False
    entries["wells_last"] = rec
    return True


def live_opening_cash(plan, entries: dict, inbox: dict | None, today_date) -> dict | None:
    """The cash the forecast should start next year with, built from today's Wells balances (v21.20):
        Wells savings + money market + checking today
      - what is still to go out of checking before December 31 (bills, card payments, one-time items still pending or planned)
      + what is still to come in (deferred comp, the monthly transfer from the trust)
      + savings interest and money-market dividends still to come this year (from the interest and dividends table)
      - this year's estimated tax payments still to make (the January one included)
      + the refund the year's tax forecast expects
    Transfers between your own Wells accounts move nothing in or out, so they are left out. A line already at the bank (it carries the
    bank's id) is in today's balance, so only pending lines without one count. None when there is no fetch to start from."""
    wb = wells_live_balance(plan, entries, inbox)
    stale = False
    if wb is None:                                                # no fetch at hand: the last balances read from one
        last = entries.get("wells_last")
        if not last:
            return None
        wb, stale = (float(last["total"]), last["asof"], [tuple(x) for x in last["parts"]], last["t"]), True
    total, asof, parts, t_iso = wb
    try:
        t_read = _dt.datetime.fromisoformat(str(t_iso))
        t_read = t_read if t_read.tzinfo else t_read.replace(tzinfo=_dt.timezone.utc)
    except ValueError:
        t_read = _dt.datetime.combine(today_date, _dt.time.min, tzinfo=_dt.timezone.utc)
    y = today_date.year
    k = min(today_date.strftime("%Y-%m"), t_read.strftime("%Y-%m"))  # from the month of the reading, so nothing after it is missed
    months = [m for m in month_list(plan, today_date) if k <= m <= f"{y}-12"]

    def in_balance(r, mk) -> bool:
        """Already in the balance that was read: ticked before the reading, or a bank line dated on or before its day."""
        if mk > t_read.strftime("%Y-%m"):
            return False
        if r.get("bank_id"):
            return str(r.get("date", ""))[:10] <= t_read.date().isoformat()
        if is_reconciled(r):
            try:
                ra = _dt.datetime.fromisoformat(str(r.get("rec_at")))
                return (ra if ra.tzinfo else ra.replace(tzinfo=_dt.timezone.utc)) <= t_read
            except (TypeError, ValueError):
                return True                                       # ticked before times were kept: long ago
        return False
    fl = entries.get("forecast_lines", {})
    out_ = in_ = 0.0
    for mk in months:
        actual = entries["ledger"].get(mk, [])
        real = [r for r in actual if not r.get("xfer")]
        lines = actual if real else [r for r in fl.get(mk, []) if not is_planned_transfer(r)]
        for r in lines:
            if _is_savings_transfer(r) or is_planned_transfer(r):
                continue                                          # between your own accounts
            if in_balance(r, mk):
                continue                                          # already in the balance that was read
            out_ += _n(r.get("debit"))
            in_ += _n(r.get("credit"))
    rate = plan.inputs.defcomp.withholding_rate
    interest = 0.0
    if inv_has_table(entries, y):
        for r in invest_year(entries, y, rate)["rows"]:
            if r["month"] >= k and r["estimated"]:
                interest += float(r.get("wells") or 0.0) + float(r.get("wellstrade") or 0.0)
    stub = {"ts": pd.DataFrame()}
    tax_rows = tax_schedule(plan, stub, y)
    tax_left = round(sum(float(r["amount"]) for r in tax_rows if not r.get("paid")), 2)
    refund = 0.0
    try:
        pos = year_tax_position(plan, entries, stub, y)
        refund = max(0.0, -pos["balance"]) if pos else 0.0
    except Exception:  # noqa: BLE001 - the forecast is optional here
        refund = 0.0
    opening = total - out_ + in_ + interest - tax_left + refund
    return {"year": y + 1, "opening": round(opening, 2), "wells_today": total, "asof": asof, "parts": parts, "stale": stale, "read_at": t_read.isoformat(),
            "out": round(out_, 2),
            "in": round(in_, 2), "interest": round(interest, 2), "tax_left": tax_left, "refund": round(refund, 2), "through": f"{y}-12"}


def tax_forecast_table(R: dict, years) -> pd.DataFrame:
    """Forecast tax by year and the estimated payments it implies (what withholding does not cover, in four parts)."""
    ts = R["ts"]
    out = []
    for y in years:
        if y in ts.index:
            t = ts.loc[y]
            out.append({"Year": str(y), "Forecast tax": float(t["fed_tax"]), "Withheld": float(t["withholding"]),
                        "Estimated payments needed": float(t["tax_due_after_wh"]), "Each of four": float(t["tax_due_after_wh"]) / 4.0,
                        "Refund expected next year": float(t["excess_wh"])})
    return pd.DataFrame(out)


# ---- reminders: the small, non-sensitive note a scheduled script reads ---------------------------------------------------------------
def last_reconciled_on(entries: dict):
    """The date (UTC) of the latest reconcile recorded in any line's audit trail, or None. Lines reconciled before audit trails existed are not counted."""
    best = None
    for rows in entries.get("ledger", {}).values():
        for r in rows:
            for a in r.get("audit", []):
                if a.get("e") == "reconciled" and (best is None or str(a["t"]) > best):
                    best = str(a["t"])
    return best[:10] if best else None


def notify_status(entries: dict, today: _dt.date, month_info: dict, quiet_days: int = 14, alerts: list | None = None) -> dict:
    """What a reminder script needs and nothing more: dates, and which parts of a month are still missing. No amounts, no names.
    month_info: {month: {'missing': ['income', 'balances', 'transactions']}} for the previous and the current month."""
    out = {"v": 1, "written_on": today.isoformat(), "last_reconciled_on": last_reconciled_on(entries), "quiet_days": int(quiet_days),
           "months": [{"month": k, "due": due_date(k).isoformat(), "missing": list(month_info[k]["missing"])} for k in sorted(month_info)]}
    if alerts is not None:                               # the Dashboard's orange and red items that are not yet handled: an id, a kind and a date, never an amount
        out["alerts"] = [{k: v for k, v in a.items() if k in ("id", "kind", "month", "due")} for a in alerts]
    return out


