def _html_frame(doc: str, height: int) -> None:
    """v25.54: shows a small HTML page (with its script) in a frame. Uses st.iframe, which replaced st.components.v1.html (due to be
    removed); falls back to the old call on a Streamlit too old to have st.iframe. Both scroll when the page is taller than the frame,
    and both let the script reach the app page around it (same site), which the Print button and the home-screen icon rely on."""
    height = max(1, int(height))            # st.iframe refuses a height of 0
    if hasattr(st, "iframe"):
        st.iframe(doc, height=height)
    else:
        import streamlit.components.v1 as _components
        _components.html(doc, height=height, scrolling=True)

NAVY, SOFT, BRASS, GREY, BRICK, AMBER, PINE = "#3B7DB5", "#9DBBDA", "#B58A1E", "#8FA0B0", "#C2493B", "#D18A1F", "#3E9A6E"
