def tbill_reminder(plan, d) -> dict | None:
    """v25.49: the T-bill purchase the plan relies on. Shows from 1 November of the year before until ticked as bought; red once January
    of the T-bill year has passed without it. None when T-bills are off, bought, or the year is over."""
    tb = plan.expenses.get("tbill") or {"on": True, "year": 2033, "amount": 600000.0}
    if not tb.get("on") or tb.get("bought") or float(tb.get("amount", 0)) <= 0:
        return None
    y = int(tb.get("year", 2033))
    if d < _dt.date(y - 1, 11, 1) or d > _dt.date(y, 12, 31):
        return None
    late = d > _dt.date(y, 1, 31)
    return {"level": "bad" if late else "warn", "year": y, "amount": float(tb.get("amount", 0)),
            "title": f"Buy {money(float(tb.get('amount', 0)))} of T-bills maturing in January {y + 1}",
            "detail": (f"52-week bills bought at the first auctions of January {y} mature in January {y + 1}, so their interest is taxed in {y + 1} "
                       f"and {y} stays under the ACA limit. " + ("January has passed: buy now with a maturity in January " + str(y + 1) + ". " if late else "")
                       + "Tick Bought on the ACA page when done.")}


def _tbill_box(plan):
    tb = plan.expenses.get("tbill") or {}
    if not tb.get("on"):
        return
    y = int(tb.get("year", 2033))
    st.subheader("T-bill plan")
    caption(f"Buy about {money(float(tb.get('amount', 0)))} of 52-week T-bills at the first auctions of January {y}, maturing January {y + 1}. "
            f"The interest is then taxed in {y + 1}, keeping {y} under the ACA limit. A reminder appears in Actions from 1 November {y - 1}.")
    k = f"w_tbill_bought_{st.session_state.data_ver}"

    def _cb():
        d_ = dict(st.session_state.plan.expenses.get("tbill") or {})
        d_["bought"] = bool(st.session_state[k])
        st.session_state.plan.expenses["tbill"] = d_
    st.checkbox("Bought", value=bool(tb.get("bought")), key=k, on_change=_cb)


