def _aca_hub(R):
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    st.title("ACA")
    caption("Income for the Marketplace subsidy. Tap a tile to open it.")
    m, w, ts, limits = R["aca"], R["window"], R["ts"], R["limits"]
    alert = m["alert"]
    t_year = (f"MAGI, {R['aca_year']}", money(m["projected_with_one_time"]), "ok" if alert == "OK" else ("warn" if alert == "EARLY WARNING" else "bad"),
              f"{money(abs(m['headroom']))} {'under' if m['headroom'] >= 0 else 'over'} the limit", f"{m['finalized_months']} of 12 months finalized")
    ys = [y for y in range(2027, 2034) if y in ts.index]
    over = [y for y in ys if float(ts.loc[y, "total_magi"]) > limits[y]]
    planned = {int(y) for y in (plan.cash.medical_years or [])} | {int(y) for y in (plan.cash.medical_extra or {})}   # planned without the subsidy (cost in the cash flow)
    surprise = [y for y in over if y not in planned]
    t_years = ("Subsidy years", f"{len(ys) - len(over)} of {len(ys)}", "warn" if surprise else "ok", "under the limit",
               (f"Over in {', '.join(str(y) for y in surprise)}" if surprise else
                (f"{', '.join(str(y) for y in over)} planned without it" if over else f"{ys[0]} to {ys[-1]}")) if ys else "")
    t_win = ("Year-end window", money(w["capacity"]), "ok" if w["capacity"] >= 0 else "warn", "Room to convert this year", "Zero conversion in subsidy years")
    rate = plan.inputs.defcomp.withholding_rate
    iy = sorted({int(str(k)[:4]) for k in (entries.get("invest_income") or {})})
    if iy:
        t = invest_year(entries, iy[-1], rate)
        t_inv = ("Interest and dividends", money(t["actual_total"]), "idle", f"{iy[-1]}, {t['n_actual']} months actual", f"Full year {money(t['total'])}")
        ny = iy[-1] + 1
        nv = float(ts.loc[ny, "base_income"]) if ny in ts.index and "base_income" in ts.columns else None
        t_next = ("Next year's income", money(nv) if nv is not None else "\u2014", "idle", f"Investment income in {ny} MAGI", "How it is built, and checks")
    else:
        t_inv = ("Interest and dividends", "\u2014", "warn", "Not in your data yet", "Import earlier months")
        t_next = ("Next year's income", "\u2014", "idle", "From the interest table", "")
    T = lambda key, t, view: {"key": key, "label": t[0], "value": t[1], "kind": t[2], "note": t[3], "extra": t[4], "go": (lambda v=view: _aca_go(v))}
    tiles = [T("aca_y", t_year, "year"), T("aca_ys", t_years, "years"), T("aca_w", t_win, "window"), T("aca_i", t_inv, "inv"), T("aca_n", t_next, "next")]
    with _tile_area():
        cols = st.columns(len(tiles), gap="small")
        for i, tl in enumerate(tiles):
            with cols[i]:
                _segment(tl["key"], "plan", "first" if i == 0 else ("last" if i == len(tiles) - 1 else "mid"), tl["label"], tl["value"], tl["kind"],
                         tl["note"], "", tl["extra"], go=tl["go"])


