def _cf_hub(R):
    ss = st.session_state
    st.title("Cash flow")
    caption("Spendable savings and money market through 2050. Tap a tile to open it.")
    cf, cs = R["cf"], R["cf_sum"]
    low = min(cs["lowest_ending_cash"], cs["bridge_low_point"])
    bridge = cs["bridge_low_point"] < cs["lowest_ending_cash"]
    warn_at = cash_warn_level(ss.plan)
    kind, dnote = cash_draw_status(cs, warn_at)
    now_cash, now_asof, now_tax = current_cash(ss.plan, ss.entries)
    t_out = ("Cash now" if now_cash is not None else "Outlook", money(now_cash) if now_cash is not None else money(low), kind,
             f"Low point {money(low)}, " + ("early 2031" if bridge else f"end of {cs['lowest_ending_cash_year']}"),
             dnote + (f"\nWells less {money(now_tax)} tax to pay, {now_asof}" if now_cash is not None and now_tax else (f"\nWells, {now_asof}" if now_cash is not None else "")))
    t_yrs = ("Year by year", money(cs["ending_cash_final_year"]), "idle", f"Cash at the end of {cf.index[-1]}", "Choose a year to see inside it")
    try:
        lo = live_opening_cash(ss.plan, ss.entries, _inbox(), today())
    except Exception:  # noqa: BLE001
        lo = None
    t_start = (f"Starting cash, {today().year + 1}", money(lo["opening"]) if lo else money(ss.plan.cash.opening_cash), "warn" if (lo and lo.get("stale")) else "idle",
               "From today's Wells balances" if lo else "From the plan's figure", (f"Wells {money(lo['wells_today'])} now" if lo else "No bank fetch read yet"))
    c = ss.plan.cash
    t_ann = ("Annuities", money(c.annuity_cash), "idle", f"Cashed in {int(c.annuity_year)}", f"Taxable gain {money(annuity_gain_auto(ss.plan))}")
    T = lambda key, t, view: {"key": key, "label": t[0], "value": t[1], "kind": t[2], "note": t[3], "extra": t[4], "go": (lambda v=view: _cf_go(v))}
    tiles = [T("cf_out", t_out, "outlook"), T("cf_yrs", t_yrs, "years"), T("cf_start", t_start, "start"), T("cf_ann", t_ann, "annuities")]
    with _tile_area():
        cols = st.columns(len(tiles), gap="small")
        for i, tl in enumerate(tiles):
            with cols[i]:
                _segment(tl["key"], "cash", "first" if i == 0 else ("last" if i == len(tiles) - 1 else "mid"), tl["label"], tl["value"], tl["kind"],
                         tl["note"], "", tl["extra"], go=tl["go"])


