def _rep_spend_years() -> list[int]:
    ss = st.session_state
    have = {int(k[:4]) for k, rows in ss.entries["ledger"].items() if rows}
    have |= {int(str(t.get("date", ""))[:4]) for t in (ss.entries.get("card_txns") or {}).values() if str(t.get("date", ""))[:4].isdigit()}
    return sorted(have | {today().year})


