def _rep_tile_numbers(plan, items, R, name):
    """What a spending tile shows: its items, total, whether it is a group, and its biggest part (category for a group, merchant for a category)."""
    is_group = name in R["order"] and name != NOT_SPENDING
    grp = lambda it: R["group_of"].get(it["cat"], UNCATEGORIZED)
    its = [i for i in items if (grp(i) == name if is_group else i["cat"] == name)]
    total = round(sum(i["amount"] for i in its), 2)
    parts = items_frame(its, (lambda i: i["cat"]) if is_group else (lambda i: merchant_key(i["desc"]) or i["desc"]))
    top = (parts.iloc[0]["Description"], float(parts.iloc[0]["Total"])) if len(parts) else None
    return {"items": its, "total": total, "group": is_group, "parts": parts, "top": top}


def tax_paid_report(plan, entries, R, year: int) -> dict:
    """Tax paid toward one tax year: the estimated payments marked paid, federal withholding on deferred comp deposits (reconciled DefComp
    lines grossed up at the withholding rate), and the bank lines filed under Income tax payments in that calendar year."""
    rows = tax_schedule(plan, R, year)
    s = tax_summary(rows)
    rate = float(plan.inputs.defcomp.withholding_rate)
    wh = []
    for m in range(1, 13):
        k = f"{year}-{m:02d}"
        g = defcomp_received(entries.get("ledger", {}).get(k, []) or [], rate)
        if g:
            wh.append({"Month": month_label(k), "Deferred comp, gross": g, "Withheld": round(g * rate, 2), "Deposited": round(g * (1 - rate), 2)})
    withheld = round(sum(w["Withheld"] for w in wh), 2)
    bank = [i for i in spending_items(plan, entries, year) if i["cat"] == "Income tax payments"]
    return {"year": year, "schedule": rows, "summary": s, "withholding": wh, "withheld": withheld, "bank": bank,
            "bank_total": round(sum(i["amount"] for i in bank), 2), "paid_total": round(s["paid"] + withheld, 2)}


