def _mv_window(mv):
    return [y for y in YEARS if y >= mv.year]


def rules_summary(mv, code: str | None = None) -> list[str]:
    """The state's rules in plain words, with your changes."""
    code = code or mv.state
    r = STATE_RULES.get(code, {})
    if r.get("none"):
        return [f"{_state_name(code)} has no income tax on wages, retirement or investment income."] + ([STATE_NOTES[code]] if code in STATE_NOTES else [])
    rule = lambda k, d=None: state_rule(mv, k, d, code)
    b = r["b"]
    rates = (f"Flat {b[-1][1] * 100:g}%" + (f" above {money(b[-1][0])}" if b[-1][0] else "") if len(b) <= 2 and b[0][1] in (0, b[-1][1])
             else f"{min(x for _l, x in b if x) * 100:g}% to {b[-1][1] * 100:g}%, top rate above {money(b[-1][0])}")
    out = [f"Rates: {rates}" + (" (brackets grow with inflation)" if r.get("idx") is True else "") + "."]
    ded = []
    if r.get("std"):
        ded.append(f"standard deduction {money(r['std'])}" + (" (follows the federal one)" if r.get("idx") == "std" else ""))
    if r.get("ex"):
        ded.append(f"exemptions {money(r['ex'])}" + (f", plus {money(r['ex65'])} each at 65" if r.get("ex65") else ""))
    if r.get("credit"):
        ded.append(f"a {money(r['credit'])} credit")
    if r.get("age"):
        ded.append(f"an age deduction of {money(r['age'][0])} each at 65, shrinking $1 for each $1 of income (not counting Social Security) over {money(r['age'][1])}")
    out.append("For a married couple: " + (", ".join(ded) if ded else "no standard deduction") + ".")
    ss_ = rule("ss")
    out.append("Social Security: " + ("not taxed." if ss_ is None else "taxed." if float(ss_) == 0 else
               f"not taxed while income is up to {money(ss_)}; above that " + (f"{float(rule('ss_part', 1)) * 100:g}% of it is taxed." if float(rule('ss_part', 1)) < 1 else "it is taxed.")))
    ret = rule("ret", 0) or 0
    if ret:
        what = "retirement income (IRA withdrawals, Roth conversions, deferred comp, the SIPP)" + (", interest, dividends and gains" if rule("ret_inv") else "")
        amt = "all " + what if ret == _INF else f"up to {money(ret)} each of {what}"
        age = int(rule("ret_age", 0) or 0)
        out.append(f"Exempt: {amt}" + (f", from age {age}" if age else "") + (f", if income is no more than {money(rule('ret_limit'))}" if rule("ret_limit") else "") + ".")
    else:
        out.append("Retirement income, Roth conversions included, is taxed like other income.")
    out.append("Other states' municipal bond interest: " + ("taxed." if rule("muni", True) else "not taxed."))
    if rule("local"):
        out.append(f"Local income tax assumed: {float(rule('local')) * 100:g}% of taxable income.")
    if rule("veh"):
        out.append(f"Vehicle tax: {float(rule('veh')):g}% of value a year.")
    if code in STATE_NOTES:
        out.append(STATE_NOTES[code])
    return out


