def _mv_hub(ss, mv):
    st.title("Moving")
    where = f"{mv.area + ', ' if mv.area else ''}{_state_name(mv.state)}"
    when = f"{MONTHS_SHORT[int(mv.month) - 1]} {mv.year}"
    how = (f"renting in {where} from {when} for under half the year, with Florida staying home" if mv.keep_fl
           else f"moving to {where} in {when}, selling Gulf Breeze and buying there" if mv.housing == "sell"
           else f"moving to {where} in {when}, renting there and keeping Gulf Breeze")
    if mv.active:
        st.success(_esc(f"In the plan: {how}. Every page now uses it: taxes, cash flow and net worth."))
    else:
        caption(f"What {how} would change. Not in the plan yet: nothing else in the app changes until you make it the plan. Tap a tile to open it.")
    base, withm = _mv_runs()
    withm_infl = float(ss.settings.get("inflation", 0.03))
    ts, cf0, cf1 = withm["ts"], base["cf"], withm["cf"]
    win = _mv_window(mv)
    tax_tot, roth_tot = float(ts.state_tax.sum()), float(ts.state_tax_roth.sum())
    full = mv.year + 1 if mv.year + 1 in ts.index else mv.year
    cost_full = float(ts.loc[full, "move_cost"]) if full in ts.index else 0.0
    dr1 = float(cf1.drawdown.sum()) - float(cf0.drawdown.sum())
    fy1 = withm["cf_sum"].get("first_drawdown_year")
    last = int(base["pf"].index[-1])
    hv = _home_values(mv, last, withm_infl)
    chosen_name = {"Florida stays home": "Florida stays home", "Selling and buying there": "Selling and buying", "Moving there, renting": "Moving, renting"}[_how_label(mv)]
    nw0 = float(base["pf"].total_assets.iloc[-1]) + hv["Staying put"]
    nw1 = float(withm["pf"].total_assets.iloc[-1]) + hv[chosen_name]
    mvx, infl = _mv_effective()
    mvx.keep_fl = False                                    # comparing states means living there
    comp = [(c, sum(state_tax_year(c, mvx, y, base["ts"].loc[y], infl)[0] for y in base["ts"].index)) for c in (mv.compare or [])]
    best = min(comp, key=lambda x: x[1]) if comp else None
    T = lambda key, t, v: {"key": key, "t": t, "go": (lambda v_=v: _mv_go(v_))}
    _hub_row([
        T("mv_setup", ("The move", _state_name(mv.state), "ok" if mv.active else "idle", f"{when}, {mv.area or 'area not set'}",
                       _how_label(mv) + (" · in the plan" if mv.active else " · what-if")), "setup"),
        T("mv_tax", ("State income tax", money(tax_tot), "idle",
                     "None: Florida stays home" if mv.keep_fl else f"{win[0] if win else mv.year} to {YEARS[-1]}, {money(roth_tot)} on Roth conversions",
                     "Under 184 nights a year there" if mv.keep_fl else f"About {money(tax_tot / max(1, len(win)))} a year"), "tax"),
        T("mv_costs", ("Running costs", money(cost_full), "idle",
                       f"in {full}: " + ("new home's tax and insurance, less Gulf Breeze's" if selling(mv) else "rent, vehicle tax, Gulf Breeze tax"),
                       f"Gulf Breeze sold for {money(home_purchase(_mv_effective()[0], withm_infl)['sale'])}" if selling(mv) else f"Rent {money(mv.rent_month)} a month today"), "costs"),
        T("mv_cash", ("Cash flow and net worth", signed(nw1 - nw0), "warn" if dr1 > 0.5 else "idle", f"investments and home by {last}",
                      (f"Draws {money(dr1)} from investments from {fy1}" if dr1 > 0.5 else
                       f"Cash stays above {money(cash_warn_level(ss.plan))}")), "cash"),
        T("mv_compare", ("Compare states", _state_name(best[0]) if best else "—", "idle", f"least state tax, {money(best[1])}" if best else "Pick states to compare",
                         f"{len(comp)} states compared"), "compare"),
    ], "plan")
    st.write("")
    if mv.active:
        st.button("Take the move out of the plan", key="mv_off", on_click=cb_mv_active, args=(False,))
        caption("The settings stay here, so you can put it back at any time.")
    else:
        st.button(f"Make this move part of the plan", key="mv_on", on_click=cb_mv_active, args=(True,), type="primary")
        caption((f"From {when}, every page then counts the rent and running costs above (no state income tax: Florida stays home). " if mv.keep_fl else
                 f"From {when}, every page then counts {_state_name(mv.state)}'s income tax and the running costs above. ") + "You can take it out again.")


