def cb_mv_set(field_, key, kind=float):
    ss = st.session_state
    v = ss.get(key)
    if v is None:
        return
    mv = ss.plan.inputs.move
    if field_ == "state":
        if v != mv.state:
            mv.overrides = {}                                   # a new state starts from its own rules
            _mv_clear_rule_widgets()
            if v != "VA" and mv.area == "Loudoun County":
                mv.area = ""
        mv.state = v
        return
    if kind is int:
        v = int(v)
    elif kind is float:
        v = float(v)
    setattr(mv, field_, v)


def cb_mv_override(rule_key, key, scale=1.0):
    ss = st.session_state
    mv = ss.plan.inputs.move
    v = ss.get(key)
    ov = dict(mv.overrides or {})
    if rule_key == "ss":
        choice = v
        if choice == "Not taxed":
            ov["ss"] = None
        elif choice == "Always taxed":
            ov["ss"] = 0
        else:
            ov["ss"] = float(ss.get(key + "_amt") or 0) or 100000.0
    elif rule_key == "ss_amt":
        ov["ss"] = float(v or 0)
    elif rule_key == "ret_all":
        ov["ret"] = _INF if v else 0.0
    else:
        ov[rule_key] = None if v is None else float(v) * scale
    mv.overrides = ov


def _mv_clear_rule_widgets():
    ss = st.session_state
    for k in [k for k in list(ss.keys()) if str(k).startswith(("mv_ra_", "mv_ret_", "mv_ss_", "mv_loc_", "mv_veh_"))]:
        del ss[k]


def cb_mv_reset():
    st.session_state.plan.inputs.move.overrides = {}
    _mv_clear_rule_widgets()


def _mv_setup(ss, mv):
    dv = ss.data_ver
    caption("Where and when, what renting there costs, and what keeping Gulf Breeze adds. Money is in today's dollars; the plan grows it with inflation.")
    codes = _state_codes()
    c1, c2 = st.columns(2)
    c1.selectbox("State", codes, index=codes.index(mv.state) if mv.state in codes else 0, format_func=_state_name, key=f"mv_state_{dv}",
                 on_change=cb_mv_set, args=("state", f"mv_state_{dv}", str))
    c2.text_input("Area (for your notes)", value=mv.area, key=f"mv_area_{dv}", on_change=cb_mv_set, args=("area", f"mv_area_{dv}", str))
    st.radio("How you would live there", HOW_OPTS, index=_how_index(mv), key=f"mv_how_{dv}", on_change=cb_mv_how, args=(f"mv_how_{dv}",))
    if mv.keep_fl:
        caption("No income tax there and the Gulf Breeze homestead is kept, as long as Florida really is home: more than half the year spent "
                "away from the new state (counting travel), a log of nights to show it, and your licences, voter registration, cars and the "
                "motorhome all in Florida. Over 183 nights with a place to live there and most states tax you as a resident, wherever your home is. "
                "The rent and the other costs below still count.")
    mvx, infl_ = _mv_effective()
    if not selling(mv):
        st.subheader("Renting there")
        c1, c2, c3 = st.columns(3)
        c1.number_input("Rent a month", 0.0, 20000.0, float(mv.rent_month), 50.0, format="%.0f", key=f"mv_rent_{dv}", on_change=cb_mv_set, args=("rent_month", f"mv_rent_{dv}"))
        c2.number_input("Rent increase a year (%)", 0.0, 10.0, float(mv.rent_growth) * 100, 0.5, format="%.1f", key=f"mv_rg_{dv}",
                        on_change=lambda: setattr(ss.plan.inputs.move, "rent_growth", float(ss[f"mv_rg_{dv}"]) / 100))
        c3.number_input("Other new costs a month", 0.0, 10000.0, float(mv.other_month), 25.0, format="%.0f", key=f"mv_oth_{dv}",
                        on_change=cb_mv_set, args=("other_month", f"mv_oth_{dv}"), help="Renter's insurance, a second set of utilities and the like.")
        st.number_input("Moving cost (once)", 0.0, 200000.0, float(mv.moving_cost), 500.0, format="%.0f", key=f"mv_mc_{dv}", on_change=cb_mv_set, args=("moving_cost", f"mv_mc_{dv}"))
    else:
        hp = home_purchase(mvx, infl_)
        st.subheader("Selling Gulf Breeze and buying there")
        if not mvx.fl_house:
            st.warning("Add the house on the Net worth page (Capital assets) so its sale can be worked out.")
        caption(f"Gulf Breeze, from the Net worth page: {money(mvx.fl_house.get('value', 0))} today, about {money(hp['sale'])} in {mv.year}. "
                f"After selling costs that leaves {money(hp['net'])}"
                + (f", plus {money(hp['extra'])} from cash" if hp["extra"] > 0 else f", less {money(-hp['extra'])} kept in cash" if hp["extra"] < 0 else "")
                + f", which buys a home of about {money(hp['price'])} there after closing costs. No mortgage. Living in it two of the last five years "
                "means the gain on the sale is not taxed, up to $500,000 for a couple.")
        c1, c2, c3 = st.columns(3)
        c1.number_input("Selling costs (%)", 0.0, 15.0, float(mv.sell_cost_pct) * 100, 0.5, format="%.1f", key=f"mv_sc_{dv}",
                        on_change=lambda: setattr(ss.plan.inputs.move, "sell_cost_pct", float(ss[f"mv_sc_{dv}"]) / 100), help="Agent's commission and closing costs.")
        c2.number_input("Buying costs (%)", 0.0, 10.0, float(mv.buy_cost_pct) * 100, 0.5, format="%.1f", key=f"mv_bc_{dv}",
                        on_change=lambda: setattr(ss.plan.inputs.move, "buy_cost_pct", float(ss[f"mv_bc_{dv}"]) / 100))
        c3.number_input("Spend more (+) or less (-) than the sale brings", -2000000.0, 2000000.0, float(mv.buy_extra), 10000.0, format="%.0f",
                        key=f"mv_bx_{dv}", on_change=cb_mv_set, args=("buy_extra", f"mv_bx_{dv}"), help="Today's dollars; the difference comes from, or goes to, cash.")
        c1, c2, c3 = st.columns(3)
        prop = float(state_rule(mv, "prop", PROPERTY_TAX.get(mv.state, 1.0)) or 0.0)
        c1.number_input("Property tax there (% of value a year)", 0.0, 4.0, prop, 0.05, format="%.3f", key=f"mv_pt_{dv}_{mv.state}",
                        on_change=cb_mv_override, args=("prop", f"mv_pt_{dv}_{mv.state}"),
                        help="The state's average for owner-occupied homes (2024 Census survey); Virginia uses Loudoun's 2026 rate. Counties vary.")
        c2.number_input("Home insurance there, a year", 0.0, 50000.0, float(mv.home_insurance), 100.0, format="%.0f", key=f"mv_hi_{dv}",
                        on_change=cb_mv_set, args=("home_insurance", f"mv_hi_{dv}"))
        c3.number_input("Home value growth a year (%)", -5.0, 10.0, float(mv.home_growth) * 100, 0.5, format="%.1f", key=f"mv_hg_{dv}",
                        on_change=lambda: setattr(ss.plan.inputs.move, "home_growth", float(ss[f"mv_hg_{dv}"]) / 100))
        st.number_input("Moving cost (once)", 0.0, 200000.0, float(mv.moving_cost), 500.0, format="%.0f", key=f"mv_mc2_{dv}",
                        on_change=cb_mv_set, args=("moving_cost", f"mv_mc2_{dv}"))
        st.number_input("Gulf Breeze running costs that stop, a year", 0.0, 100000.0, float(mv.fl_savings_year), 100.0, format="%.0f", key=f"mv_fls2_{dv}",
                        on_change=cb_mv_set, args=("fl_savings_year", f"mv_fls2_{dv}"),
                        help="Pool service and the like. Gulf Breeze's real-estate tax and insurance stop by themselves; the new home's are counted instead.")
    if not mv.keep_fl and float(state_rule(mv, "veh", 0) or 0):
        st.subheader("Vehicles")
        cars_nw = mvx.car_items
        st.checkbox("Use the cars on the Net worth page" + (f" ({len(cars_nw)}, {money(sum(c[0] for c in cars_nw))} today)" if cars_nw else ""),
                    value=bool(mv.cars_from_networth), key=f"mv_cnw_{dv}",
                    on_change=lambda: setattr(ss.plan.inputs.move, "cars_from_networth", bool(ss[f"mv_cnw_{dv}"])))
        if not (mv.cars_from_networth and cars_nw):
            c1, c2 = st.columns(2)
            c1.number_input("Cars to register there, total value", 0.0, 500000.0, float(mv.car_value), 1000.0, format="%.0f", key=f"mv_car_{dv}",
                            on_change=cb_mv_set, args=("car_value", f"mv_car_{dv}"))
            c2.number_input("How many cars", 0, 6, int(mv.cars), 1, key=f"mv_cars_{dv}", on_change=cb_mv_set, args=("cars", f"mv_cars_{dv}", int))
        st.checkbox("The motorhome is taxed too", value=bool(mv.tax_rv), key=f"mv_rv_{dv}",
                    on_change=lambda: setattr(ss.plan.inputs.move, "tax_rv", bool(ss[f"mv_rv_{dv}"])))
    if not selling(mv):
        st.subheader("Keeping Gulf Breeze")
        c1, c2 = st.columns(2)
        c1.number_input("Extra property tax a year once it is not your homestead", 0.0, 50000.0, float(mv.fl_extra_tax_year), 100.0, format="%.0f",
                        key=f"mv_fl_{dv}", on_change=cb_mv_set, args=("fl_extra_tax_year", f"mv_fl_{dv}"),
                        help="Leaving Florida ends the homestead exemption from the next January 1: the $50,000 exemption goes, and the 3% cap on "
                             "assessment increases is replaced by the 10% cap for other property. If Amendment 3 passes in November 2026, the homestead "
                             "exemption becomes much larger, so losing it costs more.")
        c2.number_input("Gulf Breeze costs that stop, a year", 0.0, 100000.0, float(mv.fl_savings_year), 100.0, format="%.0f", key=f"mv_fls_{dv}",
                        on_change=cb_mv_set, args=("fl_savings_year", f"mv_fls_{dv}"), help="Pool service, lawn care and the like, if they stop while the house is empty.")
    st.number_input("Share of your muni bond interest from the new state's own bonds (%)", 0.0, 100.0, float(mv.muni_home_share) * 100, 5.0, format="%.0f",
                    key=f"mv_muni_{dv}", on_change=lambda: setattr(ss.plan.inputs.move, "muni_home_share", float(ss[f"mv_muni_{dv}"]) / 100),
                    help="Most states tax interest from other states' municipal bonds. Bonds from the new state itself are usually tax-free there.")
    st.subheader(f"{_state_name(mv.state)}'s tax rules")
    for line in rules_summary(mv):
        st.markdown("- " + _esc(line))
    if not STATE_RULES.get(mv.state, {}).get("none"):
        with st.expander("Adjust these rules"):
            caption("The rules above are 2026's, simplified to what matters for this plan. Change them here if you learn more; "
                    "choosing another state starts again from its own rules.")
            r = STATE_RULES[mv.state]
            ret = state_rule(mv, "ret", 0) or 0
            allr = st.checkbox("All retirement income is exempt", value=ret == _INF, key=f"mv_ra_{dv}_{mv.state}", on_change=cb_mv_override, args=("ret_all", f"mv_ra_{dv}_{mv.state}"))
            if not allr:
                st.number_input("Retirement income exempt, each of you", 0.0, 500000.0, min(float(ret), 500000.0), 500.0, format="%.0f", key=f"mv_ret_{dv}_{mv.state}",
                                on_change=cb_mv_override, args=("ret", f"mv_ret_{dv}_{mv.state}"))
            ssr = state_rule(mv, "ss")
            opts = ["Not taxed", "Taxed above an income", "Always taxed"]
            cur_ = 0 if ssr is None else (2 if float(ssr) == 0 else 1)
            st.radio("Social Security", opts, index=cur_, horizontal=True, key=f"mv_ss_{dv}_{mv.state}", on_change=cb_mv_override, args=("ss", f"mv_ss_{dv}_{mv.state}"))
            if cur_ == 1:
                st.number_input("Taxed when income is above", 0.0, 1000000.0, float(ssr), 1000.0, format="%.0f", key=f"mv_ss_{dv}_{mv.state}_amt",
                                on_change=cb_mv_override, args=("ss_amt", f"mv_ss_{dv}_{mv.state}_amt"))
            c1, c2 = st.columns(2)
            c1.number_input("Local income tax (% of taxable income)", 0.0, 6.0, float(state_rule(mv, "local", 0) or 0) * 100, 0.1, format="%.2f",
                            key=f"mv_loc_{dv}_{mv.state}", on_change=cb_mv_override, args=("local", f"mv_loc_{dv}_{mv.state}", 0.01))
            c2.number_input("Vehicle tax (% of value a year)", 0.0, 10.0, float(state_rule(mv, "veh", 0) or 0), 0.1, format="%.2f",
                            key=f"mv_veh_{dv}_{mv.state}", on_change=cb_mv_override, args=("veh", f"mv_veh_{dv}_{mv.state}"))
            if mv.overrides:
                st.button(f"Back to {_state_name(mv.state)}'s own rules", key=f"mv_reset_{dv}_{mv.state}", on_click=cb_mv_reset)


def _mv_tax(ss, mv):
    base, withm = _mv_runs()
    ts = withm["ts"]
    win = _mv_window(mv)
    if mv.keep_fl:
        st.info(_esc(f"No state income tax: with Florida as home and fewer than 184 nights a year in {_state_name(mv.state)}, you stay Florida "
                     f"residents. The figures below are what {_state_name(mv.state)} would charge if you lived there instead."))
        _base, withm_full = _mv_run(False), _mv_run(True, False)
        ts = withm_full["ts"]
    caption(f"{_state_name(mv.state)}'s income tax each year from the move, on the plan's income. Federal tax does not change. "
            "The move year counts only the months after you arrive.")
    tax_tot, roth_tot = float(ts.state_tax.sum()), float(ts.state_tax_roth.sum())
    m = st.columns(3)
    m[0].metric("State tax, all years", money(tax_tot))
    m[1].metric("Of which on Roth conversions", money(roth_tot))
    m[2].metric("Average a year", money(tax_tot / max(1, len(win))))
    if not win:
        return
    df = pd.DataFrame({"Year": [str(y) for y in win], "Income (MAGI)": [float(ts.loc[y, "total_magi"]) for y in win],
                       "Roth conversion": [float(ts.loc[y, "roth_conversion"]) for y in win], "State tax": [float(ts.loc[y, "state_tax"]) for y in win],
                       "Of which on the conversion": [float(ts.loc[y, "state_tax_roth"]) for y in win],
                       "Federal tax": [float(ts.loc[y, "fed_tax"]) for y in win]})
    fig = go.Figure()
    fig.add_trace(go.Bar(x=df.Year, y=df["State tax"] - df["Of which on the conversion"], name="On other income", marker_color="#7a63a6"))
    fig.add_trace(go.Bar(x=df.Year, y=df["Of which on the conversion"], name="On Roth conversions", marker_color="#c9a227"))
    fig.update_layout(barmode="stack")
    _plotly(style(fig, 280), use_container_width=True)
    cfg = {c: st.column_config.NumberColumn(format="dollar") for c in df.columns if c != "Year"}
    st.dataframe(df, hide_index=True, column_config=cfg)
    for line in rules_summary(mv):
        caption(line)


def _mv_costs(ss, mv):
    mvx, infl = _mv_effective()
    win = _mv_window(mv)
    sell = selling(mv)
    caption(("What selling Gulf Breeze and owning there changes each year: the new home's tax and insurance, less Gulf Breeze's, which stop. "
             if sell else "What renting there and keeping Gulf Breeze add to spending each year. ")
            + "In the dollars of each year; they come out of cash, like the living costs.")
    cols = [("Rent", "rent"), ("Other new costs", "other"), ("Vehicle tax", "vehicle_tax"), ("Gulf Breeze extra tax", "fl_tax"),
            ("New home's property tax", "home_tax"), ("New home's insurance", "home_insurance"), ("Gulf Breeze tax and insurance stop", "fl_bills"),
            ("Gulf Breeze savings", "fl_savings"), ("Moving", "moving"), ("Home purchase from cash", "home_cash")]
    neg = {"fl_bills", "fl_savings"}
    rows = []
    for y in win:
        c = move_costs(mvx, y, infl)
        rows.append({"Year": str(y), **{lab: (-c[k] if k in neg else c[k]) for lab, k in cols}, "Total": c["total"]})
    df = pd.DataFrame(rows)
    if not len(df):
        return
    df = df[[c for c in df.columns if c in ("Year", "Total") or df[c].abs().sum() > 0.5]]
    if sell:
        hp = home_purchase(mvx, infl)
        m = st.columns(4)
        m[0].metric(f"Gulf Breeze sells for, {mv.year}", money(hp["sale"]))
        m[1].metric("Left after selling costs", money(hp["net"]))
        m[2].metric("Buys a home of", money(hp["price"]))
        m[3].metric("From cash", money(hp["extra"]) if hp["extra"] >= 0 else "-" + money(-hp["extra"]))
    full = 1 if len(df) > 1 else 0
    m = st.columns(2)
    m[0].metric(f"Extra cost in {df.Year.iloc[full]}", money(df.Total.iloc[full]) if df.Total.iloc[full] >= 0 else "-" + money(-df.Total.iloc[full]))
    m[1].metric("All years", money(df.Total.sum()) if df.Total.sum() >= 0 else "-" + money(-df.Total.sum()))
    cfg = {c: st.column_config.NumberColumn(format="dollar") for c in df.columns if c != "Year"}
    st.dataframe(df, hide_index=True, column_config=cfg)
    caption("Your living-cost budget already covers running one house, so only the differences are counted here. Change the figures on The move.")


def _mv_plans():
    """The four ways, as model runs: staying put, moving and renting, selling and buying, and renting with Florida kept as home."""
    out = [("Staying put", _mv_run(False))]
    pj, sj, ej = _model_json()
    for name, keep, housing in ((f"Moving, renting", False, "rent"), ("Selling and buying", False, "sell"), ("Florida stays home", True, "rent")):
        d = json.loads(pj)
        m = d["inputs"].setdefault("move", {})
        m.update(active=True, keep_fl=keep, housing=housing)
        d["cash"]["cash_floor"] = cash_warn_level(st.session_state.plan)
        out.append((name, _run_cached(json.dumps(d, sort_keys=True), sj, ej)))
    return out


def _home_values(mv, y: int, infl: float) -> dict:
    """The home you own at year y in each plan: Gulf Breeze, or the new home after a sale."""
    mvx = _copy.deepcopy(_mv_effective()[0])
    gb = gulf_breeze_value(mvx, y)
    mvx.housing, mvx.keep_fl = "sell", False
    return {"Staying put": gb, "Moving, renting": gb, "Florida stays home": gb, "Selling and buying": new_home_value(mvx, y, infl) if y >= mv.year else gb}


def _mv_cash(ss, mv):
    plans = _mv_plans()
    infl = float(ss.settings.get("inflation", 0.03))
    floor = cash_warn_level(ss.plan)
    chosen_name = {"Florida stays home": "Florida stays home", "Selling and buying there": "Selling and buying", "Moving there, renting": "Moving, renting"}[_how_label(mv)]
    R = dict(plans)
    base, chosen = R["Staying put"], R[chosen_name]
    last = int(base["pf"].index[-1])
    hv = _home_values(mv, last, infl)
    caption(f"Spendable cash (savings and money market) and what you own: investments plus your home. Cash is kept at or above your "
            f"{money(floor)} safety line: when a year would end below it, the shortfall is drawn from investments. The four ways side by side, "
            f"moving to {_state_name(mv.state)} in {MONTHS_SHORT[int(mv.month) - 1]} {mv.year}; the figures at the top are for the way set on "
            f"The move ({_how_label(mv)}).")
    cf0, cf1 = base["cf"], chosen["cf"]
    own = lambda name, r_: float(r_["pf"].total_assets.iloc[-1]) + hv[name]
    dl = lambda x: ("-" if x < 0 else "+") + money(abs(x)) + " vs staying"     # a plain minus, so the arrow points the right way
    d0, d1 = float(cf0.drawdown.sum()), float(cf1.drawdown.sum())
    fy = chosen["cf_sum"].get("first_drawdown_year")
    m = st.columns(3)
    m[0].metric("Drawn from investments", money(d1), (("+" if d1 >= d0 else "-") + money(abs(d1 - d0)) + " vs staying") if abs(d1 - d0) > 0.5 else None,
                delta_color="inverse")
    m[1].metric("First year of drawing", str(fy) if fy else "None")
    m[2].metric(f"Investments and home, {last}", money(own(chosen_name, chosen)), dl(own(chosen_name, chosen) - own("Staying put", base)))
    colors = {"Staying put": "#7f8c99", "Moving, renting": "#7a63a6", "Selling and buying": "#c9a227", "Florida stays home": "#2e8b7a"}
    fig = go.Figure()
    for name, r_ in plans:
        fig.add_trace(go.Scatter(x=list(r_["cf"].index), y=r_["cf"].ending_cash, name=name,
                                 line=dict(color=colors[name], width=3 if name == chosen_name else 2, dash="dot" if name == "Florida stays home" else None)))
    fig.add_hline(y=floor, line=dict(color="#b26a00", width=1, dash="dash"), annotation_text=f"Safety line {money(floor)}", annotation_position="bottom right")
    _plotly(style(fig, 300), use_container_width=True)
    rows = []
    for name, r_ in plans:
        cf, fy_ = r_["cf"], r_["cf_sum"].get("first_drawdown_year")
        rows.append({"Plan": name, "State tax, all years": float(cf.state_tax.sum()), "Running costs, all years": float(cf.move_cost.sum()),
                     "Drawn from investments": float(cf.drawdown.sum()), "Drawing from": str(fy_) if fy_ else "",
                     f"Investments, {last}": float(r_["pf"].total_assets.iloc[-1]), f"Home, {last}": hv[name], f"Investments and home, {last}": own(name, r_)})
    st.dataframe(pd.DataFrame(rows), hide_index=True,
                 column_config={c: st.column_config.NumberColumn(format="dollar") for c in rows[0] if c not in ("Plan", "Drawing from")})
    df = pd.DataFrame({"Year": [str(y) for y in cf0.index], **{f"Cash: {name}": r_["cf"].ending_cash.values for name, r_ in plans},
                       f"Drawn: {chosen_name}": cf1.drawdown.values})
    st.dataframe(df, hide_index=True, column_config={c: st.column_config.NumberColumn(format="dollar") for c in df.columns if c != "Year"})
    caption("Investments already pay for spending beyond what cash covers, so a draw moves money from investments into cash: it does not change "
            "the total. Any capital gains tax on what is sold is not included. Home values: Gulf Breeze as on the Net worth page; a new home grows "
            "at the rate set on The move.")


def _mv_compare(ss, mv):
    base = _mv_run(False)
    mvx, infl = _mv_effective()
    mvx.keep_fl = False                                    # comparing states means living there
    ts = base["ts"]
    dv = ss.data_ver
    caption("Income tax alone, in each state you pick, on the same plan and the same move date. Rent and other costs are left out, since they "
            "depend on the area; vehicle tax is shown on its own.")
    codes = _state_codes()
    pick = st.multiselect("States", codes, default=[c for c in (mv.compare or []) if c in codes], format_func=_state_name, key=f"mv_cmp_{dv}",
                          on_change=lambda: setattr(ss.plan.inputs.move, "compare", list(ss[f"mv_cmp_{dv}"])))
    if not pick:
        return
    full = mv.year + 1
    ry = int(ss.plan.inputs.roth_first_year)
    rows = []
    for c in pick:
        per = {y: state_tax_year(c, mvx, y, ts.loc[y], infl) for y in ts.index}
        m2 = _copy.deepcopy(mvx); m2.state, m2.overrides = c, ({} if c != mv.state else mv.overrides)
        rows.append({"State": _state_name(c), f"Tax in {full}": per.get(full, (0, 0))[0], f"Tax in {ry} (a Roth year)": per.get(ry, (0, 0))[0],
                     "On Roth conversions": sum(v[1] for v in per.values()), "Total to " + str(YEARS[-1]): sum(v[0] for v in per.values()),
                     "Vehicle tax a year": move_costs(m2, full, infl)["vehicle_tax"]})
    df = pd.DataFrame(rows).sort_values("Total to " + str(YEARS[-1]))
    cfg = {c: st.column_config.NumberColumn(format="dollar") for c in df.columns if c != "State"}
    st.dataframe(df, hide_index=True, column_config=cfg)
    for c in pick:
        with st.expander(f"{_state_name(c)}: the rules used"):
            for line in rules_summary(mvx, c):
                st.markdown("- " + _esc(line))


def page_reporting():
    ss = st.session_state
    view = ss.get("rep_view") or "hub"
    if view == "cpa":
        _rep_back()
        _rep_cpa()
    elif view == "docs":
        _rep_back()
        _rep_docs()

    elif view == "taxpaid":
        _rep_back()
        _rep_taxpaid()
    elif view in ACT_KINDS:
        _rep_back()
        _rep_activity(view)
    elif view == "register":
        _rep_back()
        _rep_register()
    elif view == "aca":
        _rep_back()
        _rep_aca()

    else:
        _rep_hub()


def _rep_bands(bands):
    """Rows of tiles in the Dashboard's style (the whole tile is the button); more than five tiles wrap to another row."""
    with _tile_area():
        for name, sub, band, tl in bands:
            st.markdown(f"**{name}** &nbsp;·&nbsp; <span style='opacity:.6'>{_h(sub)}</span>", unsafe_allow_html=True)
            for r0 in range(0, len(tl), TILES_PER_ROW):
                chunk = tl[r0:r0 + TILES_PER_ROW]
                cols = st.columns(len(chunk), gap="small")
                for i, t in enumerate(chunk):
                    with cols[i]:
                        _segment(t["key"], band, "first" if i == 0 else ("last" if i == len(chunk) - 1 else "mid"), t["label"], t["value"], t["kind"],
                                 t["note"], "", t.get("extra", ""), go=t["go"])
            st.write("")


def _rep_hub():
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    st.title("Reporting")
    caption("Tax reporting, and reports of your activity for a week, month, quarter or year. Tap a tile to open it.")
    R = model()
    ty = min(max(today().year if today().month >= 5 else today().year - 1, 2026), 2042)
    dp = docs_progress(entries, tax_documents(plan, R, ty), ty)
    files = [f for f in docs_index(entries, ty) if not f.get("gone")]
    arch = docs_archived(entries, ty)
    tp = tax_paid_report(plan, entries, R, today().year)
    T = lambda key, label, value, kind, note, extra, go: {"key": key, "label": label, "value": value, "kind": kind, "note": note, "extra": extra, "go": go}
    tax_row = [
        T("rep_cpa", "CPA package", str(ty), "ok" if arch else "idle", f"Archived {arch}" if arch else "Build and download the zip",
          f"{len(files)} document{'s' if len(files) != 1 else ''} stored", lambda: _rep_go("cpa")),
        T("rep_docs", "Tax documents", f"{dp['received']} of {dp['needed']}", "ok" if dp["needed"] and dp["received"] >= dp["needed"] else "idle",
          f"received for {ty}", "Upload forms and statements", lambda: _rep_go("docs")),
        T("rep_taxpaid", "Tax payments", money(tp["paid_total"]), "idle", f"paid toward {tp['year']}",
          (f"{tp['summary']['n_paid']} of {tp['summary']['n']} estimated payments" if tp["summary"]["n"] else "No estimated payments set")
          + f" · withheld {money(tp['withheld'])}", lambda: _rep_go("taxpaid")),
    ]
    try:                                                    # v25.35
        ev_ = aca_evidence(plan, entries, R)
        tax_row.append(T("rep_aca", f"ACA income evidence", money(ev_["total"]), "idle", f"projected income, {ev_['year']}",
                         "Sources, documents and a letter to sign", lambda: _rep_go("aca")))
    except Exception:  # noqa: BLE001 - the tile must always draw
        pass
    act_row = []
    for kind, (label, _w) in ACT_KINDS.items():
        try:
            st_, en_ = act_periods(kind)[0][1]
            its_ = _wk_items(plan, entries, st_, min(en_, today()))
            val = money(sum(i["amount"] for i in its_))          # v25.19: net -- spent less refunds, as the report's Net spending
            note = "net spending, " + act_label(kind, st_, en_)
        except Exception:  # noqa: BLE001 - the tile must always draw
            val, note = "\u2014", ""
        act_row.append(T(f"rep_{kind}", label, val, "idle", note, "View, print or download", (lambda k=kind: _rep_go(k))))
    try:                                                    # v25.28
        cur_k, _m = current_month_key()
        rows_ = entries["ledger"].get(cur_k, [])
        n_c = sum(1 for r in rows_ if is_reconciled(r))
        act_row.append(T("rep_register", "Reconciliation register", month_short(cur_k), "ok" if rows_ and n_c == len(rows_) else "idle",
                         f"{n_c} of {len(rows_)} lines cleared", "View, print or download", lambda: _rep_go("register")))
    except Exception:  # noqa: BLE001 - the tile must always draw
        act_row.append(T("rep_register", "Reconciliation register", "—", "idle", "", "View, print or download", lambda: _rep_go("register")))
    _rep_bands([("Tax reporting", f"tax year {ty}", "home", tax_row), ("Activity reports", "spending, checking and cards for a period", "cash", act_row)])
    caption("Spending by category is on the Dashboard, at the end of the Cash row, and on the Spending page.")


