def _card_brief(src) -> str:
    """A card's name short enough for a table column: 'Citi/AAdvantage Executive World Legend Mastercard (5590)' -> 'Citi/AAdvantage (5590)'."""
    if src == "Checking":
        return "Checking"
    n = _card_short(src)
    if len(n) <= 28:
        return n
    m = _re.search(r"\((\d{3,5})\)\s*$", n)
    return (n.split()[0] + (f" ({m.group(1)})" if m else "")) if n.split() else n


# v25.28: printing from inside the embedded report froze the iPad (Safari prints the whole app page around the frame, and a long report,
# like the Annual one, never finished). The button now opens the report by itself in a new tab and prints that; in that tab it prints directly.
_PRINT_JS = ("<script>function _repPrint(){var top=true;try{top=window.self===window.top}catch(e){top=false}"
             "if(top){window.print();return}var w=null;try{w=window.open('','_blank')}catch(e){}"
             "if(!w){window.print();return}w.document.open();w.document.write('<!doctype html>'+document.documentElement.outerHTML);"
             "w.document.close();try{w.focus();w.print()}catch(e){}}"
             "try{if(window.self===window.top){document.querySelectorAll('.pnote').forEach(function(n){n.style.display='none'})}}catch(e){}</script>")


def print_button_html(label: str) -> str:
    return (f"<div class='noprint'><button class='pbtn' onclick='_repPrint()'>{_html.escape(label)}</button>"
            "<div class='pnote'>Opens the page in a new tab to print. Close that tab when you are done.</div></div>" + _PRINT_JS)


def report_document(d: dict, print_button: bool = True) -> str:
    """v25.14: an activity report laid out as a printable report: title block, headline figures, then sections with tables and bars."""
    e = _html.escape
    kind, start, end = d["kind"], d["start"], d["end"]
    label = {"week": "Weekly report", "month": "Monthly report", "quarter": "Quarterly report", "year": "Annual report"}.get(kind, "Report")
    so_far = end > today()
    shown_end = min(end, today())
    period = (f"{fmt_date(start)}, {start.year} to {fmt_date(shown_end)}, {shown_end.year}" if start.year != shown_end.year
              else f"{fmt_date(start)} to {fmt_date(shown_end)}, {shown_end.year}")
    head = (f"<div class='top'><div><div class='org'>Shooman retirement plan</div><h1>{e(label)}: {e(act_label(kind, start, end))}</h1></div>"
            f"<div class='sub'>{e(period)}{' (to date)' if so_far else ''}<br>Prepared {e(fmt_date(today()))}, {today().year}</div></div>")
    ck = d.get("checking")
    k4 = (("Checking", money(ck[1]), f"{signed(ck[1] - ck[0])} from {money(ck[0])}") if ck
          else ("Paid to the cards", money(sum(c[2] for c in d.get("cards", []))), "card payments made"))
    kpis = [("Spent", money(d.get("gross", 0.0)), f"{d.get('n', 0)} charges"),
            ("Refunds and credits", money(d.get("back", 0.0)), "returned to you"),
            ("Net spending", money(d.get("net", 0.0)), "spent less refunds"), k4]
    kp = "<div class='kpis'>" + "".join(f"<div class='kpi'><div class='l'>{e(l)}</div><div class='v'>{e(v)}</div><div class='n'>{e(n)}</div></div>" for l, v, n in kpis) + "</div>"
    body = [head, kp]
    if d.get("stale"):
        body.append("<div class='note'><b>Bank connections behind:</b> " + "; ".join(f"{e(n)} (data from {fmt_date(dt_)}, {dd} day{'s' if dd != 1 else ''} behind)" for n, dt_, dd in d["stale"])
                    + ". Remove that bank's connection on the SimpleFIN Bridge site and add it again.</div>")
    if d.get("reversed", (0, 0))[0]:
        nr, vr = d["reversed"]
        body.append(f"<div class='note' style='border-left-color:var(--accent);background:var(--soft)'>{nr} charge{'s' if nr != 1 else ''} totalling {money(vr, 2)} "
                    f"{'were' if nr != 1 else 'was'} refunded in full (voided tickets, returns) and {'are' if nr != 1 else 'is'} left out, together with the refund{'s' if nr != 1 else ''}.</div>")
    if d["unc"][0]:
        body.append(f"<div class='note'>{d['unc'][0]} line{'s' if d['unc'][0] != 1 else ''} ({money(d['unc'][1], 2)}) have no category yet; they are counted under Uncategorized.</div>")
    groups = [(g, v) for g, v in d.get("groups", []) if abs(v) > 0.005]
    if groups:
        mx = max((v for _g, v in groups), default=1.0) or 1.0
        pos = sum(v for _g, v in groups if v > 0) or 1.0
        rows = "".join(f"<tr><td>{e(g)}</td><td class='barcell'><div class='bar' style='width:{max(0.0, v) / mx * 100:.1f}%'></div></td>"
                       f"<td class='r'>{money(v, 2)}</td><td class='r'>{(v / pos * 100) if v > 0 else 0:.0f}%</td></tr>" for g, v in groups)
        body.append("<section><h2>Spending by group</h2><table><tr><th>Group</th><th></th><th class='r'>Amount</th><th class='r'>Share</th></tr>"
                    + rows + f"<tr class='tot'><td>Total</td><td></td><td class='r'>{money(d.get('net', 0.0), 2)}</td><td class='r'></td></tr></table></section>")
    if d.get("months"):
        mx = max((c + k for _m, c, k in d["months"]), default=1.0) or 1.0
        rows = "".join(f"<tr><td>{e(MONTH_NAMES[int(m[5:]) - 1])}</td><td class='barcell'><div class='bar' style='width:{max(0.0, c + k) / mx * 100:.1f}%'></div></td>"
                       f"<td class='r'>{money(c, 2)}</td><td class='r'>{money(k, 2)}</td><td class='r'><b>{money(c + k, 2)}</b></td></tr>" for m, c, k in d["months"])
        tc, tk = sum(c for _m, c, _k in d["months"]), sum(k for _m, _c, k in d["months"])
        body.append("<section><h2>Month by month</h2><table><tr><th>Month</th><th></th><th class='r'>Checking</th><th class='r'>Cards</th><th class='r'>Total</th></tr>"
                    + rows + f"<tr class='tot'><td>Total</td><td></td><td class='r'>{money(tc, 2)}</td><td class='r'>{money(tk, 2)}</td><td class='r'>{money(tc + tk, 2)}</td></tr></table></section>")
    if d.get("top"):
        rows = "".join(f"<tr><td class='d'>{e(fmt_date(_dt.date.fromisoformat(dt_)))}</td><td>{e(desc[:46])}</td><td>{e(_card_brief(src))}</td>"
                       f"<td>{e(cat)}</td><td class='r'>{money(amt, 2)}</td></tr>" for dt_, desc, src, cat, amt in d["top"])
        body.append(f"<section><h2>Largest items</h2><table><tr><th>Date</th><th>Description</th><th>Paid from</th><th>Category</th><th class='r'>Amount</th></tr>{rows}</table></section>")
    cards = [c for c in d.get("cards", []) if c[1] or c[2]]
    if cards:
        rows = "".join(f"<tr><td>{e(n)}</td><td class='r'>{money(ch, 2) if ch else '—'}</td><td class='r'>{money(pd_, 2) if pd_ else '—'}</td></tr>" for n, ch, pd_, _l in cards)
        body.append("<section><h2>Credit cards</h2><table><tr><th>Card</th><th class='r'>Charged</th><th class='r'>Paid to the card</th></tr>" + rows
                    + f"<tr class='tot'><td>Total</td><td class='r'>{money(sum(c[1] for c in cards), 2)}</td><td class='r'>{money(sum(c[2] for c in cards), 2)}</td></tr></table></section>")
    if d.get("register"):                                   # v25.28: the month's reconciliation register, on a page of its own
        body.append("<div class='pb'></div>" + register_sections(d["register"]))
    body.append("<div class='foot'>Activity for the period only: checking and credit card spending, with transfers and card payments left out and refunds netted. "
                + ("The register lists every checking line, transfers included; pending lines are planned or not yet at the bank. " if d.get("register") else "")
                + "Figures come from your app's records as of the latest bank fetch. Balances, budgets and plans are on the Dashboard.</div>")
    btn = print_button_html("Print this report") if print_button else ""
    title = f"{label}: {act_label(kind, start, end)}"
    return (f"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{e(title)}</title>"
            f"<style>{REPORT_CSS}</style></head><body><div class='page'>{btn}{''.join(body)}</div></body></html>")


# ---- v25.28: the monthly reconciliation register (printable, and the last section of the Monthly report) ----------------------------
def recon_register(entries: dict, k: str, opening: float, account: str = "", live: dict | None = None) -> dict:
    """One month of checking as a check register: every line in date order with the running balance, whether it has cleared, and the
    reconciliation -- cleared opening + cleared lines = what Wells should show; + the outstanding lines = the ledger's month-end.
    'opening' is the ledger opening (every earlier line, cleared or not); the cleared opening leaves out lines from earlier months that
    are still outstanding. 'live' is this month's automatic bank check (auto_bank_check), if any."""
    rows = entries["ledger"].get(k, [])
    unc_before = round(sum(_n(r.get("credit")) - _n(r.get("debit")) for mk, rs in entries["ledger"].items() if mk < k
                           for r in rs if not is_reconciled(r)), 2)
    lines = []
    for r, bal in running_balances(rows, opening)["lines"]:
        lines.append({"date": str(r.get("date") or "")[:10], "bank_date": str(r.get("bank_date") or "")[:10], "desc": str(r.get("desc") or ""),
                      "cls": str(r.get("cls") or ""), "out": _n(r.get("debit")), "in": _n(r.get("credit")), "cleared": is_reconciled(r),
                      "balance": bal, "note": str(r.get("note") or "")})
    s = lambda f, side: round(sum(l[side] for l in lines if f(l)), 2)
    clr, out = (lambda l: l["cleared"]), (lambda l: not l["cleared"])
    reg = {"k": k, "account": account, "lines": lines, "opening": round(float(opening), 2), "unc_before": unc_before,
           "cleared_open": round(float(opening) - unc_before, 2),
           "in_all": s(lambda l: True, "in"), "out_all": s(lambda l: True, "out"),
           "in_clr": s(clr, "in"), "out_clr": s(clr, "out"), "in_os": s(out, "in"), "out_os": s(out, "out"),
           "n_clr": sum(1 for l in lines if l["cleared"]), "n_os": sum(1 for l in lines if not l["cleared"])}
    reg["cleared_close"] = round(reg["cleared_open"] + reg["in_clr"] - reg["out_clr"], 2)
    reg["close"] = round(reg["opening"] + reg["in_all"] - reg["out_all"], 2)
    checks = sorted((c for c in entries.get("bank_checks", []) if c.get("month") == k), key=lambda c: str(c.get("t", "")))
    reg["last_match"] = checks[-1] if checks else None
    reg["live"] = live if live and live.get("k") == k else None
    return reg


def _reg_date(s: str) -> str:
    try:
        return fmt_date(_dt.date.fromisoformat(s[:10]))
    except (ValueError, TypeError):
        return s or "—"


def register_sections(reg: dict) -> str:
    """The register as report sections (the table, then the reconciliation), in the report's own style."""
    e = _html.escape
    m2 = lambda v: money(v, 2) if v else ""
    rows = [f"<tr class='open'><td class='d'>{e(_reg_date(reg['k'] + '-01'))}</td><td colspan='3'><b>Opening balance</b></td>"
            f"<td class='r'></td><td class='r'></td><td class='r'><b>{money(reg['opening'], 2)}</b></td></tr>"]
    for l in reg["lines"]:
        bank = (f"<div class='bd'>bank {e(_reg_date(l['bank_date']))}</div>" if l["bank_date"] and l["bank_date"] != l["date"] else "")
        rows.append(f"<tr class='{'' if l['cleared'] else 'pend'}'><td class='d'>{e(_reg_date(l['date']))}{bank}</td>"
                    f"<td>{e(l['desc'][:52])}</td><td>{e(l['cls'])}</td><td class='c'>{'&#10003;' if l['cleared'] else 'Pending'}</td>"
                    f"<td class='r'>{m2(l['out'])}</td><td class='r'>{m2(l['in'])}</td><td class='r'>{money(l['balance'], 2)}</td></tr>")
    rows.append(f"<tr class='tot'><td></td><td colspan='3'>Totals, {len(reg['lines'])} line{'s' if len(reg['lines']) != 1 else ''}</td>"
                f"<td class='r'>{money(reg['out_all'], 2)}</td><td class='r'>{money(reg['in_all'], 2)}</td><td class='r'>{money(reg['close'], 2)}</td></tr>")
    table = ("<section class='reg'><h2>Register: " + e(month_label(reg["k"])) + "</h2><table><tr><th>Date</th><th>Description</th><th>Class</th>"
             "<th class='c'>Cleared</th><th class='r'>Payment</th><th class='r'>Deposit</th><th class='r'>Balance</th></tr>" + "".join(rows) + "</table></section>")

    R = lambda label, v, cls="": f"<tr class='{cls}'><td>{label}</td><td class='r'>{money(v, 2)}</td></tr>"
    rec = [R("Cleared opening balance", reg["cleared_open"]),
           R("Plus cleared deposits", reg["in_clr"]),
           R("Less cleared payments", -reg["out_clr"]),
           R("Cleared balance: what Wells should show", reg["cleared_close"], "subt")]
    lv, lm = reg.get("live"), reg.get("last_match")
    if lv:
        when = f"fetch of {_reg_date(str(lv.get('date') or ''))}" if lv.get("date") else "latest fetch"
        verdict = ("matches" if lv["status"] == "match" else
                   f"waiting: {lv.get('waiting')} bank line{'s' if lv.get('waiting') != 1 else ''} to review" if lv["status"] == "waiting" else
                   f"differs by {money(abs(lv['diff']), 2)}")
        rec.append(f"<tr class='bank {'ok' if lv['status'] == 'match' else 'bad'}'><td>Wells balance, {e(when)} ({e(verdict)})</td><td class='r'>{money(lv['bank'], 2)}</td></tr>")
    elif lm:
        when = _reg_date(str(lm.get("auto") or lm.get("t") or "")[:10])
        rec.append(f"<tr class='bank ok'><td>Last matched with Wells, {e(when)}</td><td class='r'>{money(lm['balance'], 2)}</td></tr>")
    else:
        rec.append("<tr class='bank'><td>Not yet matched with Wells this month</td><td class='r'>—</td></tr>")
    if abs(reg["unc_before"]) > 0.005:
        rec.append(R("Outstanding from earlier months (net)", reg["unc_before"]))
    rec += [R(f"Plus outstanding deposits ({sum(1 for l in reg['lines'] if not l['cleared'] and l['in'])})", reg["in_os"]),
            R(f"Less outstanding payments ({sum(1 for l in reg['lines'] if not l['cleared'] and l['out'])})", -reg["out_os"]),
            R("Ledger balance, month-end", reg["close"], "subt")]
    osl = [l for l in reg["lines"] if not l["cleared"] and (l["in"] or l["out"])]
    os_tbl = ""
    if osl:
        os_tbl = ("<h3>Outstanding items</h3><table class='ost'><tr><th>Date</th><th>Description</th><th class='r'>Payment</th><th class='r'>Deposit</th></tr>"
                  + "".join(f"<tr><td class='d'>{e(_reg_date(l['date']))}</td><td>{e(l['desc'][:52])}</td><td class='r'>{m2(l['out'])}</td><td class='r'>{m2(l['in'])}</td></tr>" for l in osl)
                  + "</table>")
    recon = ("<section class='recon'><h2>Reconciliation</h2><table class='rt'>" + "".join(rec) + "</table>" + os_tbl
             + "<div class='sign'><span>Reconciled by</span><span>Date</span></div></section>")
    return table + recon


def register_document(reg: dict, print_button: bool = True) -> str:
    """v25.28: the reconciliation register on its own, as a printable page."""
    e = _html.escape
    title = f"Reconciliation register: {month_label(reg['k'])}"
    head = (f"<div class='top'><div><div class='org'>Shooman retirement plan</div><h1>{e(title)}</h1></div>"
            f"<div class='sub'>{e(reg.get('account') or 'Checking')}<br>Prepared {e(fmt_date(today()))}, {today().year}</div></div>")
    kpis = [("Opening", money(reg["opening"], 2), f"start of {month_short(reg['k'])}"),
            ("Deposits", money(reg["in_all"], 2), f"{sum(1 for l in reg['lines'] if l['in'])} lines"),
            ("Payments", money(reg["out_all"], 2), f"{sum(1 for l in reg['lines'] if l['out'])} lines"),
            ("Month-end", money(reg["close"], 2), f"{reg['n_clr']} cleared, {reg['n_os']} pending")]
    kp = "<div class='kpis'>" + "".join(f"<div class='kpi'><div class='l'>{e(l)}</div><div class='v'>{e(v)}</div><div class='n'>{e(n)}</div></div>" for l, v, n in kpis) + "</div>"
    btn = print_button_html("Print this register") if print_button else ""
    foot = ("<div class='foot'>Every ledger line for the month in date order. Balance counts every line; Cleared marks the lines matched to Wells. "
            "Pending lines are planned or not yet at the bank. A bank date is shown where it differs from the ledger date.</div>")
    return (f"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{e(title)}</title>"
            f"<style>{REPORT_CSS}</style></head><body><div class='page'>{btn}{head}{kp}{register_sections(reg)}{foot}</div></body></html>")


def register_for(k: str) -> dict:
    """The register for month k from the session, with this month's automatic bank check when k is the current month."""
    ss = st.session_state
    cur, _m = current_month_key()
    live = _auto_bank_check() if k == cur else None
    op = opening_any(k)
    return recon_register(ss.entries, k, 0.0 if op is None else op, ss.plan.expenses.get("sfin_account_name") or "Checking", live)


# ---- v25.28: the reports as PDF files. On the iPad, printing from the page inside the app froze Safari, and a page opened in a new tab
# had no Print option; a PDF always opens with Print in its Share menu, on the iPad and on Windows alike. Needs fpdf2 in requirements.txt.
def pdf_available() -> bool:
    try:
        import fpdf  # noqa: F401
        return True
    except ImportError:
        return False


_PDF_SUBS = {"−": "-", "—": "-", "–": "-", "…": "...", "✓": "Yes", "’": "'", "‘": "'", "“": '"',
             "”": '"', " ": " ", "⚠️": "", "⚠": "", "›": ">"}
_INK, _MUTED, _RULE, _SOFT, _ACCENT, _WARN, _GOOD = (31, 41, 51), (107, 119, 133), (217, 222, 228), (244, 246, 248), (47, 111, 168), (178, 106, 0), (46, 125, 79)


def _pt(s) -> str:
    """Text for the PDF's built-in fonts (Latin-1 only): typographic signs swapped for plain ones."""
    s = str("" if s is None else s)
    for a, b in _PDF_SUBS.items():
        s = s.replace(a, b)
    return s.encode("latin-1", "replace").decode("latin-1")


def _pdf_doc(foot_left: str):
    from fpdf import FPDF

    class _Doc(FPDF):
        def footer(self):
            self.set_y(-28)
            self.set_font("Helvetica", "", 7.5)
            self.set_text_color(*_MUTED)
            self.cell(0, 10, _pt(foot_left), align="L")
            self.set_x(self.l_margin)
            self.cell(0, 10, f"Page {self.page_no()} of {{nb}}", align="R")

    pdf = _Doc(format="letter", unit="pt")
    pdf.set_margins(40, 40, 40)
    pdf.set_auto_page_break(True, 44)
    pdf.alias_nb_pages()
    pdf.add_page()
    return pdf


def _pdf_head(pdf, title: str, right: list[str]):
    w = pdf.w - pdf.l_margin - pdf.r_margin
    y0 = pdf.get_y()
    pdf.set_font("Helvetica", "B", 7.5)
    pdf.set_text_color(*_MUTED)
    pdf.cell(w * 0.62, 10, "SHOOMAN RETIREMENT PLAN", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "B", 17)
    pdf.set_text_color(*_INK)
    pdf.multi_cell(w * 0.64, 21, _pt(title), new_x="LMARGIN", new_y="NEXT")
    y1 = pdf.get_y()
    pdf.set_font("Helvetica", "", 8.5)
    pdf.set_text_color(*_MUTED)
    pdf.set_xy(pdf.l_margin + w * 0.6, y0 + 4)
    for ln in right:
        pdf.set_x(pdf.l_margin + w * 0.6)
        pdf.cell(w * 0.4, 11, _pt(ln), align="R", new_x="LMARGIN", new_y="NEXT")
    y = max(y1, pdf.get_y()) + 6
    pdf.set_draw_color(*_ACCENT)
    pdf.set_line_width(2)
    pdf.line(pdf.l_margin, y, pdf.l_margin + w, y)
    pdf.set_line_width(0.5)
    pdf.set_y(y + 12)


def _pdf_kpis(pdf, kpis: list):
    w = pdf.w - pdf.l_margin - pdf.r_margin
    gap, n = 8, len(kpis)
    bw, bh, y = (w - gap * (n - 1)) / n, 50, pdf.get_y()
    pdf.set_draw_color(*_RULE)
    for i, (label, value, note) in enumerate(kpis):
        x = pdf.l_margin + i * (bw + gap)
        pdf.set_fill_color(*_SOFT)
        pdf.rect(x, y, bw, bh, style="DF")
        pdf.set_xy(x + 8, y + 6)
        pdf.set_font("Helvetica", "B", 6.5)
        pdf.set_text_color(*_MUTED)
        pdf.cell(bw - 16, 9, _pt(label.upper()))
        pdf.set_xy(x + 8, y + 16)
        pdf.set_font("Helvetica", "B", 13)
        pdf.set_text_color(*_INK)
        pdf.cell(bw - 16, 16, _pt(value))
        pdf.set_xy(x + 8, y + 34)
        pdf.set_font("Helvetica", "", 7.5)
        pdf.set_text_color(*_MUTED)
        pdf.cell(bw - 16, 10, _pt(note))
    pdf.set_y(y + bh + 14)


def _pdf_note(pdf, text: str, color=_WARN):
    w = pdf.w - pdf.l_margin - pdf.r_margin
    pdf.set_font("Helvetica", "", 8.5)
    pdf.set_text_color(*_INK)
    pdf.set_fill_color(*_SOFT)
    y = pdf.get_y()
    pdf.set_x(pdf.l_margin + 6)
    pdf.multi_cell(w - 6, 12, _pt(_re.sub(r"<[^>]+>", "", _html.unescape(text))), fill=True, padding=(4, 6), new_x="LMARGIN", new_y="NEXT")
    pdf.set_fill_color(*color)
    pdf.rect(pdf.l_margin, y, 3, pdf.get_y() - y, style="F")
    pdf.set_fill_color(255, 255, 255)
    pdf.ln(8)


def _pdf_h2(pdf, text: str, new_page: bool = False):
    if new_page:
        pdf.add_page()
    elif pdf.get_y() > pdf.h - 140:                      # a heading never sits alone at the foot of a page
        pdf.add_page()
    w = pdf.w - pdf.l_margin - pdf.r_margin
    pdf.ln(4)
    pdf.set_font("Helvetica", "B", 9.5)
    pdf.set_text_color(*_ACCENT)
    pdf.cell(w, 14, _pt(text.upper()), new_x="LMARGIN", new_y="NEXT")
    pdf.set_draw_color(*_RULE)
    pdf.line(pdf.l_margin, pdf.get_y() + 1, pdf.l_margin + w, pdf.get_y() + 1)
    pdf.ln(5)


def _pdf_table(pdf, headers, rows, widths, aligns, styles=None, width=None, size=8.5):
    """rows: lists of cell text; styles: per row None, 'tot' (bold), 'pend' (grey italic), 'open' (shaded, bold) or 'sub' (bold)."""
    from fpdf.fonts import FontFace
    pdf.set_font("Helvetica", "", size)
    pdf.set_text_color(*_INK)
    pdf.set_draw_color(*_RULE)
    pdf.set_fill_color(255, 255, 255)
    head = FontFace(emphasis="BOLD", color=_MUTED, size_pt=size - 1.5, fill_color=(255, 255, 255))
    look = {"tot": FontFace(emphasis="BOLD", color=_INK), "sub": FontFace(emphasis="BOLD", color=_INK),
            "pend": FontFace(emphasis="ITALICS", color=_MUTED), "open": FontFace(emphasis="BOLD", color=_INK, fill_color=_SOFT),
            "bank_ok": FontFace(color=_GOOD, fill_color=_SOFT), "bank_bad": FontFace(color=_WARN, fill_color=_SOFT)}
    with pdf.table(col_widths=widths, text_align=aligns, headings_style=head, line_height=size * 1.45, padding=(2, 4),
                   borders_layout="HORIZONTAL_LINES", width=width, align="LEFT", first_row_as_headings=bool(headers)) as t:
        if headers:
            hr = t.row()
            for h in headers:
                hr.cell(_pt(h.upper()))
        for i, r in enumerate(rows):
            stl = look.get((styles or [None] * len(rows))[i])
            row = t.row()
            for c in r:
                row.cell(_pt(c), style=stl)
    pdf.ln(6)


def _pdf_register(pdf, reg: dict, new_page: bool):
    """The register table, the reconciliation and the outstanding items: the same content as register_sections."""
    m2 = lambda v: money(v, 2) if v else ""
    _pdf_h2(pdf, f"Register: {month_label(reg['k'])}", new_page)
    rows, styles = [[_reg_date(reg["k"] + "-01"), "Opening balance", "", "", "", "", money(reg["opening"], 2)]], ["open"]
    for l in reg["lines"]:
        d = _reg_date(l["date"]) + (f" (bank {_reg_date(l['bank_date'])})" if l["bank_date"] and l["bank_date"] != l["date"] else "")
        rows.append([d, l["desc"][:60], l["cls"], "Yes" if l["cleared"] else "Pending", m2(l["out"]), m2(l["in"]), money(l["balance"], 2)])
        styles.append(None if l["cleared"] else "pend")
    rows.append(["", f"Totals, {len(reg['lines'])} lines", "", "", money(reg["out_all"], 2), money(reg["in_all"], 2), money(reg["close"], 2)])
    styles.append("tot")
    _pdf_table(pdf, ["Date", "Description", "Class", "Cleared", "Payment", "Deposit", "Balance"], rows,
               (62, 160, 50, 44, 58, 58, 62), ("LEFT", "LEFT", "LEFT", "CENTER", "RIGHT", "RIGHT", "RIGHT"), styles, size=8)
    _pdf_h2(pdf, "Reconciliation")
    rec, st_ = [], []
    add = lambda label, v, s=None: (rec.append([label, money(v, 2)]), st_.append(s))
    add("Cleared opening balance", reg["cleared_open"])
    add("Plus cleared deposits", reg["in_clr"])
    add("Less cleared payments", -reg["out_clr"])
    add("Cleared balance: what Wells should show", reg["cleared_close"], "sub")
    lv, lm = reg.get("live"), reg.get("last_match")
    if lv:
        when = f"fetch of {_reg_date(str(lv.get('date') or ''))}" if lv.get("date") else "latest fetch"
        verdict = ("matches" if lv["status"] == "match" else f"waiting: {lv.get('waiting')} bank lines to review" if lv["status"] == "waiting"
                   else f"differs by {money(abs(lv['diff']), 2)}")
        add(f"Wells balance, {when} ({verdict})", lv["bank"], "bank_ok" if lv["status"] == "match" else "bank_bad")
    elif lm:
        add(f"Last matched with Wells, {_reg_date(str(lm.get('auto') or lm.get('t') or '')[:10])}", lm["balance"], "bank_ok")
    else:
        rec.append(["Not yet matched with Wells this month", "-"]); st_.append(None)
    if abs(reg["unc_before"]) > 0.005:
        add("Outstanding from earlier months (net)", reg["unc_before"])
    add(f"Plus outstanding deposits ({sum(1 for l in reg['lines'] if not l['cleared'] and l['in'])})", reg["in_os"])
    add(f"Less outstanding payments ({sum(1 for l in reg['lines'] if not l['cleared'] and l['out'])})", -reg["out_os"])
    add("Ledger balance, month-end", reg["close"], "sub")
    _pdf_table(pdf, None, rec, (250, 90), ("LEFT", "RIGHT"), st_, width=340)
    osl = [l for l in reg["lines"] if not l["cleared"] and (l["in"] or l["out"])]
    if osl:
        pdf.set_font("Helvetica", "B", 9)
        pdf.set_text_color(*_INK)
        pdf.cell(0, 14, "Outstanding items", new_x="LMARGIN", new_y="NEXT")
        _pdf_table(pdf, ["Date", "Description", "Payment", "Deposit"], [[_reg_date(l["date"]), l["desc"][:44], m2(l["out"]), m2(l["in"])] for l in osl],
                   (55, 165, 60, 60), ("LEFT", "LEFT", "RIGHT", "RIGHT"), width=340)
    if pdf.get_y() > pdf.h - 90:
        pdf.add_page()
    y = pdf.get_y() + 24
    pdf.set_draw_color(*_INK)
    for x0, label in ((pdf.l_margin, "Reconciled by"), (pdf.l_margin + 190, "Date")):
        pdf.line(x0, y, x0 + 160, y)
        pdf.set_xy(x0, y + 2)
        pdf.set_font("Helvetica", "", 7.5)
        pdf.set_text_color(*_MUTED)
        pdf.cell(160, 10, label)
    pdf.set_y(y + 22)


def _pdf_foot(pdf, text: str):
    pdf.ln(6)
    pdf.set_font("Helvetica", "", 7.5)
    pdf.set_text_color(*_MUTED)
    pdf.multi_cell(0, 10, _pt(text), new_x="LMARGIN", new_y="NEXT")


def register_pdf(reg: dict) -> bytes:
    title = f"Reconciliation register: {month_label(reg['k'])}"
    pdf = _pdf_doc(title)
    _pdf_head(pdf, title, [reg.get("account") or "Checking", f"Prepared {fmt_date(today())}, {today().year}"])
    _pdf_kpis(pdf, [("Opening", money(reg["opening"], 2), f"start of {month_short(reg['k'])}"),
                    ("Deposits", money(reg["in_all"], 2), f"{sum(1 for l in reg['lines'] if l['in'])} lines"),
                    ("Payments", money(reg["out_all"], 2), f"{sum(1 for l in reg['lines'] if l['out'])} lines"),
                    ("Month-end", money(reg["close"], 2), f"{reg['n_clr']} cleared, {reg['n_os']} pending")])
    _pdf_register(pdf, reg, new_page=False)
    _pdf_foot(pdf, "Every ledger line for the month in date order. Balance counts every line; Cleared marks the lines matched to Wells. "
                   "Pending lines are planned or not yet at the bank. A bank date is shown where it differs from the ledger date.")
    return bytes(pdf.output())


def report_pdf(d: dict) -> bytes:
    """The activity report (week, month, quarter or year) as a PDF: the same sections as report_document."""
    kind, start, end = d["kind"], d["start"], d["end"]
    label = {"week": "Weekly report", "month": "Monthly report", "quarter": "Quarterly report", "year": "Annual report"}.get(kind, "Report")
    title = f"{label}: {act_label(kind, start, end)}"
    shown_end = min(end, today())
    period = (f"{fmt_date(start)}, {start.year} to {fmt_date(shown_end)}, {shown_end.year}" if start.year != shown_end.year
              else f"{fmt_date(start)} to {fmt_date(shown_end)}, {shown_end.year}") + (" (to date)" if end > today() else "")
    pdf = _pdf_doc(title)
    _pdf_head(pdf, title, [period, f"Prepared {fmt_date(today())}, {today().year}"])
    ck = d.get("checking")
    k4 = (("Checking", money(ck[1]), f"{signed(ck[1] - ck[0])} from {money(ck[0])}") if ck
          else ("Paid to the cards", money(sum(c[2] for c in d.get("cards", []))), "card payments made"))
    _pdf_kpis(pdf, [("Spent", money(d.get("gross", 0.0)), f"{d.get('n', 0)} charges"), ("Refunds and credits", money(d.get("back", 0.0)), "returned to you"),
                    ("Net spending", money(d.get("net", 0.0)), "spent less refunds"), k4])
    for n, dt_, dd in d.get("stale") or []:
        _pdf_note(pdf, f"Bank connection behind: {n} (data from {fmt_date(dt_)}, {dd} day{'s' if dd != 1 else ''} behind). "
                       "Remove that bank's connection on the SimpleFIN Bridge site and add it again.")
    nr, vr = d.get("reversed", (0, 0))
    if nr:
        _pdf_note(pdf, f"{nr} charge{'s' if nr != 1 else ''} totalling {money(vr, 2)} {'were' if nr != 1 else 'was'} refunded in full (voided tickets, returns) "
                       f"and {'are' if nr != 1 else 'is'} left out, together with the refund{'s' if nr != 1 else ''}.", _ACCENT)
    if d["unc"][0]:
        _pdf_note(pdf, f"{d['unc'][0]} line{'s' if d['unc'][0] != 1 else ''} ({money(d['unc'][1], 2)}) have no category yet; they are counted under Uncategorized.")
    groups = [(g, v) for g, v in d.get("groups", []) if abs(v) > 0.005]
    if groups:
        pos = sum(v for _g, v in groups if v > 0) or 1.0
        _pdf_h2(pdf, "Spending by group")
        _pdf_table(pdf, ["Group", "Amount", "Share"], [[g, money(v, 2), f"{(v / pos * 100) if v > 0 else 0:.0f}%"] for g, v in groups]
                   + [["Total", money(d.get("net", 0.0), 2), ""]], (300, 120, 70), ("LEFT", "RIGHT", "RIGHT"), [None] * len(groups) + ["tot"], width=490)
    if d.get("months"):
        tc, tk = sum(c for _m, c, _k in d["months"]), sum(k for _m, _c, k in d["months"])
        _pdf_h2(pdf, "Month by month")
        _pdf_table(pdf, ["Month", "Checking", "Cards", "Total"], [[MONTH_NAMES[int(m[5:]) - 1], money(c, 2), money(k, 2), money(c + k, 2)] for m, c, k in d["months"]]
                   + [["Total", money(tc, 2), money(tk, 2), money(tc + tk, 2)]], (190, 100, 100, 100), ("LEFT", "RIGHT", "RIGHT", "RIGHT"),
                   [None] * len(d["months"]) + ["tot"], width=490)
    if d.get("top"):
        _pdf_h2(pdf, "Largest items")
        _pdf_table(pdf, ["Date", "Description", "Paid from", "Category", "Amount"],
                   [[fmt_date(_dt.date.fromisoformat(dt_)), desc[:46], _card_brief(src), cat, money(amt, 2)] for dt_, desc, src, cat, amt in d["top"]],
                   (50, 190, 110, 100, 82), ("LEFT", "LEFT", "LEFT", "LEFT", "RIGHT"))
    cards = [c for c in d.get("cards", []) if c[1] or c[2]]
    if cards:
        _pdf_h2(pdf, "Credit cards")
        _pdf_table(pdf, ["Card", "Charged", "Paid to the card"], [[n, money(ch, 2) if ch else "-", money(p_, 2) if p_ else "-"] for n, ch, p_, _l in cards]
                   + [["Total", money(sum(c[1] for c in cards), 2), money(sum(c[2] for c in cards), 2)]], (250, 120, 120), ("LEFT", "RIGHT", "RIGHT"),
                   [None] * len(cards) + ["tot"], width=490)
    if d.get("register"):
        _pdf_register(pdf, d["register"], new_page=True)
    _pdf_foot(pdf, "Activity for the period only: checking and credit card spending, with transfers and card payments left out and refunds netted. "
                   + ("The register lists every checking line, transfers included; pending lines are planned or not yet at the bank. " if d.get("register") else "")
                   + "Figures come from your app's records as of the latest bank fetch. Balances, budgets and plans are on the Dashboard.")
    return bytes(pdf.output())


# ---- v25.35: ACA income evidence -- the projected year's household income (MAGI), source by source, with how each is worked out, the
# documents that support it, and a signed explanation; built from the same figures as the ACA page, for uploading to HealthCare.gov ----------
def aca_evidence(plan, entries, R) -> dict:
    """The projected income for the ACA year, as evidence: one line per source with its basis and the supporting documents."""
    y = int(R["aca_year"])
    ts = R["ts"]
    t = ts.loc[y]
    rate = plan.inputs.defcomp.withholding_rate
    lines = []

    def add(src, amount, basis, docs, counts="Yes"):
        lines.append({"source": src, "amount": float(amount), "basis": basis, "docs": docs, "counts": counts})

    rr = invest_run_rate(entries, y - 1, rate)
    base, muni = float(t.base_income), float(t.tax_exempt)
    if rr and abs(float(rr["total"]) - base) < 1.0:
        q0, q1 = rr["quarter"]
        qtxt = f"{month_short(q0)} to {month_short(q1)}"
        add("Interest, Wells Fargo savings", rr["wells_savings"], f"{month_label(rr['last_month'])} interest x 12 (the balance is being drawn down, so the latest month is used)",
            f"Wells Fargo savings statements, {qtxt}")
        if rr["wellstrade"]:
            add("Interest and dividends, WellsTrade brokerage", rr["wellstrade"], f"{qtxt} x 4", f"WellsTrade statements, {qtxt}")
        sch_taxable = float(rr["schwab"]) - muni
        add("Dividends and interest, Schwab brokerage (taxable)", sch_taxable, f"{qtxt} x 4, less the tax-exempt part below",
            f"Schwab brokerage statements, {qtxt}")
        if muni > 0.5:
            add("Tax-exempt municipal bond interest, Schwab", muni, f"{qtxt} x 4. Not taxed, but counted in income for premium tax credits",
                f"Schwab brokerage statements, {qtxt}")
    else:
        add("Interest and dividends, all accounts", base - muni, "Current yearly rate of interest and dividends", "Bank and brokerage statements")
        if muni > 0.5:
            add("Tax-exempt municipal bond interest", muni, "Counted in income for premium tax credits", "Brokerage statements")
    if float(t.defcomp) > 0.5:
        add("Deferred compensation payments", t.defcomp, f"Scheduled payments for {y}, before the {rate * 100:g}% federal withholding "
            f"({money(t.withholding)})", "Payment schedule from the plan's trustee (Northern Trust)")
    if float(t.sipp) > 0.5:
        sp = plan.meta.get("sipp") or {}
        add("UK pension (SIPP) drawdown", t.sipp, f"£{float(sp.get('gbp_month') or 0):,.0f} a month x 12 at ${float(sp.get('fx') or 1):.2f} per £",
            "Letter or statement from the SIPP provider showing the monthly payment")
    for col, src, docs in (("annuity_gain", "Annuity gain", "Annuity statement"), ("roth_conversion", "Roth conversion", "Conversion confirmation"),
                           ("rmd_target", "IRA withdrawals", "IRA statement"), ("ss_taxable", "Social Security (taxable part)", "SSA benefit letter")):
        if float(t[col]) > 0.5:
            add(src, t[col], f"Planned for {y}", docs)
    if float(t.loss_used) > 0.5:
        add("Capital loss carried forward", -float(t.loss_used), "Up to $3,000 a year against other income", "Prior-year Schedule D")
    total = round(sum(l["amount"] for l in lines), 2)
    none = [n for n, c in (("Wages or self-employment", None), ("Social Security", "ss_taxable"), ("IRA withdrawals", "rmd_target"),
                           ("Roth conversions", "roth_conversion"), ("Annuity income", "annuity_gain")) if c is None or float(t[c]) <= 0.5]
    months = []
    df = R.get("aca_df")
    if df is not None and len(df):
        months = [(int(m), float(r["value_used"])) for m, r in df.iterrows()]
    return {"year": y, "lines": lines, "total": total, "model_total": float(R["aca"]["projected_with_one_time"]), "limit": float(R["aca"]["limit"]),
            "none": none, "months": months, "withholding": float(t.withholding), "ss_start": int(plan.inputs.ss_start_year)}


def aca_evidence_settings(plan) -> dict:
    d = dict({"names": "Andrew and Estele Shooman", "app_id": "", "retired": "May 2026",
              "note": "We are both retired. Our income for the year is interest and dividends from savings and investments, scheduled deferred "
                      "compensation payments from a former employer, and a small UK pension. It is lower than our last tax return, which "
                      "included wages from employment that ended on retirement."}, **(plan.meta.get("aca_evidence") or {}))
    return d


def aca_evidence_pdf(ev: dict, cfg: dict, attached: list | None = None) -> bytes:
    y = ev["year"]
    title = f"Projected {y} household income"
    pdf = _pdf_doc(f"{cfg['names']} · {title}" + (f" · Application ID {cfg['app_id']}" if cfg.get("app_id") else ""))
    _pdf_head(pdf, title, [cfg["names"], f"Married, filing jointly · household of 2",
                           f"Application ID: {cfg['app_id']}" if cfg.get("app_id") else "Application ID: ________________",
                           f"Prepared {fmt_date(today())}, {today().year}"])
    _pdf_kpis(pdf, [("Projected income", money(ev["total"]), f"{y}, all sources"), ("Monthly average", money(ev["total"] / 12), "spread over 12 months"),
                    ("Wages", "None", f"retired {cfg.get('retired') or ''}".strip()), ("Social Security", "None" if "Social Security" in ev["none"] else "See below",
                                                                                     f"starts {ev.get('ss_start')}" if "Social Security" in ev["none"] else "")])
    _pdf_h2(pdf, "Income by source")
    rows = [[l["source"], money(l["amount"], 0), l["basis"]] for l in ev["lines"]] + [["Total household income", money(ev["total"], 0), "Modified adjusted gross income for the year"]]
    _pdf_table(pdf, ["Source", "Amount", "How it is worked out"], rows, (190, 70, 272), ("LEFT", "RIGHT", "LEFT"), [None] * len(ev["lines"]) + ["tot"])
    if ev["none"]:
        pdf.set_font("Helvetica", "", 8.5)
        pdf.set_text_color(*_INK)
        pdf.multi_cell(0, 12, _pt(f"No income expected in {y} from: " + ", ".join(ev["none"]) + "."), new_x="LMARGIN", new_y="NEXT")
        pdf.ln(4)
    if ev["months"]:
        _pdf_h2(pdf, "Expected by month")
        rows = [[MONTH_NAMES[m - 1], money(v, 0)] for m, v in ev["months"]] + [["Year", money(sum(v for _m, v in ev["months"]), 0)]]
        _pdf_table(pdf, ["Month", "Income"], rows, (120, 90), ("LEFT", "RIGHT"), [None] * len(ev["months"]) + ["tot"], width=210, size=8)
        pdf.set_font("Helvetica", "", 7.5)
        pdf.set_text_color(*_MUTED)
        pdf.multi_cell(0, 10, _pt("Larger months are the quarterly fund dividends (March, June, September, December)."), new_x="LMARGIN", new_y="NEXT")
    _pdf_h2(pdf, "Supporting documents attached", new_page=True)
    seen, docs = set(), []
    for l in ev["lines"]:
        if l["docs"] not in seen:
            seen.add(l["docs"]); docs.append((l["docs"], l["source"]))
    _pdf_table(pdf, ["Document", "Supports"], [[d, s] for d, s in docs], (280, 252), ("LEFT", "LEFT"))
    if attached:                                                       # v25.36: the copies merged in after these pages
        pdf.set_font("Helvetica", "B", 9)
        pdf.set_text_color(*_INK)
        pdf.cell(0, 14, _pt(f"Attached after this page ({len(attached)}):"), new_x="LMARGIN", new_y="NEXT")
        pdf.set_font("Helvetica", "", 8.5)
        for i, nm in enumerate(attached, 1):
            pdf.cell(0, 12, _pt(f"{i}. {nm}"), new_x="LMARGIN", new_y="NEXT")
        pdf.ln(4)
    _pdf_h2(pdf, "Letter of explanation")
    pdf.set_font("Helvetica", "", 9.5)
    pdf.set_text_color(*_INK)
    pdf.multi_cell(0, 14, _pt(f"We expect our household income for {y} to be {money(ev['total'])}. {cfg.get('note') or ''} "
                              "The figures above are based on our current account statements, the deferred compensation payment schedule and "
                              "the UK pension payment, and are our best estimate for the year. We will update our application if our income changes."),
                   new_x="LMARGIN", new_y="NEXT")
    pdf.ln(26)
    w = pdf.w - pdf.l_margin - pdf.r_margin
    names = [n.strip() for n in str(cfg["names"]).replace(" and ", ",").split(",") if n.strip()]
    if len(names) == 2 and len(names[1].split()) > 1 and len(names[0].split()) == 1:
        names[0] = names[0] + " " + names[1].split()[-1]              # "Andrew and Estele Shooman" -> Andrew Shooman, Estele Shooman
    pdf.set_draw_color(*_INK)
    y0 = pdf.get_y()
    for i, nm in enumerate(names[:2] or ["Signature"]):
        x0 = pdf.l_margin + i * (w / 2)
        pdf.line(x0, y0, x0 + w / 2 - 30, y0)
        pdf.set_xy(x0, y0 + 2)
        pdf.set_font("Helvetica", "", 8)
        pdf.set_text_color(*_MUTED)
        pdf.cell(w / 2 - 30, 10, _pt(f"{nm}    Date"))
    pdf.set_y(pdf.get_y() + 30)
    _pdf_foot(pdf, "Income here is modified adjusted gross income as the Marketplace uses it: adjusted gross income plus tax-exempt interest. "
                   + ("Copies of the documents listed are attached after these pages." if attached else "Copies of the documents listed are attached."))
    return bytes(pdf.output())


def merge_documents(first: bytes, docs: list) -> tuple[bytes, list]:
    """v25.36: one PDF: `first`, then each (name, bytes) document -- a PDF's pages as they are, a photo or scan (JPG, PNG) on a page of its own.
    Returns the PDF and the names that could not be added (another file type, or a PDF that will not open)."""
    import io as _io
    from pypdf import PdfReader, PdfWriter
    w = PdfWriter()
    w.append(PdfReader(_io.BytesIO(first)))
    skipped = []
    for name, data in docs:
        low = name.lower()
        try:
            if low.endswith(".pdf") or data[:5] == b"%PDF-":
                r = PdfReader(_io.BytesIO(data))
                if r.is_encrypted:
                    r.decrypt("")
                w.append(r)
            elif low.endswith((".png", ".jpg", ".jpeg")):
                from fpdf import FPDF
                im = FPDF(format="letter", unit="pt")
                im.set_auto_page_break(False)
                im.add_page()
                im.image(_io.BytesIO(data), x=24, y=24, w=im.w - 48, keep_aspect_ratio=True, h=im.h - 48)
                w.append(PdfReader(_io.BytesIO(bytes(im.output()))))
            else:
                skipped.append(f"{name} (not a PDF or picture)")
        except Exception as e:  # noqa: BLE001 - one bad file should not stop the rest
            skipped.append(f"{name} ({type(e).__name__})")
    out = _io.BytesIO()
    w.write(out)
    return out.getvalue(), skipped


def _aca_doc_choices(entries: dict, y: int) -> list:
    """Stored documents that could back up the income: this year's and last year's, still in storage."""
    out = []
    for yr in (y - 1, y):
        for f in docs_index(entries, yr):
            if not f.get("gone"):
                out.append(dict(f, year=yr))
    return out


def _rep_aca():
    """v25.35: the ACA income evidence package."""
    ss = st.session_state
    R = model()
    ev = aca_evidence(ss.plan, ss.entries, R)
    cfg = aca_evidence_settings(ss.plan)
    st.title(f"ACA income evidence, {ev['year']}")
    caption("Your projected income for the year, source by source, with how each figure is worked out, the documents that back it up and a "
            "letter of explanation to sign. Upload it to HealthCare.gov with the documents listed, if the Marketplace asks you to confirm your income.")
    if abs(ev["total"] - ev["model_total"]) > 1.0:
        st.warning(_esc(f"The sources add to {money(ev['total'])}, but the ACA page shows {money(ev['model_total'])}: check the one-time items on the ACA page."))
    m = st.columns(3)
    m[0].metric("Projected income", money(ev["total"]))
    m[1].metric("Subsidy limit", money(ev["limit"]))
    m[2].metric("Room under it", money(ev["limit"] - ev["total"]))
    dv = ss.data_ver

    def _set(k, key):
        d = dict(ss.plan.meta.get("aca_evidence") or {})
        d[k] = ss[key]
        ss.plan.meta["aca_evidence"] = d
    c1, c2, c3 = st.columns([2, 1.3, 1])
    c1.text_input("Names", value=cfg["names"], key=f"aev_n_{dv}", on_change=_set, args=("names", f"aev_n_{dv}"))
    c2.text_input("Application ID (from HealthCare.gov)", value=cfg["app_id"], key=f"aev_id_{dv}", on_change=_set, args=("app_id", f"aev_id_{dv}"))
    c3.text_input("Retired", value=cfg["retired"], key=f"aev_r_{dv}", on_change=_set, args=("retired", f"aev_r_{dv}"))
    st.text_area("Your explanation (goes in the letter)", value=cfg["note"], key=f"aev_note_{dv}", height=90, on_change=_set, args=("note", f"aev_note_{dv}"))
    cfg = aca_evidence_settings(ss.plan)
    st.subheader("Statements to attach")
    choices = _aca_doc_choices(ss.entries, ev["year"])
    chosen = []
    if docs_cfg() is None:
        caption("Your stored documents are in your private GitHub repository, which this copy is not connected to.")
    elif not choices:
        caption("No documents stored yet. Add the statements on Reporting, Tax documents, and they can be attached here.")
    else:
        default = [f["id"] for f in choices if f.get("cat") in (DOC_STATEMENTS, DOC_OTHER)]
        ids = st.multiselect("Attach these, in this order, after the summary", [f["id"] for f in choices], default=default, key=f"aev_docs_{dv}",
                             format_func=lambda i: next(f"{f['name']} ({f['year']})" for f in choices if f["id"] == i))
        chosen = [f for i in ids for f in choices if f["id"] == i]
    if not pdf_available():
        st.warning("PDF printing is not installed yet (add fpdf2 to the cloud requirements.txt).")
    else:
        key = ("aev_pkg", tuple(f["id"] for f in chosen), json.dumps(cfg, sort_keys=True), round(ev["total"], 2))
        pkg = ss.get("aev_pkg") if ss.get("aev_pkg_key") == key else None
        if chosen and pkg is None:
            if st.button(f"Build the package with {len(chosen)} document{'s' if len(chosen) != 1 else ''}", key=f"aev_build_{dv}", type="primary"):
                got, missing = [], []
                with st.spinner("Collecting your documents..."):
                    for f in chosen:
                        try:
                            got.append((f["name"], blob_get(docs_cfg(), f["path"])))
                        except Exception as e:  # noqa: BLE001
                            missing.append(f"{f['name']} ({type(e).__name__})")
                    try:
                        _probe, skipped = merge_documents(aca_evidence_pdf(ev, cfg), got)          # which ones go in
                        bad = {x.rsplit(" (", 1)[0] for x in skipped}
                        got = [(n, d_) for n, d_ in got if n not in bad]
                        merged, _s = merge_documents(aca_evidence_pdf(ev, cfg, [n for n, _d in got]), got)
                        ss.aev_pkg, ss.aev_pkg_key = {"pdf": merged, "skipped": missing + skipped, "n": len(got)}, key
                    except ImportError:
                        st.warning("Joining PDFs is not installed yet (add pypdf to the cloud requirements.txt).")
                    except Exception as e:  # noqa: BLE001
                        st.warning(f"The package could not be made ({type(e).__name__}: {str(e)[:120]}).")
                st.rerun()
        elif pkg is not None:
            _pdf_share_button(pkg["pdf"], f"aca_income_{ev['year']}.pdf")
            caption(f"One PDF: the summary and letter, then {pkg['n']} attached document{'s' if pkg['n'] != 1 else ''}. On the iPad, Print (PDF) "
                    "opens the Share sheet, where you can save it to Files for uploading. On Windows it downloads the PDF.")
            if pkg["skipped"]:
                st.warning(_esc("Not attached: " + "; ".join(pkg["skipped"])))
        else:
            try:
                _pdf_share_button(aca_evidence_pdf(ev, cfg), f"aca_income_{ev['year']}.pdf")
                caption("The summary and letter only. Pick statements above to attach them.")
            except Exception as e:  # noqa: BLE001
                st.warning(f"The PDF could not be made ({str(e)[:120]}).")
    df = pd.DataFrame([{"Source": l["source"], "Amount": l["amount"], "How it is worked out": l["basis"], "Document": l["docs"]} for l in ev["lines"]])
    st.dataframe(df, hide_index=True, column_config={"Amount": st.column_config.NumberColumn(format="dollar")})
    st.subheader("The documents the summary lists")
    for d in dict.fromkeys(l["docs"] for l in ev["lines"]):
        st.markdown("- " + _esc(d))
    caption("Upload in your HealthCare.gov account: Application details, Upload documents. Send copies, never originals, and put your name and "
            "application ID on each page. The Marketplace's own one-page Annual Income Letter of Explanation form can go with it.")


ACT_KINDS = {"week": ("Weekly report", "week"), "month": ("Monthly report", "month"), "quarter": ("Quarterly report", "quarter"), "year": ("Annual report", "year")}


def act_label(kind, start, end) -> str:
    if kind == "week":
        return f"{fmt_date(start)} to {fmt_date(end)}"
    if kind == "month":
        return month_short(start.strftime("%Y-%m"))
    if kind == "quarter":
        return f"Q{(start.month - 1) // 3 + 1} {start.year}"
    return str(start.year)


def act_periods(kind) -> list:
    """The periods a report can cover, newest first, as (label, (start, end)). Weeks run Saturday to Friday, like the email."""
    t = today()
    first = _dt.date(2026, 1, 1)
    out = []
    if kind == "week":
        end = t - _dt.timedelta(days=(t.weekday() - 4) % 7)          # the latest Friday, today included
        while end >= first and len(out) < 52:
            out.append((end - _dt.timedelta(days=6), end))
            end -= _dt.timedelta(days=7)
    elif kind == "month":
        y, m = t.year, t.month
        while _dt.date(y, m, 1) >= first:
            nxt = _dt.date(y + (m == 12), m % 12 + 1, 1)
            out.append((_dt.date(y, m, 1), nxt - _dt.timedelta(days=1)))
            y, m = (y, m - 1) if m > 1 else (y - 1, 12)
    elif kind == "quarter":
        y, q = t.year, (t.month - 1) // 3
        while _dt.date(y, q * 3 + 1, 1) >= first:
            st_ = _dt.date(y, q * 3 + 1, 1)
            nxt = _dt.date(y + (q == 3), (q * 3 + 3) % 12 + 1, 1)
            out.append((st_, nxt - _dt.timedelta(days=1)))
            y, q = (y, q - 1) if q > 0 else (y - 1, 3)
    else:
        for y in range(t.year, first.year - 1, -1):
            out.append((_dt.date(y, 1, 1), _dt.date(y, 12, 31)))
    return [(act_label(kind, a, b) + (" (so far)" if b >= t else ""), (a, b)) for a, b in out]


def _rep_activity(kind):
    """v25.14: one activity report on screen in report layout, with Print and Download."""
    ss = st.session_state
    label, word = ACT_KINDS[kind]
    st.title(label)
    opts = act_periods(kind)
    i = st.selectbox(word.capitalize(), range(len(opts)), format_func=lambda j: opts[j][0], key=f"rep_act_{kind}_{ss.data_ver}")
    start, end = opts[i][1]
    d = activity_report(start, end, kind)["data"]
    _print_pdf_button(lambda: report_pdf(d), lambda: report_document(d, print_button=False),
                      f"{label.lower().replace(' ', '_')}_{start.isoformat()}", f"rep_dl_{kind}_{i}")
    doc = report_document(d, print_button=False)
    n = doc.count("<tr") + doc.count("class='note'")
    _html_frame(doc, height=min(5000, 420 + 33 * n))


def _pdf_share_button(data: bytes, filename: str):
    """v25.28: a Print button that never leaves the app. On the iPad (run from the Home Screen, a download took over the whole window
    with no way back) it opens the iPad's Share sheet with the PDF, which has Print. The button lives in a frame that may not use the
    Share sheet itself, so it asks the app page around it (same site) to. Elsewhere, or if sharing is refused, it downloads the PDF."""
    import base64 as _b64m
    b64 = _b64m.b64encode(data).decode("ascii")
    fn = _json.dumps(filename)
    _html_frame(
        "<style>body{margin:0;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif}"
        "button{font:600 15px -apple-system,'Segoe UI',Helvetica,Arial,sans-serif;padding:9px 18px;border:0;border-radius:8px;"
        "background:#2f6fa8;color:#fff;cursor:pointer}#m{font-size:12px;color:#6b7785;margin-left:10px}</style>"
        "<button id='b'>Print (PDF)</button><span id='m'></span><script>"
        f"var B64='{b64}',FN={fn};"
        "function blob(){var s=atob(B64),a=new Uint8Array(s.length);for(var i=0;i<s.length;i++)a[i]=s.charCodeAt(i);"
        "return new Blob([a],{type:'application/pdf'})}"
        "function dl(){var u=URL.createObjectURL(blob()),l=document.createElement('a');l.href=u;l.download=FN;document.body.appendChild(l);"
        "l.click();setTimeout(function(){URL.revokeObjectURL(u);l.remove()},4000)}"
        "function ios(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)}"
        "document.getElementById('b').onclick=function(){var m=document.getElementById('m');m.textContent='';"
        "if(!ios()){dl();return}"
        "var nav=null;try{nav=window.parent.navigator}catch(e){}if(!nav||!nav.share){nav=navigator}"
        "var f=new File([blob()],FN,{type:'application/pdf'});"
        "if(!nav.share||(nav.canShare&&!nav.canShare({files:[f]}))){m.textContent='Sharing is not available here.';return}"
        "nav.share({files:[f]}).catch(function(e){if(e&&e.name!=='AbortError'){m.textContent='Could not open the Share sheet ('+e.name+').'}})};"
        "</script>", height=48)


def _print_pdf_button(make_pdf, make_html, base: str, key: str):
    """v25.28: Print as a PDF download -- it opens in Safari (or Edge on Windows) with Print in the Share menu. Without fpdf2 installed,
    the page itself is offered instead."""
    if pdf_available():
        try:
            _pdf_share_button(make_pdf(), f"{base}.pdf")
            caption("On the iPad, Print opens the Share sheet over the app: tap Print there. Close the sheet and you are back here. "
                    "On Windows it downloads the PDF; open it and print.")
            return
        except Exception as e:  # noqa: BLE001 - fall back to the page
            st.warning(f"The PDF could not be made ({str(e)[:120]}). Here is the page instead.")
    else:
        st.warning("PDF printing is not installed yet (add fpdf2 to the cloud requirements.txt). Here is the page instead.")
    st.download_button("Download to print or share", make_html().encode("utf-8"), file_name=f"{base}.html", mime="text/html", key=key + "_html")


def _rep_register():
    """v25.28: one month's reconciliation register on screen in report layout, with Print and Download."""
    ss = st.session_state
    st.title("Reconciliation register")
    cur, _m = current_month_key()
    keys = sorted((k for k, rows in ss.entries["ledger"].items() if rows and k <= cur), reverse=True)
    if not keys:
        st.info("No transactions yet.")
        return
    want = ss.pop("reg_month_next", None) or cur
    i = st.selectbox("Month", range(len(keys)), index=keys.index(want) if want in keys else 0, format_func=lambda j: month_label(keys[j]),
                     key=f"rep_reg_m_{ss.data_ver}")
    reg = register_for(keys[i])
    _print_pdf_button(lambda: register_pdf(reg), lambda: register_document(reg, print_button=False),
                      f"reconciliation_register_{keys[i]}", f"rep_reg_dl_{keys[i]}")
    caption("The Monthly report ends with the same register.")
    doc = register_document(reg, print_button=False)
    _html_frame(doc, height=min(6000, 560 + 31 * doc.count("<tr")))


