def _rep_cpa():
    """The CPA package (the first Reporting page)."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    st.title("CPA package")
    caption("One package for your CPA: a workbook and every document for a tax year.")
    R = model()
    years = list(range(2026, 2043))
    dflt = min(max(today().year if today().month >= 5 else today().year - 1, 2026), 2042)
    y = st.selectbox("Tax year", years, index=years.index(dflt), key=f"rep_year_{ss.data_ver}")
    chores = year_chores(plan, entries, R, y, _ye_checks(plan, entries, y))
    labels = _doc_labels(tax_documents(plan, R, y))
    ddf = docs_sheet(entries, y, labels)

    def sheets_fn(df):
        return cpa_package(plan, entries, R, y, ACCOUNT_LABELS, chores, today().isoformat(), docs_df=df)
    sheets = sheets_fn(ddf)
    st.markdown("**What is in it:** " + ", ".join(n for n, _ in sheets) + ".")
    files = docs_index(entries, y)
    live = [f for f in files if not f.get("gone")]
    arch = docs_archived(entries, y)
    with st.container(border=True, key=f"rep_pkg_{y}"):
        st.markdown("**The whole package**")
        if arch:
            caption(f"{y} was archived on {arch}. The documents were removed from the app; the workbook below still has the list of what was sent.")
        else:
            caption(f"The workbook plus {len(live)} stored document{'s' if len(live) != 1 else ''} ({docs_total_bytes(entries, y) / 1048576:.1f} MB), sorted into folders, in one zip. "
                    f"Add documents with the Tax documents tile.")
        if docs_cfg() is not None and (live or not arch):
            if st.button(f"Build the {y} package", key=f"rep_build_{y}", type="primary"):
                with st.spinner("Building the package..."):
                    ss[f"cpa_pkg_{y}"] = _build_package(plan, entries, R, y, chores, sheets_fn)
        pkg = ss.get(f"cpa_pkg_{y}")
        if pkg:
            data, n, missing = pkg
            if missing:
                st.warning("Some documents could not be found in storage and are left out: " + ", ".join(missing))
            st.download_button(f"Download CPA_package_{y}.zip ({len(data) / 1048576:.1f} MB, {n} document{'s' if n != 1 else ''})", data, file_name=f"CPA_package_{y}.zip",
                               mime="application/zip", key=f"rep_dlzip_{y}")
        try:
            st.download_button(f"Just the workbook (Excel), without documents", cpa_xlsx(sheets), file_name=f"CPA_package_{y}.xlsx",
                               mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", key=f"rep_dl_{y}")
        except ImportError:
            st.warning("Excel support is not installed yet (add openpyxl to the cloud requirements.txt). Here is the same information as a zip of CSV files.")
            st.download_button(f"Just the workbook (CSV zip)", cpa_zip(sheets), file_name=f"CPA_workbook_{y}_csv.zip", mime="application/zip", key=f"rep_zip_{y}")
    if live and not arch:
        with st.expander(f"Archive {y}"):
            caption(f"When {y} is done and sent, archiving removes its documents from the app so the storage stays small. Build the package, save the zip somewhere safe first: "
                    f"after archiving the files can only be recovered from that zip. The list of documents stays here. "
                    f"Note that the private repository's history keeps earlier copies, so this keeps the working copy small rather than erasing the files.")
            ok = st.checkbox(f"I have downloaded and saved the {y} zip", key=f"rep_arch_ok_{y}", disabled=not ss.get(f"cpa_pkg_{y}"))
            st.button(f"Archive {y}", key=f"rep_arch_{y}", disabled=not ok, on_click=_archive_year, args=(y, ok))
    if ss.get("doc_msg") and arch:
        st.success(ss.doc_msg)
    caption("Figures come from your plan and ledger as recorded here. This is a summary to help your CPA, not tax advice or a filed return.")
    st.dataframe(sheets[0][1], hide_index=True, use_container_width=True)


def _rep_docs():
    """Upload tax documents: the same store as Year end > Tax documents, with the year's checklist progress."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    st.title("Tax documents")
    R = model()
    years = list(range(2026, 2043))
    dflt = min(max(today().year if today().month >= 5 else today().year - 1, 2026), 2042)
    y = st.selectbox("Tax year", years, index=years.index(dflt), key=f"rep_docs_year_{ss.data_ver}")
    docs = tax_documents(plan, R, y)
    rows = [{"Document": d["label"], "Status": doc_state(entries, y, d["id"])["status"], "When": d["when"]} for d in docs]
    dp = docs_progress(entries, docs, y)
    write(f"**{dp['received']} of {dp['needed']}** expected documents received for {y}.")
    st.dataframe(pd.DataFrame(rows), hide_index=True)
    caption("Adding a file under a checklist item below marks it Received. To mark one Not needed, use Year end > Tax documents.")
    _docs_store(plan, entries, R, y, docs)


def _rep_taxpaid():
    """What has been paid toward a tax year: estimated payments, withholding, and the payments seen at the bank."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    st.title("Tax payments")
    caption("What has actually been paid toward a year's federal tax. Planning the payments stays on the Tax payments page.")
    R = model()
    years = list(range(2026, min(today().year + 1, 2042) + 1))
    y = st.selectbox("Tax year", years, index=years.index(min(today().year, years[-1])), key=f"rep_tp_year_{ss.data_ver}")
    tp = tax_paid_report(plan, entries, R, y)
    s = tp["summary"]
    m = st.columns(4)
    m[0].metric(f"Estimated payments made ({s['n_paid']} of {s['n']})" if s["n"] else "Estimated payments made", money(s["paid"]))
    m[1].metric("Withheld from deferred comp", money(tp["withheld"]))
    m[2].metric(f"Paid toward {y}", money(tp["paid_total"]))
    m[3].metric("Estimated still to pay", money(s["unpaid"]))
    st.subheader("Estimated payments")
    sched = pd.DataFrame([{"Payment": r["label"], "Due": fmt_date(_dt.date.fromisoformat(r["due"])) + f", {r['due'][:4]}", "Amount": money(float(r["amount"]), 2),
                           "Paid": (("Paid " + fmt_date(_dt.date.fromisoformat(r["paid_on"]))) if r.get("paid_on") else "Paid") if r.get("paid") else "Not yet",
                           "Amount set by": r.get("source", "")} for r in tp["schedule"]])
    if len(sched):
        st.dataframe(sched, hide_index=True)
    else:
        st.info(f"No estimated payments set for {y}.")
    caption(f"The fourth payment for {y} is due in January {y + 1}. Mark payments paid, or change them, on the Tax payments page.")
    st.button("Tax payments page ›", key="rep_tp_go", on_click=goto_tax, args=("sched",))
    st.subheader("Withholding on deferred comp")
    if tp["withholding"]:
        wdf = pd.DataFrame(tp["withholding"])
        tot = {"Month": "Total", **{c: float(wdf[c].sum()) for c in ("Deferred comp, gross", "Withheld", "Deposited")}}
        wdf = pd.concat([wdf, pd.DataFrame([tot])], ignore_index=True)
        st.markdown(html_table(wdf, money_cols=("Deferred comp, gross", "Withheld", "Deposited"), bold_last=True), unsafe_allow_html=True)
        caption(f"From reconciled DefComp deposits, grossed up at the {plan.inputs.defcomp.withholding_rate:.0%} federal withholding rate.")
    else:
        caption(f"No reconciled deferred comp deposits in {y}.")
    st.subheader(f"Tax payments seen at the bank in {y}")
    if tp["bank"]:
        bdf = pd.DataFrame([{"Date": i["date"], "Account": i["src"], "Description": i["desc"], "Amount": i["amount"]} for i in sorted(tp["bank"], key=lambda i: i["date"])])
        bdf = pd.concat([bdf, pd.DataFrame([{"Date": "Total", "Account": "", "Description": "", "Amount": float(bdf["Amount"].sum())}])], ignore_index=True)
        st.markdown(html_table(bdf, money_cols=("Amount",), bold_last=True), unsafe_allow_html=True)
        caption("Lines filed under Income tax payments (IRS and state), by the date they left the account. A January payment usually belongs to the year before.")
    else:
        caption(f"No lines filed under Income tax payments in {y}. Payments to the IRS are filed there automatically; others can be moved there from All spending.")
    out = pd.concat([sched.assign(Section="Estimated payments") if len(sched) else pd.DataFrame(),
                     pd.DataFrame(tp["withholding"]).assign(Section="Withholding") if tp["withholding"] else pd.DataFrame(),
                     pd.DataFrame([{"Date": i["date"], "Description": i["desc"], "Amount": i["amount"]} for i in tp["bank"]]).assign(Section="Bank") if tp["bank"] else pd.DataFrame()],
                    ignore_index=True)
    if len(out):
        st.download_button("Download (CSV)", out.to_csv(index=False), file_name=f"tax payments {y}.csv", mime="text/csv", key=f"rep_tp_dl_{y}")


def _rep_month_chart(its: list[dict], y: int, key: str):
    """Month-by-month bars for one tile: a single series, so one colour and no legend; hover shows the month and amount."""
    mt = [0.0] * 12
    for i in its:
        mt[int(i["month"][5:7]) - 1] += i["amount"]
    last = today().month if y == today().year else 12
    xs = [MONTH_NAMES[m][:3] for m in range(last)]
    fig = go.Figure(go.Bar(x=xs, y=mt[:last], marker_color=NAVY, hovertemplate="%{x}: $%{y:,.0f}<extra></extra>"))
    fig.update_layout(bargap=0.35, showlegend=False)
    _plotly(style(fig, 220, legend=False), key=key)


def _rep_tile(name: str):
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    years = _rep_spend_years()
    y0 = _rep_year_default() if _rep_year_default() in years else today().year
    st.title(name)
    y = st.selectbox("Year", years, index=years.index(y0), key=f"rep_tile_year_{name}")
    ss.rep_year_val = y
    for m in range(1, 13):
        rows = entries["ledger"].get(f"{y}-{m:02d}") or []
        if any(not r.get("id") for r in rows):
            ensure_ids(rows)
    if ss.get("ru_msg"):
        st.success(ss.ru_msg)
        try:
            st.toast(ss.ru_msg, icon="✅")          # also a floating note, seen wherever the page is scrolled (on the iPad the banner above can be off screen)
        except Exception:  # noqa: BLE001
            pass
        ss.ru_msg = ""
    items = spending_items(plan, entries, y)
    CR = category_rollup(plan, items)
    tn = _rep_tile_numbers(plan, items, CR, name)
    if not tn["items"]:
        st.info(f"Nothing in {name} for {y}.")
        return
    n_months = today().month if y == today().year else 12
    share = tn["total"] / CR["spending_total"] if CR["spending_total"] else 0.0
    m = st.columns(3)
    m[0].metric(f"{name}, {y}", money(tn["total"]))
    m[1].metric("A month, on average", money(tn["total"] / n_months))
    m[2].metric("Share of all spending", f"{share:.0%}")
    _rep_month_chart(tn["items"], y, f"rep_ch_{_slug(name)}_{y}")
    if tn["group"]:
        st.subheader("Categories")
        _rollup_table(tn["parts"], f"rep_gc_{_slug(name)}_{y}", "Category")
        cats = list(tn["parts"]["Description"])
        c = st.selectbox("Look inside a category", cats, key=f"rep_gcat_{_slug(name)}_{y}")
        its = [i for i in tn["items"] if i["cat"] == c]
    else:
        c, its = name, tn["items"]
    st.subheader(f"{c}: by merchant")
    _rollup_table(items_frame(its, lambda i: merchant_key(i["desc"]) or i["desc"]), f"rep_mer_{_slug(c)}_{y}", "Merchant")
    st.subheader(f"{c}: every line")
    _ru_lines_editor(its, f"rep_{_slug(c)}_{y}")


def aca_years(R):
    """v21.56: planned MAGI for the subsidy years against the limit."""
    ts, limits, warn = R["ts"], R["limits"], R["warning"]
    ys = list(range(2027, 2034))
    magi = [float(ts.loc[y, "total_magi"]) for y in ys]
    lim = [limits[y] for y in ys]
    cols = [BRICK if v > l else (AMBER if v > warn else NAVY) for v, l in zip(magi, lim)]
    cap = max(lim[0] * 1.7, 140000)
    fig = go.Figure(go.Bar(x=[str(y) for y in ys], y=[min(v, cap) for v in magi], marker_color=cols, name="Planned MAGI",
                           customdata=magi, hovertemplate="%{x}: $%{customdata:,.0f}<extra></extra>"))
    fig.add_trace(go.Scatter(x=[str(y) for y in ys], y=lim, mode="lines", line=dict(color=BRASS, width=2), name="Subsidy limit"))
    fig.add_trace(go.Scatter(x=[str(y) for y in ys], y=[warn] * len(ys), mode="lines", line=dict(color=BRASS, dash="dot"), name="Early-warning line"))
    fig.update_yaxes(range=[0, cap * 1.05])
    caption("Planned MAGI each year against the subsidy limit. Subsidies apply only while you are on Marketplace coverage. Bars above the chart are "
               "cut off; hover to see the full figure.")
    _plotly(style(fig, 300), key="c_aca_year")


def aca_this_year(R):
    """v21.56: this year's projected MAGI (the gauge) and its running total month by month."""
    card_aca(R)
    m, w = R["aca"], R["window"]
    df = R["aca_df"]
    st.subheader(f"{R['aca_year']} month by month")
    caption("Running MAGI. A month counts as actual only when you mark it finalized; every other month uses the plan.")
    fig2 = go.Figure(go.Bar(x=[MONTH_NAMES[i - 1][:3] for i in df.index], y=df.running_magi,
                            marker_color=[NAVY if b == "ACTUAL" else SOFT for b in df.basis], name="Running MAGI"))
    fig2.add_trace(go.Scatter(x=[MONTH_NAMES[i - 1][:3] for i in df.index], y=[m["limit"]] * 12, mode="lines", line=dict(color=BRASS), name="Limit"))
    fig2.add_trace(go.Scatter(x=[MONTH_NAMES[i - 1][:3] for i in df.index], y=[m["warning_target"]] * 12, mode="lines", line=dict(color=BRASS, dash="dot"), name="Early warning"))
    _plotly(style(fig2, 280), key="c_aca_month")


def aca_window(R):
    """v21.56: how the year-end conversion window is built."""
    m, w = R["aca"], R["window"]
    rows = [("Subsidy limit", w["limit"]), ("Less your buffer", -w["buffer"]), ("Conversion ceiling", w["conversion_ceiling"]),
            ("Less finalized months", -w["ytd_finalized"]), ("Less plan for remaining months", -w["remaining_forecast"]),
            ("Less one-time items expected", -w["one_time_items"])] + ([("Plus capital loss carried over", -w["year_adjust"])] if w.get("year_adjust") else []) + [
            ("Room to convert this year", w["capacity"])]
    table(pd.DataFrame(rows, columns=["Step", "Amount"]), money_cols=["Amount"])
    caption("Zero conversion stays the plan in subsidy years. This figure is information only, and it is only as good as the months you have finalized.")


def cb_inv_estimate(year: int, key: str, months: list):
    ss = st.session_state
    v = ss.get(key)
    est = ss.entries.setdefault("invest_income_est", {})
    if v is None or v <= 0:
        est.pop(str(year), None)
    else:
        est[str(year)] = {"amount": float(v), "months": list(months), "note": "Entered on the ACA page"}


def cb_inv_estimate_clear(year: int):
    st.session_state.entries.setdefault("invest_income_est", {}).pop(str(year), None)
    st.session_state.data_ver += 1


def cb_inv_save(year: int, key: str, months: list):
    """Saves corrections made in the statement table (only the months that were already in it)."""
    ss = st.session_state
    ed = ss.get(f"{key}_df")
    if ed is None:
        return
    inv = ss.entries.setdefault("invest_income", {})
    for i, mk in enumerate(months):
        r = dict(inv.get(mk) or {})
        for f, col in [("wells", "Wells savings"), ("wellstrade", "WellsTrade"), ("schwab", "Schwab"), ("muni", "Of which muni"), ("qtr", "Of which quarterly")]:
            v = ed.iloc[i][col]
            r[f] = 0.0 if v is None or pd.isna(v) else round(float(v), 2)
        inv[mk] = r
    ss.data_ver += 1


def cb_sipp_loss(key: str, section: str, name: str, kind=float):
    ss = st.session_state
    v = ss.get(key)
    d = dict(ss.plan.meta.get(section) or {})
    d[name] = kind(v) if v is not None else (0 if kind is int else 0.0)
    ss.plan.meta[section] = d


def sipp_loss_editor(plan):
    """v21.16: the two MAGI items that are not investment income or deferred comp: the SIPP drawdown and a capital loss carried forward."""
    ss = st.session_state
    sp, lc = plan.meta.get("sipp") or {}, plan.meta.get("loss_carryover") or {}
    with st.expander("SIPP and capital loss carried over"):
        c = st.columns(3)
        for col, (label, sec, name, val, step, fmt, kind) in zip(c, [
                ("SIPP, pounds a month", "sipp", "gbp_month", float(sp.get("gbp_month") or 0.0), 10.0, "%.0f", float),
                ("Dollars per pound", "sipp", "fx", float(sp.get("fx") or 1.0), 0.01, "%.2f", float),
                ("Last year paid (0 = every year)", "sipp", "last_year", int(sp.get("last_year") or 0), 1, "%d", int)]):
            k = f"sl_{sec}_{name}_{ss.data_ver}"
            col.number_input(label, value=val, min_value=0 if kind is int else 0.0, step=step, format=fmt, key=k, on_change=cb_sipp_loss, args=(k, sec, name, kind))
        c = st.columns(3)
        for col, (label, name, val, step, fmt, kind) in zip(c, [
                ("Capital loss carried over", "amount", float(lc.get("amount") or 0.0), 10.0, "%.2f", float),
                ("Into the year", "year", int(lc.get("year") or FIRST_YEAR), 1, "%d", int)]):
            k = f"sl_loss_{name}_{ss.data_ver}"
            col.number_input(label, value=val, min_value=0 if kind is int else 0.0, step=step, format=fmt, key=k,
                             on_change=cb_sipp_loss, args=(k, "loss_carryover", name, kind))
        caption("The SIPP is paid every month at a fixed amount in pounds and counts in MAGI and the tax estimate. A carried-over loss comes off "
                f"other income at up to {money(CAP_LOSS_LIMIT)} a year until used up; it is never in a month's entries, so the ACA monitor applies it to the whole year.")


def section_invest_income(R, part="all"):
    """v21.16: the year's interest and dividends by month and account, what it gives as the next year's base, and the checks.
    v21.56: part="table" draws the year's table, the estimate and the corrections; part="next" what it gives next year and the checks."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    rate = plan.inputs.defcomp.withholding_rate
    years = sorted({int(str(k)[:4]) for k in (entries.get("invest_income") or {})})
    if not years:
        st.subheader("Interest and dividends by month")
        caption("Not in your data yet. Open Your data, then Import earlier months, and load the interest and dividends file. Until then next year's "
                "investment income is the average of the finalized months times 12.")
        sipp_loss_editor(plan)
        return
    y = years[-1]
    t = invest_year(entries, y, rate)
    if part != "next":
        st.subheader(f"Interest and dividends, {y}")
        caption("By payment date and account, from your statements, then from finalized monthly updates. A month with neither is estimated from the month "
                "three before it, so a quarterly dividend month is estimated from the last one. Kept apart from the monthly MAGI history, which is not changed.")
        names = dict(INV_ACCOUNTS)
        rows = []
        for r in t["rows"]:
            nz = lambda v: float(v) if isinstance(v, (int, float)) and v else np.nan       # blank, not 0 or None, where there is nothing
            rows.append({"Month": month_short(r["month"]), **{names[f]: nz(r.get(f)) for f in INV_FIELDS}, "Of which muni": nz(r.get("muni")),
                         "Of which quarterly": nz(r.get("qtr")), "Total": nz(r["total"]), "Basis": r["source"] + (f" ({r['note']})" if r.get("note") else "")})
        df = pd.DataFrame(rows)
        tot = {"Month": "Year", **{c: float(pd.to_numeric(df[c], errors="coerce").fillna(0).sum()) for c in df.columns if c not in ("Month", "Basis")}, "Basis": ""}
        df = pd.concat([df, pd.DataFrame([tot])], ignore_index=True)
        mcols = [names[f] for f in INV_FIELDS] + ["Of which muni", "Of which quarterly", "Total"]
        for c in mcols:                                       # cents, and blank where there is nothing
            df[c] = df[c].map(lambda v: money(v, 2) if isinstance(v, (int, float)) and not pd.isna(v) and v else "")
        st.markdown(html_table(df, bold_last=True, right_cols=tuple(mcols)), unsafe_allow_html=True)
        first_open = month_short(t["open_months"][0]) if t["open_months"] else ""
        last_open = month_short(t["open_months"][-1]) if t["open_months"] else ""
        lines = [("Actual so far" + (f" ({t['n_actual']} months)" if t["n_actual"] < 12 else ""), t["actual_total"])]
        if t["open_months"]:
            lines.append((f"Estimate {first_open} to {last_open}" + (" (yours)" if t["override"] else " (the app's)"), t["estimate_total"]))
        lines.append(("Full year", t["total"]))
        lines.append(("Of which tax-exempt muni interest", t["muni_total"]))
        table(pd.DataFrame(lines, columns=["", "Amount"]), money_cols=["Amount"])
        if t["override"]:
            caption(f"The app's own estimate for those months is {money(t['override']['app'])}; yours is {money(t['override']['amount'])}, so its month figures "
                    "are scaled to match. As months close, the ones left keep the same ratio.")
        if t["open_months"]:
            with st.expander(f"Your estimate for {first_open} to {last_open}"):
                k = f"inv_est_{y}_{ss.data_ver}"
                if k not in ss:
                    ss[k] = float(t["override"]["amount"]) if t["override"] else float(t["app_estimate"])
                st.number_input("Interest and dividends for the open months", min_value=0.0, step=100.0, format="%.0f", key=k,
                                on_change=cb_inv_estimate, args=(y, k, t["open_months"]))
                caption(f"The app's estimate, from the same months a quarter earlier: {money(t['app_estimate'])}.")
                if t["override"]:
                    st.button("Use the app's estimate", key=f"inv_est_clr_{y}", on_click=cb_inv_estimate_clear, args=(y,))
    # what it gives next year
    if part != "table":
        ny = y + 1
        if t["total"] and ny in R["ts"].index:
            r_ = R["ts"].loc[ny]
            old = monthly_finalized_from_entries(entries)
            old_n = 0 if old is None else int((pd.to_datetime(old.month_end).dt.year == y).sum())
            old_v = None if old is None or not old_n else float(old[pd.to_datetime(old.month_end).dt.year == y].amount.sum()) * 12 / old_n
            st.subheader(f"Investment income behind {ny}")
            method = invest_base_method(entries)
            rr = invest_run_rate(entries, y, rate)
            mk = f"inv_method_{ss.data_ver}"
            st.radio("Base it on", list(BASE_METHODS), index=list(BASE_METHODS).index(method), format_func=BASE_METHODS.get, horizontal=True, key=mk,
                     on_change=lambda: ss.entries.setdefault("invest_income_meta", {}).__setitem__("base_method", ss[mk]))
            if method == "run_rate" and rr:
                write(f"Wells savings: {month_short(rr['last_month'])} x 12 = {money(rr['wells_savings'])}  |  WellsTrade: {month_short(rr['quarter'][0])} to "
                      f"{month_short(rr['quarter'][1])} x 4 = {money(rr['wellstrade'])}  |  Schwab: same quarter x 4 = {money(rr['schwab'])}  |  "
                      f"**{money(rr['total'])}**, of which tax-exempt {money(rr['muni'])}")
                caption(f"Today's run rate: the latest month for savings (so a balance being drawn down is followed) and the latest full quarter for the "
                        f"brokerage accounts (quarterly dividends in, the portfolio at its current size). {y}'s full year was {money(t['total'])}"
                        + (f"; the old rule, the finalized months times 12, gave {money(old_v)}." if old_v is not None else ".")
                        + " It moves on by itself as months and quarters are finalized.")
            else:
                caption(f"{ny} investment income is {y}'s full-year interest and dividends"
                        + (f" (today's run rate would be {money(rr['total'])})." if rr else ".")
                        + (f" The old rule, the finalized months times 12, gave {money(old_v)}." if old_v is not None else ""))
            if ss.settings.get("override_income"):
                caption("The sidebar switch Override investment income is on, so the model is using that figure instead.")
            other = float(r_.total_magi) - float(r_.base_income) - float(r_.defcomp) - float(r_.other_magi)
            sp = plan.meta.get("sipp") or {}
            mrows = [("Taxable interest and dividends", float(r_.base_income) - float(r_.tax_exempt)),
                     ("Tax-exempt muni interest: counts for MAGI, not taxed", float(r_.tax_exempt)),
                     ("Deferred compensation (gross)", float(r_.defcomp)),
                     ("UK SIPP" + (f" (£{float(sp.get('gbp_month') or 0):,.0f} a month at {float(sp.get('fx') or 1):.2f})" if sp else ""), float(r_.sipp))]
            if r_.loss_used:
                mrows.append(("Capital loss carried over", -float(r_.loss_used)))
            if abs(other) >= 0.5:
                mrows.append(("Everything else in the plan", other))
            mrows.append((f"Planned {ny} MAGI", float(r_.total_magi)))
            st.markdown(html_table(pd.DataFrame(mrows, columns=["Item", "Amount"]).assign(Amount=lambda d: d.Amount.map(lambda v: money(v))),
                                   bold_last=True, right_cols=("Amount",)), unsafe_allow_html=True)
            caption(f"The muni interest is in MAGI for the subsidy but is left out of the federal tax estimate ({money(float(r_.fed_tax))} for {ny}). "
                    "The SIPP and the loss carried over count in MAGI and in the tax estimate.")
        sipp_loss_editor(plan)
        # the history check
        hc = history_check(entries, y, rate)
        flagged = [r for r in hc if r["flag"]]
        if hc:
            with st.expander("Check against the monthly MAGI history" + (f": {len(flagged)} month{'s' if len(flagged) != 1 else ''} look understated" if flagged else ""),
                             expanded=False):
                hdf = pd.DataFrame([{"Month": month_short(r["month"]), "History total": r["history"], "Interest and dividends": r["int_div"],
                                     "Left for everything else": r["rest"], "Looks understated": "Yes" if r["flag"] else ""} for r in hc])
                table(hdf, money_cols=["History total", "Interest and dividends", "Left for everything else"])
                caption("The history total is all of the month's MAGI, so it should be at least the interest and dividends. "
                        + (f"{', '.join(month_short(r['month']) for r in flagged)} {'fall' if len(flagged) != 1 else 'falls'} short or well below the other months, "
                           "probably because the workbook missed the quarterly fund dividends. " if flagged else "")
                        + "The history stays as imported; next year's base uses this table, not the history.")
        # the feed check
        fc = wells_feed_check(plan, _inbox())
        if fc["known"]:
            if fc["missing"]:
                st.warning("Not feeding the Wells interest line: " + ", ".join(fc["missing"]) + ". Open Your data, then the bank connection, and set it to Wells.")
            elif fc["wellstrade"]:
                caption("WellsTrade feeds the Wells line, as it should. Accounts feeding it: " + ", ".join(fc["feeding"]) + ".")
            else:
                caption("No WellsTrade account was found in the daily bank fetch. Accounts feeding the Wells line: " + (", ".join(fc["feeding"]) or "none") + ".")
    # corrections
    if part != "next":
        stmt = [r["month"] for r in t["rows"] if r["source"] == "Statement"]
        if stmt:
            with st.expander("Correct a month from the statements"):
                key = f"inv_ed_{y}_{ss.data_ver}"
                inv = entries.get("invest_income") or {}
                edf = pd.DataFrame([{"Month": month_short(mk), "Wells savings": inv[mk].get("wells"), "WellsTrade": inv[mk].get("wellstrade"),
                                     "Schwab": inv[mk].get("schwab"), "Of which muni": inv[mk].get("muni"), "Of which quarterly": inv[mk].get("qtr")} for mk in stmt])
                ss[f"{key}_df"] = st.data_editor(edf, hide_index=True, disabled=["Month"], key=key, num_rows="fixed",
                                                 column_config={c: st.column_config.NumberColumn(format="$%.2f") for c in edf.columns if c != "Month"})
                st.button("Save corrections", key=f"inv_save_{y}", on_click=cb_inv_save, args=(y, key, stmt))
                caption("Muni and quarterly are parts of the Schwab figure, not extra amounts.")


