def render_live_opening(R, title=True):
    """v21.20: how next year's starting cash is built from today's Wells balances."""
    ss = st.session_state
    try:
        lo = live_opening_cash(ss.plan, ss.entries, _inbox(), today())
    except Exception:  # noqa: BLE001
        lo = None
    if title:
        st.subheader(f"Starting cash for {today().year + 1}")
    else:
        caption(f"How cash on January 1, {today().year + 1} is worked out from today's Wells balances.")
    if lo is None:
        caption(f"From the plan's figures ({money(ss.plan.cash.opening_cash)}): no bank fetch with your Wells balances has been read yet. Once one is, "
                "it starts from your real Wells savings, money market and checking, and keeps the last reading for when the fetch is unavailable.")
        return
    if lo.get("stale"):
        st.warning(f"The daily fetch isn't available right now, so this starts from the last Wells balances read ({lo['asof']}). "
                   "Lines that cleared since then are counted below.")
    rows = [(f"Wells savings, money market and checking ({lo['asof']})", lo["wells_today"]),
            (f"Still to go out of checking before December 31 (bills, cards, one-time items)", -lo["out"]),
            ("Still to come in (deferred comp, the monthly transfer from the trust)", lo["in"]),
            ("Savings interest and money-market dividends still to come", lo["interest"]),
            (f"{today().year} estimated tax still to pay (the January payment included)", -lo["tax_left"])]
    if lo["refund"]:
        rows.append((f"Refund expected on {today().year}'s return", lo["refund"]))
    rows.append((f"Cash on January 1, {lo['year']}", lo["opening"]))
    st.markdown(html_table(pd.DataFrame([(a, money(b)) for a, b in rows], columns=["", "Amount"]), bold_last=True, right_cols=("Amount",)), unsafe_allow_html=True)
    caption(" + ".join(f"{n} {money(v)}" for n, v in lo["parts"]) + ". Moves between your own Wells accounts are left out: they don't change the total. "
            f"The plan's fixed figure was {money(ss.plan.cash.opening_cash)}. This updates with every fetch.")


def annuity_basis(plan) -> float:
    """What was paid into the annuities (v21.22). Kept in plan.meta; until it is set, it is read off the plan as proceeds less the gain entered."""
    b = plan.meta.get("annuity_basis")
    if isinstance(b, (int, float)):
        return float(b)
    return float(plan.cash.annuity_cash) - float(plan.inputs.annuity_gain.get(int(plan.cash.annuity_year), 0.0))


def annuity_gain_auto(plan) -> float:
    """The taxable gain when the annuities are cashed in: proceeds less what was paid in, never below zero."""
    return max(0.0, float(plan.cash.annuity_cash) - annuity_basis(plan))


def cb_annuity(field, key):
    ss = st.session_state
    v = ss.get(key)
    if v is None:
        return
    if field == "cash":
        ss.plan.meta.setdefault("annuity_basis", annuity_basis(ss.plan))        # fix the basis before the proceeds move
        ss.plan.cash.annuity_cash = float(v)
    elif field == "basis":
        ss.plan.meta["annuity_basis"] = float(v)
    elif field == "year":
        old = int(ss.plan.cash.annuity_year)
        ss.plan.cash.annuity_year = int(v)
        g = ss.plan.inputs.annuity_gain
        if old in g and int(v) != old:                              # the gain moves with the year it is taken
            g[int(v)] = g.pop(old)
    ss.plan.inputs.annuity_gain = {int(ss.plan.cash.annuity_year): annuity_gain_auto(ss.plan)}   # kept in step for anything reading the plan


def render_annuity_inputs(expanded=False):
    """v21.21: the annuity cash-out -- proceeds (cash flow), taxable gain (MAGI and tax) and the year -- set here rather than fixed in the plan."""
    ss = st.session_state
    c = ss.plan.cash
    y = int(c.annuity_year)
    gain = annuity_gain_auto(ss.plan)
    with st.expander(_esc(f"Annuities cashed in, {y}: {money(c.annuity_cash)} proceeds, {money(gain)} taxable gain"), expanded=expanded):
        cols = st.columns(3, gap="small")
        k1, k2, k3 = f"ann_cash_{ss.data_ver}", f"ann_basis_{ss.data_ver}", f"ann_year_{ss.data_ver}"
        cols[0].number_input("Proceeds", value=float(c.annuity_cash), min_value=0.0, step=10000.0, format="%.0f", key=k1, on_change=cb_annuity, args=("cash", k1))
        cols[1].number_input("Paid in (cost basis)", value=annuity_basis(ss.plan), min_value=0.0, step=10000.0, format="%.0f", key=k2,
                             on_change=cb_annuity, args=("basis", k2), help="What you put into the annuities. It doesn't change, so the gain follows the proceeds.")
        cols[2].number_input("Year", value=y, min_value=2027, max_value=2050, step=1, key=k3, on_change=cb_annuity, args=("year", k3))
        write(f"Taxable gain: **{money(gain)}** (proceeds less what you paid in)")
        caption("The proceeds come into cash that year; the gain counts in MAGI and the tax estimate (and decides whether that year keeps the subsidy).")


