def _cash_draw_settings(ss, R):
    """v25.35: where a draw to keep cash at the safety line comes from, and how much of a brokerage sale is taxable gain."""
    c = ss.plan.cash
    cs = R["cf_sum"]
    st.subheader("If cash would fall below the line")
    labels = list(DRAW_ORDERS)
    cur = next((k for k, v in DRAW_ORDERS.items() if v == list(c.draw_order or [])), labels[0])
    dk, gk = f"draw_order_{ss.data_ver}", f"draw_gain_{ss.data_ver}"
    c1, c2 = st.columns(2)
    c1.selectbox("Draw from", labels, index=labels.index(cur), key=dk,
                 on_change=lambda: setattr(ss.plan.cash, "draw_order", list(DRAW_ORDERS[ss[dk]])),
                 help="Each account is used only as far as it holds money, then the next. The annuities and deferred comp keep their own schedules.")
    c2.number_input("Share of a brokerage sale that is taxable gain (%)", 0.0, 100.0, float(c.brokerage_gain_share) * 100, 5.0, format="%.0f", key=gk,
                    on_change=lambda: setattr(ss.plan.cash, "brokerage_gain_share", float(ss[gk]) / 100),
                    help="0% if you would sell muni bonds at about what you paid. A SIPP or IRA withdrawal is all taxable income.")
    tot = float(cs.get("total_drawdown") or 0.0)
    if tot > 0.5:
        by = cs.get("draws_by_source") or {}
        caption(f"The plan draws {money(tot)} in all, from {cs.get('first_drawdown_year')}: "
                + ", ".join(f"{DRAW_SOURCE_NAMES[k]} {money(v)}" for k, v in by.items() if v > 0.5)
                + ". Any taxable part is added to that year's income and tax.")
    else:
        caption(f"Cash never falls below the line in the plan, so nothing is drawn.")


