# ---- ledger: list view of any month, including earlier ones -----------------------------------------------------------
def opening_any(k):
    ss = st.session_state
    first = ss.plan.meta.get("first_month", "2026-08")
    return _opening(ss.entries, ss.plan, k) if k >= first else back_opening(ss.entries, first, k)


def ledger_summary(keys):
    ss = st.session_state
    out = []
    for k in keys:
        rows = ss.entries["ledger"].get(k, [])
        op = opening_any(k)
        b = running_balances(rows, op) if op is not None else None
        out.append({"Month": month_label(k), "Lines": len(rows), "Reconciled": f"{sum(1 for r in rows if is_reconciled(r))} of {len(rows)}",
                    "Money in": sum(_n(r.get("credit")) for r in rows), "Money out": sum(_n(r.get("debit")) for r in rows),
                    "Opening": op, "Closing": None if b is None else b["closing"], "Lowest": None if b is None else low_point(b)["balance"]})
    return pd.DataFrame(out)


def ledger_lines(keys, status, classes, text):
    ss = st.session_state
    tz = tz_name()
    out = []
    for k in keys:
        rows = ss.entries["ledger"].get(k, [])
        op = opening_any(k)
        bal = {id(r): b for r, b in running_balances(rows, op)["lines"]} if op is not None else {}
        months_all = month_list(ss.plan, today())
        bop = bank_opening(ss.entries, months_all, k, ss.entries["opening"].get(months_all[0], 0.0)) if k >= ss.plan.meta.get("first_month", "2026-08") else op
        bank = {id(r): b for r, b in bank_balances(rows, bop)} if bop is not None else {}
        for r in ordered_rows(rows):
            rec = is_reconciled(r)
            if status == "Pending" and rec or status == "Reconciled" and not rec:
                continue
            if classes and (r.get("cls") or "No class") not in classes:
                continue
            if text and text.lower() not in f"{r.get('desc', '')} {r.get('note', '')}".lower():
                continue
            out.append({"Date": r.get("date"), "Description": r.get("desc"), "In": r.get("credit"), "Out": r.get("debit"), "Bank balance": bank.get(id(r)), "Running balance": bal.get(id(r)),
                        "Class": r.get("cls") or "No class", "Status": "Reconciled" if rec else "Pending",
                        "Reconciled at": (_fmt_local(r["rec_at"], tz) if r.get("rec_at") else "Before timestamps") if rec else "",
                        "Note": r.get("note") or ""})
    return pd.DataFrame(out, columns=["Date", "Description", "In", "Out", "Bank balance", "Running balance", "Class", "Status", "Reconciled at", "Note"])


# ---- annual roll-up: every ledger description, January to December, money out and money in -------------------------------------------------
def _desc_key(desc) -> str:
    """Lines group by their description, ignoring capitals and extra spaces."""
    return " ".join(str(desc or "").split()).casefold() or "(no description)"


def annual_rollup(entries: dict, year: int, reconciled_only: bool = False, classes=None) -> dict:
    """Totals by description and month for one calendar year of the checking ledger (lines count in the ledger month they sit in).
    Returns 'out' and 'in' tables (Description, Total, Lines, Jan..Dec; largest first), the lines behind each row, and the grand totals."""
    sums = {"out": {}, "in": {}}
    counts = {"out": {}, "in": {}}
    lines = {"out": {}, "in": {}}
    spell = {}
    for m in range(1, 13):
        k = f"{year}-{m:02d}"
        for r in entries.get("ledger", {}).get(k, []) or []:
            if reconciled_only and not is_reconciled(r):
                continue
            cls = r.get("cls") or "No class"
            if classes and cls not in classes:
                continue
            key = _desc_key(r.get("desc"))
            label = " ".join(str(r.get("desc") or "").split()) or "(no description)"
            spell.setdefault(key, {})
            spell[key][label] = spell[key].get(label, 0) + 1
            for side, amt in (("out", _n(r.get("debit"))), ("in", _n(r.get("credit")))):
                if abs(amt) < 0.005:
                    continue
                row = sums[side].setdefault(key, [0.0] * 12)
                row[m - 1] += amt
                counts[side][key] = counts[side].get(key, 0) + 1
                lines[side].setdefault(key, []).append({"Month": k, "Date": r.get("date"), "Description": r.get("desc"), "Amount": amt, "Class": cls,
                                                        "Status": "Reconciled" if is_reconciled(r) else "Pending", "Note": r.get("note") or ""})
    names = {k: max(v.items(), key=lambda kv: kv[1])[0] for k, v in spell.items()}
    cols = ["Description", "Total", "Lines"] + [MONTH_NAMES[i][:3] for i in range(12)]      # Total first, so it is in view without scrolling
    out = {}
    for side in ("out", "in"):
        rows = [[names[k], round(sum(v), 2), counts[side][k]] + [round(x, 2) for x in v] for k, v in sums[side].items()]
        df = pd.DataFrame(rows, columns=cols).sort_values(["Total", "Description"], ascending=[False, True]).reset_index(drop=True)
        out[side] = df
    return {"year": year, "out": out["out"], "in": out["in"],
            "lines": {side: {names[k]: v for k, v in lines[side].items()} for side in ("out", "in")},
            "total_out": float(out["out"]["Total"].sum()) if len(out["out"]) else 0.0,
            "total_in": float(out["in"]["Total"].sum()) if len(out["in"]) else 0.0}


# ---- spending categories: where the money goes, from checking lines and card charges together ---------------------------------------------------
# Every checking debit and every card charge gets one category. The order of say: your choice on that one line, then your own merchant rules,
# then (for checking) a payment to a card, then the built-in merchant rules, then the ledger class (Excluded -> Transfers). Anything left is
# Uncategorized. Card charges are kept for good in entries['card_txns'] (the daily feed only holds 100 days); card payments from checking are
# not spending, since the charges behind them are counted one by one -- except in a month with no charges on file for that card, where the
# payment stands in as "Card spending, not itemized" so the year's total stays whole.
NOT_SPENDING = "Not spending"
UNCATEGORIZED = "Uncategorized"
CAT_CARD_PAY, CAT_NOT_ITEMIZED, CAT_TRANSFERS = "Card payments", "Card spending, not itemized", "Transfers between your accounts"
DEFAULT_CATEGORIES = [
    ("Home", "Real estate taxes"), ("Home", "Homeowners insurance"), ("Home", "Electricity"), ("Home", "Water and sewer"),
    ("Home", "Heating fuel or gas"), ("Home", "Internet and phone"), ("Home", "Landscaping"), ("Home", "Repairs and maintenance"),
    ("Home", "Household supplies"),
    ("Auto", "Fuel"), ("Auto", "Auto insurance"), ("Auto", "Maintenance and repairs"), ("Auto", "Registration, tolls and parking"),
    ("RV", "RV"),
    ("Food", "Groceries"), ("Food", "Restaurants"),
    ("Health", "Medical"), ("Health", "Pharmacy"), ("Health", "Health insurance premiums"),
    ("Home", "Pool"),
    ("Travel", "Flights"), ("Travel", "Hotels"), ("Travel", "Cruises"), ("Travel", "Rental cars and other travel"),
    ("Personal", "Clothing"), ("Personal", "Personal care"), ("Personal", "Gifts and donations"), ("Personal", "Subscriptions and streaming"),
    ("Personal", "Entertainment and hobbies"), ("Personal", "Pets"), ("Personal", "Legal and professional"),
    ("Shopping", "Amazon and online"), ("Shopping", "General merchandise"),
    ("Kids", "Kids"),
    ("Other", "Bank and card fees"), ("Other", CAT_NOT_ITEMIZED), ("Other", "Everything else"),
    (NOT_SPENDING, CAT_TRANSFERS), (NOT_SPENDING, CAT_CARD_PAY), (NOT_SPENDING, "Income tax payments"),
]
