    m[2].metric("Transfers to plan for", money(ol["total_transfers"]), help="From savings, in total, to keep every month above your minimum")
    caption(f"Lowest point: {when}. Minimum {money(minimum)}; a transfer tops the balance up to {money(target)}.")
    x = [f"{MONTH_NAMES[int(r['month'][-2:]) - 1][:3]} \u2019{r['month'][2:4]}" for r in rows]
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=x, y=[r["closing"] for r in rows], name="Month-end", mode="lines+markers", line=dict(color=NAVY, width=2)))
    fig.add_trace(go.Scatter(x=x, y=[r["lowest"] for r in rows], name="Lowest point", mode="lines+markers", line=dict(color=BRASS, width=2)))
    need = [(xx, r) for xx, r in zip(x, rows) if r["transfer"]]
    if need:
        fig.add_trace(go.Scatter(x=[xx for xx, _ in need], y=[r["lowest"] for _, r in need], mode="markers+text", name="Transfer needed",
                                 text=[f"Transfer {money(r['transfer'])}" for _, r in need], textposition="bottom center",
                                 marker=dict(symbol="x", size=12, color="#c0392b", line=dict(width=2))))
    fig.add_hline(y=minimum, line_dash="dot", line_color="#c0392b", annotation_text=f"Minimum {money(minimum)}", annotation_position="bottom right")
    fig.update_layout(height=320, margin=dict(l=8, r=8, t=8, b=8), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)", legend=dict(orientation="h", y=-0.28))
    fig.update_yaxes(tickprefix="$", tickformat=",.0f")
    fig.update_xaxes(tickangle=-40, tickfont=dict(size=11))
    _plotly(fig, key="g_outlook")
    st.subheader("Transfers to plan for")
    if ol["transfers"]:
        st.dataframe(pd.DataFrame([{"Month": month_label(t["month"]), "Move from savings": money(t["amount"]),
                                    "By": f"{_day(t['date'])}, {str(t['date'])[:4]}", "Lowest before the transfer": money(t["lowest"], 2)} for t in ol["transfers"]]),
                     hide_index=True)
        caption("Only what keeps the balance above your minimum, topped up to your target. Each transfer is dated at the first dip and lifts every later balance. "
                "When the month gets close, the balance alert on Monthly updates offers the one-tap transfer.")
        caption("Once you have set a transfer up at your bank, record it below with the date and amount you scheduled. It goes on the ledger as a pending line, "
                "so the balances and the Dashboard count it. If the amount needed grows later, the extra shows here to add to the same transfer.")
        rev = ss.get("ol_rev", 0)
        for t in ol["transfers"]:
            mk = t["month"]
            sched = scheduled_transfer(entries, mk)
            y, m = int(mk[:4]), int(mk[5:7])
            m_first, m_last = _dt.date(y, m, 1), _dt.date(y, m, _cal.monthrange(y, m)[1])
            lo_d = max(m_first, today()) if today() <= m_last else m_first
            need_by = _dt.date.fromisoformat(str(t["date"])[:10])
            with st.container(border=True, key=f"olx_{mk}"):
                if sched:
                    st.markdown(_esc(f"**{month_label(mk)}:** {money(sched['amount'])} scheduled for {_day(sched['date'])}, "
                                     f"but {money(t['amount'])} more is needed by {_day(t['date'])}."))
                    caption(f"Raise it at your bank, then record the extra here -- it's added to the same transfer "
                            f"(making it {money(sched['amount'] + t['amount'])}), not a second one.")
                    btn = "Add the extra to the scheduled transfer"
                else:
                    st.markdown(_esc(f"**{month_label(mk)}:** {money(t['amount'])} needed by {_day(t['date'])}"))
                    caption("Once you've set it up at your bank, enter the date and amount you scheduled and add it. "
                            "It goes on the ledger as a pending transfer from savings, so every balance counts it.")
                    btn = "Scheduled at my bank -- add to ledger"
                c1, c2 = st.columns(2, gap="small")
                dkey, akey = f"ol_d_{ss.data_ver}_{mk}_{rev}", f"ol_a_{ss.data_ver}_{mk}_{rev}"
                c1.date_input("Transfer date", value=min(max(need_by, lo_d), m_last), min_value=lo_d, max_value=m_last, key=dkey)
                c2.number_input("Amount", min_value=0.0, value=float(t["amount"]), step=50.0, format="%.2f", key=akey)
                st.button(btn, key=f"ol_add_{ss.data_ver}_{mk}_{rev}", on_click=cb_sched_add, args=(mk, dkey, akey))
