        q[1].text_input("Price after the subsidy, a year", value=f"{float(ex.get('defcomp_prem_sub', 0) or 0):,.2f}" if ex.get("defcomp_prem_full") else "", key=sk)
        q[2].number_input("Premium growth, percent a year", 0.0, 20.0, value=round(float(ex.get("defcomp_prem_growth", 0.05)) * 100, 2), step=0.5, format="%.2f", key=gk)
        b = st.columns(2, gap="small")
        b[0].button("Use the 2029 difference as the subsidy cost", key=f"dc_pg_{ver}", on_click=cb_dc_prem, args=("gap", fk, sk, gk))
        b[1].button("Also use the full price for 2031 and 2032", key=f"dc_pf_{ver}", on_click=cb_dc_prem, args=("full", fk, sk, gk))
