def _dc_choice(plan, ex):
    ss = st.session_state
    ver = ss.data_ver
    bucket, asof, rate, aca, ret = _dc_vals(ex)
    caption("How the three choices for the 2013 to 2015 deferrals compare, and the setting that puts one of them in the plan. "
            "this stays here to check it or to change your mind before the deadline. Choosing A also adds the cost of losing the 2029 subsidy to that year's spending.")
    if bucket <= 0:
        st.info("Enter the balance on your statement to see the comparison.")
        return
    runner = lambda p: _run_cached(json.dumps(plan_to_dict(p), sort_keys=True, default=float), json.dumps(ss.settings, sort_keys=True, default=float),
                                   json.dumps(ss.entries, sort_keys=True, default=str))
    res = defcomp_compare(plan, runner, bucket, asof, rate, ret, aca)
    o, ranked = res["options"], res["ranked"]
    st.subheader("The three choices")
    caption(f"Cash left in 2050 in this comparison, where all your cash earns {_pct(ret)}% a year. The totals therefore run higher than the Dashboard's: compare the "
            f"choices with each other, not with that figure. The gross amounts include growth at {_pct(rate)}% to the payment date.")
    names = {1: "A. Take the lump in September 2029", 2: "B. Defer five years, then five yearly payments", 3: "C. Defer five years, then one lump in September 2034"}
    best_cash = o[ranked[0]]["cash2050"]
    for code in (1, 2, 3):
        x = o[code]
        with st.container(border=True):
            write(f"**{names[code]}**" + ("  \u2190 highest cash in 2050" if code == ranked[0] else ""))
            write(f"Pays {money(x['gross'])} in all" + (f": {', '.join(f'{y} {money(v)}' for y, v in x['by_year'].items())}" if code == 2 else ""))
            write(f"Federal tax it adds: {money(x['tax'])} ({x['tax'] / x['gross'] * 100:.1f}% of it)")
            if code == 1:
                write(f"ACA subsidy lost in 2029: {money(x['aca'])}")
            write("Left after tax" + (" and the subsidy" if code == 1 else "") + f": {money(x['after'])}")
            write(f"Cash in 2050: {money(x['cash2050'])}" + ("" if code == ranked[0] else f", {money(best_cash - x['cash2050'])} behind the best"))
    nm = {1: "the 2029 lump", 2: "the five payments", 3: "the 2034 lump"}
    st.markdown(_esc(f"**Bottom line:** at {_pct(ret)}%, {nm[ranked[0]]} leaves the most cash, {money(best_cash - o[ranked[1]]['cash2050'])} ahead of {nm[ranked[1]]} "
                     f"and {money(best_cash - o[ranked[2]]['cash2050'])} ahead of {nm[ranked[2]]}."))
    st.button("Show how the answer changes with the return", key=f"dc_sensbtn_{ver}", on_click=cb_dc_sens)
    if ss.get("dc_sens"):
        st.markdown("**How the answer changes with the return on your after-tax money**")
        for r in (0.05, 0.055, 0.06, 0.065, 0.07):
            rr = defcomp_compare(plan, runner, bucket, asof, rate, r, aca)
            oo, rk = rr["options"], rr["ranked"]
            top = oo[rk[0]]["cash2050"]
            write(f"{r * 100:g}%: {nm[rk[0]]} first; {nm[rk[1]]} {money(top - oo[rk[1]]['cash2050'])} behind and {nm[rk[2]]} {money(top - oo[rk[2]]['cash2050'])} behind.")
        caption("Each line runs your whole plan again at that return.")
    st.subheader("Put a choice into your plan")
    cur = int(plan.inputs.defcomp.election_code)
    caption("Now: " + (f"the plan models {DEFCOMP_ELECTIONS[cur][0].lower() + DEFCOMP_ELECTIONS[cur][1:]}." if cur in DEFCOMP_ELECTIONS and plan.inputs.defcomp.bucket_2029 > 0
                       else f"the older setting is in use: a stream of {money(plan.inputs.defcomp.stream_2034_annual)} a year in today's terms from October 2034."))
    pick = st.radio("Show this on the Dashboard", [1, 2, 3], index=[1, 2, 3].index(cur) if cur in (1, 2, 3) else 2, format_func=lambda c_: names[c_], key=f"dc_pick_{ver}")
    st.button("Use this choice in the plan", key=f"dc_apply_{ver}", on_click=cb_dc_apply, args=(pick, bucket, asof, rate))
    _dc_here("apply")
    with st.expander("Line up your other deferred compensation with the statement"):
        caption(f"Your model grows deferred compensation {plan.inputs.defcomp.growth_after * 100:g}% a year after 2027 and has a January 2032 lump of "
                f"{money(plan.inputs.defcomp.lump_2032, 2)}. If everything is credited at {rate * 100:g}%, set them to match.")
        lk = f"dc_l32_{ver}"
        st.text_input("January 2032 lump on your statement", value=f"{plan.inputs.defcomp.lump_2032:,.2f}", key=lk)
        st.button("Update the plan", key=f"dc_align_{ver}", on_click=cb_dc_align, args=(rate, lk))
        _dc_here("align")
    caption("Model figures, not advice. The tax uses the plan's federal estimate (state tax after a move is on the Moving page), and your conversions are re-planned around each choice. "
            "Your CPA should check the final numbers, and the plan administrator confirms the rules and the deadline.")


def defcomp_tile(plan) -> tuple:
    """The Dashboard's DefComp tile (label, value, kind, note, extra): what is still to come and the election status (back in v21.48)."""
    dcp = plan.inputs.defcomp
    dl = defcomp_deadline_ord(plan)
    sub_ = int(plan.expenses.get("defcomp_submitted", 0) or 0)
    modeled = DEFCOMP_ELECTIONS.get(int(dcp.election_code)) if dcp.bucket_2029 > 0 else None
    dc_sum = defcomp_tile_lines(plan, today())
    dc_lines = "\n".join(f"{lab}: {money(amt)}" for lab, amt in dc_sum["lines"])
    dc_val = money(dc_sum["total"]) if dc_sum["lines"] else "\u2014"
    if sub_:
        sd_ = _dt.date.fromordinal(sub_)
        dc_t = ("DefComp", dc_val, "ok", f"Elected, form in {fmt_date(sd_)}", dc_lines)
    elif dcp.bucket_2029 > 0 and int(dcp.election_code) == 1:
        dc_t = ("DefComp", dc_val, "ok", "Paid automatically", dc_lines)
    elif dl:
        dd_ = _dt.date.fromordinal(dl)
        left = (dd_ - today()).days
        dc_t = ("DefComp", dc_val, "bad" if left < 0 else ("warn" if left <= 365 else "idle"),
                f"{left:,} days to submit" if left >= 0 else "Deadline passed", dc_lines)
    else:
        dc_t = ("DefComp", dc_val, "idle", "Set the election deadline", dc_lines)
    return dc_t


