def _yr(label, year):
    """A tile is about the current year, so the year is left off its title. It is added only when the tile is about a different year."""
    return label if int(year) == today().year else f"{label}, {int(year)}"


# v21.57: a read-only table is drawn as a plain web table (html_table), not Streamlit's canvas grid. On the iPad the canvas catches every
# swipe that starts on it, so a long one (the cash-flow years) could not be scrolled past. Plain tables scroll with the page. Number and date
# formats from column_config and from a Styler's .format() are kept. A table you can tap to select, or edit, stays on the canvas.
FIT_ROWS = 25
_st_dataframe = st.dataframe


def _cell_text(v, fmt):
    if v is None or (isinstance(v, float) and math.isnan(v)) or (hasattr(pd, "isna") and not isinstance(v, (list, dict)) and pd.isna(v)):
        return ""
    if isinstance(v, bool):
        return "\u2713" if v else ""
    if fmt in ("dollar", "accounting") and isinstance(v, (int, float, np.integer, np.floating)):
        return money(float(v), 2)
    if fmt == "$%d" and isinstance(v, (int, float, np.integer, np.floating)):     # whole dollars
        return money(float(v))
    if isinstance(fmt, str) and fmt.startswith("$") and "%" in fmt and isinstance(v, (int, float, np.integer, np.floating)):
        return money(float(v), 2)
    if isinstance(fmt, str) and "%" in fmt and isinstance(v, (int, float, np.integer, np.floating)):
        try:
            return fmt % v
        except (TypeError, ValueError):
            return str(v)
    if isinstance(v, (_dt.date, pd.Timestamp)):
        return f"{MONTH_NAMES[v.month - 1][:3]} {v.day}, {v.year}"
    if isinstance(v, (float, np.floating)):
        return f"{v:,.2f}"
    if isinstance(v, (np.integer,)):
        return str(int(v))
    return str(v)


def _as_html_table(data, column_config=None):
    """A DataFrame or Styler as display text: Styler formats first, then column_config formats, then sensible defaults."""
    sty = None
    if hasattr(data, "data") and hasattr(data, "_display_funcs"):
        sty, df = data, data.data
    else:
        df = data if isinstance(data, pd.DataFrame) else pd.DataFrame(data)
    df = df.reset_index(drop=True)
    cfg = column_config or {}
    out = pd.DataFrame(index=df.index)
    right = []
    for j, c in enumerate(df.columns):
        cc = cfg.get(c) if isinstance(cfg, dict) else None
        fmt = None
        if isinstance(cc, dict):
            fmt = (cc.get("type_config") or {}).get("format")
            if (cc.get("type_config") or {}).get("type") == "date":
                fmt = "date"
        col = []
        for i, v in enumerate(df[c].tolist()):
            if sty is not None and (i, j) in getattr(sty, "_display_funcs", {}):
                try:
                    col.append(str(sty._display_funcs[(i, j)](v)))
                    continue
                except Exception:  # noqa: BLE001
                    pass
            col.append(_cell_text(v, fmt))
        out[str(c)] = col
        if pd.api.types.is_numeric_dtype(df[c]) or fmt in ("dollar", "accounting"):
            right.append(str(c))
    return out, tuple(right)


def _dataframe_fit(data=None, *a, **k):
    if k.get("on_select") or k.get("selection_mode"):
        if "height" not in k:
            try:
                n = len(getattr(data, "data", data))
            except TypeError:
                n = None
            if n is not None and n <= FIT_ROWS:
                k["height"] = 35 * (n + 1) + 3
        return _st_dataframe(data, *a, **k)
    try:
        out, right = _as_html_table(data, k.get("column_config"))
    except Exception:  # noqa: BLE001 -- anything unexpected falls back to the canvas grid
        return _st_dataframe(data, *a, **k)
    return st.markdown(html_table(out, right_cols=right), unsafe_allow_html=True)


st.dataframe = _dataframe_fit


TILES_PER_ROW = 5          # v21.44: every dashboard fills rows of five, left to right; the tile width in the CSS is one fifth of the strip


def _hub_row(tiles, band):
    """v21.69: one row of module tiles; each tile is {"key", "t": (label, value, kind, note, extra), "go"}."""
    with _tile_area():
        for start in range(0, len(tiles), TILES_PER_ROW):
            chunk = tiles[start:start + TILES_PER_ROW]
            cols = st.columns(len(chunk), gap="small")
            for i, tl in enumerate(chunk):
                with cols[i]:
                    t = tl["t"]
                    _segment(tl["key"], band, "first" if i == 0 else ("last" if i == len(chunk) - 1 else "mid"), t[0], t[1], t[2], t[3], "", t[4], go=tl["go"])


def _tile_area():
    """v21.43: the strip every row of tiles sits in: the full width of the page, the same on every dashboard, so a tile is the same size
    everywhere (one fifth of the strip, set in the CSS). A row with fewer tiles is shorter rather than stretched."""
    return st.container()


def _segment(key, band, pos, label, value, kind, note, target, extra="", go=None):
    """One segment of a band: the same size as every other, coloured by its band, and the whole segment is the button."""
    with st.container(key=f"seg_{band}_{pos}_{key}"):
        st.markdown(f"<div class='sg'><div class='sg-lab'>{_h(label)}</div><div class='sg-val'>{_h(value)}</div>"
                    f"<div class='sg-note k-{kind}'>{_h(note)}</div>" + (f"<div class='sg-ext'>{'<br>'.join(_h(x_) for x_ in extra.split(chr(10)))}</div>" if extra else "") + "</div>",
                    unsafe_allow_html=True)
        st.button(f"Open {label}", key=f"open_{key}", on_click=(go if go is not None else goto_page), args=(() if go is not None else (target,)))


