def _cash_check(plan, entries, months, cur, nxt):
    """The checking tile's state: (kind, note) and the alert to send, if one is open. The decision itself is cash_state(), shared with the
    nightly bank job so the email and the tile never disagree; this only words it."""
    c = cash_state(plan, entries, months, cur, today())
    st_, m = c["state"], c.get("month")
    # A plain space between the month and year here can wrap right between them in the narrow checking tile,
    # stranding the year alone on its own line ("Above $1,000 to Feb" / "2028"). A non-breaking space keeps
    # "Mon YYYY" together as one unit without changing anything else about how it reads. Andrew's call
    # (25 Sep 2026). Scoped to just this tile's wording, not month_short() itself, which other pages and tests
    # still render with an ordinary space.
    nb_month = lambda k: month_short(k).replace(" ", " ")
    when = (lambda: _day(c["date"])) if c["near"] else (lambda: f"in {nb_month(m)}")
    if st_ == "now":
        return ("bad", f"Below your {money(c['minimum'])} minimum now"), c["alert"]
    if st_ == "soon":
        return ("warn", f"Dips to {money(c['balance'], 2)} " + (f"({when()})" if c["near"] else when())), c["alert"]
    if st_ == "far":             # a dip more than TRANSFER_ACTION_DAYS off: shown for planning, not orange and not an open item until it is close enough to act on
        return ("idle", f"Heads up: dips to {money(c['balance'], 2)} " + (f"({when()})" if c["near"] else when())), None
    if st_ == "scheduled":
        return ("ok", f"Transfer scheduled for {_day(c['fix_date']) if c['near'] else nb_month(m)}"), None
    if st_ == "empty":
        return ("ok", f"Above {money(c['minimum'])} through {MONTH_NAMES[int(nxt[-2:]) - 1][:3]}"), None
    return ("ok", f"Above {money(c['minimum'])} to {nb_month(m)}"), None


def _tax_auto_through(plan):
    """The last due date an automatic IRS payment is set up for ('' if none). The first version was a plain tick meant for the 15 January 2027 payment."""
    ex = plan.expenses
    return str(ex.get("tax_autopay_through") or ("2027-01-15" if ex.get("tax_autopay") else ""))


def _tax_state(plan, R):
    """The tax tile: the tile's fields and the alert to send, if one is open. Only payments your CPA or you have set count: a payment that is just the
    forecast is not something to act on. A payment due on or before the date automatic payments are set up through is taken care of."""
    fy = today().year + 1
    ftax = float(R["ts"].loc[fy, "fed_tax"]) if fy in R["ts"].index else None
    ty, srows, forecast_left = None, [], False
    for yy in (today().year - 1, today().year):          # the year with the next unpaid payment (last year's January payment comes first)
        rr = tax_schedule(plan, R, yy)
        unpaid = [r for r in rr if not r["paid"] and float(r["amount"]) > 0.005]
        if any(r.get("source") != "Forecast" for r in unpaid):
            ty, srows = yy, rr
            break
        forecast_left = forecast_left or bool(unpaid)
    fx = f"{fy} forecast tax {money(ftax)}" if ftax is not None else ""
    if ty is None:
        if forecast_left:
            return ("Tax planning", "Nothing due", "idle", "Your CPA says when", fx), None
        return ("Tax planning", "All paid", "ok", "Nothing left to pay", fx), None
    s = tax_summary(srows)
    dd = _dt.date.fromisoformat(s["next_due"])
    days = (dd - today()).days
    extra = f"{s['n_paid']} of {s['n']} paid ({money(s['paid'])})" + (f" \u00b7 {fy} tax {money(ftax)}" if ftax is not None else "")
    try:                                                 # v21.17: the year's own tax forecast, when its figures are entered (Tax payments page)
        pos = year_tax_position(plan, st.session_state.entries, R, ty)
    except Exception:  # noqa: BLE001 - the tile must always draw
        pos = None
    if pos is not None:
        extra = (f"{ty} forecast: " + (f"refund {money(-pos['balance'])}" if pos["balance"] < 0 else f"owe {money(pos['balance'])} in April")
                 + f" \u00b7 {s['n_paid']} of {s['n']} paid")
    through = _tax_auto_through(plan)
    covered = bool(through) and s["next_due"] <= through
    if covered and days >= 0:
        return (_yr("Tax planning", ty), f"{money(s['unpaid'])} to pay", "ok", f"Automatic, {fmt_date(dd)}, {dd.year}", extra), None
    if covered:
        return (_yr("Tax planning", ty), f"{money(s['unpaid'])} to pay", "warn", f"Was due {fmt_date(dd)}: confirm it went", extra), {"id": f"tax_overdue:{s['next_due']}", "kind": "tax_overdue", "due": s["next_due"]}
    alert = {"id": f"tax_due:{s['next_due']}", "kind": "tax_due", "due": s["next_due"]} if days <= 45 else None      # months ahead is not yet an email
    return (_yr("Tax planning", ty), f"{money(s['unpaid'])} to pay", "warn", f"Due {fmt_date(dd)}, {dd.year}", extra), alert


def dashboard_alerts():
    """The Dashboard's open orange and red items as small notes for the reminder email (an id, a kind and a date; no amounts). Never raises."""
    ss = st.session_state
    try:
        plan, entries = ss.plan, ss.entries
        months = month_list(plan, today())
        cur, _m = current_month_key()
        nxt = months[months.index(cur) + 1] if cur in months and months.index(cur) + 1 < len(months) else cur
        out = [a for a in (_cash_check(plan, entries, months, cur, nxt)[1], _tax_state(plan, model())[1]) if a]
        return out
    except Exception:  # noqa: BLE001 - a reminder note must never break saving
        return []


def _overview_body(ss, plan, entries, R, months, cur, nxt):
    st.title("Shooman Retirement Dashboard" + (" (DEV)" if is_dev() else ""))
    # v21.62: the notes that sat here (bank lines, card charges, bill amounts, fetch problems) are actions now: see the sidebar's status bar

    # ---- the numbers behind the tiles --------------------------------------------------------------------------------------------
    minimum = min_balance(plan)
    rbal = reconciled_balance(entries, months, cur, entries["opening"].get(months[0], 0.0))
    chk, _cash_alert = _cash_check(plan, entries, months, cur, nxt)

    year = today().year
    # v21.17: the tile leads with the subsidy year's forecast (the same figure as the ACA page), with the year so far underneath.
    # In the practice year that means next year's forecast, and the practice year's running total moves to the second line.
    m = R["aca"]
    fc, lim = m["projected_with_one_time"], m["limit"]
    head = lim - fc
    st_ = "bad" if fc > lim else ("warn" if fc > m["warning_target"] else "ok")
    line1 = f"{money(abs(head))} {'under' if head >= 0 else 'over'} the {money(lim)} limit"
    if year in plan.meta.get("practice_years", [2026]):
        a = aca_practice(entries, plan.inputs.defcomp.withholding_rate, months, year, float(ss.settings["warning"]), float(R["limits"].get(year, 84600.0)))
        line2 = ("Import Jan to Jul MAGI history" if a["needs_history"]
                 else f"{year} so far {money(a['running'])} · practice year")
    else:
        line2 = f"So far {money(m['finalized_actual'])} · {m['finalized_months']} of 12 months finalized"
    aca = (_yr("ACA MAGI forecast", R["aca_year"]), money(fc), st_, line1, line2)
    yc = spend_control(spend_year())
    hd, sm = yc["headroom"], yc["summary"]
    nw = latest_net_worth(entries)

    # ---- the health tiles ---------------------------------------------------------------------------------------------------------
    cs = R["cf_sum"]
    short = cs.get("first_shortfall_year")
    low = min(cs["lowest_ending_cash"], cs["bridge_low_point"])              # the same figure and wording as the Dashboard's cash card
    bridge = cs["bridge_low_point"] < cs["lowest_ending_cash"]
    warn_at = cash_warn_level(plan)                                           # amber below this, while there is still time to course-correct
    now_cash, now_asof, now_tax = current_cash(plan, entries)                # v21.60: cash now leads; the low point is the note under it
    kind_, dnote_ = cash_draw_status(cs, warn_at)
    cash = ("Cash flow", money(now_cash) if now_cash is not None else money(low), kind_,
            f"Low point {money(low)}, " + ("early 2031" if bridge else f"end of {cs['lowest_ending_cash_year']}"),
            dnote_
            + (f"\nWells less {money(now_tax)} tax to pay, {now_asof}" if now_cash is not None and now_tax else (f"\nWells, {now_asof}" if now_cash is not None else "")))
    conv = R["irm"]["adopted_roth"]
    pos = conv[conv > 0]
    if len(pos):
        first = int(pos.index.min())
        head = R["irm_sum"]["headroom_at_target"] - R["buffer_irmaa"]
        roth = (f"Roth conversion, {first}", money(conv.loc[first]), "ok" if head >= 0 else ("warn" if R["irm_sum"]["headroom_at_target"] >= 0 else "bad"),
                "Clear of IRMAA ceiling" if head >= 0 else "Inside your buffer", f"{money(pos.sum())} total, {first} to {int(pos.index.max())}")
    else:
        roth = ("Roth conversions", "None planned", "idle", "No conversion in the plan", "")
    tax, _tax_alert = _tax_state(plan, R)
    late = open_m = None
    for k in months:
        s = month_status(plan, entries, k)
        if late is None and s["ended"] and s["overall"] != "Complete":
            late = (k, s)
        if open_m is None and not s["ended"]:
            open_m = k
    if late:
        k, s = late
        close = ("Monthly close", f"{month_short(k)} {'overdue' if s['overall'] == 'Overdue' else 'due'}", "bad" if s["overall"] == "Overdue" else "warn",
                 f"Still to do: {', '.join(s['missing'])}", f"Due {fmt_date(s['due'])}")
    else:
        close = ("Monthly close", "Caught up", "ok", "Nothing overdue", f"{month_label(open_m)} is due {fmt_date(due_date(open_m))}" if open_m else "")
    checks = entries.get("bank_checks", [])
    if checks:
        last = checks[-1]
        age = (today() - _dt.datetime.fromisoformat(last["t"]).date()).days
        bank = ("Last bank match", _fmt_local(last["t"], tz_name()).split(",")[0], "ok" if age <= 7 else "warn",
                "Matched Wells within the last week" if age <= 7 else f"{age} days since the last match", f"Matched at {money(last['balance'], 2)}")
    else:
        bank = ("Last bank match", "Not yet", "idle", "Not checked yet", "Type your Wells balance on Transactions")
    if local_on():
        v_, k_, n_ = _sync_words()
        data = ("Data save", v_, k_, n_, "")
    elif ss.get("cloud_cfg") is None:
        data = ("Data save", "File only", "warn" if unsaved() else "idle", "Unsaved changes: use Save data file" if unsaved() else "Saved to a file on this device", "")
    else:
        st_ = ss.get("cloud_status")
        data = ("Data save", "Saved" if st_ == "saved" else "Check", "ok" if st_ == "saved" else ("bad" if st_ in ("error", "conflict") else "warn"),
                "Saved to your private repository" if st_ == "saved" else "See the sidebar for what to do", "")
    pace_v = sm["normalized_variance"]                       # everyday (core) spending against the budget for the months so far
    has_pace = sm["core_budget"] > 0                         # a full-year forecast is meaningful even before anything is reconciled (a fresh January defaults to the budget itself)
    ot = one_time_register(plan, entries, yc["year"], today())                     # one-time spending counts against its own bucket, not a monthly pace
    ot_set = round(ot["reserved"] + max(ot["pending"], 0.0) + ot["planned"], 2)     # on cards, waiting to be reconciled, and planned: set aside, not spent yet
    # The tile leads with the year's headroom (budget minus actual so far plus the ledger's forecast for the months ahead); "so far" is the to-date pace.
    year_v = sm["full_year_variance"]                       # budget minus actual so far plus the ledger's forecast for the months ahead
    if has_pace and year_v < 0:
        sp_kind, sp_note = "warn", "Forecast over budget for the year"
    elif ot["spent"] > ot["budget"] + 0.005:
        sp_kind, sp_note = "warn", "One-time budget used up"
    elif ot["rest"] < -0.005:
        sp_kind, sp_note = "warn", "One-time plans exceed the budget"
    elif has_pace:
        sp_kind, sp_note = "ok", "Headroom for the year"
    else:
        sp_kind, sp_note = "idle", "Not enough months yet"
    spend_t = (_yr("Spending", yc["year"]), f"{money(abs(year_v))} {'under' if year_v >= 0 else 'over'}" if has_pace else "—", sp_kind, sp_note,
               (f"So far {money(abs(pace_v))} {'under' if pace_v >= 0 else 'over'}\n" if has_pace else "")
               + f"One-time {money(ot['spent'])}" + (f" (+{money(ot_set)} set aside)" if ot_set > 0.004 else "") + f" of {money(ot['budget'])}")
    _cy = today().year                                                   # v21.48: spending by category moved here from Reporting
    _CR = category_rollup(plan, spending_items(plan, entries, _cy))
    _unc = _CR["uncategorized"]
    cats_t = ("Spending by category", money(_CR["spending_total"]), "warn" if _unc else "ok", f"{_cy}, January to date",
              f"{len(_unc)} line{'s' if len(_unc) != 1 else ''} to sort" if _unc else "Everything sorted")
    G = investment_growth(plan, entries, today().year, today())          # v21.40: investment growth replaces the DefComp tile (DefComp stays in the sidebar)
    grow_t = ("Investment growth", f"{_gpct(G['ret'])} YTD" if G["ok"] else "\u2014", G["status"] if G["ok"] else "idle",     # v21.41: YTD and year-end forecast spelled out
              growth_words(G) if G["ok"] else "Not set up yet",
              f"{signed(G['gain'])}, 1 Jan to end of {month_short(G['end'])}\nForecast year end {_gpct(G['annual'])}" if G["ok"] else "Net worth page, Investment growth")
    y_ye = min(max(today().year if today().month >= 5 else today().year - 1, 2026), 2042)
    ye_checks = _ye_checks(plan, entries, y_ye)
    n_ok = sum(c["status"] == "ok" for c in ye_checks)
    dp = docs_progress(entries, tax_documents(plan, R, y_ye), y_ye)
    closed = year_closed(entries, y_ye)
    if closed:
        ye_t = ("Year end / start", f"{y_ye} closed", "ok", f"Closed {closed}", f"{dp['received']} of {dp['needed']} tax documents")
    else:
        ye_t = ("Year end / start", str(y_ye), "warn" if (today().year > y_ye or today().month == 12) else "idle",
                f"{n_ok} of {len(ye_checks)} checks green", f"{dp['received']} of {dp['needed']} tax documents")
    lb = plan.meta.get("last_backup")
    lbd = _dt.date.fromisoformat(lb) if lb else None
    age = (today() - lbd).days if lb else None
    bk_kind = "warn" if (lb is None or age > 30) else "ok"
    rank = {"idle": 0, "ok": 1, "warn": 2, "bad": 3}
    if rank[data[2]] >= 2:                                    # a problem saving comes first; the file copy is the second line
        db_note, db_extra = data[3], (f"Last file copy {fmt_date(lbd)}" if lb else "No file copy yet")
    elif bk_kind == "warn":
        db_note, db_extra = ("No file copy yet" if lb is None else f"Last file copy {age} days ago"), data[3]
    else:
        db_note, db_extra = data[3], f"Last file copy {fmt_date(lbd)}"
    databk = ("Data & backup", data[1], max(data[2], bk_kind, key=rank.get), db_note, db_extra)
    rep = ("Reporting", "Reports", "idle", "Tax package and documents", "Year end and year start")
    T = lambda key, t, target, go=None: {"key": key, "label": t[0], "value": t[1], "kind": t[2], "note": t[3], "extra": t[4], "target": target, "go": go}
    # A preview only -- Monthly updates() (page_updates) is what actually posts the recurring bills/income/annual
    # lines that "Pending" review depends on, and that materializing has real side effects elsewhere (it feeds the
    # balance outlook and cash alerts), so it must not run here just to count for a tile. A throwaway copy of the
    # ledger gives an accurate "how many will need review" figure -- matching what Monthly updates will actually
    # show once opened -- without touching the live entries or anything else on this page. Andrew's call
    # (September 2026): an earlier version of this ran the posters for real here, which quietly changed the cash
    # flow dip forecast too -- caught by the test suite, not shipped.
    _preview = {"ledger": _copy.deepcopy(entries.get("ledger", {}))}
    ensure_monthly_recurring_lines(plan, _preview, months, today())
    ensure_income_recurring_lines(plan, _preview, months, today())
    ensure_annual_bill_lines(plan, _preview, months, today())
    chk_pending = sum(1 for r in _preview["ledger"].get(cur, []) if not is_reconciled(r))
    chk_t = ("Checking balance", money(rbal, 2), chk[0], chk[1],
             f"Lowest this month {money(low_point(running_balances(entries['ledger'].get(cur, []), _opening(entries, plan, cur)))['balance'], 2)}\n"
             + (f"{chk_pending} to reconcile" if chk_pending else "Nothing to reconcile"))
    nw_t = ("Net worth", money_m(nw["net_worth"]), "idle", f"Financial assets {money_m(nw['assets'])}", f"As of {month_short(nw['month'])}") if nw \
        else ("Net worth", "—", "idle", "Enter all nine account balances", "")
    bands = [("Cash", "now to a year ahead",
              [T("kpi_check", chk_t, "the reconcile screen", goto_checking), T("tile_spend", spend_t, "Spending"),
               T("kpi_nw", nw_t, "Net worth"), T("tile_cash", cash, "Cash flow"), T("tile_cats", cats_t, "Spending", lambda: goto_spending_cats("Dashboard"))]),
             ("Planning", "years ahead",
              [T("kpi_aca", aca, "ACA"), T("tile_tax", tax, "Tax payments"), T("tile_roth", roth, "Roth"), T("tile_growth", grow_t, "Net worth", lambda: goto_networth("growth")), T("tile_defcomp", defcomp_tile(plan), "DefComp")]),
             ("Housekeeping", "the recurring chores",
              [T("tile_close", close, "Monthly updates", lambda: goto_updates("hub")), T("tile_year", ye_t, "Year end"),
               T("tile_bank", bank, "Monthly updates", lambda: goto_updates("hub")),
               T("tile_databk", databk, "Your data"), T("tile_report", rep, "Reporting")])]
    for name, sub, tl in bands:
        look = sum(1 for t in tl if t["kind"] in ("warn", "bad"))
        worst = "red" if any(t["kind"] == "bad" for t in tl) else ("orange" if look else "green")
        with _tile_area():                                    # v21.43: the same strip as every other dashboard, so every tile is the same size
            st.markdown(f"**{name}** &nbsp;:{worst}[●] {f'{look} to look at' if look else 'All clear'} &nbsp;·&nbsp; <span style='opacity:.6'>{sub}</span>", unsafe_allow_html=True)
            cols = st.columns(len(tl), gap="small")
            for i, (col, t) in enumerate(zip(cols, tl)):
                with col:
                    _segment(t["key"], {"Cash": "cash", "Planning": "plan", "Housekeeping": "home"}[name], "first" if i == 0 else ("last" if i == len(tl) - 1 else "mid"),
                             t["label"], t["value"], t["kind"], t["note"], t["target"], t["extra"], go=t["go"])
    side = st.columns([1, 10, 1], gap="small")                 # v21.33: Estele's view, a long thin strip under the three bands
    with side[1]:
        with st.container(key="est_btn"):
            st.button("Estele\u2019s view", key="est_open", on_click=cb_estele_open, use_container_width=True)


# ---- net worth: every account and the capital assets, month by month -------------------------------------------------------
def _slug(name):
    return _re.sub(r"\W+", "_", str(name)).strip("_").lower()


def cb_cap_toggle():
    ss = st.session_state
    ss.cap_open = not ss.get("cap_open", False)


def use_capital(k, prefix, total):
    ss = st.session_state
    v = round(total, 2)
    ss.entries["balances"].setdefault(k, {})["capital"] = v
    ss[f"{prefix}_capital"] = money_str(v)


def cb_cap_save():
    ss = st.session_state
    plan, ver = ss.plan, ss.data_ver
    parsed = []
    for it in capital_items(plan):
        s = _slug(it["name"])
        v, r = parse_money(ss.get(f"cap_v_{ver}_{s}") or ""), parse_money(ss.get(f"cap_r_{ver}_{s}") or "")
        if v is None or v < 0 or r is None or not -50 <= r <= 50:
            ss.cap_msg = f"Check {it['name']}: enter a value of zero or more, and a yearly change between -50 and 50 percent."
            return
        if it.get("linked") and r > 0:
            ss.cap_msg = "The RV can only lose value, because the plan sells it. Enter a negative yearly change."
            return
        parsed.append((it, v, r))
    raw_sy = (ss.get(f"cap_sy_{ver}") or "").strip()
    sy = 0 if raw_sy == "" else parse_money(raw_sy)     # blank: no sale is assumed
    if sy is None or (sy and not 2026 <= sy <= 2060):
        ss.cap_msg = "Enter the RV sale year as a year, for example 2029, or leave it blank if you are not planning a sale."
        return
    for it, v, r in parsed:
        if it.get("linked"):
            plan.cash.rv_current_value, plan.cash.rv_depreciation, plan.cash.rv_sale_year = float(v), -float(r) / 100.0, int(sy)
        else:
            for x in plan.meta["capital_items"]:
                if x["name"] == it["name"]:
                    x["value"], x["rate"] = float(v), float(r) / 100.0
    ss.cap_msg = (f"Saved. Capital assets are now {money(capital_total_now(plan), 2)}. To put that total on a month's balance, use Monthly updates, "
                  "Balances, Work out capital assets from the list.")


def cb_cap_remove_sale():
    ss = st.session_state
    c = ss.plan.cash
    gone, yr = c.rv_sale_proceeds, int(c.rv_sale_year)
    c.rv_sale_year = 0
    ss[f"cap_sy_{ss.data_ver}"] = ""                    # the update form must not still hold the old year, or a later Save would put the sale back
    ss.cap_msg = (f"The RV sale is removed. The RV stays in your capital assets and keeps losing value each year. Your cash flow no longer counts "
                  f"{money(gone)} in {yr}, so cash is lower from {yr} on. If you do sell it, enter the sale year under Update values.")


def cb_cap_add():
    ss = st.session_state
    plan, ver = ss.plan, ss.data_ver
    name, v, r = (ss.get(f"cap_new_n_{ver}") or "").strip(), parse_money(ss.get(f"cap_new_v_{ver}") or ""), parse_money(ss.get(f"cap_new_r_{ver}") or "0")
    if not name or v is None or v < 0 or r is None or not -50 <= r <= 50:
        ss.cap_msg = "To add an asset, enter a name, a value, and a yearly change between -50 and 50 percent."
        return
    if name.lower() in {x["name"].lower() for x in capital_items(plan)}:
        ss.cap_msg = f"{name} is already in the list."
        return
    plan.meta["capital_items"].append({"name": name, "value": float(v), "rate": float(r) / 100.0, "until": None})
    ss.cap_msg = f"{name} added. Capital assets are now {money(capital_total_now(plan), 2)}."


def cb_cap_remove():
    ss = st.session_state
    plan, ver = ss.plan, ss.data_ver
    name = ss.get(f"cap_rm_{ver}")
    keep = [x for x in plan.meta["capital_items"] if x["name"] != name]
    if not name or len(keep) == len(plan.meta["capital_items"]) or not keep:
        ss.cap_msg = "Pick an asset to remove. The list keeps at least one asset besides the RV."
        return
    plan.meta["capital_items"] = keep
    ss.cap_msg = f"{name} removed. Capital assets are now {money(capital_total_now(plan), 2)}."


def _cap_change_text(it):
    r = float(it["rate"]) * 100
    txt = f"{r:+g}% a year"
    if it.get("until") is not None:
        txt += f" through {int(it['until'])}, then flat"
    if it.get("sale_year"):
        txt += f", sold in {int(it['sale_year'])}"
    return txt


def render_capital_card(plan, on_close=None):
    ss = st.session_state
    ver = ss.data_ver
    with _card("cap_card"):
        h = st.columns([6, 1], gap="small", vertical_alignment="center")
        h[0].markdown("**Capital assets**")
        h[1].button("Close", key="cap_close", on_click=on_close or cb_cap_toggle)
        items = capital_items(plan)
        if not items:
            st.info("The itemized list is not in your data yet. Open Your data, then Import earlier months, and load the history file: it adds the house, "
                    "RV, Jeep and Mustang from your workbook. The monthly total above keeps working in the meantime.")
            return
        if ss.get("cap_msg"):
            st.info(_esc(ss.cap_msg))
        rows = []
        for it in items:
            note = ""
            if it.get("linked"):
                note = f"{money(plan.cash.rv_sale_proceeds)} to cash in {int(it['sale_year'])}" if it.get("sale_year") else "Kept: no sale assumed"
            elif it.get("until") is not None:
                note = f"Stops rising after {int(it['until'])}"
            rows.append({"Asset": it["name"], "Value today": it["value"], "Yearly change": _cap_change_text(it), "Notes": note})
        rows.append({"Asset": "Total", "Value today": capital_total_now(plan), "Yearly change": "", "Notes": ""})
        st.markdown(html_table(pd.DataFrame(rows), money_cols=("Value today",), bold_last=True), unsafe_allow_html=True)
        if plan.cash.rv_sale_year:
            caption("The RV is sold in the plan, and its sale proceeds are the cash in your cash flow, so changing the RV changes both.")
            st.button("Remove the RV sale from the plan", key=f"cap_rmsale_{ver}", on_click=cb_cap_remove_sale,
                      help="Keeps the RV as something you own. Cash flow stops counting the sale until you enter a sale year again.")
        else:
            caption("No RV sale is assumed. The RV stays in your capital assets and keeps losing value each year, like your other vehicles. "
                    "If you decide to sell, enter the year under Update values.")
        with st.expander("Update values, add an asset or remove one"):
            caption("Change a value or yearly change and click Save values. To add an asset, fill in the Add an asset row. To put the new total on a month's "
                    "balance, open Monthly updates, Balances, Work out capital assets from the list, and click Use this figure.")
            for it in items:
                s = _slug(it["name"])
                c1, c2, c3 = st.columns([2, 2, 2], gap="small", vertical_alignment="bottom")
                c1.markdown(f"**{it['name']}**")
                c2.text_input("Value today", value=f"{it['value']:.2f}", key=f"cap_v_{ver}_{s}")
                c3.text_input("Yearly change, percent (negative for a loss)", value=f"{float(it['rate']) * 100:g}", key=f"cap_r_{ver}_{s}")
            rv = next(x for x in items if x.get("linked"))
            st.text_input("RV sale year (leave blank for no sale)", value=str(int(rv["sale_year"])) if rv.get("sale_year") else "", key=f"cap_sy_{ver}")
            st.button("Save values", key=f"cap_save_{ver}", on_click=cb_cap_save)
            st.markdown("**Add an asset**")
            a1, a2, a3, a4 = st.columns([2, 2, 2, 1], gap="small", vertical_alignment="bottom")
            a1.text_input("Name", key=f"cap_new_n_{ver}", placeholder="Name of the asset")
            a2.text_input("Value today", key=f"cap_new_v_{ver}", placeholder="25000")
            a3.text_input("Yearly change, percent", key=f"cap_new_r_{ver}", placeholder="-5")
            a4.button("Add", key=f"cap_add_{ver}", on_click=cb_cap_add)
            r1, r2 = st.columns([3, 1], gap="small", vertical_alignment="bottom")
            r1.selectbox("Remove an asset", [x["name"] for x in items if not x.get("linked")], key=f"cap_rm_{ver}")
            r2.button("Remove", key=f"cap_rmgo_{ver}", on_click=cb_cap_remove)
        st.markdown("**Forecast by year**")
        start = int(str(plan.meta.get("as_of", "2026-08-31"))[:4])
        fc = capital_forecast(plan, range(start, 2035))
        st.markdown(html_table(fc, money_cols=[c for c in fc.columns if c != "Year"]), unsafe_allow_html=True)
        caption("Values today are entered above. The forecast applies each asset's yearly change from this year on, and the RV drops to zero when it is sold.")


def _nw_go(view):
    st.session_state.nw_view = view


def goto_networth(view="hub"):
    """Open Net worth at one of its views (the Dashboard's growth tile opens the growth view directly)."""
    ss = st.session_state
    ss["page"] = "Net worth"
    ss.nw_view_next = view


def _nw_back():
    back_bar("‹ Net worth", _nw_go, ("hub",), "nw_back")


def page_networth():
    """v21.42: a dashboard of tiles, one per part of net worth; each opens its own view with a way back."""
    ss = st.session_state
    view = ss.get("nw_view") or "hub"
    rows = networth_table(ss.entries)
    done = [r for r in rows if r["complete"]]
    if view == "hub":
        _nw_hub(ss, rows, done)
        return
    _nw_back()
    if view == "latest":
        _nw_latest(rows, done)
    elif view == "history":
        _nw_history(rows, done)
    elif view == "capital":
        st.title("Capital assets")
        render_capital_card(ss.plan, on_close=lambda: _nw_go("hub"))
    elif view == "growth":
        _nw_growth(ss)
    elif view == "growthm":
        _nw_growth_months(ss)
    elif view == "forecast":
        st.title("Net worth forecast")
        if done:
            networth_forecast(ss.plan)
        else:
            st.info("The forecast starts from a month with all nine accounts entered.")
    else:
        _nw_go("hub")
        st.rerun()


def _nw_hub(ss, rows, done):
    plan, entries = ss.plan, ss.entries
    st.title("Net worth")
    caption("Tap a tile to open it. Each month's balances are entered on Monthly updates, in the Balances tab.")
    cur = done[-1] if done else None
    G = investment_growth(plan, entries, today().year, today())
    M = G.get("monthly") or [] if G["ok"] else []
    lastm = M[-1] if M else None
    F = nw_forecast(plan, _fc_rate()) if done else None
    fl = F["years"][-1] if F else None
    caps = capital_items(plan)
    T = lambda key, label, value, kind, note, extra, view: {"key": key, "label": label, "value": value, "kind": kind, "note": note, "extra": extra,
                                                            "go": (lambda v=view: _nw_go(v))}
    tiles = [
        T("nw_latest", "Net worth", money_m(cur["net_worth"]) if cur else "—", "idle",
          f"Financial assets {money_m(cur['assets'])}" if cur else "No month with all nine accounts yet",
          (f"As of {month_short(cur['month'])}" + (f"\n{signed(cur['change'])} on the month" if cur["change"] is not None else "")) if cur else "", "latest"),
        T("nw_history", "Month by month", f"{len(rows)} month{'s' if len(rows) != 1 else ''}" if rows else "—", "idle",
          "Every account, each month", f"{len(done)} with all nine accounts" if rows else "Enter balances on Monthly updates", "history"),
        T("nw_capital", "Capital assets", money(capital_total_now(plan)) if caps else (money(cur["capital"] or 0.0) if cur else "—"), "idle",
          f"{len(caps)} asset{'s' if len(caps) != 1 else ''}" if caps else "Not itemized yet", "Values and yearly change", "capital"),
        T("nw_growth", "Investment growth", f"{_gpct(G['ret'])} YTD" if G["ok"] else "—", G["status"] if G["ok"] else "idle",
          growth_words(G) if G["ok"] else "Not set up yet", f"Forecast year end {_gpct(G['annual'])}" if G["ok"] else "1 January values needed", "growth"),
        T("nw_growthm", "Growth by month", f"{_gpct(lastm['ret'], 2)} in {lastm['label'][:3]}" if lastm and lastm["ret"] is not None else "—", "idle",
          "Roll-up or one account", f"{len(M)} month{'s' if len(M) != 1 else ''} so far" if M else "", "growthm"),
        T("nw_forecast", "Forecast", money_m(F["nb"][fl]) if F else "—", "idle", f"Net worth in {fl}" if F else "Not available",
          f"2035: {money_m(F['nb'][2035])}" if F and 2035 in F["nb"] else "", "forecast"),
    ]
    with _tile_area():
        for r0 in range(0, len(tiles), TILES_PER_ROW):
            chunk = tiles[r0:r0 + TILES_PER_ROW]
            cols = st.columns(len(chunk), gap="small")
            for i, t in enumerate(chunk):
                with cols[i]:
                    _segment(t["key"], "cash", "first" if i == 0 else ("last" if i == len(chunk) - 1 else "mid"), t["label"], t["value"], t["kind"],
                             t["note"], "", t["extra"], go=t["go"])


def _nw_latest(rows, done):
    st.title("Net worth")
    if not done:
        st.info("No month has all nine accounts yet, so there are no totals. The balances entered so far are under Month by month.")
        return
    cur = done[-1]
    m = st.columns(3, gap="small")
    m[0].metric("Net worth", money(cur["net_worth"], 2), help=f"As of {month_label(cur['month'])}")
    m[1].metric("Financial assets", money(cur["assets"], 2))
    m[2].metric("Change since last month", signed(cur["change"]) if cur["change"] is not None else "First month")
    st.subheader(f"Latest month: {month_label(cur['month'])}")
    lines = [{"Account": lab, "Balance": cur[k], "Share of financial assets": f"{100.0 * cur[k] / cur['assets']:.1f}%" if cur["assets"] else ""}
             for k, lab in ACCOUNT_LABELS]
    lines.append({"Account": "Financial assets", "Balance": cur["assets"], "Share of financial assets": "100.0%"})
    lines.append({"Account": "Capital assets", "Balance": cur["capital"], "Share of financial assets": ""})
    lines.append({"Account": "Net worth", "Balance": cur["net_worth"], "Share of financial assets": ""})
    st.dataframe(pd.DataFrame(lines), hide_index=True, column_config={"Balance": st.column_config.NumberColumn(format="dollar")})


def _nw_history(rows, done):
    st.title("Net worth month by month")
    if not rows:
        st.info("No balances entered yet. Enter them on Monthly updates, in the Balances tab.")
        return
    # v21.47: months across, accounts down, whole dollars, one year at a time, so the table fits an iPad without scrolling sideways
    ss = st.session_state
    years = sorted({r["month"][:4] for r in rows}, reverse=True)
    yr = st.selectbox("Year", years, index=years.index(ss.get("nw_hist_year")) if ss.get("nw_hist_year") in years else 0, key="nw_hist_sel",
                      on_change=lambda: ss.__setitem__("nw_hist_year", ss.nw_hist_sel))
    yrows = [r for r in rows if r["month"][:4] == yr]
    short = {"wells": "Wells cash", "schwabTax": "Schwab taxable", "schwabIra": "Schwab IRA", "empower": "DefComp", "sipp": "SIPP",
             "planeasy": "Planeasy", "wellsAnn": "Wells annuities", "hsa": "HSA", "etrade": "E*TRADE"}
    cell = lambda v: (("\u2212" if v < 0 else "") + f"{abs(v) / 1000:,.0f}") if isinstance(v, (int, float)) else ""     # $ thousands: a year fits an iPad
    lines = [{"$ thousands": short.get(k, lab)} | {MONTH_NAMES[int(r["month"][5:]) - 1][:3]: cell(r[k]) for r in yrows} for k, lab in ACCOUNT_LABELS]
    lines += [{"$ thousands": "Financial assets"} | {MONTH_NAMES[int(r["month"][5:]) - 1][:3]: cell(r["assets"]) for r in yrows},
              {"$ thousands": "Capital assets"} | {MONTH_NAMES[int(r["month"][5:]) - 1][:3]: cell(r["capital"]) for r in yrows},
              {"$ thousands": "Change"} | {MONTH_NAMES[int(r["month"][5:]) - 1][:3]: (("+" if r["change"] >= 0 else "") + cell(r["change"])) if r["change"] is not None else "" for r in yrows},
              {"$ thousands": "Net worth"} | {MONTH_NAMES[int(r["month"][5:]) - 1][:3]: cell(r["net_worth"]) for r in yrows}]
    tdf = pd.DataFrame(lines)
    st.markdown("<div class='nwgrid'>" + html_table(tdf, bold_last=True, right_cols=tuple(c for c in tdf.columns if c != "$ thousands")) + "</div>", unsafe_allow_html=True)
    caption("Figures are in thousands of dollars (1,471 is $1,471,000). Change is the move in net worth from the month before, including money arriving (for example the annuities in February).")
    if len(done) >= 2:
        fig = go.Figure()
        for name, key, col in (("Net worth", "net_worth", NAVY), ("Financial assets", "assets", BRASS)):
            fig.add_trace(go.Scatter(x=[month_short(r["month"]) for r in done], y=[r[key] for r in done], mode="lines+markers", name=name, line=dict(color=col, width=2)))
        fig.update_layout(height=260, margin=dict(l=8, r=8, t=8, b=8), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)", legend=dict(orientation="h", y=-0.25))
        fig.update_yaxes(tickprefix="$", tickformat="~s")
        _plotly(fig, key="g_networth")
    else:
        caption("The trend chart appears once two months of balances are entered.")
    caption("Totals appear only for a month in which all nine accounts were entered. Capital assets are entered as one figure each month.")


