# ---- investment growth (v21.39): the real return on the invested accounts this year, against the 6.5% aim and the 5% need ------------------
GROWTH_ACCOUNTS = [("schwabTax", "Schwab taxable"), ("schwabIra", "Schwab IRA"), ("sipp", "MES SIPP")]     # E*TRADE (about $5K) left out
GROWTH_AIM, GROWTH_NEED = 0.065, 0.05


def _growth_store(entries: dict) -> dict:
    g = entries.setdefault("inv_growth", {})
    for k in ("start", "values", "flows"):
        g.setdefault(k, {})
    return g


def growth_value(entries: dict, acct: str, month: str):
    """An account's month-end value: a value entered for growth (from the statement, exact to the day) where there is one, otherwise the month's
    recorded balance from Monthly updates."""
    v = (entries.get("inv_growth", {}).get("values", {}).get(month) or {}).get(acct)
    if isinstance(v, (int, float)):
        return float(v)
    b = entries.get("balances", {}).get(month, {})
    return float(b[acct]) if isinstance(b.get(acct), (int, float)) else None


def growth_flow(plan, entries: dict, acct: str, month: str) -> float:
    """Money moved into (+) or out of (-) an account in a month, as entered. The SIPP's monthly payment out is filled in from the plan when no
    figure has been entered for that month (it pays every month, so leaving it out would read as a loss)."""
    f = (entries.get("inv_growth", {}).get("flows", {}).get(month) or {})
    if isinstance(f.get(acct), (int, float)):
        return float(f[acct])
    if acct == "sipp":
        s = (plan.meta or {}).get("sipp") or {}
        if isinstance(s.get("gbp_month"), (int, float)):
            return -float(s["gbp_month"]) * float(s.get("fx") or 1.0)
    return 0.0


def _dietz_chain(points: list, flows: dict, month_index) -> float | None:
    """Chain-linked Modified Dietz: between each pair of valuation points the gain is the change in value less the money moved in or out, over
    the starting value plus each flow weighted by the share of the period it was invested (a flow counts from the middle of its month)."""
    total = 1.0
    for (ma, va), (mb, vb) in zip(points, points[1:]):
        ia, ib = month_index(ma), month_index(mb)
        span = ib - ia
        fl = [(m, a) for m, a in flows.items() if ia < month_index(m) <= ib]
        net = sum(a for _, a in fl)
        base = va + sum(a * (ib - month_index(m) + 0.5) / span for m, a in fl)
        if base <= 0:
            return None
        total *= 1 + (vb - va - net) / base
    return total - 1


def investment_growth(plan, entries: dict, year: int, today_date) -> dict:
    """The year's return on the invested accounts (Schwab taxable and IRA, the SIPP, E*TRADE), from 1 January to the latest month-end with a
    value for every one of them. Money moved in or out is taken out, so a deposit is not growth and a withdrawal is not a loss."""
    g = entries.get("inv_growth", {})
    start = g.get("start", {}).get(str(year)) or {}
    accts = [a for a, _ in GROWTH_ACCOUNTS]
    missing = [lab for a, lab in GROWTH_ACCOUNTS if not isinstance(start.get(a), (int, float))]
    if missing:
        return {"ok": False, "why": "Needs the 1 January value for " + ", ".join(missing) + "."}
    last = f"{today_date.year}-{today_date.month:02d}"
    months = [f"{year}-{m:02d}" for m in range(1, 13) if f"{year}-{m:02d}" < last]
    full = [m for m in months if all(growth_value(entries, a, m) is not None for a in accts)]
    if not full:
        return {"ok": False, "why": "Needs a month-end value for every invested account."}
    end = full[-1]
    idx = lambda m: 0 if m == "start" else int(m[5:7])
    upto = [m for m in months if m <= end]
    flows = {m: {a: growth_flow(plan, entries, a, m) for a in accts} for m in upto}
    pts = [("start", sum(float(start[a]) for a in accts))] + [(m, sum(growth_value(entries, a, m) for a in accts)) for m in full]
    r = _dietz_chain(pts, {m: sum(flows[m].values()) for m in upto}, idx)
    if r is None:
        return {"ok": False, "why": "The values entered do not add up to a return."}
    n = idx(end)
    annual = (1 + r) ** (12 / n) - 1
    rows = []
    for a, lab in GROWTH_ACCOUNTS:
        ap = [("start", float(start[a]))] + [(m, growth_value(entries, a, m)) for m in upto if growth_value(entries, a, m) is not None]
        ra = _dietz_chain(ap, {m: flows[m][a] for m in upto}, idx)
        sv, ev, net = float(start[a]), growth_value(entries, a, end), sum(flows[m][a] for m in upto)
        rows.append({"acct": a, "label": lab, "start": sv, "net": net, "end": ev, "gain": ev - sv - net, "ret": ra,
                     "annual": (1 + ra) ** (12 / n) - 1 if ra is not None and ra > -1 else None})
    sv, ev = pts[0][1], pts[-1][1]
    net = sum(sum(f.values()) for f in flows.values())
    status = "ok" if annual >= GROWTH_AIM else ("warn" if annual >= GROWTH_NEED else "bad")
    return {"ok": True, "year": year, "end": end, "months": n, "start": sv, "end_value": ev, "net": net, "gain": ev - sv - net,
            "ret": r, "annual": annual, "status": status, "rows": rows, "monthly": growth_by_month(pts, flows, start, entries, idx),
            "_flows": flows, "_start": start, "_upto": upto, "_entries": entries,
            "entered_flows": sorted(entries.get("inv_growth", {}).get("flows", {}))}


def growth_account_months(G: dict, acct: str) -> list:
    """v21.42: the same month-by-month view for one account: its own month-end values and its own money in or out."""
    entries, flows, start = G["_entries"], G["_flows"], G["_start"]
    idx = lambda m: 0 if m == "start" else int(m[5:7])
    out, cum, prev = [], 1.0, ("start", float(start[acct]))
    for m in G["_upto"]:
        v = growth_value(entries, acct, m)
        if v is None:
            continue
        span = [x for x in flows if idx(prev[0]) < idx(x) <= idx(m)]
        net = sum(flows[x][acct] for x in span)
        r = _dietz_chain([prev, (m, v)], {x: flows[x][acct] for x in span}, idx)
        if r is not None:
            cum *= 1 + r
        label = month_short(m) if len(span) == 1 else f"{month_short(span[0])[:3]}–{month_short(m)}"
        out.append({"month": m, "label": label, "start": prev[1], "net": net, "end": v, "gain": v - prev[1] - net, "ret": r,
                    "ytd": cum - 1 if r is not None else None})
        prev = (m, v)
    return out


def growth_by_month(pts: list, flows: dict, start: dict, entries: dict, idx) -> list:
    """v21.40: the growth for each month (or each run of months between two month-ends that have every value), account by account and in total,
    with the period's return and the year so far linked month to month. Uses the same Modified Dietz as the year figure, so they agree."""
    out, cum = [], 1.0
    for (ma, va), (mb, vb) in zip(pts, pts[1:]):
        span = [m for m in flows if idx(ma) < idx(m) <= idx(mb)]
        gains = {}
        for a, _ in GROWTH_ACCOUNTS:
            a0 = float(start[a]) if ma == "start" else growth_value(entries, a, ma)
            gains[a] = growth_value(entries, a, mb) - a0 - sum(flows[m][a] for m in span)
        r = _dietz_chain([(ma, va), (mb, vb)], {m: sum(flows[m].values()) for m in span}, idx)
        if r is not None:
            cum *= 1 + r
        label = month_short(mb) if len(span) == 1 else f"{month_short(span[0])[:3]}–{month_short(mb)}"
        out.append({"month": mb, "label": label, "start": va, "net": sum(sum(flows[m].values()) for m in span), "end": vb,
                    "gains": gains, "gain": sum(gains.values()), "ret": r, "ytd": cum - 1 if r is not None else None})
    return out


def growth_words(G: dict) -> str:
    if G["status"] == "ok":
        return f"Ahead of the {GROWTH_AIM * 100:g}% aim"
    if G["status"] == "warn":
        return f"Below the {GROWTH_AIM * 100:g}% aim, above the {GROWTH_NEED * 100:g}% needed"
    return f"Below the {GROWTH_NEED * 100:g}% needed"


def _gpct(x, d=1):          # v21.42: renamed from _pct, which hid the DefComp page's own _pct (rates showed as '+5.0%%')
    return "—" if x is None else f"{'+' if x >= 0 else '−'}{abs(x) * 100:.{d}f}%"


def growth_detail(G: dict, monthly: bool = True):
    """The detail under the growth tile: the year so far, account by account, against the aim and the need."""
    st.subheader(f"Investment growth, {G['year']}")
    st.markdown(f"**{_gpct(G['ret'])} YTD**, from 1 January to the end of {month_label(G['end'])}. Forecast year end **{_gpct(G['annual'])}** "
                f"if the rest of the year keeps the same pace. {growth_words(G)}.")
    rows = [{"Account": r["label"], "1 Jan": money(r["start"]), "Money in or out": signed(r["net"]) if abs(r["net"]) >= 0.5 else "—",
             f"End of {month_short(G['end'])}": money(r["end"]), "Growth": signed(r["gain"]), "Return YTD": _gpct(r["ret"]), "Forecast year end": _gpct(r["annual"])}
            for r in G["rows"]]
    rows.append({"Account": "Invested accounts", "1 Jan": money(G["start"]), "Money in or out": signed(G["net"]) if abs(G["net"]) >= 0.5 else "—",
                 f"End of {month_short(G['end'])}": money(G["end_value"]), "Growth": signed(G["gain"]), "Return YTD": _gpct(G["ret"]), "Forecast year end": _gpct(G["annual"])})
    st.markdown(html_table(pd.DataFrame(rows), bold_last=True, right_cols=tuple(c for c in rows[0] if c != "Account")), unsafe_allow_html=True)
    caption(f"The aim is {GROWTH_AIM * 100:g}% a year; {GROWTH_NEED * 100:g}% is what the plan needs once these are drawn on, which is not "
            "expected for at least five years, so one year above or below matters less than the long-run average. Money moved in or out "
            "(deposits, withdrawals, the SIPP's monthly payment) is taken out, so it is neither growth nor a loss. Wells cash, DefComp (a fixed "
            "5%), the annuities (fixed until 2031), the HSA and the small E*TRADE account are not included.")
    if monthly:
        growth_monthly_detail(G)


def growth_monthly_detail(G: dict, acct: str | None = None, title: bool = True):
    """v21.40: month by month, the growth in each invested account and in total, the month's return and the year so far.
    v21.42: acct shows one account alone (its start value, money in or out, growth and return each month)."""
    labs = dict(GROWTH_ACCOUNTS)
    if acct is None:
        rows_m = G.get("monthly") or []
        if not rows_m:
            return
        if title:
            st.markdown(f"**Month by month, {G['year']}**")
        rows = [{"Month": r["label"]} | {labs[a]: signed(r["gains"][a]) for a, _ in GROWTH_ACCOUNTS}
                | {"Money in or out": signed(r["net"]) if abs(r["net"]) >= 0.5 else "—", "Value at month-end": money(r["end"]),
                   "Growth": signed(r["gain"]), "Return": _gpct(r["ret"], 2), "Year so far": _gpct(r["ytd"], 2)}
                for r in rows_m]
        tot = {"Month": "Year so far"} | {labs[a]: signed(x["gain"]) for a, _ in GROWTH_ACCOUNTS for x in G["rows"] if x["acct"] == a} \
              | {"Money in or out": signed(G["net"]) if abs(G["net"]) >= 0.5 else "—", "Value at month-end": money(G["end_value"]),
                 "Growth": signed(G["gain"]), "Return": _gpct(G["ret"], 2), "Year so far": _gpct(G["ret"], 2)}
    else:
        rows_m = growth_account_months(G, acct)
        if not rows_m:
            st.info(f"No month-end values for {labs[acct]} yet.")
            return
        if title:
            st.markdown(f"**{labs[acct]}, month by month, {G['year']}**")
        rows = [{"Month": r["label"], "Value at start": money(r["start"]), "Money in or out": signed(r["net"]) if abs(r["net"]) >= 0.5 else "—",
                 "Growth": signed(r["gain"]), "Value at month-end": money(r["end"]), "Return": _gpct(r["ret"], 2), "Year so far": _gpct(r["ytd"], 2)}
                for r in rows_m]
        A = next(x for x in G["rows"] if x["acct"] == acct)
        tot = {"Month": "Year so far", "Value at start": money(A["start"]), "Money in or out": signed(A["net"]) if abs(A["net"]) >= 0.5 else "—",
               "Growth": signed(A["gain"]), "Value at month-end": money(A["end"]), "Return": _gpct(A["ret"], 2), "Year so far": _gpct(A["ret"], 2)}
    rows.append(tot)
    st.markdown(html_table(pd.DataFrame(rows), bold_last=True, right_cols=tuple(c for c in rows[0] if c != "Month")), unsafe_allow_html=True)
    done = [r for r in rows_m if r["ret"] is not None]
    if len(done) >= 2:
        fig = go.Figure()
        fig.add_trace(go.Bar(x=[r["label"] for r in done], y=[r["ret"] * 100 for r in done], name="Month's return",
                             marker_color=[NAVY if r["ret"] >= 0 else "#B5533C" for r in done]))
        fig.add_trace(go.Scatter(x=[r["label"] for r in done], y=[r["ytd"] * 100 for r in done], name="Year so far",
                                 mode="lines+markers", line=dict(color=BRASS, width=2)))
        fig.update_layout(height=260, margin=dict(l=8, r=8, t=8, b=8), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                          legend=dict(orientation="h", y=-0.2))
        fig.update_yaxes(ticksuffix="%")
        _plotly(fig, key=f"g_growth_monthly_{acct or 'all'}")
    caption("Growth is the change in value less the money moved in or out that month. A month shown as a range (for example Jan–Mar) is "
            "one where an account had no month-end value, so the months are reported together. For 2026, the SIPP's months between its "
            "quarterly statements were spread evenly across the quarter.")


def growth_editor(plan, entries: dict, year: int):
    """Net worth page: the 1 January values, values for months before the monthly balances began, and money moved in or out each month."""
    g = _growth_store(entries)
    ss = st.session_state
    caption("The growth tile needs each invested account's value on 1 January, a value at any month-end before the monthly balances began, "
            "and the money moved in or out each month (+ in, − out; a move between your own Schwab accounts is not a move in or out). "
            "A value typed here (from the statement) is used ahead of the month's balance from Monthly updates. The SIPP's monthly payment fills in by itself for a month left blank.")
    labs = dict(GROWTH_ACCOUNTS)
    last = f"{today().year}-{today().month:02d}"
    months = [f"{year}-{m:02d}" for m in range(1, 13) if f"{year}-{m:02d}" < last]
    st_row = {"Month": f"1 Jan {year}"} | {labs[a]: (g["start"].get(str(year)) or {}).get(a) for a, _ in GROWTH_ACCOUNTS}
    vrows = [st_row] + [{"Month": month_label(m)} | {labs[a]: growth_value(entries, a, m) for a, _ in GROWTH_ACCOUNTS} for m in months]
    st.markdown("**Values**")
    ve = st.data_editor(pd.DataFrame(vrows), hide_index=True, disabled=["Month"], key=f"gr_vals_{year}_{ss.data_ver}",
                        column_config={labs[a]: st.column_config.NumberColumn(format="dollar") for a, _ in GROWTH_ACCOUNTS})
    frows = [{"Month": month_label(m)} | {labs[a]: (g["flows"].get(m) or {}).get(a) for a, _ in GROWTH_ACCOUNTS} for m in months]
    st.markdown("**Money moved in (+) or out (−)**")
    fe = st.data_editor(pd.DataFrame(frows), hide_index=True, disabled=["Month"], key=f"gr_flows_{year}_{ss.data_ver}",
                        column_config={labs[a]: st.column_config.NumberColumn(format="dollar") for a, _ in GROWTH_ACCOUNTS})
    if st.button("Save growth figures", key=f"gr_go_{year}_{ss.data_ver}"):
        num = lambda v: float(v) if isinstance(v, (int, float)) and v == v else None
        vr = ve.to_dict("records")
        g["start"][str(year)] = {a: num(vr[0][labs[a]]) for a, _ in GROWTH_ACCOUNTS if num(vr[0][labs[a]]) is not None}
        for m, row in zip(months, vr[1:]):
            bal = entries.get("balances", {}).get(m, {})
            keep = {a: num(row[labs[a]]) for a, _ in GROWTH_ACCOUNTS if num(row[labs[a]]) is not None
                    and not (isinstance(bal.get(a), (int, float)) and abs(float(bal[a]) - num(row[labs[a]])) < 0.005)}
            if keep:
                g["values"][m] = keep
            else:
                g["values"].pop(m, None)
        for m, row in zip(months, fe.to_dict("records")):
            keep = {a: num(row[labs[a]]) for a, _ in GROWTH_ACCOUNTS if num(row[labs[a]]) is not None}
            if keep:
                g["flows"][m] = keep
            else:
                g["flows"].pop(m, None)
        ss.gr_msg = "Growth figures saved."
        st.rerun()
    if ss.get("gr_msg"):
        st.success(ss.pop("gr_msg"))


# ---- Estele's view (v21.32; button moved under the bands in v21.33): a simple four-tile view of cash, net worth and the forecast ----------------------------------------
def wells_cash_accounts(plan, entries: dict, inbox: dict | None) -> dict | None:
    """The Wells accounts that make up cash (savings, money market, checking): each one's balance now and at the end of every month
    the fetch has a snapshot for, and its posted transactions (the fetch keeps about 100 days)."""
    live = wells_live_balance(plan, entries, inbox)
    if not live:
        return None
    total, asof, parts, _t = live
    snaps = (inbox or {}).get("snapshots") or {}
    mapping = income_inbox_mapping(plan, inbox)
    snap = snaps[max(snaps)]
    ids = [a["id"] for a in snap.get("accounts") or [] if mapping.get(a.get("id")) == "wells" and a.get("balance") is not None]
    accts = [{"id": i, "name": n, "now": b} for i, (n, b) in zip(ids, parts)]          # same order as wells_live_balance builds them
    ends = {k: {a["id"]: float(a["balance"]) for a in (v.get("accounts") or []) if a.get("balance") is not None} for k, v in snaps.items()}
    lines = [ln for ln in (inbox or {}).get("lines") or [] if ln.get("acct") in set(ids)]
    return {"total": total, "asof": asof, "accounts": accts, "month_end": ends, "lines": lines}


def _prev_month_key(d: _dt.date) -> str:
    return (d.replace(day=1) - _dt.timedelta(days=1)).strftime("%Y-%m")


# ---- actions: everything that needs you, in one list (v21.62) -------------------------------------------------------------------------------
# The status bar at the top of the sidebar counts these on every page, and opens the Actions page; each action opens the place to deal with it.
# It replaces the warning banners that used to sit at the top of pages. Every check is the one the Dashboard tiles or the old banners used,
# so the bar, the tiles and the pages never disagree. A check that fails is skipped, never allowed to stop the app.
def goto_spending(view="main"):
    ss = st.session_state
    ss["page"] = "Spending"
    ss.sp_view_next = view
    ss.sp_view = view


def _act_month(k):
    goto_updates("hub")
    goto_month(k)


def collect_actions(plan, entries) -> list[dict]:
    out = []

    def add(level, area, title, detail="", go=None, args=()):
        out.append({"level": level, "area": area, "title": title, "detail": detail, "go": go, "args": args})

    def safe(fn):
        try:
            fn()
        except Exception:  # noqa: BLE001
            pass

    months = month_list(plan, today())
    cur, _m = current_month_key()

    def _close():
        for k in months:
            s_ = month_status(plan, entries, k)
            if s_["ended"] and s_["overall"] != "Complete":
                add("bad" if s_["overall"] == "Overdue" else "warn", "Monthly updates",
                    f"{month_label(k)} {'is overdue' if s_['overall'] == 'Overdue' else 'is due ' + fmt_date(s_['due'])}",
                    "Still to do: " + ", ".join(s_["missing"]) + ".", _act_month, (k,))
    safe(_close)

    def _balance():
        minimum, target = min_balance(plan), top_up_target(plan)
        for a in balance_alerts_for(cur, True):
            if a["kind"] != "now" and transfer_covered(entries, a["month"], a["transfer"]):
                continue
            if a["kind"] != "now" and not transfer_due_soon(a["fix_date"], today()):
                continue
            add("bad" if a["kind"] == "now" else "warn", "Checking", alert_text(a, minimum, target), "Open Bank match to add the transfer.",
                goto_updates, ("bankmatch",))
    safe(_balance)

    def _bank():
        chk = _auto_bank_check()
        if chk and chk["status"] == "off":
            add("bad", "Checking", f"Wells and the ledger differ by {money(abs(chk['diff']), 2)}", "Bank match shows the likely cause.", goto_updates, ("bankmatch",))
        fresh = new_feed_accounts(plan, _inbox(), st.session_state.get("sfin_accts"))   # v25.38
        if fresh:
            add("warn", "Cards", (f"New account in the bank feed: {_card_short(fresh[0]['label'])}" if len(fresh) == 1
                                  else f"{len(fresh)} new accounts in the bank feed"),
                "Watch it as a card, or mark it as not needed.", goto_new_accounts)
        n = _inbox_waiting(entries)
        if n:
            add("warn", "Checking", f"{n} new bank line{'s' if n != 1 else ''} to review", "From the nightly fetch, before reconciling.", goto_updates, ("reconcile",))
        ib = _inbox()
        if ib:
            age = inbox_age_days(ib, today())
            if age is not None and age > INBOX_STALE_DAYS:
                add("bad", "Bank fetch", f"The nightly bank fetch last ran {age} days ago", "Check the Actions tab of your data repository on GitHub.", goto_data, ("save",))
            if ib.get("errors") and ib["errors"] != (ib.get("dismissed_errors") or []):
                add("bad", "Bank fetch", "The bank fetch reported a problem", "; ".join(ib["errors"])[:160], goto_updates, ("reconcile",))
    safe(_bank)

    def _sfin_fresh():                                   # v25.13: SimpleFIN still answering, but no longer getting new data from a bank
        ss_ = st.session_state
        if _sfin_url() and ss_.get("sfin_accts") is None and not ss_.get("sfin_load_tried"):
            ss_.sfin_load_tried = True                   # one small balances-only request per visit
            _sfin_list_accounts()
        for name, d, days in stale_accounts(plan, ss_.get("sfin_accts") or [], today()):
            add("warn", "Bank fetch", f"{name} is behind: SimpleFIN data from {fmt_date(d)}, {days} day{'s' if days != 1 else ''} older than your other accounts",
                "SimpleFIN has stopped getting new data for it. On the SimpleFIN Bridge site, remove that bank's connection and add it again; "
                "the app follows the new account numbers and picks up what it missed by itself.", goto_updates, ("reconcile",))
    safe(_sfin_fresh)

    def _cards():
        nc = len(_card_txn_plan(entries))
        if nc:
            add("warn", "Spending", f"{nc} new card charge{'s' if nc != 1 else ''} to review", "One-time spending, Card charges.", goto_card_charges)
    safe(_cards)

    def _unclassified():
        c = ledger_control(plan, entries, cur)
        if c["unclassified"]:
            add("warn", "Checking", f"{c['unclassified']} line{'s' if c['unclassified'] != 1 else ''} in {month_short(cur)} need a class", "Core, One-Time or Excluded.",
                goto_updates, ("reconcile",))
    safe(_unclassified)

    def _categories():
        y = today().year
        unc = category_rollup(plan, spending_items(plan, entries, y))["uncategorized"]
        if unc:
            add("warn", "Spending", f"{len(unc)} spending line{'s' if len(unc) != 1 else ''} need a category",
                "Give each a category or a rule, so spending by category is complete.", goto_spending, ("rollup",))
    safe(_categories)

    def _bills():
        sg = bill_amount_suggestions(plan, entries, today())
        if sg:
            add("warn", "Spending", f"{len(sg)} recurring bill{'s have' if len(sg) != 1 else ' has'} a suggested new amount", "What you really paid has drifted.",
                goto_spending, ("bills",))
        bl = all_recurring_bills(plan, entries, months, today(), today().year)
        nd = [b["name"] for b in bl if b.get("next") is None]
        if nd:
            add("warn", "Spending", f"{len(nd)} bill{'s have' if len(nd) != 1 else ' has'} no due date", ", ".join(nd)[:120], goto_spending, ("bills",))
    safe(_bills)

    def _budget():
        h = spend_control(spend_year())["headroom"]
        if h["headroom"] < 0:
            add("warn", "Spending", f"Spending is forecast {money(-h['headroom'])} over the {spend_year()} budget", "", goto_spending, ("budget",))
    safe(_budget)

    def _plan_checks():
        R = model()
        cs = R["cf_sum"]
        low = min(cs["lowest_ending_cash"], cs["bridge_low_point"])
        if float(cs.get("total_drawdown") or 0) > 0.5:
            add("warn", "Cash flow", cash_draw_status(cs, cash_warn_level(plan))[1], "Cash is kept at your safety line by drawing from investments.",
                goto_page, ("Cash flow",))
        elif low < cash_warn_level(plan):
            add("warn", "Cash flow", f"The low point, {money(low)}, is below your {money(cash_warn_level(plan))} warning line", "", goto_page, ("Cash flow",))
        m = R["aca"]
        if m["alert"] != "OK":
            add("bad" if m["alert"] != "EARLY WARNING" else "warn", "ACA",
                f"{R['aca_year']} MAGI is {'over the subsidy limit' if m['alert'] != 'EARLY WARNING' else 'above your early-warning line'}",
                f"Projected {money(m['projected_with_one_time'])} against a limit of {money(m['limit'])}.", goto_page, ("ACA",))
        tr = tbill_reminder(plan, today())             # v25.49
        if tr:
            add(tr["level"], "Investments", tr["title"], tr["detail"], goto_page, ("ACA",))
        t_, _alert = _tax_state(plan, R)
        if t_[2] in ("warn", "bad"):
            add(t_[2], "Tax payments", f"{t_[1]}: {t_[3]}", t_[4], goto_tax, ("sched",))
    safe(_plan_checks)

    def _keys():
        d = token_days_left()
        if d is not None and d <= 30:
            add("bad" if d <= 7 else "warn", "Your data", "Your GitHub access key has expired" if d < 0 else f"Your GitHub access key expires in {d} day{'s' if d != 1 else ''}",
                "Renew it so saving keeps working. The steps are on the Your data page.", goto_data, ("key",))
        if local_on() and st.session_state.get("sync_status") == "conflict":
            add("bad", "Your data", "Two versions of your data exist", "Nothing has been overwritten. Choose which copy to keep.", goto_data, ("save",))
    safe(_keys)
    rank = {"bad": 0, "warn": 1}
    return sorted(out, key=lambda a: rank.get(a["level"], 2))


