def sidebar_status(acts):
    """The status bar under the title: green with nothing to do, amber or red with the number of actions; tapping it opens the Actions page."""
    worst = "bad" if any(a["level"] == "bad" for a in acts) else ("warn" if acts else "ok")
    n = len(acts)
    label = f"●  {n} action{'s' if n != 1 else ''}" + ("  ·  all clear" if not n else " to look at")      # v21.63: the count always shows
    with st.sidebar.container(key=f"actbar_{worst}"):
        st.button(label, key="actbar_btn", on_click=cb_actions_open, use_container_width=True)


