def _estele_body(ss, plan, entries):
    st.title("Estele\u2019s view")      # v21.36: no Back button; tapping any page in the sidebar leaves this view
    W = wells_cash_accounts(plan, entries, _inbox())
    nw = latest_net_worth(entries)
    F = nw_forecast(plan, _fc_rate())
    last = F["years"][-1] if F else None
    t_cash = ("Wells cash", money(W["total"]) if W else "—", "idle", "Savings, checking and money market" if W else "No bank fetch yet",
              f"As of {W['asof'].replace('the fetch of ', '')}" if W else "")
    t_nw = ("Current net worth", money_m(nw["net_worth"]) if nw else "—", "idle",
            f"Financial assets {money_m(nw['assets'])}" if nw else "No complete month of balances yet", f"As of {month_short(nw['month'])}" if nw else "")
    t_fc = (f"Forecast net worth, {F['base'] * 100:g}%" if F else "Forecast net worth", money_m(F["nb"][last]) if F else "—", "idle",
            f"In {last}" if F else "Not available", f"2035: {money_m(F['nb'][2035])}" if F and 2035 in F["nb"] else "")
    t_gr = (f"Forecast at {F['rate'] * 100:g}%" if F else "Forecast at your rate", money_m(F["nr"][last]) if F else "—", "idle",
            f"In {last}" if F else "Not available", "Pick the growth rate inside")
    G = investment_growth(plan, entries, today().year, today())
    t_grow = ("Investment growth", f"{_gpct(G['ret'])} YTD" if G["ok"] else "—", G["status"] if G["ok"] else "idle",     # v21.41: as on the Dashboard
              growth_words(G) if G["ok"] else "Not set up yet", f"Forecast year end {_gpct(G['annual'])}" if G["ok"] else "")
    tiles = [("est_cash", t_cash), ("est_nw", t_nw), ("est_grow", t_grow), ("est_fc", t_fc), ("est_rate", t_gr)]
    with _tile_area():
        cols = st.columns(len(tiles), gap="small")
    for i, (col, (k, t)) in enumerate(zip(cols, tiles)):
        with col:
            _segment(k, "est", "first" if i == 0 else ("last" if i == len(tiles) - 1 else "mid"), t[0], t[1], t[2], t[3], None, t[4],
                     go=lambda k=k: _est_pick(k))
    pick = ss.get("est_tile", "est_cash")
    if pick == "est_cash":
        _est_cash(W)
    elif pick == "est_nw":
        _est_networth(entries, nw)
    elif pick == "est_grow":
        if G["ok"]:
            growth_detail(G)
        else:
            st.subheader("Investment growth")
            st.info(G["why"] + " They are entered on the Net worth page, under Investment growth.")
    elif pick == "est_fc":
        _est_forecast(F)
    else:
        st.subheader("Forecast net worth at a growth rate you pick")
        networth_forecast(plan, key="est_fc_rate", chart_key="g_est_rate")


def _est_cash(W):
    st.subheader("Wells cash")
    if not W:
        st.info("No balances from the bank yet. They arrive with the nightly bank fetch.")
        return
    months = sorted({ln["date"][:7] for ln in W["lines"]}, reverse=True)
    prev = _prev_month_key(today())
    if not months:
        months = [prev]
    mk = st.selectbox("Transactions for", months, index=months.index(prev) if prev in months else 0, format_func=month_label, key="est_month")
    end = W["month_end"].get(mk, {})
    rows = []
    for a in W["accounts"]:
        rows.append({"Account": a["name"], f"End of {month_short(mk)}": money(end[a["id"]], 2) if a["id"] in end else "—", "Now": money(a["now"], 2)})
    tot_end = sum(end[a["id"]] for a in W["accounts"] if a["id"] in end)
    rows.append({"Account": "Wells cash", f"End of {month_short(mk)}": money(tot_end, 2) if end else "—", "Now": money(W["total"], 2)})
    st.markdown(html_table(pd.DataFrame(rows), bold_last=True, right_cols=(f"End of {month_short(mk)}", "Now")), unsafe_allow_html=True)
    caption(f"Now is from {W['asof']}. The month-end figure is the last nightly fetch of that month. This total is the cash the cash flow starts from.")
    for a in W["accounts"]:
        ln = sorted((x for x in W["lines"] if x["acct"] == a["id"] and x["date"][:7] == mk), key=lambda x: x["date"])
        tin = sum(x["amount"] for x in ln if x["amount"] > 0)
        tout = -sum(x["amount"] for x in ln if x["amount"] < 0)
        with st.expander(f"{a['name']}: {len(ln)} transaction{'s' if len(ln) != 1 else ''} in {month_label(mk)} · in {money(tin)} · out {money(tout)}"):
            if not ln:
                caption("No transactions this month.")
                continue
            df = pd.DataFrame([{"Date": fmt_date(_dt.date.fromisoformat(x["date"])), "Description": x["desc"], "Amount": money(x["amount"], 2)} for x in ln]
                              + [{"Date": "", "Description": "Net for the month", "Amount": money(tin - tout, 2)}])
            st.markdown(html_table(df, bold_last=True, right_cols=("Amount",)), unsafe_allow_html=True)


def _est_networth(entries, nw):
    st.subheader("Current net worth")
    done = [r for r in networth_table(entries) if r["complete"]]
    if not done:
        st.info("No month has all nine account balances yet.")
        return
    cur = done[-1]
    rows = [{"Account": lab, "Balance": money(cur[k], 2)} for k, lab in ACCOUNT_LABELS]
    rows.append({"Account": "Financial assets", "Balance": money(cur["assets"], 2)})
    rows.append({"Account": "Capital assets (house, RV, vehicles)", "Balance": money(cur["capital"] or 0.0, 2)})
    rows.append({"Account": "Net worth", "Balance": money(cur["net_worth"], 2)})
    st.markdown(html_table(pd.DataFrame(rows), bold_last=True, right_cols=("Balance",)), unsafe_allow_html=True)
    caption(f"As of the end of {month_label(cur['month'])}, the latest month with every account's balance.")


def _est_forecast(F):
    if F is None:
        st.warning("The forecast could not be worked out.")
        return
    st.subheader(f"Forecast net worth at {F['base'] * 100:g}% growth")
    _fc_chart(F, "g_est_fc", False)
    years = F["years"]
    df = pd.DataFrame({"Year": [str(y) for y in years],
                       "Financial assets": [float(F["pb"].loc[y, "total_assets"]) for y in years],
                       "Capital assets": [F["cap"][y] for y in years],
                       "Net worth": [F["nb"][y] for y in years]})
    st.dataframe(df, hide_index=True, column_config={c: st.column_config.NumberColumn(format="dollar") for c in df.columns if c != "Year"})
    caption(f"The plan's own growth rate of {F['base'] * 100:g}% a year on the investments. " + FC_NOTE)


FC_DEFAULT_RATE = 0.065      # v21.32: where the comparison slider starts (the low end of the return expected on the investments)


def nw_forecast(plan, rate: float) -> dict | None:
    """v21.31: net worth by year to the end of the plan, at the plan's growth rate (base) and at `rate`. None if it cannot be worked out."""
    base = float(plan.portfolio.growth)
    pj, sj, ej = _model_json()
    try:
        pb = _portfolio_at_rate(pj, sj, ej, base)
        pr = _portfolio_at_rate(pj, sj, ej, rate)
    except Exception:  # noqa: BLE001 - a forecast problem should never take the page down
        return None
    years = list(pb.index)
    try:
        capf = capital_forecast(plan, years).set_index("Year")["Total"]
        cap = {y: float(capf.get(str(y), 0.0)) for y in years}
    except Exception:  # noqa: BLE001 - no capital assets entered: financial assets only
        cap = {y: 0.0 for y in years}
    return {"base": base, "rate": rate, "years": years, "cap": cap, "pb": pb, "pr": pr, "same": abs(rate - base) < 1e-9,
            "nb": {y: float(pb.loc[y, "total_assets"]) + cap[y] for y in years},
            "nr": {y: float(pr.loc[y, "total_assets"]) + cap[y] for y in years}}


def _fc_rate() -> float:
    return float(st.session_state.get("fc_rate", FC_DEFAULT_RATE))


def _fc_slider(key: str, base: float):
    """The comparison-rate slider. Its value is kept in fc_rate, so it is the same on the Net worth page and Estele's overview."""
    def _keep():
        st.session_state["fc_rate"] = st.session_state[key] / 100.0
    st.slider("Compare with a growth rate of (%)", 2.0, 10.0, round(_fc_rate() * 100, 2), 0.25, format="%.2f", key=key, on_change=_keep,
              help=f"The plan itself always uses {base * 100:.2f}%. This only changes the second line, not the plan.")


def _fc_breakdown(F: dict, p: pd.DataFrame, nw: dict):
    years = F["years"]
    bd = pd.DataFrame({"Year": [str(y) for y in years],
                       "Wells, Schwab taxable, E*TRADE": [float(p.loc[y, "end_taxable"]) for y in years],
                       "IRA, DefComp, SIPP": [float(p.loc[y, "end_pretax"]) for y in years],
                       "Annuities": [float(p.loc[y, "end_annuity"]) for y in years],
                       "HSA": [float(p.loc[y, "hsa"]) for y in years],
                       "Roth": [float(p.loc[y, "roth_balance"]) for y in years],
                       "Capital assets": [F["cap"][y] for y in years],
                       "Net worth": [nw[y] for y in years]})
    st.dataframe(bd, hide_index=True, column_config={c: st.column_config.NumberColumn(format="dollar") for c in bd.columns if c != "Year"})


def _fc_chart(F: dict, key: str, compare: bool):
    years, bl, rl = F["years"], f"at {F['base'] * 100:g}%", f"at {F['rate'] * 100:g}%"
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=years, y=[F["nb"][y] for y in years], mode="lines", name=f"Net worth {bl} (plan)", line=dict(color=NAVY, width=2.5)))
    if compare and not F["same"]:
        fig.add_trace(go.Scatter(x=years, y=[F["nr"][y] for y in years], mode="lines", name=f"Net worth {rl}", line=dict(color=BRASS, width=2.5, dash="dash")))
    fig.update_layout(height=300, margin=dict(l=8, r=8, t=8, b=8), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      legend=dict(orientation="h", y=-0.2), hovermode="x unified")
    fig.update_yaxes(tickprefix="$", tickformat="~s")
    _plotly(fig, key=key)


FC_NOTE = ("End-of-year values, starting from the latest complete month of balances. Spending, taxes, Roth conversions and deferred comp payments are "
           "the same at every growth rate; only the investment growth changes. Cash keeps its own interest rate and the annuities their contract rates "
           "through 2031. Capital assets follow their own yearly change.")


def networth_forecast(plan, key: str = "nw_fc_rate", chart_key: str = "g_nw_forecast"):
    """v21.31: net worth by year to the end of the plan -- at the plan's growth rate and at a rate picked on the slider."""
    base = float(plan.portfolio.growth)
    _fc_slider(key, base)
    F = nw_forecast(plan, _fc_rate())
    if F is None:
        st.warning("The forecast could not be worked out.")
        return
    years, nb, nr, same = F["years"], F["nb"], F["nr"], F["same"]
    bl, rl = f"at {base * 100:g}%", f"at {F['rate'] * 100:g}%"
    last = years[-1]
    mid = 2035 if 2035 in years else years[min(len(years) - 1, 8)]
    m = st.columns(2 if same else 3, gap="small")
    m[0].metric(f"Net worth {mid}, {bl}", money_m(nb[mid]))
    m[1].metric(f"Net worth {last}, {bl}", money_m(nb[last]))
    if not same:
        d = nr[last] - nb[last]
        m[2].metric(f"Net worth {last}, {rl}", money_m(nr[last]), delta=f"{'+' if d >= 0 else '-'}{money_m(abs(d))} vs plan")
    _fc_chart(F, chart_key, True)
    tbl = pd.DataFrame({"Year": [str(y) for y in years], f"Net worth {bl}": [nb[y] for y in years]})
    if not same:
        tbl[f"Net worth {rl}"] = [nr[y] for y in years]
        tbl["Difference"] = [nr[y] - nb[y] for y in years]
    st.dataframe(tbl, hide_index=True, column_config={c: st.column_config.NumberColumn(format="dollar") for c in tbl.columns if c != "Year"})
    with st.expander(f"What makes up net worth, {bl if same else rl}"):
        _fc_breakdown(F, F["pr"], nr)
    caption(f"The plan line grows investments at {base * 100:g}% a year; the slider changes only the comparison line. " + FC_NOTE)


# ---- spending control: annual budget, committed items, headroom ---------------------------------------------------
def spend_year():
    ss = st.session_state
    first, last = int(ss.plan.meta.get("first_month", "2026-08")[:4]), int(ss.plan.meta.get("last_month", "2027-12")[:4])
    return min(max(today().year, first), last)


def spend_control(year):
    ss = st.session_state
    return year_control(ss.plan, ss.entries, year, replica=bool(ss.settings.get("replica")))


def bar_committed(h, s):
    # Recurring items + scheduled bills only ever covered the named, fixed commitments -- never the day-to-day
    # variable spending (groceries, gas, restaurants...) that's most of what actually shows up as Core actual.
    # A "Rest of your spending" segment fills that gap with the forecast for the whole year (actual so far, plus
    # budget-rate for whatever's still ahead) beyond what's named here, so the bar reflects real spending, not
    # just the itemized list -- and Headroom, at the end, is genuinely what's left, not a leftover of a partial
    # picture. If the full-year forecast alone already clears the budget line, the bar runs past it and there's
    # no Headroom segment, same as running out of room for real.
    parts = [("Recurring items", h["recurring_annual"], NAVY)]
    if h["extras_annual"] > 0:
        parts.append(("Added here", h["extras_annual"], SOFT))
    parts.append(("Scheduled bills", h["scheduled_bills"], BRASS))
    rest = max(0.0, s["normalized_full_year"] - h["committed"])
    if rest > 0:
        parts.append(("Rest of your spending", rest, GREY))
    if h["headroom"] > 0:
        parts.append(("Headroom", h["headroom"], PINE))
    fig = go.Figure()
    for name, v, col in parts:
        fig.add_trace(go.Bar(x=[v], y=[""], orientation="h", name=name, marker_color=col, hovertemplate=f"{name} $%{{x:,.0f}}<extra></extra>"))
    fig.add_vline(x=h["core_budget"], line_color=BRICK, line_width=2)
    fig.update_layout(barmode="stack", height=120, margin=dict(l=8, r=8, t=8, b=8), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      legend=dict(orientation="h", y=-0.4, x=0), showlegend=True)
    fig.update_xaxes(range=[0, max(h["core_budget"], h["committed"], s["normalized_full_year"]) * 1.03], tickprefix="$", tickformat="~s", showgrid=False)
    fig.update_yaxes(visible=False)
    return fig


def pace_text(s):
    if s["core_budget"] <= 0:
        return "No budget set yet, so there is no pace to show."
    return (f"Year to date: {money(abs(s['normalized_variance']))} {'under' if s['normalized_variance'] >= 0 else 'over'} the budget to date. "
            f"Full-year forecast {money(s['normalized_full_year'])} against {money(s['core_budget'])}.")


def dashboard_spending():
    y = spend_year()
    yc = spend_control(y)
    h, s = yc["headroom"], yc["summary"]
    with st.container(border=True):
        a, b = st.columns([2, 3])
        with a:
            caption(f"Core spending, {y}")
            st.markdown(f"<div class='big'>{money(h['headroom'])}</div>", unsafe_allow_html=True)
            write(f"headroom on a {money(h['core_budget'])} budget, after {money(s['normalized_full_year'])} actual and forecast spending for the year")
            status_line("ok" if h["headroom"] >= 0 else "bad", "On track for the year" if h["headroom"] >= 0 else "Forecast to go over the budget")
        with b:
            _plotly(bar_committed(h, s), key="g_spend")
            caption(pace_text(s))
        caption("Red line: the annual budget. The Spending page has the committed items, the monthly table and the pace views.")


PLAN_VIOLET = "#8064A2"


def bar_onetime(o):
    """The one-time budget split into what is spent, waiting to be reconciled, on cards, planned, and left. Past the red line means over the budget."""
    budget = o["budget"]
    parts = [("Spent", max(o["spent"], 0.0), NAVY), ("Waiting to be reconciled", max(o["pending"], 0.0), SOFT),
             ("On cards, not paid yet", o["reserved"], BRASS), ("Planned", o["planned"], PLAN_VIOLET)]
    total = sum(v for _, v, _ in parts)
    if total <= budget:
        parts.append(("Left", budget - total, PINE))
    fig = go.Figure()
    for name, v, col in parts:
        if v > 0 or name == "Spent":
            fig.add_trace(go.Bar(x=[v], y=[""], orientation="h", name=name, marker_color=col, hovertemplate=f"{name} $%{{x:,.0f}}<extra></extra>"))
    fig.add_vline(x=budget, line_color=BRICK, line_width=2)
    fig.update_layout(barmode="stack", height=150, margin=dict(l=8, r=8, t=8, b=8), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      legend=dict(orientation="h", y=-0.95, x=0), showlegend=True)
    fig.update_xaxes(range=[0, max(budget, total) * 1.03], tickprefix="$", tickformat="~s", showgrid=False)
    fig.update_yaxes(visible=False)
    return fig


