def _oc_status(entries, a):
    if not a.get("line"):
        return "On the card, set aside from the budget"
    r = alloc_line(entries, a)
    if r is None:
        return "Applied, but that payment line is gone"
    when = fmt_date(_dt.date.fromisoformat(str(r.get("date"))[:10])) if r.get("date") else "undated"
    return (f"Paid: counted in one-time ({r.get('desc')} payment, {when})" if is_reconciled(r) else f"On the {r.get('desc')} payment of {when}: counts once it is reconciled")


def _card_charges_tab(o):
    ss = st.session_state
    plan, entries, ver = ss.plan, ss.entries, ss.data_ver
    caption("When you put a one-time purchase on a credit card, set it aside here. It comes off the one-time budget straight away, so you can see what is really left. "
            "When you pay the card, apply the charge to that payment: from then on it counts as one-time spending, and stops counting as everyday card spending, "
            "once the payment is reconciled.")
    msg = ss.pop("ot_msg", None)                                 # shown once, right after the action: a leftover would mislead after a sync
    if msg:
        st.info(_esc(msg))
    txns = _card_txn_plan(entries)
    if txns:
        st.markdown("**New card charges found**")
        threshold = plan.expenses.get("card_flag_threshold", 250.0)
        caption(f"From the daily bank fetch, on the cards you are watching. Charges of {money(threshold, 2)} or more are flagged as likely one-time purchases; "
                "the rest are assumed routine and left off unless you say otherwise.")
        for t in txns:
            r = st.columns([1, 4, 2, 2, 2], gap="small", vertical_alignment="center")
            if t["flag"]:
                r[0].markdown(":orange[**Looks big**]")
            r[1].markdown(f"{_esc(t['desc'])}  \n{_esc(t.get('card_name', ''))} · {fmt_date(_dt.date.fromisoformat(t['date']))}")
            r[2].markdown(f"**{_esc(money(t['amount'], 2))}**")
            r[3].button("One-time" if t["flag"] else "Set aside", key=f"txn_add_{t['id']}", type="primary" if t["flag"] else "secondary",
                       on_click=oc_cb_txn_add, args=(t,), help="Sets it aside from the one-time budget, exactly like adding it by hand below.")
            r[4].button("Routine", key=f"txn_skip_{t['id']}", on_click=oc_cb_txn_skip, args=(t["id"],),
                       help="Not a one-time purchase: leaves it to be covered by the card's regular payment, and stops asking about this one.")
    cards = [str(k) for k in plan.expenses["card_keywords"]]
    st.markdown("**Set aside a card charge**")
    f = st.columns([3, 2, 2, 2], gap="small", vertical_alignment="bottom")
    f[0].text_input("What was it", key=f"oc_desc_{ver}", placeholder="Flight to Denver")
    f[1].text_input("Amount", key=f"oc_amt_{ver}", placeholder="3000")
    f[2].date_input("Date charged", value=today(), key=f"oc_date_{ver}", format="YYYY-MM-DD")
    f[3].selectbox("Card", cards, key=f"oc_card_{ver}", format_func=lambda c: c.title())
    open_plans = {x["id"]: x for x in plan_items(entries) if not x.get("done")}
    if open_plans:
        st.selectbox("Part of a plan (optional)", [""] + list(open_plans), key=f"oc_for_{ver}",
                     format_func=lambda i: "Not part of a plan" if not i else f"{open_plans[i]['name']} · {fmt_date(_dt.date.fromisoformat(open_plans[i]['date']))}",
                     help="A charge that belongs to a planned item uses up that plan, so it is not held back twice.")
    st.button("Set it aside", key=f"oc_add_{ver}", on_click=oc_cb_add)
    allocs = alloc_list(entries)
    if not allocs:
        caption("No card charges set aside yet.")
        return
    st.markdown("**Card charges**")
    for a in sorted(allocs, key=lambda x: (bool(x.get("line")), x["date"])):
        r = st.columns([4, 2, 5, 2], gap="small", vertical_alignment="center")
        pl = plan_find(entries, a["plan"]) if a.get("plan") else None
        r[0].markdown(f"**{_esc(a['desc'])}**  \n{_esc(a['card'].title())} · {fmt_date(_dt.date.fromisoformat(a['date']))}" + (f" · for {_esc(pl['name'])}" if pl else ""))
        r[1].markdown(f"**{_esc(money(a['amount'], 2))}**")
        r[2].caption(_esc(_oc_status(entries, a)))
        if a.get("line"):
            r[3].button("Take off", key=f"oc_undo_{a['id']}", on_click=oc_cb_undo, args=(a["id"],), help="Put it back on the card, no longer part of that payment.")
        else:
            r[3].button("Remove", key=f"oc_del_{a['id']}", on_click=oc_cb_delete, args=(a["id"],))
    waiting = [a for a in allocs if not a.get("line")]
    if waiting:
        st.markdown("**Apply a charge to a card payment**")
        aid = st.selectbox("Charge", [a["id"] for a in waiting], key=f"oc_pick_{ver}",
                           format_func=lambda i: next(f"{x['desc']} · {money(x['amount'], 2)} · {x['card'].title()}" for x in waiting if x["id"] == i))
        chosen = next(a for a in waiting if a["id"] == aid)
        # Any payment with room left is offered, even when the charge is bigger than that room (v21.14): a rounded payment -- 7,700 paid
        # against two tickets totalling 7,727.46 -- must be usable without raising the payment above what the bank actually paid.
        cands = card_payment_lines(plan, entries, chosen["card"], chosen["date"])
        if not cands:
            caption(f"No {chosen['card'].title()} payment with room left, dated on or after {fmt_date(_dt.date.fromisoformat(chosen['date']))}, is in your transactions yet. "
                    "When you pay the card and the payment appears, come back and apply it.")
        else:
            st.selectbox("Card payment", [f"{c['month']}|{c['ref']}" for c in cands], key=f"oc_line_{ver}_{aid}",
                         format_func=lambda v: next(f"{fmt_date(_dt.date.fromisoformat(c['date'][:10]))}, {c['date'][:4]} · {c['desc']} · {money(c['debit'], 2)} ({money(c['free'], 2)} free) · "
                                                    f"{'reconciled' if c['reconciled'] else 'not reconciled yet'}" for c in cands if f"{c['month']}|{c['ref']}" == v))
            st.button("Apply to this payment", key=f"oc_apply_{ver}", on_click=oc_cb_apply, args=(aid,))


