def _plan_tab(o):
    ss = st.session_state
    ver = ss.data_ver
    caption("Hold back part of the one-time budget for things you know are coming, like a cruise. Whatever is not held back is the rest, for example the holidays. "
            "When you charge a planned item to a card, choose the plan on the Card charges tab: the charge uses up the plan, so nothing is held back twice. "
            "Mark a plan done when it is over and any leftover goes back into the rest.")
    if ss.get("op_msg"):
        st.info(_esc(ss.op_msg))
    rows = []
    for i in o["plan_items"]:
        late = (not i["done"]) and i["left"] > 0 and _dt.date.fromisoformat(i["date"]) < today()
        rows.append({"Item": i["name"], "Expected": fmt_date(_dt.date.fromisoformat(i["date"])), "Planned": money(i["amount"], 2), "Charged so far": money(i["linked"], 2),
                     "Still held back": money(i["left"], 2), "Status": "Done" if i["done"] else ("Date has passed: mark it done or update it" if late else "Held back")})
    rows.append({"Item": o["rest_name"], "Expected": "", "Planned": "", "Charged so far": "", "Still held back": money(o["rest"], 2), "Status": "The rest"})
    st.markdown(html_table(pd.DataFrame(rows), right_cols=("Planned", "Charged so far", "Still held back"), bold_last=True), unsafe_allow_html=True)
    caption(f"Budget {money(o['budget'], 2)} = spent {money(o['spent'], 2)} + waiting to be reconciled {money(o['pending'], 2)} + on cards {money(o['reserved'], 2)} "
            f"+ planned, still to spend {money(o['planned'], 2)} + the rest {money(o['rest'], 2)}.")
    st.markdown("**Hold something back**")
    f = st.columns([3, 2, 2], gap="small", vertical_alignment="bottom")
