    f[2].text_input("Amount", key=f"op_amt_{ver}", placeholder="3000")
    st.button("Hold it back", key=f"op_add_{ver}", on_click=op_cb_add)
    st.text_input("What the rest is for", value=o["rest_name"], key=f"op_rest_{ver}", on_change=op_cb_rest_name)
    if o["plan_items"]:
        st.markdown("**Change a plan**")
        for i in o["plan_items"]:
            r = st.columns([3, 2, 1, 2, 2], gap="small", vertical_alignment="center")
            r[0].markdown(f"**{_esc(i['name'])}**  \n{fmt_date(_dt.date.fromisoformat(i['date']))}")
            r[1].text_input("Amount", value=f"{i['amount']:.2f}", key=f"op_edit_{ver}_{i['id']}", label_visibility="collapsed")
            r[2].button("Update", key=f"op_up_{i['id']}", on_click=op_cb_update, args=(i["id"],))
            r[3].button("Reopen" if i["done"] else "Mark done", key=f"op_done_{i['id']}", on_click=op_cb_done, args=(i["id"], not i["done"]))
            r[4].button("Remove", key=f"op_del_{i['id']}", on_click=op_cb_delete, args=(i["id"],))


