def page_onetime():
    """v21.69: One-time spending is a dashboard of five tiles for the chosen year; each opens one view."""
    ss = st.session_state
    plan = ss.plan
    tab = ss.pop("ot_tab", None)                          # an action, or the Dashboard's card-charges note, asks for one view
    if tab in OT_TAB_VIEW:
        ss.ot_view = OT_TAB_VIEW[tab]
    first, last = int(plan.meta.get("first_month", "2026-08")[:4]), int(plan.meta.get("last_month", "2027-12")[:4])
    years = list(range(first, last + 1))
    y = int(ss.get("ot_y") or spend_year())
    y = y if y in years else spend_year()
    o = one_time_register(plan, ss.entries, y, today())
    view = ss.get("ot_view") or "hub"
    if view not in OT_VIEWS:
        back_bar("\u2039 Spending", goto_page, ("Spending",), "ot_to_spending")
        st.title("One-time spending")
        k = f"ot_year_{ss.data_ver}"
        st.selectbox("Year", years, index=years.index(y), key=k, on_change=cb_ot_year, args=(k,))
        _ot_hub(o, y)
        return
    back_bar("\u2039 One-time spending", _ot_go, ("hub",), "ot_back")
    st.title(f"{OT_VIEWS[view]}, {y}")
    if view == "budget":
        m = st.columns(4, gap="small")
        m[0].metric("One-time budget", money(o["budget"]))
        m[1].metric("Spent so far", money(o["spent"], 2))
        m[2].metric("Remaining", money(o["remaining"], 2))
        m[3].metric("Room per month left", money(o["per_month"]) if o["per_month"] is not None else "–")
        parts = ([f"On cards, not paid yet: {money(o['reserved'], 2)}"] if o["reserved"] > 0 else []) + \
                ([f"waiting to be reconciled: {money(o['pending'], 2)}"] if abs(o["pending"]) > 0.004 else []) + \
                ([f"planned, still to spend: {money(o['planned'], 2)}"] if o["planned"] > 0 else [])
        if parts:
            caption(" · ".join(parts) + f". After those, {money(o['rest'], 2)} is left" + (f" for {o['rest_name'].lower()}" if o["planned"] > 0 else "") + ".")
        if o["rest"] < 0:
            status_line("warn", f"Over the one-time budget by {money(-o['rest'], 2)}" + (" once everything set aside is spent" if o["remaining"] >= 0 else ""))
        else:
            status_line("ok", f"Within the one-time budget, {o['used'] * 100:.0f}% used")
        _plotly(bar_onetime(o), key="g_onetime")
        if o["start_month"] > 1:
            caption(f"The one-time budget for {y} covers {MONTH_NAMES[o['start_month'] - 1]} to December only, a share of the yearly amount. Items dated before "
                    f"{MONTH_NAMES[o['start_month'] - 1]} are listed below but do not count against it.")
        else:
            caption(f"The one-time budget covers all of {y}. Only reconciled lines count against it.")
        if o["per_month"] is not None:
            caption(f"Room per month left is the remaining budget over the {o['months_left']} month{'s' if o['months_left'] != 1 else ''} after this one.")
    elif view == "register":
        rows = o["rows"]
        if not rows:
            st.info(f"No one-time items in {y} yet. Set a line's class to One-Time on Monthly updates, Transactions, and it appears here.")
        else:
            df = pd.DataFrame([{"Date": fmt_date(_dt.date.fromisoformat(r["date"])), "Description": r["desc"], "Amount": money(r["amount"], 2),
                                "Status": "Reconciled" if r["reconciled"] else "Pending", "Counts against the budget": r["why"],
                                "Running total": money(r["running"], 2) if r["running"] is not None else ""} for r in rows])
            st.markdown(html_table(df, right_cols=("Amount", "Running total")), unsafe_allow_html=True)
            parts = [f"Counted against the budget: {money(o['spent'], 2)}"]
            if abs(o["pending"]) > 0.004:
                parts.append(f"waiting to be reconciled: {money(o['pending'], 2)}")
            if abs(o["before"]) > 0.004:
                parts.append(f"before the budget period: {money(o['before'], 2)}")
            caption(" · ".join(parts) + ". A negative amount is money back, such as a refund or a sale.")
        msg = ss.pop("ot_cls_msg", None)
        if msg:
            st.info(_esc(msg))
        with st.expander("Change a line's class"):
            caption("Use this to take a line out of one-time spending. For example, a refund whose original purchase was never in your ledger only distorts the "
                    "numbers: set it to Excluded and it no longer counts. It works on any month, including earlier months you imported, and you can put a line back "
                    "the same way.")
            ver, n = ss.data_ver, ss.get("oc_cls_n", 0)
            cl = one_time_class_lines(ss.entries, y)
            if not cl:
                caption("There are no one-time lines to change.")
            else:
                st.selectbox("Line", [f"{c['month']}|{c['ref']}" for c in cl], key=f"oc_cls_line_{ver}_{n}", index=None, placeholder="Pick the line to change",
                             format_func=lambda v: next(f"{fmt_date(_dt.date.fromisoformat(c['date']))} · {c['desc']} · {money(c['amount'], 2)} · {c['cls']}"
                                                        + (" (moved out)" if c["moved"] else "") for c in cl if f"{c['month']}|{c['ref']}" == v))
                st.selectbox("New class", list(CLASS_CHOICES), index=2, key=f"oc_cls_new_{ver}_{n}")
                st.button("Change class", key=f"oc_cls_go_{ver}", on_click=oc_cb_class)
        st.button("Open this month's transactions", key="ot_to_tx", on_click=goto_checking)
        caption("To add an item, open Transactions and set its class: One-Time puts it here. For a purchase on a credit card, use the Card charges tile; "
                "to hold back money for something coming, use the Plan tile.")
    elif view == "plan":
        _plan_tab(o)
    elif view == "card":
        _card_charges_tab(o)
    elif view == "month":
        d = pd.DataFrame([{"Month": MONTH_NAMES[x["month"] - 1][:3], "Spent": money(x["spent"], 2), "Left in the budget": money(x["left"], 2)} for x in o["monthly"]])
        st.markdown(html_table(d, right_cols=("Spent", "Left in the budget")), unsafe_allow_html=True)
        caption("Each month's spending is the reconciled One-Time lines dated in that month. The Spending page shows the same figures beside the core budget.")


def _ot_hub(o, y):
    n_reg = len(o["rows"])
    T = lambda key, t, v: {"key": key, "t": t, "go": (lambda v_=v: _ot_go(v_))}
    over = o["rest"] < 0
    tiles = [
        T("ot_budget", ("Budget", money(o["remaining"]), "warn" if over else "ok", "remaining" if not over else f"Over by {money(-o['rest'])} once set-asides are spent",
                        f"Spent {money(o['spent'])} of {money(o['budget'])}"), "budget"),
        T("ot_register", ("Register", f"{n_reg} item{'s' if n_reg != 1 else ''}", "idle", f"{money(o['spent'])} counted", f"{money(o['pending'])} waiting to reconcile" if abs(o["pending"]) > 0.004 else ""), "register"),
        T("ot_plan", ("Plan", money(o["planned"]), "idle", "set aside, still to spend", "Money held back for things coming"), "plan"),
        T("ot_card", ("Card charges", money(o["reserved"]), "warn" if o["reserved"] > 0 else "idle", "on cards, not paid yet", "Purchases on a credit card"), "card"),
        T("ot_month", ("By month", money(o["per_month"]) if o["per_month"] is not None else "\u2014", "idle", "room per month left", "Spent and left, month by month"), "month"),
    ]
    _hub_row(tiles, "cash")


def sp_cb_update(xid):
    ss = st.session_state
    amt = parse_money(ss.get(f"sp_amt_{xid}"))
    if amt is None or amt <= 0:
        ss.sp_msg = "Enter an amount above zero."
        return
    n = update_extra_amount(ss.plan, ss.entries, xid, amt, next_month_key(f"{today().year}-{today().month:02d}"))
    ss.sp_msg = f"Amount updated; {n} later pending line{'s' if n != 1 else ''} changed."


def sp_cb_stop(xid):
    ss = st.session_state
    n = stop_repeating(ss.plan, ss.entries, xid, f"{today().year}-{today().month:02d}")
    ss.sp_msg = f"Stopped after this month; {n} later pending line{'s' if n != 1 else ''} removed."


def sp_cb_add():
    ss = st.session_state
    name, amt = ss.get("sp_new_name", "").strip(), parse_money(ss.get("sp_new_amt"))
    if not name or amt is None or amt <= 0:
        ss.sp_msg = "Enter a name and an amount above zero."
        return
    add_extra(ss.plan, name, amt, int(ss.get("sp_new_day", 1)), ss.get("sp_new_start"))
    ensure_recurring_lines(ss.plan, ss.entries, month_list(ss.plan, today()))
    ss.sp_msg = f"{name} added. It repeats from {month_label(ss.get('sp_new_start'))} and reduces your headroom."
    ss.sp_n = ss.get("sp_n", 0) + 1


def goto_spending_cats(came_from="Spending"):
    """v21.48: open Spending by category (from the Dashboard's Cash row or the Spending page); its back button returns where you came from."""
    ss = st.session_state
    ss.sp_cat_from = came_from
    if came_from == "Spending":
        ss.sp_view = "cat"
    else:
        ss["page"] = "Spending"
        ss.sp_view_next = "cat"


def _sp_go(view):
    st.session_state.sp_view = view


def _sp_cat_hub():
    """Spending by category: All spending and the chosen category tiles for a year (on Reporting until v21.47)."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    back = ss.get("sp_cat_from") or "Spending"
    if back == "Dashboard":
        st.button("\u2302 Dashboard", key="sp_cat_back", on_click=goto_page, args=("Dashboard",))
    else:
        back_bar("‹ Spending", _sp_go, ("main",), "sp_cat_back")
    st.title("Spending by category")
    caption("Where the money goes: checking and credit cards together. Tap a tile to open it.")
    T = lambda key, label, value, kind, note, extra, go: {"key": key, "label": label, "value": value, "kind": kind, "note": note, "extra": extra, "go": go}
    years = _rep_spend_years()
    y = _rep_year_default() if _rep_year_default() in years else today().year
    items = spending_items(plan, entries, y)
    CR = category_rollup(plan, items)
    unc = CR["uncategorized"]
    n_months = today().month if y == today().year else 12
    spend_row = [T("sp_all", "All spending", money(CR["spending_total"]), "warn" if unc else "ok", f"{y} by category",
                   f"{len(unc)} line{'s' if len(unc) != 1 else ''} to sort" if unc else "Everything sorted", lambda: _sp_go("rollup"))]
    for name in report_tiles_of(plan):
        tn = _rep_tile_numbers(plan, items, CR, name)
        share = tn["total"] / CR["spending_total"] if CR["spending_total"] else 0.0
        extra = f"About {money(tn['total'] / n_months)} a month" + (f"\nBiggest: {tn['top'][0]}" if tn["top"] else "")
        spend_row.append(T(f"sp_t_{_slug(name)}", name, money(tn["total"]), "idle", f"{share:.0%} of spending", extra, (lambda v=f"tile:{name}": _sp_go(v))))
    c = st.columns([1, 3], vertical_alignment="bottom")
    c[0].selectbox("Year", years, index=years.index(y), key="rep_year_pick", on_change=lambda: ss.__setitem__("rep_year_val", ss.rep_year_pick))
    _rep_bands([("Spending", f"{y}, January to date" if y == today().year else str(y), "cash", spend_row)])
    with st.expander("Choose the spending tiles"):
        groups = [g for g in CR["order"] if g != NOT_SPENDING]
        cats = [c_ for g, c_ in categories_of(plan) if g != NOT_SPENDING and c_ not in groups]
        opts = groups + cats
        cur = [t for t in report_tiles_of(plan) if t in opts]
        pick = st.multiselect("Tiles, in order", opts, default=cur, key=f"rep_tiles_{ss.get('ru_rev', 0)}",
                              format_func=lambda o: f"{o} (group)" if o in groups else o)
        b = st.columns(3, gap="small")
        if b[0].button("Save tiles", key="rep_tiles_save", type="primary"):
            plan.expenses["report_tiles"] = list(pick)
            _ru_rev()
            st.rerun()
        if b[1].button("Deselect all", key="rep_tiles_clear", disabled=not cur):
            plan.expenses["report_tiles"] = []
            _ru_rev()
            st.rerun()
        if b[2].button("Standard tiles", key="rep_tiles_default", disabled=cur == [t for t in DEFAULT_REPORT_TILES if t in opts]):
            plan.expenses["report_tiles"] = list(DEFAULT_REPORT_TILES)
            _ru_rev()
            st.rerun()
        caption("Deselect all clears every spending tile at once (All spending always stays); then pick the ones you want and save. "
                "A group tile opens its categories, then the merchants and lines behind each. A category tile opens its merchants and lines.")


SP_VIEWS = {"budget": "Budget", "bills": "Recurring bills", "deposits": "Recurring deposits", "monthly": "Monthly", "pace": "Pace", "cards": "Credit cards"}


def _sp_year_pick() -> int:
    ss = st.session_state
    plan = ss.plan
    first, last = int(plan.meta.get("first_month", "2026-08")[:4]), int(plan.meta.get("last_month", "2027-12")[:4])
    years = list(range(first, last + 1))
    return st.selectbox("Year", years, index=years.index(spend_year()), key=f"sp_year_{ss.data_ver}")


def _sp_msg():
    ss = st.session_state
    msg = ss.pop("sp_msg", None)                # shown once, on the screen where it happened
    if msg:
        st.info(_esc(msg))


def _card_short(name: str) -> str:
    """'Chase Bank Chase Sapphire Preferred (3329)' -> 'Chase Sapphire Preferred (3329)': the bank's name is dropped when the card repeats it."""
    n = _re.sub(r"[\u00ae\u2122]", "", str(name or "Card")).strip()
    for bank in ("Chase Bank ", "American Express ", "Citibank "):
        if n.startswith(bank):
            n = n[len(bank):]
    return _re.sub(r"-\d{4} \((\d{4})\)$", r" (\1)", n)


def card_month(plan, entries: dict, k: str, inbox: dict | None = None) -> dict:
    """v25.2: one month of credit card activity, card by card: each charge and credit in date order with the month's running balance
    (charges less refunds and credits), plus what was paid to the card. Payments to the card do not count as spending, so they do not
    move that balance. Uses the same card history and the same de-duplication as Spending by category.
    v25.3: what is owed on each card, from the balance the nightly fetch reads (the month's last reading), and on each line the amount
    owed just after it, worked back from that reading through the card's own lines, payments included."""
    y = int(k[:4])
    items = [it for it in spending_items(plan, entries, y) if it["ref"][0] == "card" and it["month"] == k]
    hist = entries.get("card_txns") or {}
    canon = card_canon(hist)
    ids_by_name = {}
    for c_ in card_accounts_of(plan):                  # later entries win: a card re-ticked after a reconnection follows its new id
        nm_ = c_.get("name", "")
        ids_by_name[canon.get(card_key(nm_), nm_)] = c_.get("id", "")
    for t in hist.values():
        ids_by_name.setdefault(t.get("acct_name") or "Card", t.get("acct", ""))
    snap = ((inbox or {}).get("snapshots") or {}).get(k) or {}
    snap_bal = {a_.get("id"): a_.get("balance") for a_ in (snap.get("accounts") or [])}
    cards = {}
    new = lambda name: {"name": name, "rows": [], "charges": 0.0, "credits": 0.0, "paid": 0.0, "last": "", "acct": ids_by_name.get(name, "")}
    for it in items:
        c = cards.setdefault(it["src"], new(it["src"]))
        raw = hist.get(it["id"], {})
        c["rows"].append({"id": it["id"], "date": it["date"], "desc": it["desc"], "cat": it["cat"], "amount": float(it["amount"]),
                          "raw": float(raw.get("amount", -it["amount"])), "pay": False})
    for iid, t in hist.items():                     # payments made to each card this month
        if str(t.get("date", ""))[:7] == k and float(t.get("amount") or 0) > 0 and is_card_payment_credit(t.get("desc", "")):
            name = t.get("acct_name") or "Card"
            c = cards.setdefault(name, new(name))
            c["paid"] += float(t["amount"])
            c["rows"].append({"id": iid, "date": str(t["date"]), "desc": t.get("desc", ""), "cat": "Payment to the card", "amount": -float(t["amount"]),
                              "raw": float(t["amount"]), "pay": True})
    for c in cards.values():
        c["rows"].sort(key=lambda r: (r["date"], r["pay"], r["id"]))
        run = 0.0
        for r in c["rows"]:
            if not r["pay"]:
                if r["amount"] >= 0:
                    c["charges"] += r["amount"]
                else:
                    c["credits"] += -r["amount"]
                run = round(c["charges"] - c["credits"], 2)
                c["last"] = max(c["last"], r["date"])
            r["running"] = run
        bal = snap_bal.get(c["acct"])
        c["owed"], c["owed_at"] = (None, "") if bal is None else (round(-float(bal), 2), snap.get("date", ""))
        if c["owed"] is not None:                   # owed just after each line: the reading, less every later line up to the reading's date
            after = 0.0
            for r in reversed(c["rows"]):
                if r["date"] <= c["owed_at"]:
                    r["owed"] = round(c["owed"] + after, 2)
                    after += r["raw"]
    for acct_id, bal in snap_bal.items():           # a card with a balance but no activity this month still shows what is owed
        name = next((n for n, i in ids_by_name.items() if i == acct_id), None)
        if name and name not in cards and acct_id in {c_.get("id") for c_ in card_accounts_of(plan)} and bal is not None and abs(float(bal)) > 0.005:
            c = cards[name] = new(name)
            c["owed"], c["owed_at"] = round(-float(bal), 2), snap.get("date", "")
    out = sorted(cards.values(), key=lambda c: -(c["charges"] - c["credits"]))
    for c in out:
        c["net"] = round(c["charges"] - c["credits"], 2)
        c["short"] = _card_short(c["name"])
    owed = [c["owed"] for c in out if c.get("owed") is not None]
    return {"month": k, "cards": out, "net": round(sum(c["net"] for c in out), 2), "lines": sum(len([r for r in c["rows"] if not r["pay"]]) for c in out),
            "owed": round(sum(owed), 2) if owed else None, "owed_at": snap.get("date", "") if owed else ""}


def card_months(entries: dict) -> list[str]:
    ks = sorted({str(t.get("date", ""))[:7] for t in (entries.get("card_txns") or {}).values() if t.get("date")})
    cur = today().strftime("%Y-%m")
    return sorted(set(ks) | {cur}, reverse=True)


def sp_cards():
    """v25.2: credit card transactions month by month, card by card, with each card's running balance for the month."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    ks = card_months(entries)
    c1, c2 = st.columns([1, 2], gap="small")
    k = c1.selectbox("Month", ks, index=0, key=f"cc_month_{ss.data_ver}", format_func=month_label)
    cm = card_month(plan, entries, k, _inbox())
    names = ["All cards"] + [c["short"] for c in cm["cards"]]
    pick = c2.selectbox("Card", names, index=0, key=f"cc_card_{ss.data_ver}_{k}")
    if not cm["cards"]:
        st.info(f"No card activity on file for {month_label(k)} yet. It arrives with the nightly bank fetch.")
        return
    m = st.columns(4, gap="small")
    m[0].metric("Owed on the cards", money(cm["owed"], 2) if cm["owed"] is not None else "\u2014",
                help=(f"From the bank's balance on {fmt_date(_dt.date.fromisoformat(cm['owed_at']))}" if cm["owed_at"] else "No balance read for this month"))
    m[1].metric(f"Spent in {MONTH_NAMES[int(k[5:]) - 1][:3]}", money(cm["net"], 2), help="Charges less refunds and credits. Payments to the cards are not counted.")
    m[2].metric("Charges", money(sum(c["charges"] for c in cm["cards"]), 2), help=f"{cm['lines']} lines")
    m[3].metric("Paid to the cards", money(sum(c["paid"] for c in cm["cards"]), 2))
    if pick == "All cards":
        summ = pd.DataFrame([{"Card": c["short"], "Owed": money(c["owed"], 2) if c.get("owed") is not None else "", "Spent this month": money(c["net"], 2),
                              "Charges": money(c["charges"], 2), "Credits": money(-c["credits"], 2) if c["credits"] else "",
                              "Paid to card": money(c["paid"], 2) if c["paid"] else "",
                              "Last charge": fmt_date(_dt.date.fromisoformat(c["last"])) if c["last"] else ""} for c in cm["cards"]])
        st.markdown(html_table(summ, right_cols=("Owed", "Spent this month", "Charges", "Credits", "Paid to card")), unsafe_allow_html=True)
    for c in cm["cards"]:
        if pick != "All cards" and c["short"] != pick:
            continue
        st.subheader(c["short"])
        caption(" \u00b7 ".join(x for x in [
            (f"Owed {money(c['owed'], 2)} on {fmt_date(_dt.date.fromisoformat(c['owed_at']))}" if c.get("owed") is not None else ""),
            f"spent this month {money(c['net'], 2)}", (f"paid to the card {money(c['paid'], 2)}" if c["paid"] else "")] if x))
        if c["rows"]:
            has_owed = any("owed" in r for r in c["rows"])
            df = pd.DataFrame([{"Date": fmt_date(_dt.date.fromisoformat(r["date"])), "Description": r["desc"], "Category": r["cat"],
                                "Amount": money(r["amount"], 2), "Spent this month": "" if r["pay"] else money(r["running"], 2),
                                **({"Owed after": money(r["owed"], 2) if "owed" in r else ""} if has_owed else {})} for r in reversed(c["rows"])])
            st.markdown(html_table(df, right_cols=("Amount", "Spent this month", "Owed after")), unsafe_allow_html=True)
    caption("Newest first. Owed is the card's balance as the bank reported it at the nightly fetch (for an earlier month, its last reading that month); "
            "Owed after works back from it line by line. Both count posted charges only: the fetch does not bring in pending ones. "
            "Spent this month is the calendar month to date, charges less refunds and credits; payments to a card are shown but do not change it.")


def page_spending():
    """v21.53: Spending is a dashboard of tiles for the chosen year; each opens one view (By category has its own tiles)."""
    ss = st.session_state
    view = ss.get("sp_view") or "main"
    if view == "cat":
        _sp_cat_hub()
        return
    if view == "rollup":
        back_bar("‹ Spending by category", _sp_go, ("cat",), "sp_back_cat")
        page_rollup()
        return
    if view.startswith("tile:"):
        back_bar("‹ Spending by category", _sp_go, ("cat",), "sp_back_cat")
        _rep_tile(view[5:])
        return
    if view in SP_VIEWS:
        back_bar("‹ Spending", _sp_go, ("main",), "sp_back")
        st.title(SP_VIEWS[view])
        {"budget": sp_budget, "bills": sp_bills, "deposits": sp_deposits, "monthly": sp_monthly, "pace": sp_pace, "cards": sp_cards}[view]()
        return
    _sp_hub()


def _sp_hub():
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    st.title("Spending")
    y = _sp_year_pick()
    _sp_msg()
    caption("Tap a tile to open it.")
    yc = spend_control(y)
    h, s, tk = yc["headroom"], yc["summary"], yc["tracker"]
    months_all = month_list(plan, today())
    over = h["headroom"] < 0
    t_bud = ("Budget", money(abs(h["headroom"])) + (" over" if over else " headroom"), "bad" if over else "ok",
             "Forecast to go over" if over else "On track for the year", f"Core budget {money(h['core_budget'])}")
    try:
        bl = all_recurring_bills(plan, entries, months_all, today(), y)
        sg = bill_amount_suggestions(plan, entries, today())
    except Exception:  # noqa: BLE001
        bl, sg = [], []
    nodate = sum(1 for b in bl if b.get("next") is None)
    t_bill = ("Recurring bills", f"{len(bl)} bills", "warn" if (sg or nodate) else "idle",
              (f"{len(sg)} suggested amount{'s' if len(sg) != 1 else ''}" if sg else (f"{nodate} without a due date" if nodate else f"{money(sum(b['year_total'] for b in bl))} a year")),
              f"{money(sum(b['year_total'] for b in bl))} a year" if (sg or nodate) else "Add, change or remove")
    try:
        tgt = monthly_funding_target(plan, y)
    except Exception:  # noqa: BLE001
        tgt = None
    t_dep = ("Recurring deposits", f"{money(tgt)} a month" if tgt is not None else "\u2014", "idle" if plan.recurring.defcomp_year_amount else "warn",
             "Monthly funding target" if plan.recurring.defcomp_year_amount else "Set DefComp's amount by year", "DefComp and Savings deposit")
    d = tk.reset_index()
    mnow = today().month if y == today().year else 12
    row = d[d["month"] == mnow]
    if len(row) and row.iloc[0]["status"] != "NO DATA":
        r0 = row.iloc[0]
        t_mon = ("Monthly", money(r0["core_actual"]), "ok" if r0["core_variance"] >= 0 else "warn",
                 f"{money(abs(r0['core_variance']))} {'under' if r0['core_variance'] >= 0 else 'over'} in {MONTH_NAMES[mnow - 1][:3]}", f"Budget {money(r0['core_budget'])} a month")
    else:
        t_mon = ("Monthly", "\u2014", "idle", "No reconciled lines yet", "Core spend month by month")
    fy_var = s["full_year_variance"]
    t_pace = ("Pace", money(s["normalized_full_year"]), "ok" if fy_var >= 0 else "warn", f"Full-year forecast, {money(abs(fy_var))} {'under' if fy_var >= 0 else 'over'}",
              f"So far {money(s['normalized_core_ytd'])}")
    CR = category_rollup(plan, spending_items(plan, entries, y))
    unc = CR["uncategorized"]
    t_cat = ("By category", money(CR["spending_total"]), "warn" if unc else "ok", f"{y}, January to date",
             f"{len(unc)} line{'s' if len(unc) != 1 else ''} to sort" if unc else "Everything sorted")
    try:
        ot = one_time_register(plan, entries, y, today())
        t_ot = ("One-time spending", money(ot["spent"]), "warn" if ot["spent"] > ot["budget"] + 0.005 else "idle", f"of {money(ot['budget'])} for the year",
                f"{money(max(ot['rest'], 0.0))} left" if ot["rest"] >= 0 else "Plans exceed the budget")
    except Exception:  # noqa: BLE001
        t_ot = ("One-time spending", "\u2014", "idle", "Open the page", "")
    try:                                                     # v25.2: credit cards, this month
        cm_ = card_month(plan, entries, today().strftime("%Y-%m"), _inbox())
        mon_ = MONTH_NAMES[today().month - 1][:3]
        if cm_["owed"] is not None:
            t_cards = ("Credit cards", money(cm_["owed"]), "idle", "Owed on the cards now", f"Spent in {mon_} so far {money(cm_['net'])}")
        else:
            t_cards = ("Credit cards", money(cm_["net"]), "idle", f"Spent in {mon_} so far", "Card transactions by month")
    except Exception:  # noqa: BLE001 - the tile must always draw
        t_cards = ("Credit cards", "\u2014", "idle", "Card transactions by month", "")
    T = lambda key, t, go: {"key": key, "label": t[0], "value": t[1], "kind": t[2], "note": t[3], "extra": t[4], "go": go}
    tiles = [T("sp_bud", t_bud, lambda: _sp_go("budget")), T("sp_bills", t_bill, lambda: _sp_go("bills")), T("sp_deps", t_dep, lambda: _sp_go("deposits")),
             T("sp_mon", t_mon, lambda: _sp_go("monthly")), T("sp_pace", t_pace, lambda: _sp_go("pace")),
             T("sp_cat", t_cat, lambda: goto_spending_cats("Spending")), T("sp_ot", t_ot, lambda: goto_page("One-time spending")),
             T("sp_cards", t_cards, lambda: _sp_go("cards"))]
    with _tile_area():
        for r0 in range(0, len(tiles), TILES_PER_ROW):
            chunk = tiles[r0:r0 + TILES_PER_ROW]
            cols = st.columns(len(chunk), gap="small")
            for i, tl in enumerate(chunk):
                with cols[i]:
                    _segment(tl["key"], "cash", "first" if i == 0 else ("last" if i == len(chunk) - 1 else "mid"), tl["label"], tl["value"], tl["kind"],
                             tl["note"], "", tl["extra"], go=tl["go"])


def sp_budget():
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    y = _sp_year_pick()
    yc = spend_control(y)
    h, s, tk = yc["headroom"], yc["summary"], yc["tracker"]
    _sp_msg()
    c1, c2, c3 = st.columns(3)
    c1.metric(f"Core budget, {y}", money(h["core_budget"]))
    c2.metric("Committed", money(h["committed"]))
    c3.metric("Headroom", money(h["headroom"]))
    status_line("ok" if h["headroom"] >= 0 else "bad", "On track for the year" if h["headroom"] >= 0 else "Forecast to go over the budget")
    _plotly(bar_committed(h, s), key="g_spend_page")
    caption(f"Recurring items {money(h['recurring_annual'])}" + (f", added here {money(h['extras_annual'])}" if h["extras_annual"] else "")
            + f", scheduled bills {money(h['scheduled_bills'])}, the rest of this year's forecast spending "
            f"{money(max(0.0, s['normalized_full_year'] - h['committed']))}. Headroom is the budget minus this year's actual-plus-forecast "
            f"spending, {money(s['normalized_full_year'])} -- not just the items above. Red line: the annual budget.")
    sugg_window = 90
    sugg = suggested_core_budget(entries, today(), window_days=sugg_window)
    if sugg is not None:
        # The raw annualized figure (sugg["annualized"]) is exact, to the penny, for anything measuring against
        # it precisely -- but nobody sets up a real monthly transfer to the penny, and Andrew already settled on
        # rounding to a practical number for that (the same "can't leave it to the penny" call as the deposit
        # buffer). So what's actually offered to apply is rounded to the nearest $100, and a monthly figure sits
        # right next to the annual one since the transfer itself is monthly, not annual.
        sugg_rounded = round(sugg["annualized"] / 100.0) * 100.0
        diff = sugg_rounded - h["core_budget"]
        with st.expander(f"Suggested {y} Core budget, from your last {sugg['days_covered']} days of real spending"):
            sc1, sc2 = st.columns(2)
            sc1.metric("Suggested annual Core budget", money(sugg_rounded))
            sc2.metric("...a month", money(sugg_rounded / 12.0))
            caption(f"{money(sugg['sample_total'])} of real reconciled Core spending over the trailing "
                    f"{sugg['days_covered']} day{'s' if sugg['days_covered'] != 1 else ''}"
                    + ("" if sugg["full_window"] else f" (your data doesn't go back the full {sugg_window} days yet)")
                    + f", annualized and rounded to the nearest $100 ({money(sugg['annualized'], 2)} exactly). That's "
                    f"{money(abs(diff))} {'above' if diff >= 0 else 'below'} the current {money(h['core_budget'])} budget. "
                    "This is a suggestion only -- it never changes the budget by itself, and applying it doesn't touch anything already "
                    "reconciled in past months, only the annual figure everything else (pace, headroom, the funding target) is measured against.")
            if st.button(f"Apply as the {y} Core budget", key=f"sp_sugg_go_{ss.data_ver}"):
                key = "core_budget_2027" if y < 2028 else ("core_budget_2028" if y == 2028 else "core_budget_from_2028")
                plan.expenses[key] = float(sugg_rounded)
                ss.sp_msg = f"{y} Core budget updated to {money(sugg_rounded)} ({money(sugg_rounded / 12.0)} a month) from your recent spending."
                st.rerun()


def sp_bills():
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    y = _sp_year_pick()
    yc = spend_control(y)
    h, s, tk = yc["headroom"], yc["summary"], yc["tracker"]
    _sp_msg()
    rf = plan.recurring
    items = dict(rf.monthly)
    bill_names = sorted(set(rf.annual_bills) | set(rf.annual_bills_from_2028) | set(rf.annual_bill_year_amounts))
    bill_year = 2027 if ss.settings.get("replica") else y   # mirrors core_forecast_headroom's own replica handling
    bills = {n: annual_bill_amount_for(rf, n, bill_year) for n in bill_names}
    if y >= 2028 and not ss.settings.get("replica"):
        items.update(rf.monthly_from_2028)
    months_all = month_list(plan, today())
    with st.expander("Add a recurring bill"):                 # v21.27: every period from one place
        a1, a2 = st.columns([3, 2], vertical_alignment="bottom")
        nb_name = a1.text_input("Name", key=f"sp_nb_name_{ss.data_ver}", placeholder="For example WastePro USA")
        nb_amt = a2.number_input("Amount each time", min_value=0.0, step=10.0, format="%.2f", key=f"sp_nb_amt_{ss.data_ver}")
        a3, a4 = st.columns(2, vertical_alignment="bottom")
        nb_freq = a3.selectbox("How often", list(BILL_FREQUENCIES), index=2, key=f"sp_nb_freq_{ss.data_ver}")
        nb_date = a4.date_input("Next due", value=today(), key=f"sp_nb_date_{ss.data_ver}", format="YYYY-MM-DD")
        if st.button("Add bill", key=f"sp_nb_go_{ss.data_ver}", type="primary", disabled=not (nb_name or "").strip() or not nb_amt):
            ok, msg = add_recurring_bill(plan, entries, nb_name, float(nb_amt), BILL_FREQUENCIES[nb_freq], nb_date, months_all, today())
            ss.sp_msg = msg
            if ok:
                st.rerun()
        caption("Monthly bills are due on the same day every month; the others every 2, 3, 6 or 12 months from the next due date. "
                "Each posts a pending Core line to the ledger on its due dates, which counts in the budget, the balance outlook and the cash flow.")
    sugg_b = bill_amount_suggestions(plan, entries, today())                 # v21.38
    if sugg_b:
        with st.container(border=True):
            st.markdown(f"**Suggested bill amounts** ({len(sugg_b)})")
            caption(f"What you really paid over the last {BILL_SUGG_DAYS} days is more than {int(BILL_SUGG_PCT * 100)}% away from these bills' amounts. "
                    "Using the average moves the pending lines, so the budget and cash flow follow your ledger.")
            for sg in sugg_b:
                c1, c2, c3 = st.columns([3, 1, 1], vertical_alignment="center")
                c1.markdown(f"**{_h(sg['name'])}**: {_h(money(sg['current'], 2))} now, average {_h(money(sg['avg'], 2))} "
                            f"({'+' if sg['pct'] > 0 else ''}{sg['pct'] * 100:.0f}%, {sg['n']} payment{'s' if sg['n'] != 1 else ''})", unsafe_allow_html=True)
                if c2.button(f"Use {money(sg['use'], 2)}", key=f"bs_use_{ss.data_ver}_{sg['name']}", type="primary"):
                    ss.sp_msg = apply_bill_suggestion(plan, entries, sg["name"], sg["kind"], sg["use"], months_all, today())
                    st.rerun()
                if c3.button("Keep", key=f"bs_keep_{ss.data_ver}_{sg['name']}", help=f"Keep the current amount and hide this for {BILL_SUGG_SNOOZE_DAYS} days"):
                    until = today() + _dt.timedelta(days=BILL_SUGG_SNOOZE_DAYS)
                    plan.expenses.setdefault("bill_sugg_kept", {})[sg["name"]] = until.isoformat()
                    ss.sp_msg = f"{sg['name']} stays at {money(sg['current'], 2)}. The suggestion is hidden until {fmt_date(until)}."
                    st.rerun()
    st.subheader("Recurring bills")
    n_auto = ensure_monthly_recurring_lines(plan, entries, months_all, today())
    n_bill = ensure_annual_bill_lines(plan, entries, months_all, today())
    all_bills = all_recurring_bills(plan, entries, months_all, today(), y)
    db = pd.DataFrame([{"Bill": b["name"], "How often": b["freq"], "Next due": b["next"], "Each time": b["each"], "Per year": b["year_total"],
                        "Note": b["note"]} for b in all_bills], columns=["Bill", "How often", "Next due", "Each time", "Per year", "Note"])
    st.dataframe(db, hide_index=True, column_config={"Next due": st.column_config.DateColumn(format="MMM D, YYYY"),
                                                     "Each time": st.column_config.NumberColumn(format="dollar"),
                                                     "Per year": st.column_config.NumberColumn(format="dollar")})
    caption(f"{len(all_bills)} bills, soonest first: {money(sum(b['year_total'] for b in all_bills))} a year in total "
            f"({money(sum(b['year_total'] for b in all_bills if b['freq'] == 'Monthly'))} of it monthly). Each posts a pending Core line to the ledger "
            "on its due dates across your whole plan, which counts in the budget, the balance outlook and the cash flow.")
    with st.expander("Change a bill: how often, next due date or amount", expanded=any(b["next"] is None for b in all_bills)):
        no_date = [b["name"] for b in all_bills if b["next"] is None]
        if no_date:
            st.warning(f"{', '.join(no_date)} {'has' if len(no_date) == 1 else 'have'} no due date yet -- nothing posts to the ledger until you set one here.")
        caption("Change any cell: it is saved as soon as you leave the cell (tap elsewhere). Changing how often keeps the amount each time; the "
                "other due dates follow from the next one. A next due date in a later month starts the bill then. Pending ledger lines move to "
                "match; reconciled ones stay as the record.")
        editable = [b for b in all_bills if b["kind"] != "extra"]
        ss.sp_bills_base = editable
        ed_df = pd.DataFrame([{"Bill": b["name"], "How often": b["freq"] if b["freq"] in BILL_FREQUENCIES else None, "Next due": b["next"],
                               "Each time": round(b["each"], 2), "Status": b["status"]} for b in editable],
                             columns=["Bill", "How often", "Next due", "Each time", "Status"])
        ek = f"sp_bills_{ss.data_ver}_{ss.get('sp_bills_rev', 0)}"       # v25.37: a fresh table after every save, so no edit lingers
        sab = st.data_editor(ed_df, hide_index=True, disabled=["Bill", "Status"], key=ek, on_change=cb_bill_edits, args=(ek, y),
                             column_config={"How often": st.column_config.SelectboxColumn(options=list(BILL_FREQUENCIES)),
                                            "Next due": st.column_config.DateColumn(format="MMM D, YYYY"),
                                            "Each time": st.column_config.NumberColumn(format="dollar", min_value=0.0)})
        del sab
        st.divider()
        e1, e2, e3 = st.columns([2, 2, 1], vertical_alignment="bottom")              # v25.37: a bill that is being replaced
        mon_names = [b["name"] for b in editable if b["kind"] == "monthly"]
        end_name = e1.selectbox("End a monthly bill", ["—"] + mon_names, key=f"sp_bills_end_{ss.data_ver}")
        cur_k = today().strftime("%Y-%m")
        end_opts = [m for m in months_all if m >= cur_k][:24]
        end_m = e2.selectbox("Last payment in", end_opts, format_func=month_label, key=f"sp_bills_endm_{ss.data_ver}")
        if e3.button("End it", key=f"sp_bills_endgo_{ss.data_ver}", disabled=end_name == "—"):
            plan.recurring.monthly_end[end_name] = end_m
            before_n = _pending_lines_for(entries, end_name)
            ensure_monthly_recurring_lines(plan, entries, months_all, today())
            gone = before_n - _pending_lines_for(entries, end_name)
            ss.sp_msg = f"{end_name} ends after {month_label(end_m)}; {gone} later pending line{'s' if gone != 1 else ''} removed."
            st.rerun()
        caption("For a bill that is being replaced (moved to a card, say): it keeps posting up to that month, then stops. Remove deletes it entirely.")
        rm1, rm2 = st.columns([2, 1], vertical_alignment="bottom")
        rm_name = rm1.selectbox("Remove a bill entirely", ["—"] + [b["name"] for b in editable], key=f"sp_bills_rm_{ss.data_ver}")
        if rm2.button("Remove", key=f"sp_bills_rmgo_{ss.data_ver}", disabled=rm_name == "—"):
            kind = next(b["kind"] for b in editable if b["name"] == rm_name)
            n_rm = remove_monthly_item(plan, entries, rm_name) if kind == "monthly" else remove_annual_bill(plan, entries, rm_name)
            ss.sp_msg = f"{rm_name} removed" + (f"; {n_rm} pending line{'s' if n_rm != 1 else ''} removed with it." if n_rm else ".") + " Reconciled lines stay as the record."
            st.rerun()
        rn1, rn2, rn3 = st.columns([2, 2, 1], vertical_alignment="bottom")            # v21.38
        rn_old = rn1.selectbox("Rename a bill", ["—"] + [b["name"] for b in editable], key=f"sp_bills_rn_{ss.data_ver}")
        rn_new = rn2.text_input("New name", key=f"sp_bills_rnto_{ss.data_ver}", placeholder="As the bank words it, e.g. Gulf Breeze utility")
        if rn3.button("Rename", key=f"sp_bills_rngo_{ss.data_ver}", disabled=rn_old == "—" or not (rn_new or "").strip()):
            ok, msg = rename_recurring_bill(plan, entries, rn_old, rn_new)
            ss.sp_msg = msg
            if ok:
                st.rerun()
        caption("Use a name with a word the bank uses for this payee, so the daily bank lines line up with it.")
    with st.expander("Year-specific amounts", expanded=False):
        caption("For a bill paid every 2 to 12 months, the yearly amount is the flat figure, used for every year unless you override "
                "it here -- a bill whose dollar figure changes on its own schedule (a tax bill that steps down over a few "
                "years, say) instead of tracking a fixed amount. Add a row per year that needs its own figure; any year "
                "you don't list here just uses the flat amount (or the 2028-on figure, if you have one). Saving refreshes "
                "any pending line already posted for that year to match.")
        rows_yr = [{"Bill": name, "Year": int(yr), "Amount": float(amt)}
                   for name, yrs in rf.annual_bill_year_amounts.items() for yr, amt in yrs.items()]
        syr = st.data_editor(pd.DataFrame(rows_yr, columns=["Bill", "Year", "Amount"]), hide_index=True, num_rows="dynamic",
                             column_config={"Bill": st.column_config.SelectboxColumn(options=bill_names, required=True),
                                            "Year": st.column_config.NumberColumn(min_value=2024, max_value=2100, step=1, required=True),
                                            "Amount": st.column_config.NumberColumn(format="dollar", min_value=0.0, required=True)},
                             key=f"sp_bills_yr_{ss.data_ver}")
        if st.button("Save year-specific amounts", key=f"sp_bills_yrgo_{ss.data_ver}"):
            plan.recurring.annual_bill_year_amounts = parse_annual_bill_year_rows(syr.to_dict("records"))
            ensure_annual_bill_lines(plan, entries, months_all, today())
            ss.sp_msg = "Year-specific amounts saved."
            st.rerun()
    if (n_auto or n_bill) and not ss.get("sp_msg"):
        ss.sp_msg = f"{n_auto + n_bill} pending line{'s' if n_auto + n_bill != 1 else ''} added to the ledger for recurring bills just now."
    if rf.extras:
        st.subheader("Repeating items ticked on the ledger")
        for x in rf.extras:
            with st.container(border=True):
                until = f", until {month_label(x['until'])}" if x.get("until") else ""
                st.markdown(f"<div class='txrow'><div><div class='txname'>{_h(x['name'])}</div>"
                            f"<div class='txmeta'>From {_h(month_label(x['from']))}{_h(until)}, day {int(x.get('day', 1))}</div></div>"
                            f"<div class='txamt'>{_h(money(x['amount'], 2))} a month</div></div>", unsafe_allow_html=True)
                a, b, c = st.columns([2, 1, 1])
                a.text_input("New amount", value=f"{x['amount']:.2f}", key=f"sp_amt_{x['id']}", label_visibility="collapsed")
                b.button("Update", key=f"sp_up_{x['id']}", on_click=sp_cb_update, args=(x["id"],))
                c.button("Stop", key=f"sp_stop_{x['id']}", on_click=sp_cb_stop, args=(x["id"],))


def sp_deposits():
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    y = _sp_year_pick()
    yc = spend_control(y)
    h, s, tk = yc["headroom"], yc["summary"], yc["tracker"]
    rf = plan.recurring
    months_all = month_list(plan, today())
    _sp_msg()
    n_inc = ensure_income_recurring_lines(plan, entries, months_all, today())
    caption("DefComp payment and Savings deposit are expected every month same as any recurring bill, so the balance outlook "
            "now posts them forward too -- otherwise it would count every future expense but miss the income that funds it. "
            "There are only ever these two: DefComp pays a fixed amount you set per year, and Savings deposit is always "
            "your monthly funding target minus that same month's DefComp -- a plain subtraction, never a separate top-up, "
            "so the two can't quietly add up to more than the target (Andrew's call, September 2026).")
    with st.expander("Monthly funding target and DefComp's amount by year", expanded=not plan.recurring.defcomp_year_amount):
        cur_target = monthly_funding_target(plan, y)
        tc1, tc2 = st.columns(2)
        tc1.metric(f"Monthly funding target, {y}", money(cur_target))
        buf = tc2.number_input("Buffer, for peaks and troughs", min_value=0.0, step=50.0,
                               value=float(plan.recurring.deposit_buffer), key=f"sp_buffer_{ss.data_ver}")
        caption(f"Target = this year's Core budget ({money(h['core_budget'])}) ÷ 12, plus the buffer -- Core budget and the "
                "required deposit are one and the same thing, so the \"Suggested Core budget\" box above (from your last 90 "
                "days of real spending) is also the deposit recommendation: applying it moves this target, and Savings "
                "deposit right along with it. Only the buffer is set here by hand.")
        if st.button("Save buffer", key=f"sp_buffer_go_{ss.data_ver}"):
            plan.recurring.deposit_buffer = float(buf)
            ensure_income_recurring_lines(plan, entries, months_all, today())
            ss.sp_msg = "Buffer saved."
            st.rerun()
        caption("DefComp pays what your plan says it pays, not what last happened to land in the bank -- set its fixed "
                "monthly amount for each year below. A year left out falls back to the closest earlier year you have set; "
                "with no year set at all yet, it's guessed from your most recent reconciled DefComp deposit instead, "
                "flagged for review (and Savings deposit along with it) until you set a real figure. Add a row per year "
                "that needs its own amount; saving refreshes every pending line already posted to match.")
        rows_dc = [{"Year": int(yr), "Amount": float(amt)} for yr, amt in sorted(plan.recurring.defcomp_year_amount.items())]
        sdc = st.data_editor(pd.DataFrame(rows_dc, columns=["Year", "Amount"]), hide_index=True, num_rows="dynamic",
                             column_config={"Year": st.column_config.NumberColumn(min_value=2020, max_value=2100, step=1, required=True),
                                            "Amount": st.column_config.NumberColumn(format="dollar", min_value=0.0, required=True)},
                             key=f"sp_defcomp_yr_{ss.data_ver}")
        if st.button("Save DefComp amounts", key=f"sp_defcomp_yr_go_{ss.data_ver}"):
            def _blank(v):
                return v is None or v == "" or (isinstance(v, float) and v != v)
            plan.recurring.defcomp_year_amount = {str(int(row["Year"])): float(row["Amount"])
                                                  for row in sdc.to_dict("records")
                                                  if not _blank(row.get("Year")) and not _blank(row.get("Amount"))}
            ensure_income_recurring_lines(plan, entries, months_all, today())
            ss.sp_msg = "DefComp amounts saved."
            st.rerun()
    with st.expander("Check the day of the month for each deposit"):
        caption("The Day column is read from a matching reconciled line in your ledger where one is found, and day 1 "
                "otherwise. Correct it and save; every pending line already posted for that item is updated in place, "
                "not recreated.")
        rows_id = []
        for name in RECURRING_INCOME_ITEMS:
            c_day = plan.recurring.income_day.get(name)
            inferred = None if c_day else infer_income_line(entries, name, months_all, today())[0]
            rows_id.append({"Item": name, "Day": c_day or inferred or 1,
                            "Status": "Confirmed" if c_day else ("Guessed from your ledger" if inferred else "Guessed; no match found yet")})
        sid = st.data_editor(pd.DataFrame(rows_id), hide_index=True, disabled=["Item", "Status"],
                             column_config={"Day": st.column_config.NumberColumn(min_value=1, max_value=31, step=1)},
                             key=f"sp_inc_{ss.data_ver}")
        if st.button("Save days", key=f"sp_inc_go_{ss.data_ver}"):
            n = sum(confirm_income_day(plan, entries, row["Item"], int(row["Day"]), months_all) for _, row in sid.iterrows())
            ss.sp_msg = f"Days saved; {n} pending line{'s' if n != 1 else ''} updated."
            st.rerun()
    if n_inc and not ss.get("sp_msg"):
        ss.sp_msg = f"{n_inc} pending line{'s' if n_inc != 1 else ''} added to the ledger for recurring deposits just now."


def sp_monthly():
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    y = _sp_year_pick()
    yc = spend_control(y)
    h, s, tk = yc["headroom"], yc["summary"], yc["tracker"]
    d = tk.reset_index()
    d["Month"] = d["month"].map(lambda m: MONTH_NAMES[m - 1][:3])
    show = d[["Month", "status", "core_budget", "core_actual", "core_variance", "core_avg_3m", "one_time_spend", "one_time_remaining"]].copy()
    show.columns = ["Month", "Status", "Core budget", "Core actual", "Under budget", "3-month average", "One-time spent", "One-time left"]
    show["Status"] = show["Status"].replace({"NO DATA": "No data"})
    no = tk["status"].eq("NO DATA").to_numpy()
    for col in ("Core actual", "Under budget", "3-month average"):
        show.loc[no, col] = None
    cfg = {c: st.column_config.NumberColumn(format="dollar") for c in show.columns if c not in ("Month", "Status")}
    st.dataframe(show, hide_index=True, column_config=cfg)
    caption("Core actual counts reconciled Core lines, and for this month and earlier also Core lines already on the ledger but not yet ticked, "
            "so reconciling a known bill does not move it. Under budget is positive when you spent less than the monthly budget.")


def sp_pace():
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    y = _sp_year_pick()
    yc = spend_control(y)
    h, s, tk = yc["headroom"], yc["summary"], yc["tracker"]
    live = int((yc["control"].status != "NO DATA").sum())
    rows = [("Core spend to date", s["normalized_core_ytd"], s["normalized_budget_to_date"], s["normalized_variance"], s["normalized_status"].replace("ON TRACK", "On track").replace("OVER", "Over")),
            ("Full-year forecast", s["normalized_full_year"], s["core_budget"], s["full_year_variance"], s["full_year_status"].replace("ON TRACK", "On track").replace("OVER", "Over")),
            ("One-time balance for the year", s["one_time_budget"] - s["one_time_balance"], s["one_time_budget"], s["one_time_balance"], "Available" if s["one_time_balance"] >= 0 else "Overspent")]
    dp = pd.DataFrame(rows, columns=["View", "Actual or forecast", "Budget", "Left", "Status"])
    if not live:
        st.info("No reconciled months yet for this year.")
    st.dataframe(dp, hide_index=True, column_config={c: st.column_config.NumberColumn(format="dollar") for c in ("Actual or forecast", "Budget", "Left")})
    pace_start = pace_actual_start_month(y)
    transition_note = (f" January through {month_label(f'{y}-{pace_start - 1:02d}')} are counted at budget rather than their real total, "
                        "since big one-off items weren't consistently split out to One-Time that early in the year; "
                        f"{month_label(f'{y}-{pace_start:02d}')} on uses the real reconciled number. ") if pace_start > 1 else " "
    caption(f"Based on {live} month{'s' if live != 1 else ''} with reconciled data.{transition_note}"
            "Core spend to date is your real Core spending, card payments included at their real amount -- nothing is smoothed. Up to this month it "
            "includes Core lines already on the ledger but not yet ticked, so reconciling a bill you already knew about changes nothing. "
            "A genuine one-off big purchase belongs in One-Time instead of Core, which is what keeps this figure meaningful. Full-year "
            "forecast is that total plus the Core lines already on the ledger for each month still ahead (card-payment estimates, bills, "
            "annual items), or the monthly budget for a month with none. The one-time budget for "
            "2026 covers September to December only.")


