def ledger_control(plan: Plan, entries: dict, key: str) -> dict:
    rows = entries["ledger"].get(key, [])
    led = ledger_frame(rows)
    led["ledger_month"] = int(key[-2:])
    year = int(key[:4])
    c = monthly_control(led, year, plan.expenses["card_allowance"], tuple(plan.expenses["card_keywords"])).loc[int(key[-2:])]
    unclassified = sum(1 for r in rows if (_n(r.get("debit")) > 0 or _n(r.get("credit")) > 0) and not r.get("cls"))
    return {"core": float(c.core), "one_time": float(c.one_time), "excluded": float(c.excluded), "pending": int(c.pending_debits),
            "status": c.status, "normalized": float(c.normalized_core), "unclassified": unclassified}


def month_status(plan, entries, key):
    t = today()
    magi = entries["magi"].get(key, {}).get("status") == "Finalized"
    b = entries["balances"].get(key, {})
    have = sum(isinstance(b.get(a), (int, float)) for a in NINE_ACCOUNTS)
    c = ledger_control(plan, entries, key)
    exp = c["status"] == "Reconciled" and c["unclassified"] == 0
    ended, due = month_end_date(key) < t, due_date(key)
    done = magi and have == 9 and exp
    overall = "Future" if not ended else ("Complete" if done else ("Overdue" if t > due else "Due"))
    missing = [n for n, ok in (("income", magi), ("balances", have == 9), ("transactions", exp)) if not ok]
    return {"magi": magi, "bal": have == 9, "have": have, "exp": exp, "ctl": c, "ended": ended, "due": due, "overall": overall, "missing": missing}


def goto_month(key):
    ss = st.session_state
    ss.month = key
    ss[f"w_month_{ss.data_ver}"] = key


def banner(plan, entries, months):
    late = cur = None
    for k in months:
        s = month_status(plan, entries, k)
        if late is None and s["ended"] and s["overall"] != "Complete":
            late = (k, s)
        if cur is None and not s["ended"]:
            cur = k
    box = st.container(border=True)
    with box:
        if late:
            k, s = late
            (st.error if s["overall"] == "Overdue" else st.warning)(
                f"**{month_label(k)} is {'overdue' if s['overall'] == 'Overdue' else 'due ' + fmt_date(s['due'])}.** Still to do: "
                f"{', '.join(s['missing'])}. Due {fmt_date(s['due'])}.")
            st.button(f"Open {month_short(k)}", key="banner_go", on_click=goto_month, args=(k,))
        elif cur:
            st.success(f"**You are caught up.** {month_label(cur)} closes {fmt_date(month_end_date(cur))} and is due {fmt_date(due_date(cur))}.")
        else:
            st.success("**You are caught up.**")


