def page_updates():
    """v21.51: Monthly updates is a dashboard of tiles for the chosen month; each tile opens one view, with a way back."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    months = month_list(plan, today())
    ensure_monthly_recurring_lines(plan, entries, months, today())
    ensure_income_recurring_lines(plan, entries, months, today())
    ensure_annual_bill_lines(plan, entries, months, today())
    view = ss.get("mu_view") or "hub"
    if view not in MU_VIEWS and view != "hub":
        view = ss.mu_view = "hub"
    if view != "hub":
        back_bar("‹ Monthly updates", _mu_go, ("hub",), "mu_back")
    st.title("Monthly updates" if view == "hub" else MU_VIEWS[view])
    banner_box = st.container()          # filled in below, after this run's edits have landed
    key = f"w_month_{ss.data_ver}"
    if key not in ss or ss[key] not in months:
        ss[key] = ss.month if ss.month in months else months[-1]
    k = st.selectbox("Month", months, key=key, format_func=month_label)
    ss.month = k
    if view == "hub":
        _mu_hub(plan, entries, months, k)
    elif view == "reconcile":
        upd_reconcile(plan, entries, k)
    elif view == "bankmatch":
        upd_bankmatch(plan, entries, k)
    elif view == "chart":
        upd_chart(plan, entries, k)
    elif view == "add":
        upd_add(plan, entries, k)
    elif view == "income":
        upd_income(plan, entries, k)
    elif view == "balances":
        upd_balances(plan, entries, months, k)
    elif view == "close":
        upd_overview(plan, entries, months, k)
    elif view == "outlook":
        outlook_view()
    # The reminder banner shows on the tiles page only (a view is for one job); it is drawn last so it reflects this run's edits.
    if view == "hub":
        with banner_box:
            banner(plan, entries, months)


def _mu_hub(plan, entries, months, k):
    ss = st.session_state
    caption("Tap a tile to open it. Each month closes with three things: income, balances and transactions.")
    ensure_ids(entries["ledger"].get(k, []))
    rows = entries["ledger"].get(k, [])
    opening = _opening(entries, plan, k)
    minimum = min_balance(plan)
    bal = running_balances(rows, opening)
    lo = low_point(bal)
    first_open = entries["opening"].get(months[0], 0.0)
    rbal = reconciled_balance(entries, months, k, first_open)
    s = month_status(plan, entries, k)
    c = s["ctl"]
    # reconcile
    if c["status"] == "NO DATA":
        rec = ("Reconcile", money(rbal, 2), "idle", "No lines yet", "Bank lines arrive each night")
    elif c["pending"] or c["unclassified"]:
        rec = ("Reconcile", money(rbal, 2), "warn" if c["unclassified"] else "idle",
               f"{c['pending']} to reconcile" + (f", {c['unclassified']} need a class" if c["unclassified"] else ""), "Bank balance, reconciled lines")
    else:
        rec = ("Reconcile", money(rbal, 2), "ok", "All reconciled", "Bank balance, reconciled lines")
    # bank match
    cur, _m = current_month_key()
    chk = _auto_bank_check() if k == cur else None
    mine = [x for x in entries.get("bank_checks", []) if x.get("month") == k]
    if chk and chk["status"] == "match":
        bm = ("Bank match", "Matches", "ok", f"Wells {money(chk['bank'], 2)}", f"Fetch of {_day(chk['date'])}" if chk.get("date") else "Last fetch")
    elif chk and chk["status"] == "waiting":
        bm = ("Bank match", "Waiting", "idle", f"{chk['waiting']} bank line{'s' if chk['waiting'] != 1 else ''} to review", "Checked once they are in")
    elif chk:
        bm = ("Bank match", "Differs", "warn", f"Wells {money(abs(chk['diff']), 2)} {'less' if chk['diff'] < 0 else 'more'}", "Open to see why")
    elif mine:
        bm = ("Bank match", "Matched", "ok", money(mine[-1]["balance"], 2), _fmt_local(mine[-1]["t"], tz_name()))
    else:
        bm = ("Bank match", "Not checked", "idle", "Check against your bank", "")
    # chart
    ch = ("Balance chart", money(lo["balance"], 2), "ok" if lo["balance"] >= minimum else "warn",
          "Lowest point this month", f"Minimum {money(minimum)}" + ("" if lo["date"] == "Start of month" else f" · lowest on {_day(lo['date'])}"))
    # add
    n_tx = sum(1 for r in rows if not r.get("xfer"))
    ad = ("Add transactions", f"{n_tx} line{'s' if n_tx != 1 else ''}", "idle", "Add one or paste a statement", f"in {month_short(k)}, not counting transfers")
    # income
    t = income_totals(income_record(entries, k, plan.inputs.defcomp.withholding_rate))
    inc = ("Income", money(t["total"]) if t["total"] else "\u2014", "ok" if s["magi"] else "idle", "Finalized" if s["magi"] else "Draft",
           "Taxable income this month")
    # balances
    b = entries["balances"].get(k, {})
    bt = sum(_n(b.get(a)) for a in NINE_ACCOUNTS) if s["bal"] else None
    bl = ("Balances", f"{s['have']} of 9", "ok" if s["bal"] else ("warn" if s["ended"] else "idle"),
          "Complete" if s["bal"] else "Accounts entered", f"Financial assets {money_m(bt)}" if bt is not None else "Month-end balances")
    # close
    done_n = sum([s["magi"], s["bal"], s["exp"]])
    kind = {"Complete": "ok", "Overdue": "bad", "Due": "warn", "Future": "idle"}.get(s["overall"], "idle")
    cl = ("Month close", s["overall"] if s["overall"] != "Future" else "Open", kind, f"{done_n} of 3 done", f"Due {fmt_date(s['due'])}")
    # outlook (v21.69: moved here from the Ledger page)
    try:
        ol = outlook(entries, months, first_open, minimum, top_up_target(plan), cur, today().strftime("%Y-%m-%d"))
        lo2 = ol["lowest"] if ol["rows"] else None
    except Exception:  # noqa: BLE001 - the tile must always draw
        ol, lo2 = None, None
    if lo2:
        nb = sum(r["below"] for r in ol["rows"])
        ou = ("Balance outlook", money(lo2["lowest"], 2), "warn" if nb else "ok", "Lowest point ahead",
              (f"{nb} month{'s' if nb != 1 else ''} below your minimum" if nb else f"Above {money(minimum)} every month") + (f"\nTransfers to plan {money(ol['total_transfers'])}" if ol["total_transfers"] else ""))
    else:
        ou = ("Balance outlook", "\u2014", "idle", "Nothing to project yet", "Checking month by month")
    T = lambda key, t, view: {"key": key, "label": t[0], "value": t[1], "kind": t[2], "note": t[3], "extra": t[4], "go": (lambda v=view: _mu_go(v))}
    tiles = [T("mu_rec", rec, "reconcile"), T("mu_bank", bm, "bankmatch"), T("mu_chart", ch, "chart"), T("mu_add", ad, "add"),
             T("mu_inc", inc, "income"), T("mu_bal", bl, "balances"), T("mu_close", cl, "close"), T("mu_out", ou, "outlook")]
    with _tile_area():
        for r0 in range(0, len(tiles), TILES_PER_ROW):
            chunk = tiles[r0:r0 + TILES_PER_ROW]
            cols = st.columns(len(chunk), gap="small")
            for i, tl in enumerate(chunk):
                with cols[i]:
                    _segment(tl["key"], "cash", "first" if i == 0 else ("last" if i == len(chunk) - 1 else "mid"), tl["label"], tl["value"], tl["kind"],
                             tl["note"], "", tl["extra"], go=tl["go"])


def upd_overview(plan, entries, months, k):
    s = month_status(plan, entries, k)
    st.subheader(month_label(k))
    caption(f"Three things close each month. Due {fmt_date(s['due'])}.")
    t = income_totals(income_record(entries, k, plan.inputs.defcomp.withholding_rate))
    b = entries["balances"].get(k, {})
    bal_total = sum(_n(b.get(a)) for a in NINE_ACCOUNTS) if s["bal"] else None
    c = s["ctl"]
    rows = [("Income", "Finalized" if s["magi"] else "Draft", f"{money(t['total'], 2)} of taxable income entered" if t["total"] else "Nothing entered yet"),
            ("Balances", "Complete" if s["bal"] else f"{s['have']} of 9 accounts", f"Financial assets {money(bal_total)}" if bal_total is not None else "Enter all nine accounts to total the month"),
            ("Transactions", "Reconciled" if s["exp"] else ("No data" if c["status"] == "NO DATA" else f"{c['pending']} pending" + (f", {c['unclassified']} unclassified" if c["unclassified"] else "")),
             "No transactions yet" if c["status"] == "NO DATA" else f"Core {money(c['core'])}, one-time {money(c['one_time'])}")]
    st.dataframe(pd.DataFrame(rows, columns=["Step", "Status", "What is in it"]), hide_index=True)
    st.subheader("All months")
    allrows = []
    for mk in months:
        x = month_status(plan, entries, mk)
        allrows.append({"Month": month_short(mk), "Income": "Done" if x["magi"] else "Open", "Balances": "Done" if x["bal"] else "Open",
                        "Transactions": "Done" if x["exp"] else "Open", "Due": fmt_date(x["due"]), "Status": x["overall"]})
    st.dataframe(pd.DataFrame(allrows), hide_index=True)


def money_input(label, store: dict, field: str, prefix: str, disabled=False, help=None):
    ss = st.session_state
    key = f"{prefix}_{field}"
    if key not in ss:
        ss[key] = money_str(store.get(field))
    raw = st.text_input(label, key=key, placeholder="0.00", disabled=disabled, help=help)
    if not disabled:
        v = parse_money(raw)
        if v is None:
            store.pop(field, None)
        else:
            store[field] = v
    return raw


def income_watch_text(w, guard_name, ref_name):
    """(headline, sentence) for the if-this-continues check."""
    g, r = w["guardrail"], w["reference"]
    if w["status"] == "bad":
        return (f"Past the {ref_name}: you could compromise the subsidy cliff",
                f"Your income so far, {money(w['ytd'])}, is already past the {money(r)} {ref_name}." if w["ytd_over_reference"]
                else f"If this continues you finish the year at {money(w['continues'])}, past the {money(r)} {ref_name}. You could compromise the subsidy cliff.")
    if w["status"] == "warn":
        return (f"Above your {guard_name}: ease off before year end",
                f"Your income so far, {money(w['ytd'])}, is already above your {money(g)} {guard_name}." if w["ytd_over_guardrail"]
                else f"If this continues you finish the year at {money(w['continues'])}, above your {money(g)} {guard_name}.")
    return (f"Inside your {guard_name}", f"At this pace you finish the year at {money(w['continues'])}, inside your {money(g)} {guard_name}.")


def income_watch_lines(w, k, guard_name, ref_name):
    """The lines and the colored message of the if-this-continues check."""
    g = w["guardrail"]
    write(f"Year so far through {month_short(k)}: {money(w['ytd'])}")
    write(f"If this month's income repeats each month to December: {money(w['continues'])}")
    if w.get("quarterly"):
        caption(f"Allows for the quarterly fund dividends (about {money(w['quarterly'])} in March, June, September and December): "
                + (f"{money(w['quarterly_here'])} of this month is treated as this quarter's and not repeated" if w.get("quarterly_here")
                   else ("no quarterly dividend is in this month's figures yet" if w.get("quarter_month") else "this is not a quarterly month"))
                + (f"; {w['quarterly_left']} quarterly month{'s' if w['quarterly_left'] != 1 else ''} still to come {'are' if w['quarterly_left'] != 1 else 'is'} added." if w.get("quarterly_left") else "; none left this year."))
    write(f"Room under your {money(g)} {guard_name} so far: {money(w['room'])}" if w["room"] >= 0 else f"Over your {money(g)} {guard_name} so far by {money(-w['room'])}")
    head, msg = income_watch_text(w, guard_name, ref_name)
    status_line(w["status"], head)
    caption(msg)


