def income_side(plan, entries, k, rec):
    rate = plan.inputs.defcomp.withholding_rate
    t = income_totals(income_record(entries, k, rate))
    cur, n_cur = run_rate_projection(entries, rate)
    with_this, n_with = run_rate_projection(entries, rate, include=k)
    with st.container(border=True):
        st.markdown("**This month**")
        write(f"Interest and dividends: {money(t['int_div'], 2)}")
        write(f"Everything else: {money(t['other'], 2)}")
        write(f"**Taxable income: {money(t['total'], 2)}**")
        st.markdown("**Projected annual MAGI**")
        write(f"Finalized months only ({n_cur}): {money(cur) if cur is not None else '–'}")
        if rec.get("status") != "Finalized":
            write(f"If you finalize {month_short(k)} ({n_with}): {money(with_this) if with_this is not None else '–'}")
        caption("Recurring income is multiplied up to 12 months, with the quarterly fund dividends counted four times a year rather than every month. "
                "Realized gains count once. The more months you finalize, the steadier this gets.")
        y = int(k[:4])
        if y in plan.meta.get("practice_years", [2026]):
            st.markdown("**Subsidy check**")
            R0 = model()
            w = income_watch(entries, rate, month_list(plan, today()), y, k, float(st.session_state.settings["warning"]), float(R0["limits"].get(y, 84600.0)))
            if w["needs_history"]:
                caption("Import your Jan to Jul MAGI history on the Your data page to see the guardrail check.")
            else:
                income_watch_lines(w, k, "guardrail", "reference")
            caption(plan.meta.get("practice_note", "This is a practice year, so no subsidy limit applies yet."))
        elif y <= 2033:
            s = dict(st.session_state.settings); s.update({"aca_year": y, "whatif": False, "one_time": 0.0})
            R = run_model(plan, s, entries)
            m = R["aca"]
            st.markdown(f"**Subsidy check, {y}**")
            write(f"Projected year-end MAGI: {money(m['projected_with_one_time'])}")
            write(f"Limit: {money(m['limit'])}  |  Headroom: {money(m['headroom'])}")
            write(f"Room to convert: {money(R['window']['capacity'])}")
            status_line("ok" if m["alert"] == "OK" else ("warn" if m["alert"] == "EARLY WARNING" else "bad"),
                        "Within your early-warning line" if m["alert"] == "OK" else ("Above your early-warning line" if m["alert"] == "EARLY WARNING" else "Over the subsidy limit"))
            caption(f"{m['finalized_months']} of 12 months finalized; the rest uses the plan.")
            st.markdown("**If this month continues**")
            income_watch_lines(income_watch(entries, rate, month_list(plan, today()), y, k, float(m["warning_target"]), float(m["limit"]),
                                            adjust=float(m.get("year_adjust", 0.0))), k, "early-warning line", "limit")


def _inc_fetch(k):
    ss = st.session_state
    ss.inc_err, ss.inc_month = "", None
    y, m = int(k[:4]), int(k[5:7])
    start = _dt.datetime(y, m, 1, tzinfo=_dt.timezone.utc) - _dt.timedelta(days=1)
    end = (_dt.datetime(y + (m == 12), m % 12 + 1, 1, tzinfo=_dt.timezone.utc) + _dt.timedelta(days=1))
    saved = ss.plan.expenses.get("sfin_map") or {}
    if (end - start).days > 89 or (today() - start.date()).days > 89:
        ib = _inbox()
        lines = [ln for ln in ((ib or {}).get("lines") or []) if ln["date"][:7] == k]
        if not lines:
            ss.inc_err = "SimpleFIN only goes back about 90 days and the daily fetch has nothing for this month, so enter it by hand from the statements."
            return False
        snaps = (ib or {}).get("snapshots") or {}
        accts = list({a["id"]: a for k2 in sorted(snaps) for a in snaps[k2]["accounts"]}.values())
        errs = []
    else:
        try:
            data = simplefin_accounts(_sfin_url(), start=start.timestamp(), end=end.timestamp())
        except StorageError as e:
            ss.inc_err = str(e)
            return False
        accts, lines, errs = simplefin_account_list(data), simplefin_lines(data), simplefin_errors(data)
    mapping = {a["id"]: (saved[a["id"]] if a["id"] in saved else sfin_guess_line(a["org"], a["name"])) for a in accts}
    ss.inc_rows = income_candidates(lines, mapping, k, ss.plan.expenses.get("income_rules") or {})
    ss.inc_err = "; ".join(errs)
    ss.inc_month = k
    return True


def _inc_apply(k):
    ss = st.session_state
    edited = ss.get("inc_edited") or []
    rules = dict(ss.plan.expenses.get("income_rules") or {})
    for r in edited:
        key = income_key(r["desc"])
        if r.get("kind") in ("int", "div", "muni"):
            rules[key] = {"kind": r["kind"], "amt": r["amount"]}
        elif key not in rules or r.get("kind") == "none":   # neither: remembered so it is not asked again (an interest or dividend rule is kept
            rules[key] = {"kind": "none", "amt": r["amount"]}   # when a one-off big line under that name is left blank)
    ss.plan.expenses["income_rules"] = rules
    ss.plan.expenses["income_seen"] = (list(ss.plan.expenses.get("income_seen") or []) + [r["id"] for r in edited if r.get("id")])[-600:]
    ss.income_fill = (k, income_totals_from(edited))
    n = len(ss.income_fill[1])
    ss.income_toast = (f"Filled {n} interest and dividend box{'es' if n != 1 else ''} for {month_label(k)}. The app will remember your choices." if n
                       else f"Noted for {month_label(k)}: no interest or dividends among those lines.")


def _inc_open(rows, k, err: str = ""):
    """Opens the review window afresh: a new editor each time, so choices from a window closed without Apply never linger out of sight
    (v21.17: the table showed blank while hidden earlier choices still counted in the totals)."""
    ss = st.session_state
    old = f"inc_editor_{ss.get('inc_open_n', 0)}"
    ss.pop(old, None)
    ss.inc_open_n = ss.get("inc_open_n", 0) + 1
    ss.inc_rows, ss.inc_month, ss.inc_err, ss.inc_edited = rows, k, err, []
    _inc_review()


@st.dialog("Check these before anything changes", width="large")
def _inc_review():
    ss = st.session_state
    rows, k = ss.get("inc_rows") or [], ss.get("inc_month")
    if ss.get("income_fill"):                           # Apply was pressed: leave the window and let the page fill in the boxes
        st.rerun()
    write(f"**Money that came in during {month_label(k)}** to the accounts feeding Wells and Schwab taxable. Set what each line is; Neither (or blank) for a transfer, a sale or anything else.")
    caption("Schwab often lists a dividend under the fund's name alone, so the app cannot tell it from a sale. Set the ones that are dividends once (Tax-exempt dividend for the muni funds, SCMB and VTEB) and it remembers them by name "
            "and fills them in by itself from then on; a line much larger than last time is left blank for you to look at. Capital gain distributions belong under realized gains. "
            "A bank line is not a substitute for your 1099.")
    if not rows:
        st.info("No money-in lines came back for those accounts this month.")
        return
    labels = {"": "", "int": "Interest", "div": "Dividend", "muni": "Tax-exempt dividend", "none": "Neither"}
    df = pd.DataFrame([{"Account": r.get("acct_name", ""), "Date": r["date"], "Bank line": r["desc"][:60], "Amount": r["amount"], "Counts as": labels.get(r["kind"], "")} for r in rows])
    ed = st.data_editor(df, hide_index=True, use_container_width=True, disabled=["Account", "Date", "Bank line", "Amount"], key=f"inc_editor_{ss.get('inc_open_n', 0)}",
                        column_config={"Amount": st.column_config.NumberColumn(format="$%.2f"),
                                       "Counts as": st.column_config.SelectboxColumn("Counts as", options=["", "Interest", "Dividend", "Tax-exempt dividend", "Neither"], width="medium")})
    inv = {v: k2 for k2, v in labels.items()}
    edited = [{**r, "kind": inv.get(ed.iloc[i]["Counts as"] or "", "")} for i, r in enumerate(rows)]
    tot = income_totals_from(edited)
    names = {f: lab for _g, its in INCOME_GROUPS for f, lab in its}
    cur = ss.entries["magi"].get(k, {})
    for f in INCOME_FEED_FIELDS:
        if f in tot:
            write(f"{names[f]}: **{money(tot[f], 2)}** (now {money(cur.get(f), 2) if isinstance(cur.get(f), (int, float)) else 'blank'})")
    c = st.columns([1, 1, 3])
    ss.inc_edited = edited
    c[0].button("Apply", type="primary", key="inc_apply", on_click=_inc_apply, args=(k,))
    if c[1].button("Cancel", key="inc_cancel"):
        st.rerun()


def upd_income(plan, entries, k):
    ss = st.session_state
    existed = k in entries["magi"]
    rec = entries["magi"].get(k) or {"status": "Draft", "notes": ""}
    fin = rec.get("status") == "Finalized"
    y = int(k[:4])
    prefix = f"inc_{ss.data_ver}_{k}"
    sk = f"{ss.data_ver}_{k}"
    snaps, prevs, acks = ss.setdefault("watch_snap", {}), ss.setdefault("watch_prev", {}), ss.setdefault("watch_ack", {})
    pend = ss.pop("watch_cancel", None)                 # Cancel was chosen in the popup: put the earlier amounts back before any box is drawn
    if pend and pend[0] == sk:
        for f in INCOME_FIELDS:
            v = pend[1].get(f)
            ss[f"{prefix}_{f}"] = money_str(v)
            if v is None:
                rec.pop(f, None)
            else:
                rec[f] = v
        acks.pop(sk, None)
    pf = ss.get("income_fill")
    if pf and pf[0] == k and not fin:                   # an interest and dividend fill was applied: set the boxes before any is drawn
        ss.pop("income_fill")
        auto = dict(rec.get("auto_inc") or {})
        for f, v in pf[1].items():
            ss[f"{prefix}_{f}"] = money_str(v)
            rec[f] = auto[f] = v                        # counts as filled from the bank, so later lines keep it up to date
        if pf[1]:
            rec["auto_inc"] = auto
        entries["magi"][k] = rec
        existed = True
        ss.income_toast_show = ss.pop("income_toast", None)
    watch = cur_fields = None
    status, culprits = "ok", []
    if not fin and (y in plan.meta.get("practice_years", [2026]) or 2027 <= y <= 2033):
        probe = dict(rec)                               # the amounts as they stand now, including what was just typed
        for f in INCOME_FIELDS:
            v = parse_money(ss[f"{prefix}_{f}"]) if f"{prefix}_{f}" in ss else probe.get(f)
            if v is None:
                probe.pop(f, None)
            else:
                probe[f] = v
        e2 = {**entries, "magi": {**entries["magi"], k: probe}}
        _ts = model()["ts"]
        watch = income_watch(e2, plan.inputs.defcomp.withholding_rate, month_list(plan, today()), y, k,
                             float(ss.settings["warning"]), float(model()["limits"].get(y, 84600.0)),
                             adjust=-float(_ts.loc[y, "loss_used"]) if y in _ts.index else 0.0)
        if watch.get("needs_history"):
            watch = None
        else:
            cur_fields = {f: probe.get(f) for f in INCOME_FIELDS}
            status = watch["status"]
            if sk not in snaps or status == "ok":
                snaps[sk] = dict(cur_fields)            # the last state that was fine
            if status != "ok":
                culprits = [f for f in INCOME_FIELDS if cur_fields.get(f) != snaps[sk].get(f)]
            if status != "bad":
                acks.pop(sk, None)
    st.subheader(f"Income for {month_label(k)}")
    caption("Enter taxable income when it is received or realized. Leave a field blank if there is none this month."
               + (" This month is finalized; reopen it to make changes." if fin else ""))
    left, right = st.columns([3, 2])
    with left:
        for gname, items in INCOME_GROUPS:
            st.markdown(f"**{gname}**")
            for f, lab in items:
                flag = status if f in culprits and status in ("bad", "warn") else ""
                with st.container(key=f"fld{flag}_{f}"):
                    money_input(lab, rec, f, prefix, disabled=fin)
                    if flag == "bad":
                        st.markdown(":red[**Past the subsidy reference with this amount**]")
                    elif flag == "warn":
                        st.markdown(":orange[**Above your guardrail with this amount**]")
            if gname == "Interest and dividends":
                if _n(rec.get(MUNI_FIELD)) > _n(rec.get("schwabDiv")) + _n(rec.get("wellsDiv")) + 0.005:
                    st.warning("The tax-exempt muni figure is more than the dividends it is part of. It is a part of the Schwab dividends, not an extra amount.")
                if ss.get("income_toast_show"):
                    st.toast(ss.pop("income_toast_show"), icon="\u2705")
                chk = income_bank_check(plan, _inbox(), k) if k >= AUTO_INCOME_FROM else None
                if chk is not None and not fin:
                    auto = rec.get("auto_inc") or {}
                    hand = [f for f in INCOME_FEED_FIELDS if f in chk["totals"] and f not in auto and isinstance(rec.get(f), (int, float))
                            and abs(rec[f] - chk["totals"][f]) >= 0.005]
                    caption("Filled in automatically from the daily bank fetch as the lines arrive"
                            + (f" (last on {rec['auto_inc_at'][:10]})" if rec.get("auto_inc_at") else "") + ". A box you type in yourself is left as you set it."
                            + (f" The bank lines add to {', '.join(money(chk['totals'][f], 2) for f in hand)} for the box{'es' if len(hand) > 1 else ''} you typed." if hand else ""))
                    if chk["unknown"]:
                        n = len(chk["unknown"])
                        st.warning(f"{n} money-in line{'s' if n != 1 else ''} at Wells or Schwab the app does not recognize ({money(sum(r['amount'] for r in chk['unknown']), 2)}). "
                                   "Say once whether each is interest, a dividend or neither, and it is filled in by itself from then on.")
                    fc = wells_feed_check(plan, _inbox())
                    if fc["missing"]:
                        st.warning("Not feeding the Wells interest line, so its interest is missing here: " + ", ".join(fc["missing"])
                                   + ". Open Your data, then the bank connection, and set it to Wells.")
                    if st.button("Review the bank lines" + (" now" if chk["unknown"] else ""), key=f"inc_fill_{k}", type=("primary" if chk["unknown"] else "secondary")):
                        _inc_open(chk["rows"], k)
                elif chk is not None and fin:
                    off = [f for f in INCOME_FEED_FIELDS if f in chk["totals"] and abs(float(rec.get(f) or 0) - chk["totals"][f]) >= 0.005]
                    if off:
                        names = dict(INCOME_GROUPS[0][1])
                        st.info("The bank lines now add up differently from what was finalized: "
                                + "; ".join(f"{names[f]} {money(chk['totals'][f], 2)} (finalized {money(float(rec.get(f) or 0), 2)})" for f in off)
                                + ". Reopen the month if the bank figure is right.")
                elif not fin and _sfin_url():
                    if st.button("Fill interest and dividends from my bank", key=f"inc_fill_{k}"):
                        if _inc_fetch(k):
                            _inc_open(ss.inc_rows, k, ss.get("inc_err", ""))
                    if ss.get("inc_err") and ss.get("inc_month") in (None, k):
                        st.warning(ss.inc_err)
            if gname == "Gains and other income":
                dc = defcomp_received(entries["ledger"].get(k, []), plan.inputs.defcomp.withholding_rate)
                st.text_input("Deferred compensation received", value=money_str(dc), disabled=True, key=f"{prefix}_dc_{'x' if dc is None else 'y'}",
                              help="Filled in from reconciled DefComp deposits on the Transactions tab, grossed up for withholding.")
        notes_key = f"{prefix}_notes"
        if notes_key not in ss:
            ss[notes_key] = rec.get("notes", "")
        rec["notes"] = st.text_area("Notes", key=notes_key, disabled=fin, placeholder="Anything unusual this month")
        if fin:
            if st.button("Reopen this month", key=f"reopen_{k}"):
                rec["status"] = "Draft"; entries["magi"][k] = rec; st.rerun()
        else:
            if ss.get("pending_confirm") == ("fin", k):
                t = income_totals(income_record(entries, k, plan.inputs.defcomp.withholding_rate))
                with st.container(border=True):
                    st.markdown(f"**Finalize {month_label(k)}?**")
                    write(("No taxable income is entered, so this month will count as zero. " if t["total"] == 0 else "")
                             + "Finalizing adds these figures to the projection" + (" and the subsidy monitor" if int(k[:4]) >= 2027 else "") + ". You can reopen the month later.")
                    a, b = st.columns(2)
                    if a.button("Finalize", key=f"fin_yes_{k}", type="primary"):
                        rec["status"] = "Finalized"; entries["magi"][k] = rec; ss.pending_confirm = None; st.rerun()
                    if b.button("Cancel", key=f"fin_no_{k}"):
                        ss.pending_confirm = None; st.rerun()
            elif st.button("Finalize month", key=f"fin_{k}", type="primary"):
                ss.pending_confirm = ("fin", k); st.rerun()
    has_content = any(f in rec for f in INCOME_FIELDS) or rec.get("notes") or rec.get("status") == "Finalized"
    if existed or has_content:
        entries["magi"][k] = rec
    with right:
        income_side(plan, entries, k, rec)
    if watch is not None:
        prev_fields = dict(prevs.get(sk, snaps[sk]))    # the amounts before the latest change, for Cancel
        pending = status == "bad" and bool(culprits) and acks.get(sk) != round(watch["continues"], 2)
        if not pending:
            prevs[sk] = dict(cur_fields)                # only move on once the popup has been answered, so Cancel always has the earlier amounts
        if pending:
            labels = dict(f_lab for _g, its in INCOME_GROUPS for f_lab in its)
            _head, msg = income_watch_text(watch, "guardrail" if y in plan.meta.get("practice_years", [2026]) else "early-warning line",
                                           "reference" if y in plan.meta.get("practice_years", [2026]) else "limit")
            ss["_watch_dialog"] = sk                     # a marker the tests can read
            income_warn_dialog(sk, "**" + msg + "**", [f"{labels[f]} {money(cur_fields[f], 2)}" for f in culprits if cur_fields.get(f) is not None],
                               prev_fields, round(watch["continues"], 2))


def upd_balances(plan, entries, months, k):
    ss = st.session_state
    existed = k in entries["balances"]
    b = entries["balances"].get(k) or {"notes": ""}
    st.subheader(f"Balances for {month_label(k)}")
    caption("Month-end balances only. Unrealized growth stays here and does not touch MAGI.")
    prefix = f"bal_{ss.data_ver}_{k}"
    left, right = st.columns([3, 2])
    with left:
        src = entries.setdefault("balances_src", {}).setdefault(k, {})
        for f, lab in ACCOUNT_LABELS:
            before = b.get(f)
            money_input(lab, b, f, prefix)
            if b.get(f) != before and not (isinstance(before, (int, float)) and isinstance(b.get(f), (int, float)) and abs(before - b[f]) < 0.005):
                src[f] = "hand"                     # v21.50: typed here, so the month-end snapshot never replaces it
        money_input("Capital assets (house and vehicles)", b, "capital", prefix)
        toast = ss.pop("sfin_bal_toast", None)
        if toast:
            st.toast(toast, icon="\u2705")
        if _sfin_url() and ss.plan.expenses.get("sfin_account_name"):
            if st.button("Fill from my bank (SimpleFIN)", key=f"sfin_bal_{prefix}"):
                _sfin_bal_fetch(k, prefix)
                if ss.get("sfin_bal_err"):
                    st.warning(ss.sfin_bal_err)
                else:
                    _sfin_bal_review()
        nk = f"{prefix}_notes"
        if nk not in ss:
            ss[nk] = b.get("notes", "")
        b["notes"] = st.text_area("Notes", key=nk, placeholder="Anything unusual this month")
        with st.expander("Work out the Wells figure"):
            caption("Current savings, less the money set aside for estimated-tax payments, plus money market and ETFs.")
            vals = {}
            for f, lab in (("sav", "Savings balance"), ("res", "Reserved for estimated tax"), ("mm", "Money market"), ("etf", "ETFs")):
                vals[f] = parse_money(st.text_input(lab, key=f"{prefix}_w_{f}", placeholder="0.00"))
            calc = _n(vals["sav"]) - _n(vals["res"]) + _n(vals["mm"]) + _n(vals["etf"])
            write(f"**Wells cash and money market: {money(calc, 2)}**")
            st.button("Use this figure", key=f"{prefix}_w_use", on_click=use_wells, args=(k, prefix, calc))
        with st.expander("Work out capital assets from the list"):
            if not capital_items(plan):
                caption("Add your house, RV and vehicles first: open the Net worth page and click Capital assets.")
            else:
                ctotal = capital_total_now(plan)
                write(f"**Capital assets from your list: {money(ctotal, 2)}**")
                caption("Update the values on the Net worth page, in Capital assets, then use the total here.")
                st.button("Use this figure", key=f"{prefix}_c_use", on_click=use_capital, args=(k, prefix, ctotal))
    if existed or any(isinstance(v, (int, float)) for f, v in b.items() if f != "notes") or b.get("notes"):
        entries["balances"][k] = b
    with right:
        have = sum(isinstance(b.get(a), (int, float)) for a in NINE_ACCOUNTS)
        total = sum(_n(b.get(a)) for a in NINE_ACCOUNTS) if have == 9 else None
        cap = b.get("capital") if isinstance(b.get("capital"), (int, float)) else None
        prior = None
        for pk in reversed(months[: months.index(k)]):
            pb = entries["balances"].get(pk, {})
            if all(isinstance(pb.get(a), (int, float)) for a in NINE_ACCOUNTS):
                prior = (pk, sum(_n(pb.get(a)) for a in NINE_ACCOUNTS)); break
        fc = entries["forecast"].get(k)
        with st.container(border=True):
            st.markdown("**Totals**")
            write(f"Financial assets: {money(total, 2) if total is not None else '–'}")
            write(f"Capital assets: {money(cap) if cap is not None else '–'}")
            write(f"**Net worth: {money(total + cap, 2) if total is not None and cap is not None else '–'}**")
            st.markdown("**Against the last month and the forecast**")
            if total is not None and prior:
                write(f"Change since {month_short(prior[0])}: {signed(total - prior[1])} ({(total - prior[1]) / prior[1] * 100:.2f}%)")
            else:
                write("Change since last month: –")
            write(f"Forecast: {money(fc) if fc else '–'}")
            write(f"Variance to forecast: {signed(total - fc) + f' ({(total - fc) / fc * 100:.2f}%)' if total is not None and fc else '–'}")
            caption(f"{have} of 9 accounts entered. The month totals once all nine are in.")


def use_wells(k, prefix, calc):
    ss = st.session_state
    v = round(calc, 2)
    ss.entries["balances"].setdefault(k, {})["wells"] = v
    ss[f"{prefix}_wells"] = money_str(v)
    ss.entries.setdefault("balances_src", {}).setdefault(k, {})["wells"] = "hand"      # v21.50: worked out by hand, so kept


def rows_to_frame(rows):
    return pd.DataFrame([{"Date": pd.Timestamp(r["date"]).date() if r.get("date") else None, "Description": r.get("desc", ""),
                          "In": r.get("credit"), "Out": r.get("debit"), "Class": (r.get("cls") or None),
                          "Reconciled": str(r.get("rec", "")).lower() == "yes", "Note": r.get("note", "")} for r in rows],
                        columns=["Date", "Description", "In", "Out", "Class", "Reconciled", "Note"])


def frame_to_rows(df):
    out = []
    for _, r in df.iterrows():
        if pd.isna(r["Date"]):
            date = ""
        else:
            date = pd.Timestamp(r["Date"]).strftime("%Y-%m-%d")
        num = lambda v: None if v is None or (isinstance(v, float) and math.isnan(v)) else float(v)
        cls = r["Class"] if isinstance(r["Class"], str) else ""
        out.append({"date": date, "desc": r["Description"] if isinstance(r["Description"], str) else "", "credit": num(r["In"]), "debit": num(r["Out"]),
                    "rec": "Yes" if bool(r["Reconciled"]) else "Pending", "cls": cls, "note": r["Note"] if isinstance(r["Note"], str) else ""})
    return out


def parse_pasted(text: str):
    rows, skipped = [], []
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = _re.split(r"\t|,", line)
        if len(parts) < 3:
            skipped.append(line); continue
        amt = parse_money(parts[-1]); d = parts[0].strip(); desc = ",".join(parts[1:-1]).strip()
        us = _re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", d)
        if us:
            d = f"{us.group(3)}-{int(us.group(1)):02d}-{int(us.group(2)):02d}"
        elif not _re.match(r"^\d{4}-\d{2}-\d{2}$", d):
            skipped.append(line); continue
        if amt is None:
            skipped.append(line); continue
        rows.append({"date": d, "desc": desc, "credit": amt if amt > 0 else None, "debit": -amt if amt < 0 else None, "rec": "Pending", "cls": "", "note": ""})
    return rows, skipped


def bump_tx():
    st.session_state.tx_ver += 1


def _day(date_str):
    try:
        ts = pd.Timestamp(date_str)
        return f"{ts.strftime('%b')} {ts.day}"
    except (ValueError, TypeError):
        return str(date_str)


def alert_text(a, minimum, target):
    floor, goal = money(minimum), money(target)
    if a["kind"] == "now":
        return (f"Your reconciled balance is {money(a['balance'], 2)}, below your {floor} minimum. "
                f"Transfer {money(a['transfer'])} from savings now to bring it to {goal}.")
    when = "at the start of " + month_label(a["month"]) if a["date"] == "Start of month" else f"on {_day(a['date'])}" + (f" ({a['desc']})" if a["desc"] else "")
    return (f"{month_label(a['month'])}: your projected balance falls to {money(a['balance'], 2)} {when}. "
            f"Transfer {money(a['transfer'])} from savings by {_day(a['fix_date'])} to keep your balance at {goal} or more from then on.")


def current_month_key():
    ss = st.session_state
    months = month_list(ss.plan, today())
    key = f"{today().year}-{today().month:02d}"
    return key if key in months else (months[0] if key < months[0] else months[-1]), months


def cb_start_forecast(k):
    n = start_month_from_forecast(st.session_state.entries, k)
    tx_msg(f"{month_label(k)} now has the workbook's {n} forecast lines. Tick each one when it shows at your bank." if n else "Nothing to add.")


def balance_alerts_for(k, include_now):
    ss = st.session_state
    months = month_list(ss.plan, today())
    return planned_balance_alerts(ss.entries, months, k, min_balance(ss.plan), top_up_target(ss.plan), include_now, today().strftime("%Y-%m-%d"))


def cb_transfer(mk, date, amount):
    add_transfer(st.session_state.entries, mk, date, float(amount))
    tx_msg(f"Transfer of {money(amount)} from savings added on {_day(date)}. Tick it when it shows at your bank.")


def render_alerts(alerts, scope):
    """A future ('low') alert is left out once a transfer scheduled at your bank (Cash flow page) covers what's currently
    needed -- same rule the Dashboard's Cash tile already uses, so the two don't disagree. One scheduled but no longer
    enough (the amount needed grew since) says so instead of offering to add a second, stacking transfer on the ledger.
    A dip more than TRANSFER_ACTION_DAYS out is shown for planning only, with no button yet: that far ahead the amount
    is likely to move more than once before it actually matters, so prompting you to act on it now is just noise."""
    ss = st.session_state
    minimum, target = min_balance(ss.plan), top_up_target(ss.plan)
    td = today()
    for a in alerts:
        sched = scheduled_transfer(ss.entries, a["month"]) if a["kind"] != "now" else None
        if a["kind"] != "now" and transfer_covered(ss.entries, a["month"], a["transfer"]):
            continue
        far = a["kind"] != "now" and not transfer_due_soon(a["fix_date"], td)
        if far and scope == "g":        # the banner on every other page is for things to act on; a far-off dip is only noted on Monthly updates
            continue
        (st.error if a["kind"] == "now" else st.warning)(_esc(alert_text(a, minimum, target)))
        if a["kind"] == "now" and pending_transfer(ss.entries):
            caption("A transfer from savings is already on the ledger. Tick it once it shows at your bank.")
            continue
        if far:
            caption(f"That's {(_dt.date.fromisoformat(a['fix_date']) - td).days} days off -- for planning for now. The app will prompt you to actually "
                    f"schedule it once it's about {TRANSFER_ACTION_DAYS} days out, since the amount is likely to change before then.")
            continue
        if sched:
            caption(f"You have {money(sched['amount'])} scheduled at your bank for this month, and {money(a['transfer'])} more is needed. "
                    f"Raise it to {money(sched['amount'] + a['transfer'])} at your bank, then tick it on the Cash flow page -- adding a transfer here would be a second one.")
            continue
        st.button(f"Add a {money(a['transfer'])} transfer from savings ({_day(a['fix_date'])})", key=f"xfer_{scope}_{a['kind']}_{a['month']}",
                  on_click=cb_transfer, args=(a["month"], a["fix_date"], a["transfer"]))


