def balance_chart(b, minimum, k):
    y, m = map(int, k.split("-"))
    xs = [pd.Timestamp(y, m, 1)] + [_row_date(r) for r, _ in b["lines"]]
    ys = [b["opening"]] + [bal for _, bal in b["lines"]]
    fig = go.Figure(go.Scatter(x=xs, y=ys, mode="lines+markers", line=dict(shape="hv", color=NAVY, width=2), marker=dict(size=5),
                               hovertemplate="%{x|%b %d}: $%{y:,.2f}<extra></extra>"))
    fig.add_hline(y=minimum, line_color=BRICK, line_dash="dash", line_width=2)
    fig.update_layout(height=200, margin=dict(l=8, r=8, t=8, b=8), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)", showlegend=False)
    fig.update_yaxes(tickprefix="$", tickformat="~s", rangemode="tozero")
    return fig


TZ_CHOICES = ["America/New_York", "America/Chicago", "America/Denver", "America/Los_Angeles", "America/Phoenix", "America/Anchorage", "Pacific/Honolulu", "UTC"]


def tz_name():
    return st.session_state.plan.meta.get("timezone", DEFAULT_TZ)


def cb_tz(key):
    st.session_state.plan.meta["timezone"] = st.session_state.get(key, DEFAULT_TZ)


def _h(s):
    """Text that is safe inside the HTML cards: escaped, with dollar signs kept from turning into math."""
    return _html.escape(str(s)).replace("$", "&#36;")


def tx_msg(msg, last=None):
    st.session_state.tx_msg, st.session_state.tx_last = msg, last


def cb_hint_act(act):
    """The button on the bank-check box: untick a line ticked too early, or tick one that has cleared."""
    kind, k, rid = act
    ss = st.session_state
    r = find_row(ss.entries, k, rid)
    if r is None:
        return
    if kind == "untick":
        unreconcile_row(ss.entries, k, rid)
        tx_msg(f"{r.get('desc')} is pending again; the bank fetch ticks it when it clears.", None)
    else:
        why = reconcile_row(ss.entries, k, rid)
        tx_msg(why or f"{r.get('desc')} ticked.", None if why else (k, rid))


def render_difference(items: list, head: str, key: str):
    """The bank check's box: when a likely cause is found it leads, in the box itself, with a button to fix it; the red box is only for when
    nothing explains the difference."""
    found = [i for i in items if i.get("found")]
    if not found:
        st.error(_esc(head))
        for i in items:
            caption(i["text"])
        return
    with st.container(border=True, key=f"diffbox_{key}"):
        st.markdown(":orange[**" + _esc(head) + "**]")
        st.markdown("**Likely cause:** " + _esc(found[0]["text"]))
        if found[0].get("act"):
            kind, _k, _rid = found[0]["act"]
            st.button("Untick it" if kind == "untick" else "Tick it", key=f"diffact_{key}_0", type="primary", on_click=cb_hint_act, args=(found[0]["act"],))
        for n, i in enumerate(found[1:], 1):
            st.markdown("**Or:** " + _esc(i["text"]))
            if i.get("act"):
                st.button("Untick it" if i["act"][0] == "untick" else "Tick it", key=f"diffact_{key}_{n}", on_click=cb_hint_act, args=(i["act"],))


def cb_reconcile(k, rid):
    ss = st.session_state
    r = find_row(ss.entries, k, rid)
    if r is not None and (ss.get("tx_confirm") or (None, None))[:2] != (k, rid):
        try:
            why_ask = reconcile_warnings(ss.plan, ss.entries, _inbox(), r, today())
        except Exception:  # noqa: BLE001 -- a failed check never blocks ticking
            why_ask = []
        if why_ask:
            ss.tx_confirm = (k, rid, why_ask)           # ask in the card itself before ticking
            return
    ss.tx_confirm = None
    why = reconcile_row(ss.entries, k, rid)
    if why:
        tx_msg(why)
        return
    months = month_list(ss.plan, today())
    line = next((b for x, b in running_balances(ss.entries["ledger"].get(k, []), _opening(ss.entries, ss.plan, k))["lines"] if x is r), None)
    now = reconciled_balance(ss.entries, months, k, ss.entries["opening"].get(months[0], 0.0))
    tx_msg(f"{r['desc']} reconciled {_fmt_local(r['rec_at'], tz_name())}. "
           + (f"Balance after this line {money(line, 2)}; " if line is not None else "") + f"bank balance now {money(now, 2)}.", (k, rid))


def cb_confirm_no():
    st.session_state.tx_confirm = None


def cb_undo(k, rid):
    unreconcile_row(st.session_state.entries, k, rid)
    tx_msg("Back to pending.")


def cb_class(k, rid, wkey):
    set_row_class(st.session_state.entries, k, rid, st.session_state.get(wkey))
