def cb_add(k, ak):
    ss = st.session_state
    desc, amt = ss[f"{ak}_d"].strip(), parse_money(ss[f"{ak}_a"])
    if not desc or amt is None or amt < 0:
        tx_msg("Enter a description and an amount (zero or more).")
        return
    money_in = ss.get(f"{ak}_dir") == "Money in"
    cls = ss.get(f"{ak}_c") or ""
    r = add_row(ss.entries, k, ss[f"{ak}_t"].strftime("%Y-%m-%d"), desc, float(amt), money_in, cls)
    msg = f"{desc} added. Choose its class, then reconcile it." if not cls else f"{desc} added."
    if ss.get(f"{ak}_r") and cls == "Core" and not money_in:
        x = make_repeating(ss.plan, ss.entries, k, r["id"])
        if x:
            ensure_recurring_lines(ss.plan, ss.entries, month_list(ss.plan, today()))
            msg = f"{desc} added, and it repeats from {month_label(x['from'])}."
    ss.add_n = ss.get("add_n", 0) + 1
    ss.tx_view_force = "Pending"
    tx_msg(msg)


def _tx_edit_panel(k, r):
    ss = st.session_state
    rid = r["id"]
    pref = f"ed_{ss.data_ver}_{rid}_{ss.get('tx_edit_n', 0)}"
    money_in = _n(r.get("credit")) > 0 and not _n(r.get("debit"))
    y, m = map(int, k.split("-"))
    try:
        cur = pd.Timestamp(r.get("date")).date()
    except (ValueError, TypeError):
        cur = _dt.date(y, m, 1)
    st.date_input("Date", value=cur, key=f"{pref}_t")
    st.text_input("Description", value=r.get("desc", ""), key=f"{pref}_d")
    st.text_input("Amount", value=f"{(_n(r.get('credit')) if money_in else _n(r.get('debit'))):.2f}", key=f"{pref}_a")
    st.segmented_control("Direction", ["Money out", "Money in"], default="Money in" if money_in else "Money out", key=f"{pref}_dir")
    st.text_input("Note", value=r.get("note", ""), key=f"{pref}_n")
    a, b, c = st.columns(3)
    a.button("Save", key=f"{pref}_save", on_click=cb_save_edit, args=(k, rid, pref))
    b.button("Cancel", key=f"{pref}_cancel", on_click=cb_cancel)
    c.button("Delete line", key=f"{pref}_del", on_click=cb_delete, args=(k, rid))
    for line in audit_history(r, tz_name()):
        st.caption(_esc(line))
    if r.get("recur"):
        st.caption("This line repeats every month.")
        d, e = st.columns(2)
        d.button("Use this amount for later months", key=f"{pref}_amt", on_click=cb_apply_amount, args=(k, rid))
        e.button("Stop repeating after this month", key=f"{pref}_stop", on_click=cb_stop, args=(k, rid))
    elif r.get("cls") == "Core" and _n(r.get("debit")) > 0:
        st.button("Repeat every month from next month", key=f"{pref}_rep", on_click=cb_repeat, args=(k, rid))


def tx_card(k, r, bal=None, minimum=None, bank=None):
    ss = st.session_state
    rid, done = r["id"], is_reconciled(r)
    amt = _n(r.get("credit")) - _n(r.get("debit"))
    try:
        ts = pd.Timestamp(r.get("date"))
        when = f"{ts.strftime('%b')} {ts.day}"
    except (ValueError, TypeError):
        when = "No date"
    note = r.get("note") or ""
    prefilled = "replace with actual" in note.lower()          # the workbook's stock wording on forecast lines
    tag = " · ".join(x for x in (("Repeating" if r.get("recur") else ""), ("Prefilled" if prefilled and not done else ""),
                                 (r.get("cls") or "No class") if done else "") if x)
    audit = audit_line(r, tz_name())
    shown = ("+" if amt > 0 else "") + money(abs(amt), 2)
    name = r.get("desc") or "No description"
    meta = _h(when) + (" · " + _h(tag) if tag else "")
    if bal is not None:                                            # running balance after this line, every line in date order
        meta += f" · <span style='color:{BRICK if (minimum is not None and bal < minimum) else 'inherit'}'>balance {_h(money(bal, 2))}</span>"
        if done and bank is not None and abs(bank - bal) >= 0.005:  # reconciled-only balance, shown when an earlier line is still unticked
            meta += f" · bank {_h(money(bank, 2))}"
    with st.container(border=True):
        st.markdown(f"<div class='txbox'><div class='txrow'><div><div class='txname' title=\"{_h(name)}\">{'&#10003; ' if done else ''}{_h(name)}</div>"
                    f"<div class='txmeta'" + (f" title=\"{_h(note)}\"" if prefilled else "") + f">{meta}</div>"
                    + (f"<div class='txmeta txnote' title=\"{_h(note)}\">{_h(note)}</div>" if note and not prefilled else "")
                    + (f"<div class='txmeta'>{_h(money(_n(r.get('ot_split')), 2))} of this is one-time: {_h(r.get('ot_desc') or '')}</div>" if _n(r.get("ot_split")) > 0 else "")
                    + (f"<div class='txmeta'>{_h(audit)}</div>" if audit else "")
                    + f"</div><div class='txamt' style='color:{PINE if amt > 0 else 'inherit'}'>{_h(shown)}</div></div></div>", unsafe_allow_html=True)
        if ss.get("tx_edit") == rid:
            _tx_edit_panel(k, r)
            return
        if not done:
            wkey = f"cls_{ss.data_ver}_{rid}"
            ss[wkey] = r.get("cls") or None
            st.segmented_control("Class", CLASSES, key=wkey, on_change=cb_class, args=(k, rid, wkey), label_visibility="collapsed")
        conf = ss.get("tx_confirm")
        if not done and conf and tuple(conf[:2]) == (k, rid):
            st.markdown(":orange[**Check before ticking.** " + _esc(" ".join(conf[2] if len(conf) > 2 else [])) + " Has it really cleared at the bank?]")
            a, b = st.columns(2)
            a.button("Tick anyway", key=f"recyes_{ss.data_ver}_{rid}", type="primary", on_click=cb_reconcile, args=(k, rid))
            b.button("Not yet", key=f"recno_{ss.data_ver}_{rid}", on_click=cb_confirm_no)
            return
        a, b = st.columns(2)
        if done:
            a.button("Undo", key=f"undo_{ss.data_ver}_{rid}", on_click=cb_undo, args=(k, rid))
        else:
            a.button("Reconcile", key=f"rec_{ss.data_ver}_{rid}", on_click=cb_reconcile, args=(k, rid))
        b.button("Edit", key=f"edit_{ss.data_ver}_{rid}", on_click=cb_edit, args=(rid,))


MT_SCROLL_ROWS = 40      # v21.30: html tables longer than this get a scrolling box with a pinned heading row


def html_table(df, money_cols=(), bold_last=False, right_cols=()):
    """A small, compact table that wraps long text instead of scrolling sideways (whole dollars)."""
    rt = set(money_cols) | set(right_cols)
    head = "".join(f"<th class='{'r' if c in rt else ''}'>{_h(c)}</th>" for c in df.columns)
    body = ""
    for i, (_, row) in enumerate(df.iterrows()):
        cells = ""
        for c in df.columns:
            v = row[c]
            empty = v is None or (isinstance(v, float) and math.isnan(v))
            txt = "" if empty else (money(float(v)) if c in money_cols else str(v))
            cells += f"<td class='{'r' if c in rt else ''}'>{_h(txt)}</td>"
        body += f"<tr class='{'tot' if bold_last and i == len(df) - 1 else ''}'>{cells}</tr>"
    # v21.30: a long table scrolls inside its own box so its heading row stays pinned at the top (short ones are left as they were)
    box = "txbox mtscroll" if len(df) > MT_SCROLL_ROWS else "txbox"
    return f"<div class='{box}'><table class='mt'><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>"


def _card(key):
    """A bordered card. Newer Streamlit versions take a key and a gap; older ones fall back gracefully."""
    for kw in ({"key": key, "gap": "small"}, {"key": key}, {}):
        try:
            return st.container(border=True, **kw)
        except TypeError:
            continue
    return st.container(border=True)


def upd_reconcile(plan, entries, k):
    """v21.51: the reconcile view: the status, the lines to tick and the bank lines waiting for review."""
    ss = st.session_state
    ensure_ids(entries["ledger"].get(k, []))
    rows = entries["ledger"].get(k, [])
    months_all = month_list(plan, today())
    opening = _opening(entries, plan, k)
    minimum = min_balance(plan)
    bal = running_balances(rows, opening)
    lo = low_point(bal)
    first_open = entries["opening"].get(months_all[0], 0.0)
    rbal = reconciled_balance(entries, months_all, k, first_open)
    c = ledger_control(plan, entries, k)
    caption(f"{month_label(k)}. Choose a class, then tick each line that matches your statement. Only reconciled lines count toward the totals.")
    with _card("cardstat"):
        st.markdown("**Status**")
        m1 = st.columns(2, gap="small")
        m1[0].metric("Pending", c["pending"])
        m1[1].metric("Need a class", c["unclassified"])
        m2 = st.columns(2, gap="small")
        m2[0].metric("Core, reconciled", money(c["core"], 2))
        m2[1].metric("One-time, reconciled", money(c["one_time"], 2))
        status_line("ok" if c["status"] == "Reconciled" else ("warn" if c["status"] == "Pending" else "idle"), f"Status: {c['status'] if c['status'] != 'NO DATA' else 'No data'}")
        y = int(k[:4])
        budget = core_budget_for(plan, y) / 12
        write(f"Core spend {money(c['normalized'])} against a monthly budget of {money(budget)}: "
              f"**{money(abs(budget - c['normalized']))} {'under' if c['normalized'] <= budget else 'over'}**.")

    y = int(k[:4])
    with _card("cardtx"):
        vkey = f"txview_{ss.data_ver}_{k}"
        if ss.pop("tx_view_force", None):
            ss[vkey] = "Pending"
        hc = st.columns([2, 3, 2], gap="small", vertical_alignment="center")
        hc[0].markdown(f"**To reconcile** ({c['pending']} pending)")
        view = hc[1].radio("Show", ["Pending", "All lines", "Register"], horizontal=True, key=vkey, label_visibility="collapsed")
        hc[2].button("Mark all reconciled", key=f"allyes_{ss.data_ver}_{k}", on_click=cb_mark_all, args=(k,))
        st.markdown(f"<div class='txbox'><div class='txbanknow'>Bank balance now <b>{_h(money(rbal, 2))}</b> "
                    "(reconciled lines only). Compare it with your bank after ticking.</div></div>", unsafe_allow_html=True)
        # The message row is always there at the same height, empty or not, so the cards below never jump under your finger
        # when a message appears or clears (a tap landing on a card that had just moved can tick the wrong line).
        n1, n2 = st.columns([4, 1], gap="small", vertical_alignment="center")
        n1.markdown(f"<div class='txmsg'>{_h(ss.get('tx_msg') or '')}</div>", unsafe_allow_html=True)
        last = ss.get("tx_last") if ss.get("tx_msg") and ss.get("tx_last") and ss.tx_last[0] == k else None
        n2.button("Undo", key=f"lastundo_{ss.data_ver}_{k}", on_click=cb_undo, args=last or (k, ""), disabled=last is None)
        shown = [r for r in ordered_rows(rows) if view == "All lines" or not is_reconciled(r)]
        if view == "Register":
            render_register(plan, entries, k, rows, opening, minimum, months_all)
        else:
            if not any(not r.get("xfer") for r in rows) and entries.get("forecast_lines", {}).get(k):
                fl = entries["forecast_lines"][k]
                with st.container(border=True):
                    write(f"**No lines yet for {month_label(k)}.** The workbook forecast has {len(fl)} lines: {money(sum(_n(r.get('credit')) for r in fl))} in, "
                          f"{money(sum(_n(r.get('debit')) for r in fl))} out. Start from them, then edit or tick each one as it happens.")
                    st.button(f"Start {month_short(k)} from the forecast", key=f"fcstart_{ss.data_ver}_{k}", on_click=cb_start_forecast, args=(k,))
            elif not rows:
                st.info("No transactions yet. Bank lines arrive each night; you can also add one or paste a statement from the Add transactions tile.")
            elif not shown:
                st.success("Everything is reconciled for this month.")
            bank_map = {r["id"]: v for r, v in bank_balances(rows, bank_opening(entries, months_all, k, first_open)) if r.get("id")}
            for i in range(0, len(shown), 2):
                cols = st.columns(2, gap="small")
                for j, r in enumerate(shown[i:i + 2]):
                    with cols[j]:
                        tx_card(k, r, bal["by_id"].get(r["id"]), minimum, bank_map.get(r["id"]))
        _bank_import_box(entries)
        caption(f"Opening balance {money(opening, 2)}; projected closing balance {money(bal['closing'], 2)}. Unclassified lines: {c['unclassified']}.")


def upd_bankmatch(plan, entries, k):
    """v21.51: the balance check against Wells."""
    ss = st.session_state
    ensure_ids(entries["ledger"].get(k, []))
    rows = entries["ledger"].get(k, [])
    months_all = month_list(plan, today())
    opening = _opening(entries, plan, k)
    minimum = min_balance(plan)
    bal = running_balances(rows, opening)
    lo = low_point(bal)
    first_open = entries["opening"].get(months_all[0], 0.0)
    rbal = reconciled_balance(entries, months_all, k, first_open)
    c = ledger_control(plan, entries, k)
    with _card("cardbal"):
        b1 = st.columns(3, gap="small")
        b1[0].metric("Bank balance (reconciled)", money(rbal, 2), help="Opening balance plus the lines you have ticked. It should match your bank.")
        b1[1].metric("Projected month-end", money(bal["closing"], 2), help="Opening balance plus every line in the month, ticked or not.")
        b1[2].metric("Lowest point", money(lo["balance"], 2), help="The lowest running balance this month, counting lines not yet ticked.")
        cur, _m = current_month_key()
        alerts = balance_alerts_for(k, k == cur)
        if k != cur:
            alerts += [a for a in balance_alerts_for(cur, True) if (a["kind"], a["month"]) not in {(x["kind"], x["month"]) for x in alerts}]
        render_alerts(alerts, "t")
        if lo["balance"] >= minimum:
            caption(f"Stays above your {money(minimum)} minimum all month. Lowest: {money(lo['balance'], 2)}"
                    + ("" if lo["date"] == "Start of month" else f" on {_day(lo['date'])}") + ".")
        if k == today().strftime("%Y-%m"):             # the check done for you each morning, from the fetch's own Wells balance
            chk = _auto_bank_check()
            if chk:
                when = _day(chk["date"]) if chk.get("date") else "the last fetch"
                if chk["status"] == "match":
                    status_line("ok", _esc(f"Checked automatically: Wells shows {money(chk['bank'], 2)} as of the fetch on {when}, and the ledger agrees."))
                elif chk["status"] == "waiting":
                    caption(_esc(f"Wells shows {money(chk['bank'], 2)} as of the fetch on {when}. {chk['waiting']} bank line{'s' if chk['waiting'] != 1 else ''} "
                                 "from that fetch still wait for review (Import data from financial institutions); the check runs once they are in."))
                else:
                    render_difference(explain_difference_items(entries, plan, months_all, k, chk["diff"], _inbox()),
                                      f"Checked automatically: Wells shows {money(abs(chk['diff']), 2)} {'less' if chk['diff'] < 0 else 'more'} than the ledger "
                                      f"({money(chk['bank'], 2)} against {money(chk['ledger'], 2)}), as of the fetch on {when}.", f"auto_{ss.data_ver}_{k}")
                if chk.get("late"):
                    caption("Lines ticked by hand since that fetch are left out of this check; they are compared with tomorrow's.")
            caption("To check against your bank right now, type the balance it shows:")
        bk = f"bankchk_{ss.data_ver}"
        typed = st.text_input("Balance your bank shows now", key=bk, placeholder="Balance your bank shows now, to check against the ledger", label_visibility="collapsed")
        if typed.strip():
            bank_now = parse_money(typed)
            if bank_now is None:
                st.error("Enter the balance as a number, for example 1234.56.")
            else:
                diff = round(bank_now - rbal, 2)
                if abs(diff) < 0.005:
                    st.success(f"Matches. Your bank and the ledger agree at {money(rbal, 2)}.")
                    st.button("Record this match", key=f"bankrec_{ss.data_ver}_{k}", on_click=cb_record_match, args=(k, rbal))
                else:
                    render_difference(explain_difference_items(entries, plan, months_all, k, diff, _inbox()),
                                      f"Your bank shows {money(abs(diff), 2)} {'less' if diff < 0 else 'more'} than the ledger ({money(bank_now, 2)} against {money(rbal, 2)}).",
                                      f"chk_{ss.data_ver}_{k}")
        checks = entries.get("bank_checks", [])
        if checks:
            caption(f"Last recorded match: {_fmt_local(checks[-1]['t'], tz_name())}, {money(checks[-1]['balance'], 2)}.")


