def upd_add(plan, entries, k):
    """v21.51: add a line by hand, or paste lines from a statement."""
    ss = st.session_state
    ensure_ids(entries["ledger"].get(k, []))
    rows = entries["ledger"].get(k, [])
    months_all = month_list(plan, today())
    opening = _opening(entries, plan, k)
    minimum = min_balance(plan)
    bal = running_balances(rows, opening)
    lo = low_point(bal)
    first_open = entries["opening"].get(months_all[0], 0.0)
    rbal = reconciled_balance(entries, months_all, k, first_open)
    c = ledger_control(plan, entries, k)
    y = int(k[:4])
    with _card("cardadd"):
        with st.expander("Add a transaction", expanded=True):
            ak = f"add_{ss.data_ver}_{k}_{ss.get('add_n', 0)}"
            last_day = pd.Timestamp(y, int(k[-2:]), 1).days_in_month
            default_day = today() if (today().year, today().month) == (y, int(k[-2:])) else _dt.date(y, int(k[-2:]), last_day)
            a1, a2, a3 = st.columns([1, 2, 1], gap="small")
            a1.date_input("Date", value=default_day, key=f"{ak}_t")
            a2.text_input("Description", key=f"{ak}_d", placeholder="Grocery store")
            a3.text_input("Amount", key=f"{ak}_a", placeholder="84.12")
            d1, d2 = st.columns(2, gap="small")
            with d1:
                st.segmented_control("Direction", ["Money out", "Money in"], default="Money out", key=f"{ak}_dir")
            with d2:
                st.segmented_control("Class", CLASSES, key=f"{ak}_c")
            if ss.get(f"{ak}_c") == "Core" and ss.get(f"{ak}_dir", "Money out") == "Money out":
                st.toggle("Repeat every month from next month", key=f"{ak}_r", help="Adds it to your committed spending and to every future month as a pending line.")
            st.button("Add to this month", key=f"{ak}_go", on_click=cb_add, args=(k, ak))
        with st.expander("Paste lines from a statement", expanded=True):
            caption("One line per transaction: date, description, amount. Money out is negative. Separate with commas or tabs. Pasted lines start as Pending and unclassified.")
            pk = f"paste_{ss.data_ver}_{k}_{ss.get('paste_n', 0)}"
            txt = st.text_area("Lines", key=pk, placeholder="2026-09-21, Grocery store, -84.12", height=100)
            if st.button("Add pasted lines", key=f"dopaste_{ss.data_ver}_{k}"):
                add, skipped = parse_pasted(txt)
                entries["ledger"][k] = entries["ledger"].get(k, []) + add
                ensure_ids(entries["ledger"][k])
                ss.paste_msg = f"{len(add)} line{'s' if len(add) != 1 else ''} added" + (f"; {len(skipped)} skipped because the date or amount could not be read." if skipped else ".")
                ss.paste_n = ss.get("paste_n", 0) + 1          # a fresh, empty box on the next run
                st.rerun()
            if ss.get("paste_msg"):
                caption(ss.paste_msg)


def _inbox():
    """The daily job's file (recent bank lines and month-end balances), read once per session. None when the job has not run."""
    ss = st.session_state
    if "inbox" not in ss:
        cfg = docs_cfg()
        ss.inbox, ss.inbox_err = None, ""
        if cfg is not None:
            try:
                ss.inbox = inbox_follow_moves(inbox_load(cfg), ss.plan.expenses.get("sfin_moved"))
            except (StorageError, StorageNotFound) as e:
                ss.inbox_err = f"Could not read the daily bank fetch: {e}"
    return ss.get("inbox")


def _inbox_reload():
    st.session_state.pop("inbox", None)


def _inbox_plan(entries):
    """What the daily job's lines would do, leaving out lines you have already been through."""
    ss = st.session_state
    return inbox_review_plan(ss.plan, entries, _inbox(), today())


def _card_txn_plan(entries):
    """New card charges from the daily fetch, waiting for you to say whether each is a one-time purchase."""
    ss = st.session_state
    ib = _inbox()
    card_ids = [a["id"] for a in ss.plan.expenses.get("sfin_card_accounts") or []]
    if not ib or not card_ids:
        return []
    rows = inbox_card_rows(ib.get("lines") or [], card_ids)
    return card_txn_plan(entries, rows, ss.plan.expenses.get("card_flag_threshold", 250.0))


def _inbox_waiting(entries) -> int:
    ss = st.session_state
    return inbox_waiting(ss.plan, entries, _inbox(), today())


def _inbox_open(entries):
    ss = st.session_state
    ss.bank_plan, ss.bank_skipped, ss.bank_msg = _inbox_plan(entries), [], ""
    ss.bank_from_inbox = [p["bank"]["id"] for p in ss.bank_plan]


def _auto_bank_check():
    """The automatic bank check for this session (see auto_bank_check); a match is recorded once per fetch."""
    ss = st.session_state
    try:
        chk = auto_bank_check(ss.plan, ss.entries, _inbox(), today())
    except Exception:  # noqa: BLE001 -- never let the check stop a page
        return None
    auto_bank_record(ss.entries, chk)
    return chk


def _inbox_notes(entries):
    """Dashboard and import-box notes about the daily fetch: lines waiting, or the job having stopped.
    Each note is (kind, message, action); action is "bank" or "cards" when the Dashboard should offer a button to act on it (v21.37), else None."""
    ib = _inbox()
    if not ib:
        return []
    out = []
    chk = _auto_bank_check()
    if chk and chk["status"] == "off":
        when = "this morning's fetch" if chk.get("source") != "manual" else f"your fetch at {_fmt_local(chk['at'], tz_name())}"
        out.append(("warning", f"Wells and the ledger differ by {money(abs(chk['diff']), 2)} as of {when}. "
                               "Monthly updates, Transactions shows the likely cause.", None))
    n = _inbox_waiting(entries)
    if n:
        out.append(("info", f"{n} new bank line{'s' if n != 1 else ''} waiting. Review {'them' if n != 1 else 'it'} under Transactions, Import data from financial institutions.", "bank"))
    nc = len(_card_txn_plan(entries))
    if nc:
        out.append(("info", f"{nc} new card charge{'s' if nc != 1 else ''} waiting. Review {'them' if nc != 1 else 'it'} on One-time spending, Card charges.", "cards"))
    age = inbox_age_days(ib, today())
    if age is not None and age > INBOX_STALE_DAYS:
        out.append(("warning", f"The daily bank fetch last ran {age} days ago. Check the Actions tab of your data repository on GitHub.", None))
    return out                                  # a fetch-error warning, if any, is rendered separately by _inbox_error_banner -- it needs a Dismiss button


def _inbox_error_banner(key_prefix: str):
    """The bank fetch's error warning, shown on both the Dashboard and the import tab, with a Dismiss button once you've fixed it.
    Dismissing hides this exact wording until the fetch reports something different -- or clears and later reports the same thing again."""
    ib = _inbox()
    if not ib or not ib.get("errors"):
        return
    errs = ib["errors"]
    if errs == (ib.get("dismissed_errors") or []):
        return
    st.warning("The bank fetch reported: " + "; ".join(errs))
    if st.button("Dismiss -- I've fixed this", key=f"{key_prefix}_inbox_err_dismiss"):
        cfg = docs_cfg()
        if cfg is None:
            st.warning("No data connection is set up, so there is nothing to save the dismissal to.")
        else:
            try:
                inbox_dismiss_errors(cfg, errs)
                _inbox_reload()
                st.rerun()
            except (StorageError, StorageNotFound, StorageConflict) as e:
                st.warning(f"Could not save the dismissal: {e}")


def _bank_amount_text(p):
    return (f"+{money(p['amount'], 2)} in" if p["money_in"] else f"-{money(p['amount'], 2)} out")


def _bank_what(p):
    a = p["action"]
    if a == "match":
        b = p["bank"]["date"]
        return f"Tick the existing line ({p['strength']})" + ("" if p["cls"] else "; choose a class to tick it")
    if a == "update":
        if p.get("auto"):
            return f"Matches the bill shown, under {money(AUTO_BILL_LIMIT, 0)} and within {money(AUTO_BILL_TOLERANCE, 0)} ({money(p.get('old_amt', 0.0), 2)} on the ledger). Apply updates and reconciles it"
        if p.get("sure"):
            return f"Matches the ledger line shown, amount within 10% ({money(p.get('old_amt', 0.0), 2)} on the ledger). Apply updates it to the bank's amount and reconciles it"
        return (f"Check: matches the ledger line shown but the amount differs ({money(p.get('old_amt', 0.0), 2)} on the ledger"
                + (", different wording" if p.get("strength") else "") + "). Tick Use to update it to the bank's amount and reconcile it")
    if a == "new":
        return "Add a new line" + ("" if p["cls"] else "; choose a class to tick it")
    if a == "near":
        return "Possible match with the ledger line shown, but the amount or date differs. Tick to add it as a new line anyway"
    if a == "have":
        return "Already in your ledger and ticked" + (" (different wording: check it is the same payment)" if p.get("strength") else "") + ". Only the bank's wording is noted"
    if a == "dupe":
        return "Already imported: skipped"
    return "Month not tracked: skipped"


def _inbox_mark_done(acted: list | None = None, ignored: list | None = None):
    """Lines from the daily fetch that you acted on stop being counted as waiting: applied to the ledger (acted) or ticked Ignore (ignored).
    A line left with neither ticked stays in the review list until you decide (v21.13; it used to be hidden too)."""
    ss = st.session_state
    from_inbox = set(ss.pop("bank_from_inbox", None) or [])
    acted = [i for i in (acted or []) if i in from_inbox]
    ignored = [i for i in (ignored or []) if i in from_inbox]
    if acted or ignored:
        ss.plan.expenses["inbox_done"] = (list(ss.plan.expenses.get("inbox_done") or []) + acted + ignored)[-2000:]
    if ignored:
        ss.plan.expenses["inbox_ignored"] = (list(ss.plan.expenses.get("inbox_ignored") or []) + ignored)[-2000:]


def _inbox_unignore(line_id: str):
    ss = st.session_state
    ss.plan.expenses["inbox_ignored"] = [i for i in (ss.plan.expenses.get("inbox_ignored") or []) if i != line_id]
    ss.plan.expenses["inbox_done"] = [i for i in (ss.plan.expenses.get("inbox_done") or []) if i != line_id]


@st.dialog("Check these before anything changes", width="large")
def _bank_review():
    ss = st.session_state
    plan = ss.get("bank_plan") or []
    if not plan:
        st.write("Nothing to review.")
        return
    n = {a: sum(1 for p in plan if p["action"] == a) for a in ("match", "update", "new", "near", "dupe", "have", "outside")}
    write(f"**{n['match']}** match a line already in your ledger, " + (f"**{n['update']}** match a line at a different amount (tick to confirm), " if n["update"] else "") + f"**{n['new']}** are new, **{n['near']}** are possible matches to check, **{n['have'] + n['dupe']}** are already ticked in your ledger or were imported before, **{n['outside']}** fall outside your months.")
    from_inbox = bool(ss.get("bank_from_inbox"))
    if from_inbox:
        caption("Tick Use to put a line on the ledger, or Ignore if it should never be added. A line with neither ticked stays in this list for next time. "
                "Look at the matches marked Check: the amount and date agree but the wording differs. A class is needed to tick a line as reconciled.")
    else:
        caption("Untick any line you do not want. Look at the matches marked Check: the amount and date agree but the wording differs. A class is needed to tick a line as reconciled.")
    rows_ = []
    for p in plan:
        # v21.38: an amount that differs ("update") is pre-ticked only when the wording also matches and it is within 10% (Andrew, Oct 2026:
        # confirm with Apply for a few weeks, then consider applying these on their own); anything less certain waits for your tick
        row = {"Use": p["action"] in ("match", "new", "have") or (p["action"] == "update" and bool(p.get("sure") or p.get("auto")))}
        if from_inbox:
            row["Ignore"] = False
        row.update({"Date": p["bank"]["date"], "Bank line": p["bank"]["desc"][:60], "Amount": _bank_amount_text(p),
                    "What will happen": _bank_what(p), "Ledger line": p["row_desc"], "Class": p["cls"]})
        rows_.append(row)
    df = pd.DataFrame(rows_, index=[p["i"] for p in plan])
    ed = st.data_editor(df, key="bank_editor", hide_index=True, use_container_width=True, disabled=["Date", "Bank line", "Amount", "What will happen", "Ledger line"],
                        column_config={"Use": st.column_config.CheckboxColumn("Use", width="small"),
                                       "Ignore": st.column_config.CheckboxColumn("Ignore", width="small", help="Never add this bank line. You can bring it back later."),
                                       "Class": st.column_config.SelectboxColumn("Class", options=["", *CLASSES], width="small")})
    if ss.get("bank_skipped"):
        st.warning(f"{len(ss.bank_skipped)} line(s) could not be read and are not included.")
    c = st.columns([1, 1, 3])
    if c[0].button("Apply", type="primary", key="bank_apply"):
        ign = {int(i) for i, r in ed.iterrows() if from_inbox and bool(r.get("Ignore"))}
        both = [p["bank"]["desc"][:40] for p in plan if p["i"] in ign and bool(ed.loc[p["i"], "Use"])]
        if both:
            st.error("Tick either Use or Ignore on a line, not both: " + "; ".join(both[:3]))
        else:
            choices = {int(i): {"apply": bool(r["Use"]) and int(i) not in ign, "cls": r["Class"] or ""} for i, r in ed.iterrows()}
            res = apply_bank_import(ss.entries, plan, choices)
            acted = [p["bank"].get("id") for p in plan if p["action"] in ("dupe", "outside") or (choices.get(p["i"], {}).get("apply") and p["i"] not in ign)]
            ignored = [p["bank"].get("id") for p in plan if p["i"] in ign and p["action"] not in ("dupe", "outside")]
            left = len(plan) - len(acted) - len(ignored)
            ss.bank_msg = (f"{res['matched']} ticked, {res['added']} added" + (f", {len(res['pending'])} left Pending for want of a class ({', '.join(res['pending'][:3])}{'...' if len(res['pending']) > 3 else ''})" if res["pending"] else "")
                           + (f", {len(ignored)} ignored" if ignored else "") + (f", {left} still waiting for a decision" if from_inbox and left else "") + ".")
            _inbox_mark_done(acted, ignored)
            ss.bank_plan, ss.bank_n = None, ss.get("bank_n", 0) + 1
            ss.tx_ver = ss.get("tx_ver", 0) + 1
            ss.bank_toast = "Bank import applied: " + ss.bank_msg
            st.rerun()
    if c[1].button("Cancel", key="bank_cancel"):
        ss.pop("bank_from_inbox", None)
        ss.bank_plan, ss.bank_n = None, ss.get("bank_n", 0) + 1
        st.rerun()


def _sfin_url():
    """The SimpleFIN access address: a secret if one is set, otherwise the encrypted copy in the data repository. Cached for the session."""
    ss = st.session_state
    try:
        v = st.secrets["SIMPLEFIN_ACCESS_URL"]
        if v:
            return str(v)
    except Exception:  # noqa: BLE001 - no such secret is normal
        pass
    if "sfin_url" not in ss:
        cfg = docs_cfg()
        try:
            ss.sfin_url = simplefin_load(cfg) if cfg is not None else None
        except (StorageError, StorageNotFound) as e:
            ss.sfin_url, ss.sfin_msg = None, f"Could not read the saved bank connection: {e}"
    return ss.get("sfin_url")


def _sfin_connect(token):
    ss, cfg = st.session_state, docs_cfg()
    if cfg is None:
        ss.sfin_msg = "The bank connection is kept in your private GitHub repository, which this copy is not connected to."
        return
    try:
        url = simplefin_claim(token)
        simplefin_save(cfg, url)
    except StorageError as e:
        ss.sfin_msg = str(e)
        return
    ss.sfin_url, ss.sfin_accts, ss.sfin_load_tried = url, None, False
    ss.sfin_msg = "Connected. Now choose which account is your Wells checking account."


def _sfin_disconnect():
    ss, cfg = st.session_state, docs_cfg()
    try:
        simplefin_forget(cfg)
    except StorageError as e:
        ss.sfin_msg = f"Could not remove the saved connection: {e}"
        return
    ss.sfin_url, ss.sfin_accts, ss.sfin_load_tried = None, None, False
    ss.plan.expenses.pop("sfin_account", None)
    ss.plan.expenses.pop("sfin_account_name", None)
    ss.sfin_msg = "Disconnected. You can also switch the connection off on the SimpleFIN Bridge site."


def _sfin_list_accounts():
    ss = st.session_state
    try:
        data = simplefin_accounts(_sfin_url(), balances_only=True)
    except StorageError as e:
        ss.sfin_msg = str(e)
        return
    ss.sfin_accts = simplefin_account_list(data)
    ss.sfin_errs = simplefin_errors(data)
    banks = heal_bank_accounts(ss.plan, ss.sfin_accts, _inbox())
    if banks:
        _inbox_reload()                                  # read again, so lines under the old and new ids are counted once
        ss.sfin_healed = list(ss.get("sfin_healed") or []) + banks
    healed = heal_card_accounts(ss.plan, ss.sfin_accts)
    if healed:
        try:
            card_history_sync(ss.entries, _inbox(), [a["id"] for a in card_accounts_of(ss.plan)])
        except Exception:  # noqa: BLE001
            pass
        ss.sfin_healed = list(ss.get("sfin_healed") or []) + healed
    ss.sfin_msg = "" if ss.sfin_accts else "SimpleFIN returned no accounts. Link your banks on the SimpleFIN Bridge site first."


def _sfin_choose(acct):
    ss = st.session_state
    ss.plan.expenses["sfin_account"] = acct["id"]
    ss.plan.expenses["sfin_account_name"] = f"{acct['org']} {acct['name']}".strip()
    ss.sfin_msg = f"Using {ss.plan.expenses['sfin_account_name']} for the ledger."


def _sfin_pick_changed():
    ss = st.session_state
    n = ss.get("sfin_pick")
    if n is not None and ss.get("sfin_accts") and n < len(ss.sfin_accts):
        _sfin_choose(ss.sfin_accts[n])
        ss.sfin_pick_cur = ss.plan.expenses.get("sfin_account")


def _card_keywords_add(kw):
    ss = st.session_state
    if not kw:
        return
    kws = list(ss.plan.expenses.get("card_keywords") or [])
    if kw not in [str(k).lower() for k in kws]:
        kws.append(kw)
        ss.plan.expenses["card_keywords"] = kws


STALE_DAYS = 3   # v25.27: WEEKDAYS behind the newest account before a connection is called stale (v25.21 used 2 calendar days)


def _weekdays_between(d, newest) -> int:
    """v25.27: weekdays after d up to and including newest. Banks and card companies mostly do not post at weekends, so a card last
    updated on Thursday is not behind on Saturday: Thursday to Saturday is one weekday (Friday)."""
    n, day = 0, d
    while day < newest:
        day += _dt.timedelta(days=1)
        n += day.weekday() < 5
    return n


def stale_accounts(plan, accts: list, today_date=None) -> list:
    """v25.13: every account SimpleFIN returns should be as current as the newest one -- SimpleFIN refreshes them all together. Any account
    whose 'as of' date is behind the newest is flagged at once: SimpleFIN has stopped getting new data for it, even if the connection still
    says active. Compared with the newest date rather than today's, so the time-zone difference never raises a false alarm.
    v25.21: each bank refreshes once a day at its own time, so overnight one connection is often a day ahead of the rest. A one-day gap is
    that normal timing, not a stall. v25.27: counted in weekdays, and flagged at STALE_DAYS (3) weekdays behind the newest, since card
    companies mostly do not post at weekends (Chase and Citi at Thursday on a Saturday are on time).
    Returns [(short name, as-of date, days behind)], furthest behind first."""
    dated = []
    for a in accts or []:
        try:
            dated.append((a, _dt.date.fromisoformat(a["date"])))
        except (KeyError, TypeError, ValueError):
            continue
    if not dated:
        return []
    newest = max(d for _a, d in dated)
    out = [(_card_short(f"{a.get('org', '')} {a.get('name', '')}".strip()), d, (newest - d).days) for a, d in dated
           if _weekdays_between(d, newest) >= STALE_DAYS]
    return sorted(out, key=lambda x: x[1])


def _acct_label(a: dict) -> str:
    return f"{a.get('org', '')} {a.get('name', '')}".strip()


def heal_bank_accounts(plan, accts: list, inbox: dict | None = None) -> list:
    """v25.24: a bank connection removed and added again on SimpleFIN gives its accounts new id numbers. Your checking account and the
    accounts behind each balance line (Wells, Schwab, ...) are then followed to the new id, matched by the last four digits in the account's
    name (card_key), the way cards already are. The old id is kept in the balance mapping, so earlier months' month-end snapshots still
    count, and old -> new is recorded in sfin_moved so lines fetched under both ids are counted once (inbox_follow_moves).
    Only an id SimpleFIN no longer lists is moved, and only to a single account of the same name that nothing else already uses.
    Returns the names of the accounts followed."""
    if not accts:
        return []
    exp = plan.expenses
    live = {a["id"]: a for a in accts if a.get("id")}
    names = {}                                          # every account name ever seen, by id: snapshots, then the live list
    for k in sorted(((inbox or {}).get("snapshots") or {})):
        for a in (inbox["snapshots"][k].get("accounts") or []):
            if a.get("id"):
                names[a["id"]] = _acct_label(a)
    names.update({i: _acct_label(a) for i, a in live.items()})
    mapping = dict(exp.get("sfin_map") or {})
    moved = dict(exp.get("sfin_moved") or {})
    used = set(mapping) | {exp.get("sfin_account") or ""} | {c["id"] for c in (exp.get("sfin_card_accounts") or [])}
    by_key: dict = {}
    for i, a in live.items():
        by_key.setdefault(card_key(_acct_label(a)), []).append(i)

    def follow(old: str, old_name: str):
        if not old or old in live or not old_name:
            return None
        if old in moved and moved[old] in live:
            return moved[old]
        cands = [i for i in by_key.get(card_key(old_name), []) if i not in used]
        return cands[0] if len(cands) == 1 else None

    done = []
    cur = exp.get("sfin_account") or ""
    new = follow(cur, exp.get("sfin_account_name") or names.get(cur, ""))
    if new:
        moved[cur] = new
        exp["sfin_account"], exp["sfin_account_name"] = new, _acct_label(live[new])
        used.add(new)
        done.append(_acct_label(live[new]))
    for old, line in list(mapping.items()):
        if old == cur and new:
            mapping.setdefault(new, line)
            continue
        n2 = follow(old, names.get(old, ""))
        if n2 and n2 not in mapping:
            mapping[n2] = line                         # the old id stays: earlier months' snapshots still use it
            moved[old] = n2
            used.add(n2)
            if line:
                done.append(_acct_label(live[n2]))
    if moved != (exp.get("sfin_moved") or {}):
        exp["sfin_moved"], exp["sfin_map"] = moved, mapping
    return list(dict.fromkeys(done))


def _line_print(ln: dict) -> tuple:
    return (str(ln.get("date", ""))[:10], round(float(ln.get("amount") or 0), 2), " ".join(_clean_bank_desc(ln.get("desc", "")).lower().split()))


def inbox_follow_moves(inbox: dict | None, moved: dict | None) -> dict | None:
    """v25.24: the daily fetch keeps about 100 days of lines, so after a reconnection the same transactions are there twice, under the old and
    the new account id. Lines under an old id are shown under the new one, and a new-id line that repeats an old-id line (same date, amount and
    wording) is dropped -- the old one is kept, because what you have already ticked or ignored is recorded by its line id."""
    if not inbox or not moved:
        return inbox
    lines = [dict(ln, acct=moved.get(ln.get("acct"), ln.get("acct"))) if ln.get("acct") in moved else ln for ln in (inbox.get("lines") or [])]
    old_prints = {(ln["acct"],) + _line_print(ln) for ln, src in zip(lines, inbox.get("lines") or []) if src.get("acct") in moved}
    keep = [ln for ln, src in zip(lines, inbox.get("lines") or [])
            if src.get("acct") in moved or (ln.get("acct"),) + _line_print(ln) not in old_prints]
    return {**inbox, "lines": keep}


def heal_card_accounts(plan, accts: list) -> list:
    """v25.9: SimpleFIN sometimes gives a card a new account id (a bank connection re-linked on its side). A watched card whose id is no longer
    in SimpleFIN's list, while an account of the same name is, is switched to the new id, keeping its keyword. Returns the names switched."""
    cur = list(plan.expenses.get("sfin_card_accounts") or [])
    if not cur or not accts:
        return []
    live = {a["id"]: a for a in accts}
    by_name = {}
    for a in accts:
        by_name.setdefault(card_key(f"{a.get('org', '')} {a.get('name', '')}".strip()), []).append(a)
    watched_ids = {c["id"] for c in cur}
    out, done = [], []
    for c in cur:
        if c["id"] in live:
            out.append(c)
            continue
        cands = [a for a in by_name.get(card_key(c.get("name", "")), []) if a["id"] not in watched_ids]
        if len(cands) == 1:
            new = cands[0]
            out.append({**c, "id": new["id"]})
            watched_ids.add(new["id"])
            done.append(c.get("name", ""))
        else:
            out.append(c)
    if done:
        plan.expenses["sfin_card_accounts"] = out
    return done


def _sfin_card_toggle(acct):
    ss = st.session_state
    cur = list(ss.plan.expenses.get("sfin_card_accounts") or [])
    ids = {a["id"] for a in cur}
    checked = ss.get(f"sfin_card_{acct['id']}", False)
    if checked and acct["id"] not in ids:
        name = f"{acct['org']} {acct['name']}".strip()
        old = next((a for a in cur if card_key(a.get("name")) == card_key(name)), None)   # the same card under an earlier SimpleFIN id: replace it, keep its keyword
        kw = old["keyword"] if old and old.get("keyword") else card_keyword_guess(acct.get("org", ""), acct.get("name", ""))
        cur = [a for a in cur if card_key(a.get("name")) != card_key(name)] + [{"id": acct["id"], "name": name, "keyword": kw}]
        _card_keywords_add(kw)
        try:
            card_history_sync(ss.entries, _inbox(), [a["id"] for a in cur])
        except Exception:  # noqa: BLE001
            pass
    elif not checked and acct["id"] in ids:
        cur = [a for a in cur if a["id"] != acct["id"]]
    ss.plan.expenses["sfin_card_accounts"] = cur


def new_feed_accounts(plan, inbox: dict | None, live: list | None = None) -> list[dict]:
    """v25.38: accounts in the latest nightly fetch the app has not been told about yet -- not checking, not behind a balance line (or
    deliberately left out of one), not a watched card, not one you marked as not needed. A card that came back under a new SimpleFIN id
    (same last four digits as a watched card) is followed by itself, so it is not listed."""
    snaps = (inbox or {}).get("snapshots") or {}
    accts = list(snaps[max(snaps)].get("accounts") or []) if snaps else []
    have = {a.get("id") for a in accts}
    accts += [a for a in (live or []) if a.get("id") and a.get("id") not in have]     # v25.39: also this session's own fetch
    if not accts:
        return []
    exp = plan.expenses
    watched = exp.get("sfin_card_accounts") or []
    moved = exp.get("sfin_moved") or {}
    known = (set(exp.get("sfin_map") or {}) | {exp.get("sfin_account") or ""} | {c.get("id") for c in watched}
             | set(exp.get("sfin_seen") or []) | set(moved) | set(moved.values()))
    keys = {card_key(c.get("name")) for c in watched if str(card_key(c.get("name"))).startswith("#")}
    out = []
    for a in accts:
        i = a.get("id")
        if not i or i in known:
            continue
        lab = _acct_label(a) or i
        if card_key(lab) in keys:
            continue
        out.append({"id": i, "org": a.get("org", ""), "name": a.get("name", ""), "label": lab, "balance": a.get("balance")})
    return out


CARD_WORDS = ("card", "visa", "mastercard", "american express", "amex", "discover", "credit")


def looks_like_card(a: dict) -> bool:
    """v25.41: a credit card by its name or issuer (a card with a balance owed also shows a negative balance)."""
    t = f"{a.get('org', '')} {a.get('name', '')}".lower()
    return any(w in t for w in CARD_WORDS) or (isinstance(a.get("balance"), (int, float)) and a["balance"] < 0)


def cb_watch_new_card(acct: dict):
    """Watch a newly seen account as a card, with a keyword guessed from its name (check it against the card's payment line)."""
    ss = st.session_state
    cur = list(ss.plan.expenses.get("sfin_card_accounts") or [])
    if acct["id"] in {a["id"] for a in cur}:
        return
    kw = card_keyword_guess(acct.get("org", ""), acct.get("name", ""))
    cur.append({"id": acct["id"], "name": f"{acct.get('org', '')} {acct.get('name', '')}".strip(), "keyword": kw})
    ss.plan.expenses["sfin_card_accounts"] = cur
    ss[f"sfin_card_{acct['id']}"] = True                # v25.40: the box in the card list below shows it ticked as well
    _card_keywords_add(kw)
    try:
        card_history_sync(ss.entries, _inbox(), [a["id"] for a in cur])
    except Exception:  # noqa: BLE001
        pass
    ss.sfin_msg = f"Now watching {_card_short(acct['label'])}. Its keyword is '{kw}': change it below if the card's payment line uses another word."


def cb_skip_new_account(acct_id: str):
    ss = st.session_state
    seen = list(ss.plan.expenses.get("sfin_seen") or [])
    if acct_id not in seen:
        seen.append(acct_id)
    ss.plan.expenses["sfin_seen"] = seen


def goto_new_accounts():
    goto_updates("reconcile")
    st.session_state.sfin_new_open = True


def _sfin_card_keyword_changed(acct_id):
    ss = st.session_state
    cur = list(ss.plan.expenses.get("sfin_card_accounts") or [])
    kw = (ss.get(f"sfin_card_kw_{acct_id}") or "").strip().lower()
    if not kw:
        return
    for a in cur:
        if a["id"] == acct_id:
            a["keyword"] = kw
    ss.plan.expenses["sfin_card_accounts"] = cur
    _card_keywords_add(kw)


def _sfin_fetch(entries, days):
    ss = st.session_state
    end = _dt.datetime.combine(today() + _dt.timedelta(days=1), _dt.time.min, tzinfo=_dt.timezone.utc)
    start = end - _dt.timedelta(days=min(int(days) + 1, 44))          # SimpleFIN recommends at most 45 days a request
    try:
        data = simplefin_accounts(_sfin_url(), start=start.timestamp(), end=end.timestamp())
    except StorageError as e:
        ss.sfin_msg = str(e)
        return False
    errs = simplefin_errors(data)
    rows = simplefin_rows(data, ss.plan.expenses.get("sfin_account", ""))
    remember_live_balance(entries, ss.plan.expenses.get("sfin_account", ""), simplefin_account_list(data))
    try:                                                    # v25.39: the fetch returns every account, so the account list is brought up to date too
        ss.sfin_accts = simplefin_account_list(data)
    except Exception:  # noqa: BLE001
        pass
    if errs:
        ss.sfin_msg = "SimpleFIN reported: " + "; ".join(errs)
    if not rows:
        ss.sfin_msg = (ss.get("sfin_msg", "") + " " if errs else "") + "No posted transactions came back for that account in that period."
        return False
    plan_ = plan_bank_import(entries, rows, month_list(ss.plan, today()))
    ss.sfin_msg = ("SimpleFIN reported: " + "; ".join(errs)) if errs else ""
    auto = [p for p in plan_ if p["action"] in ("match", "update") and p.get("auto")]      # v25.24: exact matches are ticked straight away
    if auto:
        apply_bank_import(entries, auto, {p["i"]: {"apply": True, "cls": p["cls"] or "Core"} for p in auto})
        done = []
        for p in auto:
            r = find_row(entries, p["rk"], p["rid"])
            if r is not None and is_reconciled(r):
                stamp(r, "edited", "reconciled automatically: exact match" if p["action"] == "match" else
                      f"reconciled automatically: bill under {money(AUTO_BILL_LIMIT, 0)}, within {money(AUTO_BILL_TOLERANCE, 0)}")
                done.append(f"{r.get('desc')} {money(p['amount'], 2)}")
        if done:
            try:
                st.toast("Matched and reconciled automatically: " + ", ".join(done), icon="✅")
            except Exception:  # noqa: BLE001
                pass
            ss.sfin_msg = (ss.sfin_msg + " " if ss.sfin_msg else "") + "Reconciled automatically: " + ", ".join(done) + "."
    ss.bank_plan, ss.bank_skipped, ss.bank_msg = [p for p in plan_ if p not in auto], [], ""
    return any(p["action"] in ("match", "update", "new", "near") for p in ss.bank_plan)


def _sfin_bal_fetch(k, prefix):
    ss = st.session_state
    ib = _inbox()
    snap = ((ib or {}).get("snapshots") or {}).get(k) if k < today().strftime("%Y-%m") else None
    ss.sfin_bal_src = ""
    if snap:                                        # a month that has ended: the daily job's last balances from that month
        ss.sfin_bal_err = ""
        ss.sfin_accts, ss.sfin_errs = [{**a, "date": snap["date"]} for a in snap["accounts"]], []
        ss.sfin_bal_src = snap["date"]
    else:
        try:
            data = simplefin_accounts(_sfin_url(), balances_only=True)
        except StorageError as e:
            ss.sfin_bal_err = str(e)
            return
        ss.sfin_bal_err = ""
        ss.sfin_accts, ss.sfin_errs = simplefin_account_list(data), simplefin_errors(data)
    for key in [x for x in ss if str(x).startswith("sfin_map_")]:
        del ss[key]
    saved = ss.plan.expenses.get("sfin_map") or {}
    for a in ss.sfin_accts:
        ss[f"sfin_map_{a['id']}"] = saved[a["id"]] if a["id"] in saved else sfin_guess_line(a["org"], a["name"])
    ss.sfin_bal_reserve = float(ss.plan.cash.tax_reserve_remaining_2026)
    ss.sfin_bal_target = (k, prefix)


def _sfin_bal_apply():
    ss = st.session_state
    k, prefix = ss.sfin_bal_target
    mapping = {a["id"]: ss.get(f"sfin_map_{a['id']}", "") for a in ss.sfin_accts}
    ss.plan.expenses["sfin_map"] = mapping
    lines = sfin_balance_lines(ss.sfin_accts, mapping, ss.get("sfin_bal_reserve", 0.0))
    b = ss.entries["balances"].setdefault(k, {"notes": ""})
    src = ss.entries.setdefault("balances_src", {}).setdefault(k, {})
    for f, d in lines.items():
        b[f] = d["total"]
        ss[f"{prefix}_{f}"] = money_str(d["total"])
        src[f] = f"fill:{today().isoformat()}"            # v21.50: a fill after the month ended is replaced by the month-end snapshot
    ss.sfin_bal_toast = f"Filled {len(lines)} balance line{'s' if len(lines) != 1 else ''} for {month_label(k)} from the bank."
    ss.sfin_bal_done = True


@st.dialog("Check these balances before anything changes", width="large")
def _sfin_bal_review():
    ss = st.session_state
    if ss.pop("sfin_bal_done", None):
        st.rerun()
    accts = ss.get("sfin_accts") or []
    k, prefix = ss.sfin_bal_target
    if not accts:
        st.write("SimpleFIN returned no accounts.")
        return
    write(f"**Balances for {month_label(k)}.** Choose which balance line each bank account feeds. Your choices are remembered.")
    opts = ["", *[f for f, _ in ACCOUNT_LABELS]]
    names = dict(ACCOUNT_LABELS)
    for a in accts:
        c = st.columns([3, 2, 3])
        c[0].write(f"{a['org']} {a['name']}")
        c[1].write(money(a["balance"], 2) if a["balance"] is not None else "no balance")
        c[2].selectbox("Feeds", opts, format_func=lambda f: names.get(f, "Leave out"), key=f"sfin_map_{a['id']}", label_visibility="collapsed")
    st.number_input("Estimated tax still to pay, taken off the Wells line", min_value=0.0, step=500.0, key="sfin_bal_reserve",
                    help="That cash is still in savings until the payment goes out. It starts from the amount on your plan's cash inputs.")
    mapping = {a["id"]: ss.get(f"sfin_map_{a['id']}", "") for a in accts}
    lines = sfin_balance_lines(accts, mapping, ss.get("sfin_bal_reserve", 0.0))
    cur = ss.entries["balances"].get(k, {})
    df = pd.DataFrame([{"Balance line": names[f], "Now in the app": money(cur.get(f), 2) if isinstance(cur.get(f), (int, float)) else "-",
                        "From the bank": money(d["total"], 2), "Made of": " + ".join(p for p, _v in d["parts"]) + (f" less {money(d['reserve'], 2)} tax" if d["reserve"] else "")}
                       for f, d in lines.items()])
    if len(df):
        st.dataframe(df, hide_index=True, use_container_width=True)
    if ss.get("sfin_bal_src"):
        caption(f"These are the balances the daily fetch saved on {ss.sfin_bal_src}, the last time it ran in {month_label(k)}.")
    caption("Otherwise the bank's balance is as of today, so for a month that has already ended treat it as approximate. Lines not listed here, such as deferred compensation, are left as they are.")
    c = st.columns([1, 1, 3])
    c[0].button("Apply", type="primary", key="sfin_bal_apply", on_click=_sfin_bal_apply, disabled=not lines)
    if c[1].button("Cancel", key="sfin_bal_cancel"):
        st.rerun()


def _sfin_box(entries):
    ss = st.session_state
    st.markdown("**Fetch automatically from your banks and brokerages (SimpleFIN)**")
    url = _sfin_url()
    if not url:
        caption("Connect once and the app can pull your Wells transactions itself. On the SimpleFIN Bridge site: link Wells Fargo and Schwab, then Apps, New Connection, and copy the setup token. "
                "Paste it here. It works once, and the app keeps the resulting read-only address encrypted in your private repository.")
