def reminders_section():
    ss = st.session_state
    if cloud_cfg() is None:
        st.info("Reminders need automatic saving to your private GitHub data repository, which is not connected.")
        return
    caption("Email or text reminders when a month's data is late, or when nothing has been reconciled for a while. The app can't send them itself, because it only runs "
            "while you have it open. Instead it keeps a small note in your data repository, and a short Google script that you set up reads it each morning and emails you.")
    caption(f"Checking is watched even when the app is closed: each morning the daily bank fetch checks the real balance at the bank against your "
            f"{money(min_balance(ss.plan))} minimum (emailed every day while it is below), and whether a forecast dip has come within {TRANSFER_ACTION_DAYS} days "
            "(emailed weekly until a transfer is scheduled). Its note holds only the kind of alert and the month, never a balance.")
    on_key, days_key = f"nt_on_{ss.data_ver}", f"nt_days_{ss.data_ver}"
    st.checkbox("Send me reminders", value=bool(ss.plan.expenses.get("notify_on")), key=on_key, on_change=cb_notify_on, args=(on_key,))
    if not ss.plan.expenses.get("notify_on"):
        return
    st.number_input("Remind me when nothing has been reconciled for more than this many days", 3, 60, value=int(ss.plan.expenses.get("notify_days", 14)),
                    key=days_key, on_change=cb_notify_days, args=(days_key,))
    if ss.get("notify_msg"):
        st.warning(_esc(ss.notify_msg))
    elif ss.get("notify_at"):
        st.success(f"The reminder note was last written on {ss.notify_at}.")
    else:
        caption("The reminder note has not been written in this session yet.")
    st.button("Write the reminder note now", key=f"nt_now_{ss.data_ver}", on_click=cb_notify_now)
    with st.expander("Exactly what the note contains"):
        caption("Dates, and which parts of a month are missing. No amounts, no account names. The script reads only this.")
        st.json(notify_payload())


DATA_VIEWS = {"save": "Saving and copies", "import": "Import earlier months", "remind": "Reminders", "key": "GitHub access key", "inputs": "Plan inputs"}


