def page_data():
    """v21.69: Your data is a dashboard of tiles; each opens one view."""
    ss = st.session_state
    view = ss.get("data_view") or "hub"
    if view not in DATA_VIEWS:
        _data_hub()
        return
    back_bar("\u2039 Your data", _data_go, ("hub",), "data_back")
    st.title(DATA_VIEWS[view])
    if view == "save":
        if local_on():
            _sync_section()
            st.subheader("Copies you keep")
            st.markdown("- **Save data file** in the sidebar gives you a readable copy of everything, in a file you choose where to keep. Keep one now and then as a backup.\n"
                        "- **Load a data file** puts a saved file in as your current data. It is then saved here and synced, or a conflict is shown: nothing is replaced silently.")
        else:
            write("Your plan and monthly entries live in a data file that you keep. The app does not save them anywhere between sessions. "
                  "While you use it, the data you load is processed in memory on Streamlit's servers, like any hosted app.")
        if cloud_cfg() is not None and not local_on():
            st.markdown("- **Automatic saving is on.** Every change is saved to your private GitHub data repository"
                        + (", encrypted before it leaves the app" if cloud_cfg().key else "") + ", and loaded when you open the app.\n"
                        "- **Save data file** in the sidebar still gives you a copy on this device. Keep one as a backup.\n"
                        "- Loading a file from the sidebar never replaces the saved copy unless you confirm.")
        elif cloud_cfg() is None:
            st.markdown("- **Load** your file from the sidebar at the start of a session.\n"
                        "- **Save** it from the sidebar after you enter a month, and keep it somewhere safe.\n"
                        "- To save automatically instead, connect a private GitHub data repository in the app's secrets.")
        st.info(f"Current source: {ss.source}")
        if unsaved():
            st.warning("You have changes that are not saved to a file yet. Use Save data file in the sidebar.")
    elif view == "import":
        history_import()
    elif view == "remind":
        reminders_section()
    elif view == "key":
        if cloud_cfg() is not None:
            exp = cloud_cfg().token_expires
            st.write("Your access key expires on **" + (f"{MONTH_NAMES[exp.month - 1]} {exp.day}, {exp.year}" if exp else "a date GitHub has not reported yet")
                     + "**. The app warns you in the month before. To renew it:")
            st.markdown("1. On GitHub, create a new fine-grained token the same way as before: only the data repository, Contents set to Read and write.\n"
                        "2. In your Streamlit workspace, open this app's Settings, then Secrets, and replace the value of `GITHUB_TOKEN` with the new key.\n"
                        "3. Reload this page. The warning disappears once the app sees the new expiry date.\n"
                        "4. Delete the old token on GitHub. Never paste a key anywhere except the secrets box.")
    elif view == "inputs":
        caption("Numeric inputs behind the plan. Change a value, then apply. The sliders on the dashboard start from these values.")
        flat = list(flatten(plan_to_dict(ss.plan)))
        flt = st.text_input("Filter", placeholder="for example: cash, portfolio, defcomp", key=f"flt_{ss.data_ver}")
        df = pd.DataFrame([(p, v) for p, v in flat if flt.lower() in p.lower()][:400], columns=["Setting", "Value"])
        edited = st.data_editor(df, hide_index=True, disabled=["Setting"], key=f"plan_editor_{ss.data_ver}_{flt}")
        if st.button("Apply changes to the plan"):
            d = plan_to_dict(ss.plan)
            base = dict(flat)
            n = 0
            for _, r in edited.iterrows():
                if r["Setting"] in base and abs(base[r["Setting"]] - float(r["Value"])) > 1e-12:
                    set_path(d, r["Setting"], float(r["Value"])); n += 1
            if n:
                ss.plan = plan_from_dict(d)
                ss.data_ver += 1
                ss.settings = default_settings(ss.plan, ss.entries)
                st.success(f"{n} setting{'s' if n != 1 else ''} updated.")
                st.rerun()
            else:
                st.info("No changes to apply.")
        if st.button("Start over with the demo data"):
            apply_data(Plan(), demo_entries(), "Demo data (fictional). Load your data file in the sidebar."); st.rerun()
        caption(f"Build {BUILD}  ·  Streamlit {st.__version__}")
        caption(f"Home-screen icon patch: {_ICON_PATCH_STATUS}")




def _data_hub():
    ss = st.session_state
    st.title("Your data")
    caption("Where your data is kept, bringing in earlier months, reminders and the plan's settings. Tap a tile to open it.")
    if local_on():
        v_, k_, n_ = _sync_words()
        save = ("Saving and copies", v_, k_, n_, "")
    elif ss.get("cloud_cfg") is None:
        save = ("Saving and copies", "File only", "warn" if unsaved() else "idle", "Unsaved changes: use Save data file" if unsaved() else "Saved to a file on this device", "")
    else:
        st_ = ss.get("cloud_status")
        save = ("Saving and copies", "Saved" if st_ == "saved" else "Check", "ok" if st_ == "saved" else ("bad" if st_ in ("error", "conflict") else "warn"),
                "Saved to your private repository" if st_ == "saved" else "Open to see what to do", "")
    lb = ss.plan.meta.get("last_backup")
    save = save[:4] + ((f"Last file copy {fmt_date(_dt.date.fromisoformat(lb))}" if lb else "No file copy yet"),)
    T = lambda key, t, v: {"key": key, "t": t, "go": (lambda v_=v: _data_go(v_))}
    tiles = [T("dt_save", save, "save"),
             T("dt_import", ("Import earlier months", "History file", "idle", "Add earlier data", "Transactions, MAGI, balances, growth"), "import")]
    if cloud_cfg() is not None:
        on = bool(ss.plan.expenses.get("notify_on"))
        tiles.append(T("dt_remind", ("Reminders", "On" if on else "Off", "ok" if on else "idle", "Email when data is late", ""), "remind"))
        exp = cloud_cfg().token_expires
        if exp:
            d = (exp - today()).days if isinstance(exp, _dt.date) else None
            kv = ("GitHub access key", f"{fmt_date(exp)}, {exp.year}", "bad" if d is not None and d <= 7 else ("warn" if d is not None and d <= 30 else "ok"),
                  "Expires" if d is None or d >= 0 else "Expired", f"{d} days left" if d is not None and d >= 0 else "")
        else:
            kv = ("GitHub access key", "Unknown", "idle", "Expiry not reported yet", "How to renew it")
        tiles.append(T("dt_key", kv, "key"))
    else:
        tiles.append(T("dt_remind", ("Reminders", "Not available", "idle", "Needs automatic saving", ""), "remind"))
    tiles.append(T("dt_inputs", ("Plan inputs", f"{len(list(flatten(plan_to_dict(ss.plan))))}", "idle", "settings behind the plan", "Change a value, then apply"), "inputs"))
    _hub_row(tiles, "home")
    st.info(f"Current source: {ss.source}")
    caption(f"Build {BUILD}  \u00b7  Streamlit {st.__version__}")


# ---- weekly summary email (v25.5): built by the scheduled job in the data repository, sent straight to your inbox ------------------
# Amounts only ever exist inside the email itself: nothing with an amount is written to the repository in plain text.
def _wh(s):
    """Plain HTML escaping for the email (no Streamlit dollar-sign handling there)."""
    return _html.escape(str(s))


def _wk_items(plan, entries, start, end):
    """Every checking debit and card charge or refund dated in the week, with its category group; transfers and card payments left out."""
    groups = {c: g for g, c in categories_of(plan)}
    out = []
    for y in sorted({start.year, end.year}):
        for it in spending_items(plan, entries, y):
            if start.isoformat() <= str(it["date"])[:10] <= end.isoformat():
                g = groups.get(it["cat"], UNCATEGORIZED) if it["cat"] != UNCATEGORIZED else UNCATEGORIZED
                if g != NOT_SPENDING:
                    out.append({**it, "group": g})
    return sorted(out, key=lambda it: (it["date"], it["desc"]))


def _wk_acct_balance(inbox, acct, on_date):
    """A bank account's balance at the end of a day, worked back from the latest reading through the posted lines since."""
    snaps = (inbox or {}).get("snapshots") or {}
    if not acct or not snaps:
        return None, ""
    k = max(snaps)
    snap = snaps[k]
    bal = next((a.get("balance") for a in snap.get("accounts") or [] if a.get("id") == acct), None)
    if bal is None:
        return None, ""
    at = snap.get("date", "")
    later = sum(float(ln["amount"]) for ln in (inbox.get("lines") or []) if ln.get("acct") == acct and on_date.isoformat() < ln["date"] <= at)
    return round(float(bal) - later, 2), at


def weekly_summary(end: "_dt.date") -> dict:
    """The week ending `end` (a Friday), as the weekly email: subject, HTML and plain text."""
    return activity_report(end - _dt.timedelta(days=6), end, "week")


REPORT_WORD = {"week": "week", "month": "month", "quarter": "quarter", "year": "year"}


def report_title(start, end, kind) -> str:
    if kind == "week":
        return f"Your week, {fmt_date(start)} to {fmt_date(end)}, {end.year}"
    if kind == "month":
        return f"{MONTH_NAMES[start.month - 1]} {start.year}"
    if kind == "quarter":
        return f"Q{(start.month - 1) // 3 + 1} {start.year} ({MONTH_NAMES[start.month - 1][:3]} to {MONTH_NAMES[end.month - 1][:3]})"
    return f"{start.year}"


def _rep_checking(plan, entries, inbox, start, end):
    """Checking at the start and end of a period: the bank's own figures for a recent period, otherwise the ledger's month openings."""
    acct = plan.expenses.get("sfin_account")
    was_b, _ = _wk_acct_balance(inbox, acct, start - _dt.timedelta(days=1))
    now_b, _ = _wk_acct_balance(inbox, acct, min(end, today()))
    lines = sorted(ln["date"] for ln in ((inbox or {}).get("lines") or []) if ln.get("acct") == acct)
    if was_b is not None and now_b is not None and lines and lines[0] <= start.isoformat():
        return was_b, now_b
    try:
        k0 = start.strftime("%Y-%m")
        nxt = (end.replace(day=1) + _dt.timedelta(days=32)).replace(day=1)
        o0 = opening_any(k0)
        o1 = opening_any(nxt.strftime("%Y-%m")) if nxt <= today().replace(day=1) else now_b
        return o0, o1
    except Exception:  # noqa: BLE001
        return None, None


def reversed_pairs(items: list) -> set:
    """v25.17: charges that were reversed -- a charge and a refund on the same card, for the same merchant and the exact same amount, within
    60 days of each other (a voided ticket, a returned item). Returns the ids of both lines of each pair. Only pairs that match exactly count,
    so a partial refund or an unrelated credit is left alone."""
    out, pool = set(), {}
    for it in sorted(items, key=lambda x: x["date"]):
        if it["ref"][0] != "card" or abs(it["amount"]) < 0.005:
            continue
        key = (card_key(it["src"]), merchant_key(it["desc"]), round(abs(it["amount"]), 2))
        opp = pool.get(key + (-1 if it["amount"] > 0 else 1,), [])
        d = _dt.date.fromisoformat(it["date"][:10])
        m = next((o for o in opp if abs((d - o[1]).days) <= 60), None)
        if m:
            opp.remove(m)
            out |= {m[0], it["id"]}
        else:
            pool.setdefault(key + (1 if it["amount"] > 0 else -1,), []).append((it["id"], d))
    return out


def activity_report(start: "_dt.date", end: "_dt.date", kind: str = "week") -> dict:
    """v25.14: the activity for any period -- a week (the Friday email), a month, a quarter or a year: checking, spending and cards, as a
    subject, HTML and plain text. Reads the plan, entries and bank fetch from the session, the same way the screens do, so every figure
    matches the app. Longer periods add a full table by group and, for a quarter or a year, the months side by side."""
    ss = st.session_state
    plan, entries = ss.plan, ss.entries
    inbox = _inbox()
    week = kind == "week"
    word = REPORT_WORD.get(kind, "period")
    title_txt = report_title(start, end, kind)
    rng = title_txt
    secs = []                                    # (title, [lines], [table rows] or None)
    data = {"kind": kind, "start": start, "end": end, "title": title_txt, "word": word, "checking": None, "stale": [], "groups": [], "months": [],
            "top": [], "cards": [], "unc": (0, 0.0)}

    # 0. any account SimpleFIN has stopped updating (v25.13)
    old = stale_accounts(plan, ss.get("sfin_accts") or [], end) if (week and ss.get("sfin_accts")) else []
    data["stale"] = old
    if old:
        secs.append(("\u26a0\ufe0f Bank connections behind", [f"<b>{_wh(n)}</b>: SimpleFIN data from {fmt_date(d)}, {dd} day{'s' if dd != 1 else ''} behind your other accounts" for n, d, dd in old]
                     + ["Remove that bank's connection on the SimpleFIN Bridge site and add it again; the app follows the new account numbers and picks up what it missed by itself."], None))

    # 1. checking over the period
    if week:
        acct = plan.expenses.get("sfin_account")
        now_b, at = _wk_acct_balance(inbox, acct, end)
        was_b, _ = _wk_acct_balance(inbox, acct, start - _dt.timedelta(days=1))
    else:
        was_b, now_b = _rep_checking(plan, entries, inbox, start, end)
    if now_b is not None and was_b is not None:
        upto = min(end, today())
        data["checking"] = (was_b, now_b, upto)
        secs.append(("Checking", [f"Checking: <b>{money(now_b, 2)}</b> on {fmt_date(upto)}, {signed(now_b - was_b)} over the {word} (was {money(was_b, 2)} at the start)"], None))

    # 2. spending this week
    items = _wk_items(plan, entries, start, min(end, today()))         # nothing dated after today: planned lines are not activity yet
    rev_ids = reversed_pairs(_wk_items(plan, entries, start - _dt.timedelta(days=60), min(end, today()) + _dt.timedelta(days=60)))
    n_rev = sum(1 for it in items if it["id"] in rev_ids and it["amount"] > 0)
    v_rev = round(sum(it["amount"] for it in items if it["id"] in rev_ids and it["amount"] > 0), 2)
    items = [it for it in items if it["id"] not in rev_ids]           # voided or fully refunded: neither the charge nor its refund is activity
    tot = round(sum(it["amount"] for it in items), 2)
    gross = round(sum(it["amount"] for it in items if it["amount"] > 0), 2)
    back = round(-sum(it["amount"] for it in items if it["amount"] < 0), 2)
    data.update(gross=gross, back=back, net=tot, n=sum(1 for it in items if it["amount"] > 0))
    data["reversed"] = (n_rev, v_rev)
    lines = [f"Spent this {word}: <b>{money(gross, 2)}</b> across {sum(1 for it in items if it['amount'] > 0)} charges (checking and cards; transfers and card payments left out)"
             + (f", less {money(back, 2)} of refunds and credits: net {money(tot, 2)}" if back > 0.005 else "")]
    by_g = {}
    for it in items:
        by_g[it["group"]] = by_g.get(it["group"], 0.0) + it["amount"]
    if by_g and week:
        lines.append("By group: " + ", ".join(f"{_wh(g)} {money(v)}" for g, v in sorted(by_g.items(), key=lambda x: -x[1])[:6]))
    if n_rev:
        lines.append(f"{n_rev} charge{'s' if n_rev != 1 else ''} ({money(v_rev, 2)}) refunded in full {'are' if n_rev != 1 else 'is'} left out, with {'their' if n_rev != 1 else 'its'} refund{'s' if n_rev != 1 else ''}.")
    unc = [it for it in items if it["group"] == UNCATEGORIZED]
    data["unc"] = (len(unc), round(sum(i["amount"] for i in unc), 2))
    data["groups"] = sorted(by_g.items(), key=lambda x: -x[1])
    if unc:
        lines.append(f"⚠️ {len(unc)} line{'s' if len(unc) != 1 else ''} without a category ({money(sum(i['amount'] for i in unc), 2)})")
    if by_g and not week:
        gt = sum(v for v in by_g.values() if v > 0) or 1.0
        secs.append(("Spending by group", [f"Where the {money(tot)} went, largest first."],
                     (("Group", "Amount", "Share"), [(_wh(g), money(v, 2), f"{v / gt * 100:.0f}%") for g, v in sorted(by_g.items(), key=lambda x: -x[1])])))
    if kind in ("quarter", "year"):
        mon = {}
        for it in items:
            k_ = it["date"][:7]
            m_ = mon.setdefault(k_, [0.0, 0.0])
            m_[1 if it["ref"][0] == "card" else 0] += it["amount"]
        data["months"] = [(k_, v[0], v[1]) for k_, v in sorted(mon.items())]
        if mon:
            secs.append(("Month by month", [f"Spending each month, net of refunds."],
                         (("Month", "Checking", "Cards", "Total"), [(month_short(k_), money(v[0], 2), money(v[1], 2), money(v[0] + v[1], 2)) for k_, v in sorted(mon.items())])))
    top = sorted(items, key=lambda it: -it["amount"])[:{"week": 8, "month": 12}.get(kind, 15)]
    data["top"] = [(it["date"][:10], it["desc"], it["src"], it["cat"], it["amount"]) for it in top]
    short_src = lambda x: "Checking" if x == "Checking" else (_card_short(x) if len(_card_short(x)) <= 30 else _card_short(x)[:22].rstrip() + "\u2026" + _card_short(x)[-6:])
    rows = [(fmt_date(_dt.date.fromisoformat(it["date"][:10])), _wh(it["desc"][:40]), _wh(short_src(it["src"])), _wh(it["cat"]), money(it["amount"], 2)) for it in top]
    secs.insert(next((i for i, x in enumerate(secs) if x[0] in ("Spending by group", "Month by month")), len(secs)), (f"Spending this {word}" if week else "Spending", lines + ([f"The {len(top)} largest:"] if not week and top else []), (("Date", "What", "Paid from", "Category", "Amount"), rows) if rows else None))

    # 3. credit cards
    lines, rows = [], []
    try:
        wk = {}
        for it in items:
            if it["ref"][0] == "card":
                wk[it["src"]] = wk.get(it["src"], 0.0) + it["amount"]
        paid = {}
        for t in (entries.get("card_txns") or {}).values():
            if start.isoformat() <= str(t.get("date", "")) <= end.isoformat() and float(t.get("amount") or 0) > 0 and is_card_payment_credit(t.get("desc", "")):
                paid[t.get("acct_name") or "Card"] = paid.get(t.get("acct_name") or "Card", 0.0) + float(t["amount"])
        lines.append(f"Charged this {word}: <b>{money(sum(wk.values()), 2)}</b>; paid to the cards this {word}: {money(sum(paid.values()), 2)}")
        latest = {}
        for t in (entries.get("card_txns") or {}).values():
            n_ = t.get("acct_name") or "Card"
            latest[n_] = max(latest.get(n_, ""), str(t.get("date", "")))
        canon = card_canon(entries.get("card_txns") or {})
        names = []
        for c in card_accounts_of(plan):
            nm_ = canon.get(card_key(c.get("name", "")), c.get("name", ""))
            if nm_ not in names:
                names.append(nm_)
        names += [n for n in sorted(set(wk) | set(paid)) if n not in names]
        stale = []
        for name in sorted(names, key=lambda n: -wk.get(n, 0.0)):
            last = latest.get(name, "")
            if last and last < (end - _dt.timedelta(days=10)).isoformat():
                stale.append(_card_short(name))
            if not week and not wk.get(name) and not paid.get(name):
                continue
            data["cards"].append((_card_short(name), wk.get(name, 0.0), paid.get(name, 0.0), last))
            rows.append((_wh(_card_short(name)), money(wk[name], 2) if wk.get(name) else "\u2014", money(paid[name], 2) if paid.get(name) else "")
                        + ((fmt_date(_dt.date.fromisoformat(last)) if last else "none yet",) if week else ()))
        old = stale_accounts(plan, ss.get("sfin_accts") or [], end) if ss.get("sfin_accts") else None
        if week and old is None and stale:
            lines.append("\u26a0\ufe0f No lines for over 10 days from: " + ", ".join(_wh(x) for x in stale) + " \u2014 if these cards were used, their bank connection may need renewing.")
    except Exception as e:  # noqa: BLE001
        lines.append(f"Card figures unavailable: {_wh(str(e))[:120]}")
    hdr_c = ("Card", f"Charged this {word}", f"Paid this {word}") + (("Latest line",) if week else ())
    secs.append(("Credit cards", lines, (hdr_c, rows) if rows else None))

    subject = (f"Retirement plan: week of {fmt_date(start)} to {fmt_date(end)} — spent {money(gross)}" if week
               else f"Retirement plan: {title_txt} — spent {money(gross)}")
    css = "font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#222;max-width:680px"
    th = "text-align:left;border-bottom:1px solid #ccc;padding:4px 8px;font-size:13px;color:#555"
    td = "border-bottom:1px solid #eee;padding:4px 8px;font-size:13px"
    html = [f"<div style='{css}'><h2 style='margin:0 0 4px'>{_wh(rng)}</h2>"]
    text = [rng, ""]
    for title, ls, tbl in secs:
        html.append(f"<h3 style='margin:18px 0 6px;color:#3B7DB5'>{_wh(title)}</h3><ul style='margin:0;padding-left:18px'>" + "".join(f"<li style='margin:2px 0'>{x}</li>" for x in ls) + "</ul>")
        text += [title.upper()] + ["- " + _html.unescape(_re.sub(r"<[^>]+>", "", x)) for x in ls]
        if tbl:
            hdr, rws = tbl
            right = lambda i: (i >= 1) if title in ("Credit cards", "Spending by group", "Month by month") else i >= len(hdr) - 1
            html.append("<table style='border-collapse:collapse;margin-top:6px'><tr>" + "".join(f"<th style='{th}{';text-align:right' if right(i) else ''}'>{_wh(x)}</th>" for i, x in enumerate(hdr)) + "</tr>"
                        + "".join("<tr>" + "".join(f"<td style='{td}{';text-align:right;white-space:nowrap' if right(i) else (';white-space:nowrap' if i == 0 else '')}'>{x}</td>" for i, x in enumerate(r)) + "</tr>" for r in rws) + "</table>")
            text += ["  " + " | ".join(_html.unescape(_re.sub(r"<[^>]+>", "", str(x))) for x in r) for r in rws]
        text.append("")
    html.append(f"<p style='margin-top:20px;font-size:12px;color:#888'>From your retirement plan app: this {word}'s activity only"
                + (f", {fmt_date(start)} to {fmt_date(end)}, {end.year}" if not week else "") + ". Balances, budgets and open actions are on the Dashboard.</p></div>")
    if kind == "month":                                     # v25.28: the printable Monthly report ends with the reconciliation register
        try:
            data["register"] = register_for(start.strftime("%Y-%m"))
        except Exception:  # noqa: BLE001 - the report must still draw without it
            data["register"] = None
    return {"subject": subject, "html": "".join(html), "text": "\n".join(text), "data": data}


def weekly_email_run(env=None, end=None, send=True) -> dict:
    """The scheduled job's entry point: load the data and the bank fetch from the data repository, build the week's summary, and send it
    by Gmail (SMTP with an app password). Needs GITHUB_TOKEN, DATA_REPO, DATA_KEY as for saving, plus GMAIL_USER, GMAIL_APP_PASSWORD
    and SUMMARY_TO (one or more addresses, comma separated). With send=False it only returns the email, for a test."""
    import os as _os2, smtplib, ssl
    from email.mime.multipart import MIMEMultipart
    from email.mime.text import MIMEText
    from email.utils import formataddr as _formataddr
    env = env if env is not None else _os2.environ
    cfg = storage_config_from_secrets(env)
    if cfg is None:
        raise StorageError("GITHUB_TOKEN and DATA_REPO are needed.")
    data, _sha = cloud_load(cfg)
    plan, entries = plan_from_dict(data["plan"]), data["entries"]
    ss = st.session_state
    end = end or _dt.date.today()
    ss.today_override = end
    ss.plan, ss.entries, ss.source = plan, entries, "weekly email"
    ss.settings = default_settings(plan, entries)
    ss.data_ver = ss.get("data_ver", 0) + 1
    try:
        ss.inbox = inbox_load(cfg)
    except (StorageError, StorageNotFound):
        ss.inbox = None
    snaps = (ss.inbox or {}).get("snapshots") or {}
    if snaps:                               # a card SimpleFIN has renumbered is followed here too (in memory only)
        heal_card_accounts(plan, snaps[max(snaps)].get("accounts") or [])
    try:                                    # v25.13: how current SimpleFIN's data is for each account (one balances-only request)
        url = simplefin_load(cfg)
        ss.sfin_accts = simplefin_account_list(simplefin_accounts(url, balances_only=True)) if url else None
    except Exception:  # noqa: BLE001 - the email goes without this check rather than not at all
        ss.sfin_accts = None
    if ss.sfin_accts:                       # v25.24: a reconnected bank's accounts are followed here too (in memory only)
        heal_bank_accounts(plan, ss.sfin_accts, ss.inbox)
    ss.inbox = inbox_follow_moves(ss.inbox, plan.expenses.get("sfin_moved"))
    ids = [a["id"] for a in card_accounts_of(plan)]
    if ids and ss.inbox:                    # the card lines fetched since the app was last opened (in memory only; nothing is saved)
        card_history_sync(entries, ss.inbox, ids)
    mail = weekly_summary(end)
    if send:
        user, pw = env.get("GMAIL_USER"), env.get("GMAIL_APP_PASSWORD")
        to = [x.strip() for x in str(env.get("SUMMARY_TO") or user or "").split(",") if x.strip()]
        if not user or not pw or not to:
            raise StorageError("GMAIL_USER, GMAIL_APP_PASSWORD and SUMMARY_TO are needed to send.")
        msg = MIMEMultipart("alternative")
        msg["Subject"], msg["From"], msg["To"] = mail["subject"], _formataddr((EMAIL_SENDER_NAME, user)), ", ".join(to)
        msg.attach(MIMEText(mail["text"], "plain", "utf-8"))
        msg.attach(MIMEText(mail["html"], "html", "utf-8"))
        with smtplib.SMTP_SSL("smtp.gmail.com", 465, context=ssl.create_default_context()) as s:
            s.login(user, pw)
            s.sendmail(user, to, msg.as_string())
    return mail


# ---- main ---------------------------------------------------------------------------------------------------------------
# Streamlit's own page ships a viewport tag that blocks pinch-to-zoom on mobile Safari/iOS (no maximum-scale, but iOS still
# treats an app like this as a fixed-scale page). Rendering a second one here, as early as possible, overrides it in every
# mobile browser tested -- browsers use the last viewport tag they find in the document, even one injected into the body
# rather than the head, which is exactly what st.markdown produces. maximum-scale=5 with user-scalable=yes is the actual
# fix; the rest matches Streamlit's own default so nothing else about layout changes. (Andrew's call, September 2026,
# ahead of using the app on an iPad for 10 days: one real limit even this doesn't lift -- if the app is ever added to the
# iPad's home screen as its own icon, iOS disables pinch-zoom for that "standalone" mode outright, no matter what any page
# asks for; opening the same URL in an ordinary Safari tab is unaffected.)
VIEWPORT_FIX = '<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=5, user-scalable=yes">'
# The icon iOS shows for "Add to Home Screen" -- without this it just uses a screenshot of whatever page happened to
# be open. Andrew's design (September 2026): SHOOMAN in small letter-spaced caps over three ascending bars, in the
# app's own navy/soft-blue/brass palette. Full opaque square, no pre-rounded corners -- iOS applies its own corner
# mask to whatever it's given, so a source image that already rounds its own corners (with transparency showing
# through) can render oddly once iOS's mask is laid on top of it.
_APPLE_TOUCH_ICON_B64 = ('')
APPLE_TOUCH_ICON = f'<link rel="apple-touch-icon" href="data:image/png;base64,{_APPLE_TOUCH_ICON_B64}">'
# Placing that tag with st.markdown(), as done below, does NOT reach the real <head> -- Streamlit serves one fixed,
# pre-built index.html for the page load itself, and that static file's own <head> is what Safari's "Add to Home
# Screen" actually reads. Anything st.markdown() renders lands well after that -- injected client-side, deep inside
# a <div> in the body -- which is exactly why this rendered fine in every test here yet still showed the generic
# Streamlit icon on Andrew's wife's iPad even after a fresh delete-and-re-add (his first report, 25 Sep 2026). The
# st.markdown() call is kept below anyway, harmless, in case some future browser is more lenient about where it
# looks -- but the actual fix has two parts, in _patch_home_screen_icon() below:
#   1. rewrite the real <head> Streamlit serves, in the installed package itself, not just what st.markdown() renders
#   2. reference the icon as a real static file (like Streamlit's own favicon.png already is), not a data: URI --
#      after part 1 alone still didn't work (Andrew's second report, same day), a data: URI is the next suspect:
#      it's a well-known iOS quirk that "Add to Home Screen" can silently ignore an apple-touch-icon given as a
#      data: URI and fall back to the generic icon, even though every other consumer of that <link> tag (the tab,
#      a screenshot) is perfectly happy with it. A real file, served the same way favicon.png already is, sidesteps
#      that question entirely rather than betting on it.
# v25.52: the icon is fetched from a public copy. The app is private, and Safari fetches the icon without signing in, so a copy behind
# the sign-in came back as nothing and iOS drew a letter "R" instead (seen on Estele's iPad, 30 Oct 2026).
PUBLIC_ICON_URL = "https://raw.githubusercontent.com/ashooman1/app-icon/main/IMG_1006.png"
_ICON_PATCH_STATUS = "not run yet"     # shown on the Housekeeping page so this can be checked without needing a device
def _patch_home_screen_icon():
    """Rewrites the <head> of the actual index.html Streamlit serves (inside the installed streamlit package itself)
    to add a real apple-touch-icon link, and writes the icon itself as a real PNG file alongside Streamlit's own
    favicon.png -- since nothing reachable from the Python API puts either there otherwise. Idempotent (a marker in
    the tag guards against re-patching) and self-healing: any failure (a read-only filesystem, a changed file layout)
    is caught and recorded in _ICON_PATCH_STATUS rather than breaking the app, and is retried on the next rerun
    rather than remembered as permanent, in case the reason was transient.

    One real limit, inherent to how Streamlit serves the page, not fixable from here: the very first page load
    after a fresh deploy (or after the app wakes from being asleep) is served from whatever is on disk *before* this
    function gets a chance to run -- a script only starts running once that first page's own JS has already loaded
    and opened its connection back to the server. So the first visit right after a restart can still carry the old,
    unpatched page. A plain reload of that same tab (or just reopening it) right after -- before using Add to Home
    Screen -- picks up the now-patched head. Once anyone has loaded the app since the last restart, every later visit,
    on any device, gets the patched head on the very first try."""
    global _ICON_PATCH_STATUS
    if _ICON_PATCH_STATUS == "patched":
        return
    try:
        static_dir = _os.path.join(_os.path.dirname(st.__file__), "static")
        icon_path = _os.path.join(static_dir, "apple-touch-icon-shooman.png")
        index_path = _os.path.join(static_dir, "index.html")
        icon_bytes = _b64.b64decode(_APPLE_TOUCH_ICON_B64)
        if not (_os.path.exists(icon_path) and _os.path.getsize(icon_path) == len(icon_bytes)):
            open(icon_path, "wb").write(icon_bytes)
        man_path = _os.path.join(static_dir, "shooman-manifest.json")      # v25.1: a web-app manifest, so "Open as Web App" keeps the icon too
        man = json.dumps({"name": "Retirement plan", "short_name": "Retirement", "display": "standalone", "start_url": "./", "scope": "./",
                          "background_color": "#ffffff", "theme_color": "#ffffff",
                          "icons": [{"src": PUBLIC_ICON_URL, "sizes": "180x180", "type": "image/png", "purpose": "any"}]})
        if not (_os.path.exists(man_path) and open(man_path, encoding="utf-8").read() == man):
            open(man_path, "w", encoding="utf-8").write(man)
        html = open(index_path, "r", encoding="utf-8").read()
        if "shooman-head-v3" in html:
            _ICON_PATCH_STATUS = "patched"
            return
        html = _re.sub(r'<link rel="apple-touch-icon" id="shooman-apple-touch-icon"[^>]*>\s*', "", html)     # the first version's single tag
        html = _re.sub(r'<link rel="apple-touch-icon" id="shooman-head-v2".*?apple-mobile-web-app-status-bar-style" content="default">\s*',
                       "", html, flags=_re.S)                                                     # v25.52: the second version's block
        if "</head>" not in html:
            _ICON_PATCH_STATUS = "failed: index.html has no </head> to patch"
            return
        tag = (f'<link rel="apple-touch-icon" id="shooman-head-v3" sizes="180x180" href="{PUBLIC_ICON_URL}">\n'
               '    <link rel="manifest" href="./shooman-manifest.json">\n'
               '    <meta name="apple-mobile-web-app-capable" content="yes">\n'
               '    <meta name="mobile-web-app-capable" content="yes">\n'
               '    <meta name="apple-mobile-web-app-title" content="Retirement">\n'
               '    <meta name="apple-mobile-web-app-status-bar-style" content="default">\n  </head>')
        open(index_path, "w", encoding="utf-8").write(html.replace("</head>", tag, 1))
        _ICON_PATCH_STATUS = "patched"
    except Exception as e:      # noqa: BLE001 - a missing icon should never take the app down
        _ICON_PATCH_STATUS = f"failed: {type(e).__name__}: {e}"

def _outer_page_icon():
    """v25.53: on Streamlit Community Cloud the page Safari adds to the Home Screen is Streamlit's own outer page (titled
    "Retirement plan · Streamlit", with Streamlit's icon); this app runs in a frame inside it, so the head patch above never reaches
    it. That outer page is the same site, so a small script placed into it swaps in our icon and name, and keeps them there if
    Streamlit's page puts its own back."""
    fix = ("function(d){d.querySelectorAll('link[rel~=\"apple-touch-icon\"],link[rel=\"apple-touch-icon-precomposed\"]').forEach(function(l){"
           "if(l.id!=='shooman-outer-icon')l.remove();});var l=d.getElementById('shooman-outer-icon');if(!l){l=d.createElement('link');"
           "l.id='shooman-outer-icon';l.rel='apple-touch-icon';l.setAttribute('sizes','180x180');d.head.appendChild(l);}"
           "if(l.getAttribute('href')!==ICON)l.setAttribute('href',ICON);var m=d.querySelector('meta[name=\"apple-mobile-web-app-title\"]');"
           "if(!m){m=d.createElement('meta');m.name='apple-mobile-web-app-title';d.head.appendChild(m);}if(m.content!==NAME)m.content=NAME;}")
    inner = ("(function(){var ICON=" + json.dumps(PUBLIC_ICON_URL) + ",NAME='Retirement';var fix=" + fix + ";fix(document);"
             "new MutationObserver(function(){fix(document);}).observe(document.head,{childList:true,subtree:true,attributes:true});})();")
    js = ("(function(){var code=" + json.dumps(inner) + ";var w=window;for(var i=0;i<4;i++){try{if(w!==window&&!w.__shoomanIcon&&w.document&&w.document.head){"
          "w.__shoomanIcon=true;var sc=w.document.createElement('script');sc.textContent=code;w.document.head.appendChild(sc);}}catch(e){}"
          "var p=null;try{p=w.parent;}catch(e){}if(!p||p===w)break;w=p;}})();")
    with st.container(key="outer_icon"):
        _html_frame("<script>" + js + "</script>", height=1)


