def is_dev() -> bool:
    """True for the test copy: its data repository name ends in -dev, or the APP_ENV secret says dev. Read straight from the secrets so it works before the app has loaded."""
    try:
        if str(st.secrets["APP_ENV"]).strip().lower() == "dev":
            return True
    except Exception:  # noqa: BLE001 - no such secret is normal
        pass
    try:
        return str(st.secrets["DATA_REPO"]).strip().lower().endswith("-dev")
    except Exception:  # noqa: BLE001
        return False


DEV_CSS = """<style>
[data-testid="stSidebar"]{background:rgba(245,158,11,.16) !important;border-right:4px solid #f59e0b}
.devbar{background:#f59e0b;color:#1f1300;font-weight:700;letter-spacing:.04em;padding:.45rem .9rem;border-radius:.5rem;margin:0 0 .8rem 0;font-size:.95rem}
</style>"""


def main():
    local = _os.environ.get("PLAN_LOCAL") == "1"                  # the launcher on your computer sets this; the cloud copy does not
    dev = is_dev()
    st.set_page_config(page_title=("DEV Retirement plan" if dev else "Retirement plan (local)" if local else "Retirement plan"), page_icon=("🧪" if dev else "📊"), layout="wide")
    _patch_home_screen_icon()
    _outer_page_icon()                                                  # v25.53
    st.markdown(VIEWPORT_FIX, unsafe_allow_html=True)
    st.markdown(APPLE_TOUCH_ICON, unsafe_allow_html=True)
    st.markdown(CSS, unsafe_allow_html=True)
    init_state()
    if dev:
        st.markdown(DEV_CSS, unsafe_allow_html=True)
        st.markdown('<div class="devbar">DEV COPY: a test version with its own data and bank connection. Nothing here changes your real plan.</div>', unsafe_allow_html=True)
    st.sidebar.title("Retirement plan" + (" (DEV)" if dev else ""))
    ss = st.session_state
    ensure_recurring_lines(ss.plan, ss.entries, month_list(ss.plan, today()))
    sync_card_history()
    sync_auto_interest()
    sync_auto_income()
    sync_month_end()
    try:
        ss.actions_list = collect_actions(ss.plan, ss.entries)        # v21.62: the status bar and the Actions page
    except Exception:  # noqa: BLE001
        ss.actions_list = []
    sidebar_status(ss.actions_list)
    pages =["Dashboard", "Monthly updates", "Ledger", "Spending", "One-time spending", "Net worth", "Cash flow", "ACA", "Tax payments", "Roth", "DefComp", "Moving", "Year end", "Reporting", "Your data"]
    page = st.sidebar.radio("Page", pages, key="page", label_visibility="collapsed", on_change=cb_estele_close)
    if page is None and not ss.get("estele") and not ss.get("actions_open"):   # v21.35: never left without a page
        page = "Dashboard"
    if page != ss.get("_last_page"):                                  # arriving at Reporting from another page shows its tiles, not the last view opened
        ss.page_visit = ss.get("page_visit", 0) + 1                   # v21.24: a new visit, so every chart starts at its default view
        if page == "Reporting":
            ss.rep_view = ss.pop("rep_view_next", None) or "hub"
        if page == "Net worth":
            ss.nw_view = ss.pop("nw_view_next", None) or "hub"
        if page == "Spending":
            ss.sp_view = ss.pop("sp_view_next", None) or "main"
        if page == "Monthly updates":
            ss.mu_view = ss.pop("mu_view_next", None) or "hub"
        if page == "Cash flow":
            ss.cf_view = "hub"
        if page == "Moving":
            ss.mv_view = "hub"
        if page == "ACA":
            ss.aca_view = "hub"
        if page == "Tax payments":
            ss.tp_view = ss.pop("tp_view_next", None) or "hub"
        if page == "Roth":
            ss.roth_view = "hub"
        if page == "DefComp":
            ss.dc_view = "hub"
        if page == "Year end":
            ss.ye_view = "hub"
        if page == "One-time spending":
            ss.ot_view = "hub"
        if page == "Your data":
            ss.data_view = ss.pop("data_view_next", None) or "hub"
        ss._last_page = page   # the headings Cash, Planning and Housekeeping come from the CSS, keyed to the position of Monthly updates, ACA and Year end (2nd, 8th and 12th)
    status_box = sidebar_data()
    if local_on():
        local_autosave()                    # first, so the banners, tiles and status on this screen already show the result of the last change
    # v21.62: the warning banners that sat at the top of pages are now actions, counted in the sidebar's status bar
    if ss.get("actions_open"):
        page_actions()
    elif ss.get("estele"):
        page_estele()
    if ss.get("estele") or ss.get("actions_open"):
        pass
    elif page == "Dashboard":
        page_overview()
    elif page == "Cash flow":
        page_cashflow()
    elif page == "ACA":
        page_aca()
    elif page == "Roth":
        page_roth()
    elif page == "Reporting":
        page_reporting()
    elif page == "One-time spending":
        page_onetime()
    elif page == "Monthly updates":
        page_updates()
    elif page == "Ledger":
        page_ledger()
    elif page == "Net worth":
        page_networth()
    elif page == "Spending":
        page_spending()
    elif page == "Tax payments":
        page_taxpay()
    elif page == "Year end":
        page_yearend()
    elif page == "DefComp":
        page_defcomp()
    elif page == "Moving":
        page_moving()
    else:
        page_data()
    if local_on():
        local_autosave()
    else:
        autosave()
    render_cloud_status(status_box)
    st.sidebar.caption(f"App {APP_VERSION}")


if __name__ == "__main__":
    main()
